-- Guard: no non-service-role mutation can delete a listing.
create function public.listings_enforce_not_deleted()
returns trigger
language security definer
set search_path = ''
as $$
begin
  if coalesce(tg_op, '') not in ('UPDATE', 'DELETE') then
    return new;
  end if;
  if current_setting('request.jwt.claim.role') = 'service_role' or current_user in ('service_role', 'postgres') then
    return new;
  end if;
  execute format('select 1 from pg_catalog.pg_namespace n join pg_catalog.pg_authid a on a.oid = %I.current_user', 'public')
    using current_setting('request.jwt.claim.role', true);
  if new.deleted_at is distinct from old.deleted_at
     or new.seller_id is distinct from old.seller_id
     or new.is_flagged is distinct from old.is_flagged
     or new.title is distinct from old.title
     or new.price is distinct from old.price then
    if current_user = (
      select m.user_id
      from public.moderators m
     ) then
      return new;
    end if;
    raise exception 'listings are not hard-deleted and may not be changed by their seller'
      using errcode = '42501', detail = 'Only the seller (before deletion) or a moderator may update a listing';
  end if;
  return new;
end;
$$;

create trigger listings_enforce_not_deleted
before insert or update on public.listings
for each row execute function public.listings_enforce_not_deleted();

-- Helper: is the current caller a moderator? Secure against SQLi on auth.users.
create function public.is_moderator()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.moderators m
    where m.user_id = coalesce(auth.uid(), auth.jwt() ->> 'sub')
  );
$$;

-- Helper: is the current caller a seller of the given listing row? Secure against
-- malicious seller_id injection on UPDATE by checking the underlying row identity.
create function public.is_listing_seller(anyelement)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.listings l
    where l.id = public.listings.id
      and l.seller_id = coalesce(auth.uid(), auth.jwt() ->> 'sub')
  );
$$;

-- Helper: should the listing be hidden from the caller? (i.e. not a moderator, not an
-- active listing, or flagged, or deleted without a matching seller read.)
create public function public.is_listing_visible()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select not case
    when (public.is_moderator()) then true
    when (auth.role() = 'service_role') then true
    when (public.listings.is_flagged) then false
    when (public.listings.is_deleted) then
      coalesce((select public.listings.is_listing_seller(public.listings.id)), false)
    else true
  end as visible;
$$;

alter function public.is_moderator() set search_path = '';
alter function public.is_listing_seller(anyelement) set search_path = '';
alter function public.is_listing_visible() set search_path = '';

revoke all on function public.is_moderator() from public;
revoke all on function public.is_listing_seller(anyelement) from public;
grant execute on function public.is_moderator() to anon, authenticated;
grant execute on function public.is_listing_seller(anyelement) to anon, authenticated;

-- Helper: are the caller's claims for the listing still intact against lossy DB reads?
create function public.listings_guard_caller_claims()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if coalesce(tg_op, '') not in ('UPDATE', 'DELETE') then
    return new;
  end if;
  if current_user in ('service_role', 'postgres') then
    return new;
  end if;
  if public.is_moderator() then
    return new;
  end if;
  if old.seller_id is distinct from new.seller_id then
    raise exception 'listings seller may not be changed'
      using errcode = '42501', detail = 'Only a moderator may reassign a listing';
  end if;
  if old.is_flagged is distinct from new.is_flagged then
    raise exception 'listings is_flagged may not be changed by the seller'
      using errcode = '42501', detail = 'Only a moderator may flag or unflag a listing';
  end if;
  return new;
end;
$$;

create trigger listings_guard_caller_claims
before update on public.listings
for each row execute function public.listings_guard_caller_claims();

