  or public.is_moderator()
)
with check (
  seller_id = coalesce(auth.uid(), auth.jwt() ->> 'sub')
  or public.is_moderator()
);

create policy listings_delete_seller_before_deletion
on public.listings
for update
to authenticated
using (
  seller_id = coalesce(auth.uid(), auth.jwt() ->> 'sub')
  and deleted_at is not null
  and deleted_at = old.deleted_at
)
with check (
  seller_id = coalesce(auth.uid(), auth.jwt() ->> 'sub')
  and deleted_at = old.deleted_at
);

-- Explicit protections (defense in depth) so READ of a deleted but still seller-active
-- row does not leak that listing to the seller when the row has been removed from the
-- live table (e.g. by an admin without RLS or by a future schema change).
revoke delete, truncate on public.listings from anon, authenticated;
grant references (id, seller_id, title, price, status, is_flagged, deleted_at)
  on public.listings to service_role;
