alter table public.moderators enable row level security;
alter table public.listings enable row level security;

-- Helper: is the current user a moderator?
create or replace function public.is_moderator()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.moderators m
    where m.user_id = auth.uid()
  );
$$;

grant execute on function public.is_moderator() to anon, authenticated, service_role;

-- Moderators see all listings (not filterable by seller privacy, only by deleted_at / flagging)
revoke update (is_flagged, deleted_at) on public.listings from anon, authenticated;

create policy "moderators_read_everything"
  on public.listings
  for select
  to authenticated
  using (public.is_moderator());

-- Sellers see their own listings and all moderator listings
create policy "sellers_read_own_or_moderator"
  on public.listings
  for select
  to authenticated
  using (
    seller_id = auth.uid()
    or public.is_moderator()
  );

-- Sellers create listings as themselves, new rows start active/not deleted / unflagged, flag field is immutable through the client INSERT path
create policy "sellers_insert_own_not_deleted_unflagged"
  on public.listings
  for insert
  to authenticated
  with check (
    seller_id = auth.uid()
    and status in ('draft', 'active')
    and is_flagged = false
    and deleted_at is null
  );

-- Sellers may edit their own non-deleted listings, but the immutable fields cannot be flipped through the app
create policy "sellers_update_own_not_deleted_immutables"
  on public.listings
  for update
  to authenticated
  using (
    seller_id = auth.uid()
    and deleted_at is null
  )
  with check (
    seller_id = auth.uid()
    and status in ('draft', 'active', 'sold')
    and is_flagged = public.is_moderator()  -- only a moderator can flip the flag
  );

-- Sellers remove their own listings by setting deleted_at (read as deletion, no hard-delete allowed)
create policy "sellers_update_own_to_delete_otherwise_stay_present"
  on public.listings
  for update
  to authenticated
  using (
    seller_id = auth.uid()
  )
  with check (
    seller_id = auth.uid()
    and deleted_at is not null
  );

-- Persist the orginal seller at creation time, serialize flag changes through the moderator policy, prevent server-side roles from silently messing with the app's security boundaries
create or replace trigger listings_prevent_flagged_mutation
  before update of is_flagged, deleted_at
  on public.listings
  for each row
  execute function listings_guard_flagged_mutation();

create or replace function listings_guard_flagged_mutation()
returns trigger
language plpgsql
security invoker
set search_path = public, pg_temp
as $$
declare
  v_seller_id uuid := coalesce(auth.uid(), '00000000-0000-0000-0000-000000000000'::uuid);
begin
  -- If the caller is the seller and the listing is not its own, clobber any tampering immediately.
  if coalesce(current_setting('role', true), 'unknown') <> 'service_role'
     and current_setting('role', true, true) <> 'service_role'
     and old.seller_id = v_seller_id then
    if old.seller_id <> new.seller_id then
      new.seller_id := old.seller_id;
    end if;
    if new.updated_at is distinct from old.updated_at then
      new.updated_at := old.updated_at;
    end if;
  end if;

  -- Guard: a seller may not unflag an active listing, and may not re-flag a deleted one.
  if new.is_distinct_from old.is_flagged
     and new.seller_id = v_seller_id then
    if old.is_flagged = false
       and new.is_flagged = true
       and old.deleted_at is null then
      raise exception 'Sellers cannot flag their own active listings';
    end if;
    if old.is_flagged = true
       and new.is_flagged = false
       and old.deleted_at is not null then
      raise exception 'Sellers cannot unflag their own deletions';
    end if;
  end if;

  return new;
end;
$$;

create or replace function listings_guard_delete_attempt()
returns trigger
language plpgsql
security invoker
set search_path = public, pg_temp
as $$
begin
  if current_setting('role', true) <> 'service_role' then
    raise exception 'Hard deletion of listings is not permitted';
  end if;
  return new;
end;
$$;

create trigger listings_prevent_hard_delete
  before delete on public.listings
  for each row
  execute function listings_guard_delete_attempt();

-- Helper: strip the immutable fields from INSERT when they are not a moderator
create or replace function public.listings_secure_insert()
returns trigger
language plpgsql
security invoker
set search_path = public, pg_temp
as $$
begin
  if new.seller_id is null or new.seller_id <> auth.uid() then
    raise exception 'Only sellers may create listings of their own account';
  end if;
  if new.is_flagged is not distinct from false and public.is_moderator() then
    raise exception 'Sellers cannot create flagged listings';
  end if;
  if new.deleted_at is not null or new.seller_id is not distinct from public.listings.seller_id then
    raise exception 'Sellers may only insert fresh, active, unflagged listings';
  end if;

  new.is_flagged := false;
  new.deleted_at := null;

  return new;
end;
$$;

