create function public.enforce_article_status(
  p_id bigint, p_status text, p_published_at timestamptz
) returns void
language plpgsql security definer set search_path = ''
as $$
declare
  v_article articles%rowtype;
  v_editor  editors.user_id%type;
  v_writer  articles.author_id%type;
  v_current_status articles.status%type;
begin
  if auth.role() = 'service_role' then return; end if;
  if v_status is null then
    raise exception 'article status may only be draft, in_review, or published';
  end if;
  select * into v_article from public.articles where id = p_id for update;
  if not found then raise exception 'article not found'; end if;
  v_current_status := v_article.status;
  v_writer := v_article.author_id;
  select user_id into v_editor from public.editors where user_id = auth.uid();
  if v_editor is not null then
    if v_current_status = 'draft' then
      raise exception 'editors may only edit articles in review';
    end if;
    update public.articles set status = p_status, published_at = p_published_at
     where id = p_id and status = 'in_review';
    if not found then raise exception 'editor may not change article status'; end if;
  else
    if v_current_status = 'published' then
      raise exception 'published articles cannot be changed';
    end if;
    if v_current_status = 'in_review' then
      raise exception 'articles in review may only be edited by editors';
    end if;
    if v_writer is distinct from auth.uid() then
      raise exception 'writers may only edit their own drafts';
    end if;
    if p_status = 'draft' then
      update public.articles set status = 'draft', published_at = null
       where id = p_id and author_id = auth.uid();
    elsif p_status = 'in_review' then
      update public.articles set status = 'in_review', published_at = null
       where id = p_id and author_id = auth.uid();
    else
      raise exception 'writers may not publish articles';
    end if;
    if not found then raise exception 'cannot update article'; end if;
  end if;
end
$$;

create function public.send_back(p_id bigint) returns editor
language plpgsql security definer set search_path = ''
as $$
declare
  v_id editor := auth.uid();
begin
  if v_id is null then raise exception 'you are not an editor'; end if;
  perform public.enforce_article_status(p_id, 'draft', null);
  return v_id;
end
$$;

create policy editors_select on public.editors
  for select to authenticated
  using (user_id = auth.uid());

create policy articles_select on public.articles
  for select to anon, authenticated
  using (status = 'published' or author_id = auth.uid() or public.is_editor());

create policy articles_insert on public.articles
  for insert to authenticated
  with check (author_id = auth.uid() and status = 'draft');

create policy articles_update on public.articles
  for update to authenticated
  using (author_id = auth.uid() and status = 'draft')
  with check (public.enforce_article_status(id, status, published_at));

create policy articles_delete on public.articles
  for delete to authenticated
  using (author_id = auth.uid() and status = 'draft');
