-- R2 / R3: break_glass RPC - caller must be a clinician, patient must exist,
-- reason (trimmed) must be at least 10 characters.
-- The function sanitizes the reason (ignoring surrounding spaces) and
-- creates a fresh grant that expires one hour later.

create or replace function public.break_glass(p_patient_id bigint, p_reason text)
returns timestamptz
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  l_reason text := trim(p_reason);
begin
  if not exists (select 1 from public.clinicians where user_id = auth.uid()) then
    raise exception 'break_glass: caller is not a clinician';
  end if;

  if not exists (select 1 from public.patients where id = p_patient_id) then
    raise exception 'break_glass: patient does not exist';
  end if;

  if length(l_reason) < 10 then
    raise exception 'break_glass: reason must be at least 10 characters';
  end if;

  insert into public.break_glass_grants (patient_id, clinician_id, reason, expires_at)
  values (p_patient_id, auth.uid(), l_reason, now() + interval '1 hour')
  returning expires_at into return value;

  return return value;
end;
$$;

create policy "break_glass_grants_select"
on public.break_glass_grants
for select
to authenticated
using (
  clinician_id = auth.uid()
  or exists (select 1 from public.auditors where user_id = auth.uid())
);

-- R1 / R4: medical_records are read-only for app users.
-- R5: no policies for anon; no policy no-access = no access.
-- R4: no insert/update/delete on medical_records.

-- Revoke insert/update/delete on medical_records for client roles.
revoke insert, update on public.medical_records from anon, authenticated;
grant select on public.medical_records to authenticated;

-- Revoke all on break_glass_grants for client roles; let RLS filter.
revoke all on public.break_glass_grants from anon, authenticated;
grant select on public.break_glass_grants to authenticated;

-- Clinician and auditor roles needed as local granularity.
grant select on public.clinicians to authenticated;
grant select on public.auditors to authenticated;

-- Care-team pairs are never private (all rows belong to authenticated users
-- via the referenced clinician row and the health domain).
grant all on public.care_team to service_role;
revoke all on public.care_team from anon, authenticated;

-- R6: service role bypasses RLS and keeps full access.
grant all on public.clinicians, public.auditors to service_role;
grant all on public.patients to service_role;
grant all on public.care_team to service_role;
grant all on public.medical_records to service_role;
grant all on public.break_glass_grants to service_role;

-- service_role does not read/write auth.users / storage.
-- (nothing here changes those tables).
