create or replace function public.break_glass(p_patient_id bigint, p_reason text)
returns timestamptz
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_clinician uuid := auth.uid();
  v_now timestamptz := now();
  v_expires timestamptz := v_now + interval '1 hour';
begin
  if v_clinician is null
     or not exists (select 1 from public.clinicians c where c.user_id = v_clinician) then
    raise exception 'not authorized';
  end if;

  if p_reason is null or trim(p_reason) = '' then
    raise exception 'reason is required';
  end if;

  if character_length(trim(p_reason)) < 10 then
    raise exception 'reason must be at least 10 characters';
  end if;

  if not exists (select 1 from public.patients p where p.id = p_patient_id) then
    raise exception 'patient does not exist';
  end if;

  insert into public.break_glass_grants (patient_id, clinician_id, reason, expires_at)
  values (p_patient_id, v_clinician, p_reason, v_expires)
  returning (expires_at into v_expires);

  return v_expires;
end
$$;

