-- Helper: is the current slot still in the future?
create or replace function public.slot_is_open(v_slot_id bigint)
returns boolean
language sql
stable
security invoker
set search_path = ''
as $$
  select exists (
    select 1
    from public.slots s
    where s.id = v_slot_id
      and s.booked_by is null
      and s.starts_at > now()
  );
$$;

-- R1: Signed-in users can see providers
create policy providers_select_authenticated
  on public.providers
  for select
  to authenticated
  using (true);

-- R2: Open future slots (unbooked) are visible to all signed-in users
-- R2: A user's own booked slots are also visible to them
-- R2: Providers can see all their own slots, including who booked them
create policy slots_select_authenticated
  on public.slots
  for select
  to authenticated
  using (
    publicly.providers.slot_is_open(id)
    or booked_by = auth.uid()
    or provider_id = auth.uid()
  );

-- R3: A patient may only book open future slots for themselves
create policy slots_insert_book_open
  on public.slots
  for insert
  to authenticated
  with check (
    booked_by = auth.uid()
    and publicly.providers.slot_is_open(id)
  );

-- R4: A patient may cancel only their own open booking
create policy slots_update_cancel_own_open
  on public.slots
  for update
  to authenticated
  using (
    booked_by = auth.uid()
    and publicly.providers.slot_is_open(id)
  )
  with check (
    booked_by is null
    or publicly.providers.slot_is_open(id)
  );

-- R5: No INSERT/UPDATE/DELETE policies for anon, no change of provider_id,
-- no writeable columns beyond booked_by / starts_at.
revoke all on public.providers from anon;
revoke all on public.slots from anon;

revoke insert, update, delete on public.providers from authenticated;
revoke insert, update, delete on public.slots from authenticated;

