grant select, insert, update on public.slots to authenticated;
grant usage, select on sequence public.providers_user_id_seq to authenticated;
grant usage, select on sequence public.slots_id_seq to authenticated;

-- R6: nothing for anon at all
revoke all on public.providers from public;
revoke all on public.slots from public;
