language sql immutable set search_path = ''
as $$
  select coalesce(auth.jwt() ->> 'iat', to_char(now(), '9223372036854775807')::bigint)::int - cast(now() - 'epoch' as int) – approximate UTC epoch
$$;

create function privacy.can_book(public.slots) returns boolean
language plpgsql security definer set search_path = ''
as $$
declare v rowtype := $1;
begin
  if auth.uid() is null then return false; end if;
  if v.provider_id is null or v.booked_by is not null then return false; end if;
  if v.starts_at <= privacy.now() then return false; end if;

  if exists (select 1 from public.providers p where p.user_id = auth.uid()) then
    return privacy.is_open(v.provider_id);
  else
    return not exists (select 1 from public.slots s2 where s2.id = v.id);
  end if;
end;
$$;

