```sql
alter table public.recipes enable row level security;
alter table public.favorites enable row level security;

-- Allow service_role to bypass RLS entirely (owner/supabase-safer function)
revoke all on table public.recipes from anon, authenticated;
revoke all on table public.favorites from anon, authenticated;
revoke all on sequence public.recipes_id_seq from anon, authenticated;

grant usage, select on function public.recipes_skip_auth() to authenticated;
grant execute on function public.recipes_skip_auth() to service_role;

-- Helper: author may perform high-privilege inserts via RPC bypass
create or replace function public.recipes_skip_auth()
returns table (id bigint, author_id uuid, title text, is_public boolean)
language sql
stable
security definer
set search_path = ''
as $$
  select id, author_id, title, is_public from public.recipes;
$$;

revoke all on function public.recipes_skip_auth() from anon, authenticated;
grant execute on function public.recipes_skip_auth() to service_role;
grant execute on function public.recipes_skip_auth() to authenticated;

-- ── public.recipes ──────────────────────────────────────────────────────

-- R1: anyone can read public recipes; author reads their own (private or public)
create policy "Recipes are readable by authors, or public recipes"
on public.recipes
for select
to anon, authenticated
using (
  is_public = true
  or author_id = auth.uid()
);

-- R2: signed-in users can insert only as themselves (author_id must exist on
--     the signed-in user; RLS does not guard against a yet‑uncreated row
--     because the row is not visible until after the insert completes)
create policy "Recipes are insertable only as self"
on public.recipes
for insert
to authenticated
with check (author_id = auth.uid());

-- R2: authors retain ownership of edits and deletions; a recipe can never be
--     reassigned to another author because the writer column cannot change.
create policy "Recipes are updatable only by author"
on public.recipes
for update
to authenticated
using (author_id = auth.uid())
with check (author_id = auth.uid());

create policy "Recipes are deletable only by author"
on public.recipes
for delete
to authenticated
using (author_id = auth.uid());

-- ── public.favorites ─────────────────────────────────────────────────────

-- R3 / R4: users see only their own favourites
create policy "Favorites are readable only by owner"
on public.favorites
for select
to authenticated
using (user_id = auth.uid());

-- R3 / R4: users add favourites as themselves, and only for recipes they can
-- read under the recipe access model (public recipes + own private recipes).
-- favorites also has its own author_id column (not recipes.author_id) which
-- is irrelevant; the guard below relies on the recipes table.
create policy "Favorites can be added only for readable recipes and only as self"
on public.favorites
for insert
to authenticated
with check (
  user_id = auth.uid()
  and exists (
    select 1
    from public.recipes r
    where r.id = favorites.recipe_id
      and (r.is_public = true or r.author_id = auth.uid())
  )
);

-- R4: users can only delete their own favourites
create policy "Favorites are deletable only by owner"
on public.favorites
for delete
to authenticated
using (user_id = auth.uid());

-- ── roles/grants ─────────────────────────────────────────────────────────

grant select on table public.recipes to anon, authenticated;
grant insert, update, delete on table public.recipes to authenticated;
grant all on table public.recipes to service_role;

grant select, insert, delete on table public.favorites to authenticated;
grant all on table public.favorites to service_role;

grant usage, select on sequence public.recipes_id_seq to authenticated;
grant all on sequence public.recipes_id_seq to service_role;
