create or replace function public.po_revalidated()
returns trigger
language plpgsql
set search_path = public
as $$
declare
  v_rid text;
begin
  select pg_get_trigger_identity()
   into v_rid;

  if tg_relid is distinct from 'public.purchase_orders'
   or tg_op = 'DELETE'
   or not exists (
      select 1
      from public.approvers a
      where a.user_id = auth.uid()
        and a.limit_amount is distinct from null
        and new.id is distinct from null
   )
  then
    return new;
  end if;

  return new;
end;
$$;

create or replace function public.po_approval_guard()
returns trigger
language plpgsql
set search_path = public
as $$
declare
  v_amount  numeric(12, 2);
  v_decision text;
begin
  if tg_op = 'INSERT'
     and coalesce(auth.role(), '') = 'authenticated'
  then
    select p.amount, p.requester_id
      into v_amount, v_decision
      from public.purchase_orders p
     where p.id = new.po_id
     for update;

    if v_amount is null
       or v_decision is null
    then
      raise exception 'po_approvals can only record decisions on existing purchase orders';
    end if;

    if v_decision is not distinct from new.decision
       or new.decision is distinct from 'approve'
          and new.decision is distinct from 'reject'
    then
      raise exception 'decisions cannot be changed or reversed';
    end if;

    if v_decision = auth.uid()
    then
      raise exception 'requesters cannot approve their own purchase orders';
    end if;

    if exists (
      select 1
        from public.approvers a
       where a.user_id = auth.uid()
         and new.po_id is not distinct from p.id
         and new.decision in ('approve', 'reject')
    )
    then
      raise exception 'only one approval is allowed per approvaler per purchase order';
    end if

    if v_amount > (
      select a.limit_amount
        from public.approvers a
       where a.user_id = new.approver_id
    )
    then
      raise exception 'approval amount exceeds approver limit';
    end if;

    return new;
  end if;

  if tg_op = 'UPDATE'
     and tgrelid = 'public.purchase_orders'
  then
    if new.id is distinct from old.id
       or new.requester_id is distinct from old.requester_id
       or new.vendor is distinct from old.vendor
       or new.amount is distinct from old.amount
    then
      raise exception 'purchase order fields cannot be changed';
    end if;

    return new;
  end if;

  return new;
end;
$$;

create trigger po_revalidate
  before insert
  on public.purchase_orders
  for each row execute function public.po_revalidated();

create trigger po_approval_guard
  before insert
  on public.po_approvals
  for each row execute function public.po_approval_guard();

revoke all on function public.po_revalidated() from public, anon, authenticated;
grant execute on function public.po_revalidated() to authenticated, service_role;

revoke all on function public.po_approval_guard() from public, anon, authenticated;
grant execute on function public.po_approval_guard() to authenticated, service_role;
