create or replace function public.items_tenant_guard_to_own_or_shared_unexpired()
returns trigger
language plpgsql
as $$
declare
  v_tenant text := public.current_tenant();
  v_role text := public.current_role();
  v_own_tenant text := (select tenant_id from public.items where id = new.id);
begin
  if v_role = 'admin' and v_own_tenant = v_tenant then
    return new;
  end if;
  if v_role = 'member' and v_own_tenant = v_tenant and new.tenant_id = v_tenant then
    return new;
  end if;
  raise exception 'item % is owned by tenant % or lacks access guard', new.id, new.tenant_id using errcode = 'check_violation';
end;
$$;

create or replace function public.item_shares_tenant_guard()
returns trigger
language plpgsql
as $$
declare
  v_tenant text := public.current_tenant();
  v_role text := public.current_role();
  v_for_tenant text := (select tenant_id from public.items where id = new.item_id);
begin
  if new.target_tenant not in ('public')
  and not exists (
    select 1
    from public.items i
    where i.id = new.item_id
      and i.tenant_id = v_tenant
  ) then
    raise exception 'item % is not in a known tenant', new.item_id using errcode = 'check_violation';
  end if;

  if v_role = 'admin' and v_for_tenant = v_tenant then
    return new;
  end if;

  if new.target_tenant = v_tenant then
    raise exception 'only admins of % can share this item', v_for_tenant using errcode = 'check_violation';
  end if;

  raise exception 'share on item % for dedicated tenant % is not allowed', new.item_id, new.target_tenant using errcode = 'check_violation';
end;
$$;

