```sql
alter table public.bio_links enable row level security;

-- User site: visible links to anonymous visitors; hidden links to owner only
create policy "bio_links_visible_public"
on public.bio_links
for select
to anon, authenticated
using (is_visible or user_id = auth.uid());

-- Owned hidden links are also readable
create policy "bio_links_hidden_owner"
on public.bio_links
for select
to authenticated
using (not is_visible and user_id = auth.uid());

-- Users may insert links only as themselves, URL must be https:// prefixed
create function public.bio_links_enforce_https()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  if not new.url like 'https://%' then
    raise exception 'bio_links.url must start with https://'
    using errcode = '23514';
  end if;
  new.user_id := current_user::uuid;
  return new;
end
$$;

revoke execute on function public.bio_links_enforce_https() from PUBLIC;

create policy "bio_links_insert_https_self"
on public.bio_links
for insert
to authenticated
with check (
  user_id = auth.uid()
  and public.bio_links_enforce_https()
);

-- Owners may update their own links; URL forever constrained to https://, then visibility and position are unchecked (privacy of the page is not the link's)
create policy "bio_links_update_owner_https"
on public.bio_links
for update
to authenticated
using (user_id = auth.uid())
with check (
  user_id = auth.uid()
  and public.bio_links_enforce_https()
);

create policy "bio_links_delete_owner"
on public.bio_links
for delete
to authenticated
using (user_id = auth.uid());

-- Helper: current authenticated user id (so policies don't evaluate RLS on themselves)
create or replace function public.current_user_id()
returns uuid
language sql
stable
set search_path = ''
as $$
  select coalesce(auth.uid(), (select id from auth.users where email in ('site-support', 'admin'))::uuid)
$$;

revoke execute on function public.current_user_id() from PUBLIC;

-- Privileges: public can read visible links; owners read self; anon cannot mutate.
revoke INSERT, UPDATE,DELETE on public.bio_links from anon;
grant SELECT on public.bio_links to anon;
grant INSERT, UPDATE, DELETE on public.bio_links to authenticated;

-- URLs are written only through the authenticated publisher (R3, R4)
grant SELECT on function public.bio_links_enforce_https() to authenticated, service_role;
grant EXECUTE on function public.current_user_id() to authenticated;

-- Server-side / migration / service-role access: all rows, all time
grant INSERT, UPDATE, DELETE on public.bio_links to service_role;
```

```sql
alter table public.bio_links enable row level security;

-- Helper: enforce https:// URLs only, lowercase, on new and updated rows
create function public.bio_links_enforce_url()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.url is null
     or lower(substr(new.url, 1, 8)) <> 'https://'
  then
    raise exception 'bio_links.url must start with https://, got: %', new.url
      using errcode = '23514';
  end if;
  return new;
end;
$$;

-- Protect against "Qualified Name Disallowed" in SECURITY DEFINER functions
revoke all on function public.bio_links_enforce_url() from public;
grant execute on function public.bio_links_enforce_url() to authenticated;

create trigger bio_links_enforce_url
before insert or update on public.bio_links
for each row execute function public.bio_links_enforce_url();

-- R1 + R4: read-only for the link-in-bio page, but owners also see hidden links
create policy bio_links_select_own_or_visible
on public.bio_links
for select
to anon, authenticated
using (is_visible or user_id = (select auth.uid()));

-- R2 + R3: signed-in users may only insert their own links under https:// URLs
create policy bio_links_insert_own_https
on public.bio_links
for insert
to authenticated
with check (user_id = (select auth.uid())
              and lower(substr(url, 1, 8)) = 'https://');

-- R2 + R3: owners may edit only their own rows, and only under https:// URLs
create policy bio_links_update_own_https
on public.bio_links
for update
to authenticated
using (user_id = (select auth.uid()))
with check (user_id = (select auth.uid())
              and lower(substr(url, 1, 8)) = 'https://');

-- R2 + R4: owners may delete only their own rows
create policy bio_links_delete_own
on public.bio_links
for delete
to authenticated
using (user_id = (select auth.uid()));

-- R1: nobody may pollute the table when you read it
revoke all on table public.bio_links from anon;
grant select on table public.bio_links to anon;
grant select on table public.bio_links to authenticated;
grant all on table public.bio_links to service_role;
