create function public.is_team_member(p_team_id bigint)
returns boolean
language sql
stable
security invoker
set search_path = public
as $$
  select exists (
    select 1 from public.team_members
    where team_id = p_team_id and user_id = auth.uid()
  );
$$;

create function public.in_any_team()
returns boolean
language sql
stable
security invoker
set search_path = public
as $$
  select exists (
    select 1 from public.team_members
    where user_id = auth.uid()
  );
$$;

create function public.is_judge_of_event(p_event_id bigint)
returns boolean
language sql
stable
security invoker
set search_path = public
as $$
  select exists (
    select 1 from public.judges
    where event_id = p_event_id and user_id = auth.uid()
  );
$$;

create function public.submission_event_deadline(p_team_id bigint)
returns timestamptz
language sql
stable
security invoker
set search_path = public
as $$
  select e.deadline
  from public.teams t
  join public.events e on e.id = t.event_id
  where t.id = p_team_id
  limit 1;
$$;

create function public.submission_deadline_passed(p_team_id bigint)
returns boolean
language sql
stable
security invoker
set search_path = public
as $$
  select coalesce(public.submission_event_deadline(p_team_id) < now(), false);
$$;

create function public.submissions_set_deadline_or_error(p_team_id bigint)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_deadline timestamptz;
begin
  if auth.role() = 'service_role' then
    return;
  end if;

  select e.deadline into v_deadline
  from public.events e
  where exists (select 1 from public.teams t where t.event_id = e.id and t.id = p_team_id);

  if v_deadline is not null and v_deadline < now() then
    raise exception 'submission deadline has passed, edits are no longer allowed';
  end if;
end;
$$;

create trigger submissions_set_restriction_before_upsert
before insert or update on public.submissions
for each row execute function public.submissions_set_deadline_or_error(new.team_id);

create policy events_select_authenticated
on public.events
for select
to authenticated
using (true);

create policy teams_select_authenticated
on public.teams
for select
to authenticated
using (true);

