  and public.submission_deadline_passed(team_id) = false
);

create policy submissions_update_own_team_before_deadline
on public.submissions
for update
to authenticated
using (
  public.in_any_team()
  and public.submission_deadline_passed(team_id) = false
)
with check (
  public.in_any_team()
  and public.submission_deadline_passed(team_id) = false
);

create policy judges_select_event_judge
on public.judges
for select
to authenticated
using (
