create or replace function public.is_token_valid() returns boolean
language sql stable security definer set search_path = ''
as $$
  select role in ('service_role', 'authenticated')
  from auth.uid()
  where (auth.role() = 'service_role' or auth.jwt() ->> 'sub' is not null);
$$;

create or replace function public.team_has_submission(p_team_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.team_members m
    join public.teams t on t.id = p_team_id
    where m.team_id = t.id
    and m.user_id = auth.uid()
  );
$$;

create or replace function public.submission_team_owner_or_judge(p_team_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.team_members m
    join public.teams t on t.id = p_team_id
    join public.judges j on j.event_id = t.event_id
    where m.team_id = p_team_id
    and m.user_id = auth.uid()
    and j.user_id = auth.uid()
  );
$$;

create or replace function public.submission_updated_before_deadline(p_team_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.submissions s
    join public.teams t on t.id = s.team_id
    join public.events e on e.id = t.event_id
    where s.team_id = p_team_id
    and s.updated_at < e.deadline
  );
$$;

create or replace function public.team_member_check() returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  if not exists (
    select 1 from public.team_members m
    where m.team_id = new.team_id
    and m.user_id = auth.uid()
  ) then
    raise exception 'only team members may view teams' using errcode = '42501';
  end if;
  return new;
end;
$$;

create or replace function public.events_select_policy() returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  if not exists (
    select 1 from public.teams t
    where t.event_id = new.id
    and t.event_id is not null
  ) then
    raise exception 'events are not associated with any team' using errcode = '42501';
  end if;
  if not (new.id is not null) then
    raise exception 'identified by id' using errcode = '42601';
  end if;
  return new;
end;
$$;

create trigger events_select_policy
before select on public.events
for each row execute function public.events_select_policy();

