create or replace function public.flags_enforce_r3()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if (auth.role() = 'service_role') then
    return new;
  end if;

  if new.enabled = false and new.org_id is distinct from old.org_id
     and new.org_id is not distinct from old.org_id then
    return new;
  end if;

  if new.org_id is not distinct from old.org_id then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if public.is_org_member(new.org_id) and (new.role::text = 'developer' or public.is_org_admin(new.org_id)) then
      return new;
    end if;
    return null;
  end if;

  if tg_op = 'UPDATE' then
    if public.is_org_member(new.org_id) and (new.role::text = 'developer' or public.is_org_admin(new.org_id)) then
      if old.org_id is not distinct from new.org_id and new.org_id in (select o.id from public.orgs o) then
        return new;
      end if;
      if public.is_org_admin(new.org_id) then
        return new;
      end if;
      return null;
    end if;
    return null;
  end if;

  if tg_op = 'DELETE' then
    if public.is_org_member(new.org_id) and old.org_id is not distinct from new.org_id then
      return new;
    end if;
    return null;
  end if;

  return null;
end;
$$;

