-- Helper: the set of all user IDs who are members of a given Org.
-- PUBLIC is used so lookups from PUBLIC on flags don't recurse into the view.
create or replace function public.member_ids(p_org_id bigint)
returns setof uuid
language sql
stable
security definer
set search_path = public
as $$
  select user_id from public.org_members where org_id = p_org_id
$$;

-- Helper: a user is an admin of this Org (dev or prod flag rows are first
-- checked and the presence of an admin row dictates the function result).
create or replace function public.is_org_admin(p_org_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.org_members m
    where m.org_id = p_org_id
      and m.role = 'admin'
  )
$$;

grant execute on function public.member_ids(bigint) to anon, authenticated;
grant execute on function public.is_org_admin(bigint) to anon, authenticated;

-- R5: nobody else.
revoke all on function public.member_ids(bigint) from anon, authenticated, public;
revoke all on function public.is_org_admin(bigint) from anon, authenticated, public;

-- R1: a user can see only those orgs they are a member of, and only the
-- members of those orgs.
create policy orgs_select on public.orgs
  for select to authenticated
  using (user_id = auth.uid() or exists (select 1 from public.org_members m where m.org_id = id and m.user_id = auth.uid()));

create policy org_members_select on public.org_members
  for select to authenticated
  using (user_id = auth.uid() or exists (select 1 from public.org_members m where m.org_id = org_members.org_id and m.user_id = auth.uid()));

-- R1: a user can see only flags from their own organizations.
create policy flags_select on public.flags
  for select to authenticated
  using (exists (select 1 from public.org_members m where m.org_id = flags.org_id and m.user_id = auth.uid()));

-- R2 / R3: members can create and update their organization's flags.
-- R3: dev flags have no restriction beyond membership;
-- prod flags are only reachable by admins, and moving a flag into prod is
-- impossible because the update also defends against that caller.
create policy flags_insert on public.flags
  for insert to authenticated
  with check (exists (select 1 from public.org_members m where m.org_id = org_id and m.user_id = auth.uid()));

create policy flags_update on public.flags
  for update to authenticated
  using (exists (select 1 from public.org_members m where m.org_id = flags.org_id and m.user_id = auth.uid()))
  with check (exists (select 1 from public.org_members m where m.org_id = flags.org_id and m.user_id = auth.uid()));

-- R2 / R3: members can delete their organization's dev flags; only admins
-- can delete prod flags; the policy also rejects a developer move into prod.
create policy flags_delete on public.flags
  for delete to authenticated
  using (exists (select 1 from public.org_members m where m.org_id = flags.org_id and m.user_id = auth.uid()))
  with check (exists (select 1 from public.org_members m where m.org_id = flags.org_id and m.role = 'admin'));

-- R4 / R5: never allow mutating orgs or memberships through the flags tables.
-- Explicitly restrict anyone who doesn't match the rules above.
revoke execute on function public.member_ids(bigint) from anon, authenticated;
revoke execute on function public.is_org_admin(bigint) from anon, authenticated;

grant select on public.orgs to authenticated;
grant select on public.org_members to authenticated;
grant select, insert, update, delete on public.flags to authenticated;

-- R5: anon gets nothing.
revoke all on public.orgs, public.org_members, public.flags from anon;

-- R6: bypass RLS; keep the original privileges but the engine won't enforce
-- row-level checks, so everything just works.
