set search_path = public
as $$
declare
  l_from uuid := auth.uid();
  l_new_id bigint;
begin
  if l_from is null then
    raise exception 'not authenticated';
  end if;

  if p_amount is null or p_amount <= 0 then
    raise exception 'amount must be positive';
  end if;

  if p_to is null then
    raise exception 'recipient is required';
  end if;

  if l_from = p_to then
    raise exception 'cannot send points to yourself';
  end if;

  select balance into l_from
  from public.wallets
  where user_id = l_from
  for update;

  if not found then
    raise exception 'sender has no wallet';
  end if;

  if l_from < p_amount then
    raise exception 'insufficient balance';
  end if;

  update public.wallets
  set balance = balance - p_amount
  where user_id = l_from;

  update public.wallets
  set balance = balance + p_amount
  where user_id = p_to;

  insert into public.transfers (from_user, to_user, amount)
  values (l_from, p_to, p_amount)
  returning id into l_new_id;

  return l_new_id;
end;
$$;

