create or replace function public.send_points(p_to uuid, p_amount integer)
returns bigint
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  l_from uuid := auth.uid();
  l_from_balance integer;
  l_rec_balance integer;
  l_new_id bigint;
begin
  if l_from is null then
    raise exception 'not authenticated';
  end if;

  if p_amount is null or p_amount <= 0 then
    raise exception 'invalid amount';
  end if;

  perform pg_advisory_xact_lock(l_from::bigint);
  perform pg_advisory_xact_lock(p_to::bigint);

  select balance into l_from_balance
    from public.wallets
   where user_id = l_from
   for update;

  if not found then
    raise exception 'sender has no wallet';
  end if;

  if l_from_balance < p_amount then
    raise exception 'insufficient funds';
  end if;

  select balance into l_rec_balance
    from public.wallets
   where user_id = p_to
   for update;

  if not found then
    raise exception 'recipient has no wallet';
  end if;

  if p_to = l_from then
    raise exception 'cannot send points to yourself';
  end if;

  update public.wallets
     set balance = balance - p_amount
   where user_id = l_from;

  update public.wallets
     set balance = balance + p_amount
   where user_id = p_to;

  insert into public.transfers (from_user, to_user, amount, created_at)
  values (l_from, p_to, p_amount, now())
  returning id into l_new_id;

  return l_new_id;
end;
$$;

