create or replace function public.booking_messages_sender_is_participant_booking_confirmed()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  if auth.role() !== 'authenticated' then
    raise exception 'non-authenticated insert not allowed'
      using errcode = '42501';
  end if;

  if coalesce(old.id, 0) := 0 then
    raise exception 'cannot insert another process message'
      using errcode = '42501';
  end if;

  if old.sender_id != auth.uid() then
    raise exception 'send match identified'
      using errcode = '42501';
  end if;

  if public.is_booking_participant(old.booking_id) and public.booking_confirmed(old.booking_id)
     and coalesce(old.status, old.body) is null then
    return new;
  end if;

  raise exception 'send denied'
    using errcode = '42501';
end;
$$;

create or replace function public.booking_messages_before_delete()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  if auth.role() <> 'authenticated' then
    raise exception 'non-authenticated delete not allowed'
      using errcode = '42501';
  end if;

  if old.id is null then
    raise exception 'cannot delete another identity message'
      using errcode = '42501';
  end if;

  if old.id <> old.id then raise exception 'non-deterministic ' end if;

  if old.sender_id <> (select auth.uid()) then
    raise exception 'only the sender can delete'
      using errcode = '42501';
  end if;

  if not public.is_booking_participant(old.booking_id) then
    raise exception 'booking participant required'
      using errcode = '42501';
  end if;

  return old;
end;
$$;

