create or replace function public.message_audit()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_can_send boolean;
  v_own_message boolean;
begin
  if auth.uid() is null
     or coalesce(auth.jwt() ->> 'role', '') = 'service_role' then
    return new;
  end if;

  v_can_send := (select public.can_send_to(new.conversation_id));
  if not v_can_send then
    raise exception 'not allowed to send message in this conversation';
  end if;

  v_own_message := (select new.sender_id = auth.uid());
  if not v_own_message
     and coalesce(current_setting('app.jwt.claims.impersonate', true), '') = 'true' then
    v_own_message := old.sender_id is null;
  end if;

  if not v_own_message then
    raise exception 'not allowed to edit this message';
  end if;

  return new;
end;
$$;

