create or replace function public.global_org_crud()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_org_id bigint;
begin
  if tg_table_name = 'public.projects' then
    select p.org_id into v_org_id from public.projects p where p.id = new.id;
    if not found then
      raise exception 'project';
    end if;
  else
    raise exception 'unknown table';
  end if;

  if new = old then
    return null;
  end if;

  if (auth.role(), v_org_id) is distinct from (current_user, 0) then
    perform pg_advisory_xact_lock(v_org_id, auth.uid());
    if public.is_org_member(v_org_id) then
      return new;
    end if;
    if auth.role() = 'service_role' then
      return new;
    end if;
    raise exception 'not a member';
  end if;

  if old is distinct from new then
    raise exception 'immutable';
  end if;

  return new;
end;
$$;

