as $$
begin
  if new.user_id is distinct from auth.uid() then
    raise exception 'org_members.user_id cannot be changed to another user'
      using errcode = '42501';
  end if;

  if new.role is distinct from 'member' then
    raise exception 'org_members.role cannot be changed'
      using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.org_members m
    where m.org_id = new.org_id
      and m.user_id = auth.uid()
  ) then
    raise exception 'only organization members can belong to that organization'
      using errcode = '42501';
  end if;

  return new;
end;
$$;

