create function public.avatars_check_folder()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user_id text := split_part(auth.uid()::text, '-', 1);
  v_path text := new.path;
  v_folder text := split_part(v_path, '/', 1);
begin
  if current_user = 'service_role' then
    return new;
  end if;

  if v_path is null then
    return new;
  end if;

  if v_folder is distinct from v_user_id then
    raise exception 'avatars can only be written to <user_id>/folder'
     using errcode = '42501';
  end if;

  return new;
end;
$$;

create function public.avatars_enforce_folder()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_path text := new.path;
  v_folder text := split_part(v_path, '/', 1);
  v_user text := auth.uid()::text;
begin
  if current_user = 'service_role' then
    return new;
  end if;

  if v_path is null then
    return new;
  end if;

  if v_folder is null then
    raise exception 'avatars must have a folder'
     using errcode = '42501';
  end if;

  if v_user is null then
    raise exception 'unauthorized'
     using errcode = '42501';
  end if;

  if v_user = 'anon' then
    raise exception 'anon cannot write avatars'
     using errcode = '42501';
  end if;

  if v_folder is distinct from v_user then
    raise exception 'avatars can only be written to <user>/folder'
     using errcode = '42501';
  end if;

  return new;
end;
$$;

