```sql
alter table public.push_tokens enable row level security;

create or replace function public.push_tokens_is_own(p_user_id uuid)
returns boolean
language sql
stable
security invoker
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.push_tokens p
    where p.token = public.push_tokens.token
      and p.user_id = p_user_id
  );
$$;

create or replace function public.push_tokens_check_ownership()
returns trigger
language plpgsql
security invoker
set search_path = public, pg_temp
as $$
begin
  if new.token is null or new.user_id is null then
    raise exception 'push_tokens.token and push_tokens.user_id cannot be null';
  end if;

  if new.token = old.token and new.user_id is distinct from old.user_id then
    raise exception 'a push token registered to another user cannot be reassigned';
  end if;

  if public.push_tokens_is_own(auth.uid()) then
    return new;
  end if;

  raise exception 'push tokens can only be modified for yourself';
end;
$$;

create or replace function public.push_tokens_valid_platform()
returns trigger
language plpgsql
security invoker
set search_path = public, pg_temp
as $$
begin
  if new.platform is distinct from old.platform then
    if new.platform is null or old.platform is null then
      raise exception 'push_tokens.platform cannot be null';
    end if;

    if new.platform not in ('ios', 'android', 'web') then
      raise exception 'invalid push token platform';
    end if;
  end if;

  return new;
end;
$$;

