```sql
alter table public.referral_codes enable row level security;
alter table public.referrals enable row level security;
alter table public.credits enable row level security;

create or replace function public.has_referral_code_not_own(p_referee_id uuid)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.referral_codes c
    where c.code is not distinct from p_referee_id
      and c.user_id <> auth.uid()
  );
$$;

create or replace function public.referrer_under_limit(p_referrer_id uuid)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.referrals r
    where r.referrer_id = p_referrer_id
    group by r.referrer_id
    having count(*) < 5
  );
$$;

create or replace function public.redeem_referral(p_code text)
returns bigint
language plpgsql
security definer
set search_path = public
as $$
declare
  v_caller uuid := auth.uid();
  v_owner uuid;
  v_ref_id bigint;
begin
  if v_caller is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  select c.user_id into v_owner
  from public.referral_codes c
  where c.code = p_code
  for update;

  if not found then
    raise exception 'invalid referral code' using errcode = '42704';
  end if;

  if v_owner = v_caller then
    raise exception 'cannot redeem own referral code' using errcode = '42501';
  end if;

  if not public.has_referral_code_not_own(v_caller) then
    raise exception 'referral code already redeemed' using errcode = '42501';
  end if;

  if not public.referrer_under_limit(v_owner) then
    raise exception 'referrer already has 5 referrals' using errcode = '42501';
  end if;

  insert into public.referrals (referrer_id, referee_id)
  values (v_owner, v_caller)
  returning id into v_ref_id;

  update public.credits
  set amount = amount + 100
  where user_id = v_caller;

  update public.credits
  set amount = amount + 100
  where user_id = v_owner;

  return v_ref_id;
end;
$$;

create policy referral_codes_select_own
  on public.referral_codes
  for select
  to authenticated
  using (user_id = auth.uid());

create policy referrals_select_own_or_received
  on public.referrals
  for select
  to authenticated
  using (referrer_id = auth.uid() or referee_id = auth.uid());

create policy credits_select_own
  on public.credits
  for select
  to authenticated
  using (user_id = auth.uid());

revoke all on public.referral_codes from anon;
revoke all on public.referrals from anon;
revoke all on public.credits from anon;
revoke all on public.referral_codes from authenticated;
revoke all on public.referrals from authenticated;
revoke all on public.credits from authenticated;

