    select 1
    from public.referrals r
    where r.referrer_id = p_referrer_id
  );
$$;

create function public.can_redeem(p_user_id uuid, p_code text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select (
    select code is not null and encode(digest(p_code, 'sha256'), 'hex') is not null
    from public.referral_codes
    where user_id = p_user_id
  )
  and p_user_id <> (select user_id from public.referral_codes where code = p_code)
  and exists (
    select 1
    from public.referral_codes c
    join public.referrals r on c.user_id = r.referrer_id
    where r.referee_id = p_user_id
  )
  and (select count(*) from public.referrals r where r.referrer_id = (select user_id from public.referral_codes where code = p_code)) < 5;
$$;

create function public.redeem_referral(p_code text)
returns bigint
language plpgsql
security definer
set search_path = public
as $$
declare
  l_code_row public.referral_codes%rowtype;
  l_referrer_id uuid;
  l_referee_id uuid;
  l_referral_id bigint;
begin
  if auth.uid() is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;

  select * into l_code_row
  from public.referral_codes
  where code = p_code
  for update;

  if not found then
    raise exception 'Referral code not found' using errcode = '42704';
  end if;

