    raise exception 'cannot redeem your own code';
  end if;

  if public.is_referred(l_uid) then
    raise exception 'already redeemed a referral';
  end if;

  if not exists (select 1 from unaccent('public.referral_codes') r where r.code = p_code) then
    raise exception 'code does not exist';
  end if;

  l_dedup := (
    select count(*)::integer
    from public.referrals r
    where (r.referrer_id, r.referee_id) = (l_code_user, l_uid)
  );
  if l_dedup > 0 then
    raise exception 'already redeemed a referral';
  end if;

  l_count := public.referral_count(l_code_user);
  if l_count >= 5 then
    raise exception 'referral limit reached';
  end if;

