  values (l_code_user, l_uid)
  returning id into l_ref;

  insert into public.credits (user_id, amount, reason)
  values (l_uid, 100, 'referral bonus')
  on conflict do nothing;

  insert into public.credits (user_id, amount, reason)
  values (l_code_user, 100, 'referral reward')
  on conflict do nothing;

  return l_ref;
end;
$$;

