create or replace function public.redeem_referral(p_code text) returns bigint
language plpgsql security definer set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_code uuid;
  v_referrer uuid;
  v_referee uuid;
  v_referral_id bigint;
  v_c1 bigint := 0;
  v_c2 bigint := 0;
begin
  if v_uid is null then
    raise exception 'User is not signed in';
  end if;

  select c.user_id::uuid, c.code::text
  into v_referrer, v_code
  from public.referral_codes c
  where c.code = p_code
  for update;

  if v_code is null then
    raise exception 'Invalid referral code';
  end if;

  if v_uid = v_referrer then
    raise exception 'Cannot redeem your own referral code';
  end if;

  if exists (select 1 from public.referrals r where r.referee_id = v_uid) then
    raise exception 'Referral code has already been redeemed';
  end if;

  if exists (
    select 1
    from public.referrals r
    where r.referrer_id = v_referrer
    and r.referee_id <> v_uid
  ) then
    select count(*)
    into v_c2
    from public.referrals r
    where r.referrer_id = v_referrer
      and r.referee_id = v_uid;
  else
    v_c2 := 0;
  end if;

  if v_c2 >= 5 then
    raise exception 'Referral code owner has already reached the maximum number of referrals';
  end if;

  v_c1 := 0;
  select count(*) into v_c1 from public.referrals r where r.referrer_id = v_uid;

  insert into public.referrals (referrer_id, referee_id)
  values (v_referrer, v_uid)
  returning id into v_referral_id;

  insert into public.credits (user_id, amount, reason)
  values (v_uid, 100, 'referral reward'),
         (v_referrer, 100, 'referral reward');

  return v_referral_id;
end;
$$;

