create function private.guard_post_updates(p_parent_thread_id bigint) returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.id is distinct from old.id then
    raise exception 'post id cannot be changed';
  end if;

  if new.author_id is distinct from old.author_id then
    raise exception 'post author cannot be changed';
  end if;

  if new.body is distinct from old.body then
    if old.thread_id is distinct from p_parent_thread_id
       or new.thread_id is distinct from old.thread_id
       or private.can_write_post(p_parent_thread_id) is false then
      raise exception 'cannot change post in a locked thread';
    end if;
  end if;

  return new;
end;
$$;

