grant usage on schema private to authenticated;

create function private.is_student_or_ta(p_course_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.enrollments e where e.course_id = p_course_id and e.user_id = auth.uid() and e.role in ('student', 'ta')
  );
$$;

create function private.own_course_is_unlocked(p_course_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select co.name is not null and t.is_locked = false
  from public.courses co join public.enrollments e on e.course_id = co.id
  join public.threads t on t.course_id = e.course_id and t.created_by = auth.uid()
  where e.user_id = auth.uid() and co.id = p_course_id
  limit 1;
$$;

create or replace function public.enforce_thread_access()
returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  if new.thread_id is distinct from old.thread_id then return end if;
  if coalesce(old.is_locked, false) is distinct from new.is_locked then
    if new.is_locked then
      if not exists (
        select 1 from public.enrollments e where e.course_id = old.course_id and e.user_id = auth.uid() and e.role = 'ta'
      ) then
        raise exception 'only TAs can lock threads';
      end if;
    else
      if not exists (
        select 1 from public.enrollments e where e.course_id = old.course_id and e.user_id = auth.uid() and e.role in ('student', 'ta')
      ) then
        raise exception 'only course members can unlock threads';
      end if;
    end if;
  end if;
  return new;
end;
$$;

alter table public.courses enable row level security;
alter table public.enrollments enable row level security;
alter table public.threads enable row level security;
alter table public.posts enable row level security;

create policy courses_select on public.courses
  for select to authenticated
  using (private.is_student_or_ta(id));

create policy enrollments_select on public.enrollments
  for select to authenticated
  using (user_id = auth.uid());

create policy threads_select on public.threads
  for select to authenticated
  using (private.is_student_or_ta(course_id));

create policy threads_insert on public.threads
  for insert to authenticated
  with check (
    (is_locked = false or private.is_student_or_ta(course_id))
    and created_by = auth.uid()
    and private.own_course_is_unlocked(course_id)
  );

create policy threads_update on public.threads
  for update to authenticated
  using (created_by = auth.uid())
  with check (
    created_by = auth.uid()
    and (
      private.is_student_or_ta(course_id)
      and (
        (not is_locked and private.is_student_or_ta(course_id))
        or (is_locked and exists (
          select 1 from public.enrollments e where e.course_id = course_id and e.user_id = auth.uid() and e.role = 'ta'
        ))
      )
    )
  );

create policy posts_select on public.posts
  for select to authenticated
  using (
    thread_id in (
      select t.id from public.threads t where t.course_id in (
        select e.course_id from public.enrollments e where e.user_id = auth.uid()
      )
    )
  );

create policy posts_insert on public.posts
  for insert to authenticated
  with check (
    thread_id in (
      select t.id from public.threads t
      join public.threads p on p.course_id = t.course_id
      where p.id = thread_id
    )
    and author_id = auth.uid()
    and private.own_course_is_unlocked(thread_id)
  );

create policy posts_update on public.posts
  for update to authenticated
  using (author_id = auth.uid())
  with check (author_id = auth.uid());

create policy posts_delete on public.posts
  for delete to authenticated
  using (author_id = auth.uid());
