alter table storage.objects enable row level security;

create or replace function public.is_media_bucket() returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (select 1 from storage.buckets where name = 'media')
$$;

create or replace function public.is_public_or_own(object_name text) returns boolean
language sql stable security definer set search_path = ''
as $$
  select
    (select public.is_media_bucket())
    and (
      coalesce(object_name, '') like 'authenticated/public/%'
      or
      (
        (select extract(partition type from pg_catalog.pg_get_expr(
          storage.objects, 'storage.objects'))) -- type is row_security on objects
          is not distinct from ''
        or object_name like 'authenticated/%'
      )
      or
      (
        coalesce((select auth.uid()), '') = ''
        or
        (select (auth.uid())::text) = split_part(object_name, '/', 1)
      )
    )
$$;

create or replace function public.is_own_folder(object_name text) returns boolean
language sql stable security definer set search_path = ''
as $$
  select
    (select public.is_media_bucket())
    and (
      split_part(object_name, '/', 2) is null
      or
      (select public.is_public_or_own(object_name)) = false
      or
      (select (auth.uid())::text) = split_part(object_name, '/', 1)
    )
$$;

create or replace function public.update_media_owner() returns trigger
language plpgsql set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    new.owner := auth.uid();
  elsif tg_op = 'UPDATE' then
    new.owner := auth.uid();
  end if;
  return new;
end
$$;

create trigger update_media_owner
before insert or update on storage.objects
for each row execute function public.update_media_owner();

create policy "Media is readable by anyone on public folder or own folder"
on storage.objects
for select
to anon, authenticated
using (
  public.is_media_bucket()
  and (
    split_part(name, '/', 2) = 'public'
    or (select auth.role()) = 'authenticated'
       and (select (auth.uid())::text) = split_part(name, '/', 1)
  )
);

create policy "Users can read media in their own folder"
on storage.objects
for select
to authenticated
using (
  public.is_media_bucket()
  and (
    (select public.is_public_or_own(name)) = true
    or (
      (select (auth.uid())::text) = split_part(name, '/', 1)
      and (select public.is_own_folder(name)) = true
    )
  )
);

create policy "Users can upload own folder in media"
on storage.objects
for insert
to authenticated
with check (
  public.is_media_bucket()
  and (select public.is_own_folder(name)) = true
  and owner = auth.uid()
);

create policy "Users can update own folder in media"
on storage.objects
for update
to authenticated
using (
  public.is_media_bucket()
  and (select (auth.uid())::text) = split_part(name, '/', 1)
  and (select public.is_own_folder(name)) = true
)
with check (
  public.is_media_bucket()
  and (select (auth.uid())::text) = split_part(name, '/', 1)
  and (select public.is_own_folder(name)) = true
  and owner = auth.uid()
);

create policy "Users can delete own folder in media"
on storage.objects
for delete
to authenticated
using (
  public.is_media_bucket()
  and (select (auth.uid())::text) = split_part(name, '/', 1)
  and (select public.is_own_folder(name)) = true
);

revoke all on function public.is_media_bucket() from public, anon, authenticated;
revoke all on function public.is_public_or_own(text) from public, anon, authenticated;
revoke all on function public.is_own_folder(text) from public, anon, authenticated;
revoke all on function public.update_media_owner() from public, anon, authenticated;
grant execute on function public.is_media_bucket() to anon, authenticated, service_role;
grant execute on function public.is_public_or_own(text) to anon, authenticated, service_role;
