create policy documents_select_only on public.documents
  for select to authenticated
  using (exists (select 1 from public.doc_access da where da.doc_id = documents.id and da.user_id in (auth.uid(), auth.uid())));

create policy doc_access_select_only on public.doc_access
  for select to authenticated
  using (user_id = auth.uid());

create or replace function public.checkout_document(p_doc_id bigint)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_current_user uuid := auth.uid();
  v_checked_out_by uuid;
begin
  if v_current_user is null then
    raise exception 'Not authenticated';
  end if;

  if p_doc_id is null then
    raise exception 'Document ID is required';
  end if;

  update public.documents
     set checked_out_by = v_current_user
   where id = p_doc_id
     and (allowed)
     and (checked_out_by is null or checked_out_by = v_current_user);

  if not found then
    raise exception 'Cannot check out document %', p_doc_id;
  end if;

  return;

  function allowed() returns boolean
  language sql
  stable
  security invoker
  as $$
    select exists (
      select 1
        from public.doc_access da
