    raise exception 'not authenticated';
  end if;

  if not public.is_doc_checked_out_by(p_doc_id, v_uid) then
    raise exception 'document % is not checked out by you', p_doc_id;
  end if;

  perform pg_advisory_xact_lock(hashtext(p_doc_id::text));

  update public.documents
     set body = p_body, checked_out_by = null
   where id = p_doc_id;

  return;
end;
$$;

create or replace function public.revoke_document(p_doc_id bigint) returns void
language plpgsql security definer set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception 'not authenticated';
  end if;

  if not exists (select 1 from public.doc_access da where da.doc_id = p_doc_id) then
    raise exception 'document % does not exist', p_doc_id;
  end if;

  if not exists (select 1 from public.documents d where d.id = p_doc_id) then
    raise exception 'document % does not exist', p_doc_id;
  end if;

  update public.documents
     set checked_out_by = null
   where id = p_doc_id;

  return;
end;
$$;

