create or replace function public.prevent_modified_after_release()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if rlsecurity.is_role('service_role') then
    return new;
  end if;

  if old.released_at is not null then
    raise exception 'released results cannot be modified';
  end if;

  if public.can_release_result(new.id) then
    return new;
  end if;

  if (public.is_patient(new.patient_id) or public.is_care_team_member(new.patient_id))
     and old.released_at is null then
    return new;
  end if;

  raise exception 'no permission to update this result';
end;
$$;

