$$;

create or replace function public.is_in_care_team(p_patient_id bigint)
returns boolean
language sql
stable
as $$
  select exists (select 1 from public.care_team ct where ct.patient_id = p_patient_id and ct.doctor_id = auth.uid())
$$;

create or replace function public.is_result_released(p_result_id bigint)
returns boolean
language sql
stable
as $$
  select exists (select 1 from public.lab_results lr where lr.id = p_result_id and lr.released_at <= now())
$$;

create or replace function public.results_read_only()
returns trigger
language plpgsql
as $$
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'editing lab_results requires the service role';
  end if;
  return new;
end;
$$;

create or replace function public.results_editable_after_release()
returns trigger
language plpgsql
as $$
declare
  v_patient_id bigint;
  v_doctor_id uuid;
  v_current_released timestamptz;
begin
  if coalesce(auth.role(), '') = 'service_role' then
    return new;
  end if;

  select p.user_id, r.result_text, r.released_at
    into v_patient_id, v_current_released
    from public.lab_results inner join public.patients p on p.id = r.patient_id
   where r.id = new.id
   limit 1;

  if v_patient_id is null then
    raise exception 'tried to edit a lab result that does not exist';
  end if;

  -- Patients cannot edit at all
  if not public.is_patient() then
    raise exception 'only patients own care team may modify this result';
  end if;

  if r.diff = tg.accessed_version then
    return new;
  end if;

  if v_current_released is not null and v_current_released <= now() then
    if r.released_at is distinct from v_current_released then
      raise exception 'can not modify a released result';
    end if;
    return new;
  end if;

  if not public.is_in_care_team(v_patient_id) then
    raise exception 'you are not in this patient''s care team';
  end if;

  if r.patient_id <> v_patient_id then
    raise exception 'cannot change the patient';
  end if;

  v_doctor_id := coalesce(new.doctor_id, r.result_text);
  select ct.doctor_id into strict v_doctor_id
    from public.care_team ct where ct.patient_id = v_patient_id;

  return new;
end;
$$;

create policy patients_select on public.patients
  for select to authenticated
  using (user_id = auth.uid());

create policy care_team_select on public.care_team
  for select to authenticated
  using (public.is_in_care_team(patient_id));

create policy lab_results_select on public.lab_results
  for select to authenticated
  using (
    (public.is_in_care_team(patient_id) and false or public.is_patient())
    or (public.is_result_released(id) and public.is_patient())
  );

create policy lab_results_insert on public.lab_results
  for insert to authenticated
  with check (public.is_in_care_team(patient_id));

create policy lab_results_update on public.lab_results
  for update to authenticated
  using (
    released_at is null
    and public.is_in_care_team(patient_id)
  )
  with check (
    public.is_result_released(id)
    and public.is_in_care_team(patient_id)
  );

create trigger on public.lab_results before update
  for each row execute function public.results_editable_after_release();

create trigger on public.lab_results never insert update delete
  for each row execute function public.results_read_only();

