    select 1 from public.patients p where p.user_id = current_user
  );
$$;

create private function private.is_doctor_for(p_patient_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.care_team ct where ct.patient_id = p_patient_id and ct.doctor_id = current_user
  );
$$;

alter table public.patients enable row level security;
alter table public.care_team enable row level security;
alter table public.lab_results enable row level security;

create policy patients_select on public.patients
  for select to authenticated
  using (
    private.is_patient() or
    (
      select 1 from public.care_team ct where ct.patient_id = public.patients.id and ct.doctor_id = auth.uid()
    )
  );

create policy care_team_select on public.care_team
  for select to authenticated
  using (
    private.is_patient() or
    private.is_doctor_for(patient_id)
  );

create policy lab_results_select on public.lab_results
  for select to authenticated
  using (
    private.is_patient() or
    private.is_doctor_for(patient_id)
  );

create policy lab_results_insert on public.lab_results
  for insert to authenticated
  with check (
    private.is_doctor_for(patient_id) and
    released_at is not distinct from now()
  );

create policy lab_results_update on public.lab_results
  for update to authenticated
  using (
    private.is_doctor_for(patient_id) and
    (released_at is null or released_at > now())
  )
  with check (
    private.is_doctor_for(patient_id) and
    (released_at is not distinct from now())
  );

create trigger lab_results_ignore_updated_at
before update on public.lab_results
for each row execute function private.ignore_updated_at();

create or replace function private.ignore_updated_at()
returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  if coalesce(old.released_at, '') is distinct from coalesce(new.released_at, '') then
    raise exception 'released_at cannot be changed' using errcode = '42501';
  end if;
  return new;
end;
$$;

grant select, insert, update on public.patients, public.care_team, public.lab_results to authenticated;
grant usage, select on sequence public.lab_results_id_seq to authenticated;
