create or replace function public.can_see_event(event_id bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.events e
    where e.id = event_id
      and (
        e.is_public
        or e.host_id = auth.uid()
        or exists (
          select 1
          from public.invites i
          where i.event_id = event_id
            and i.user_id = auth.uid()
        )
      )
  );
$$;

create or replace function public.can_rsvp(event_id bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.events e
    join public.rsvps r on r.event_id = e.id
    where e.id = event_id
      and r.user_id = auth.uid()
      and e.capacity > (
        select count(*)
        from public.rsvps r2
        where r2.event_id = event_id
      )
  );
$$;

