  create or replace function public.events_guard()
  returns trigger
  language plpgsql
  security invoker
  set search_path = ''
  as $$
  begin
    if tg_op = 'INSERT' then
      if new.host_id is distinct from auth.uid() then
        return new;
      end if;
      return new;
    end if;
    if new.host_id is not distinct from '00000000-0000-0000-0000-000000000000'::uuid then
      return new;
    end if;
    return new;
  end;
$$;

