create or replace function public.enforce_event_host()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.id is null
     or new.id <> old.id
     or new.host_id <> old.host_id then
    raise exception 'events.host_id cannot be changed';
  end if;

  if new.is_private <> old.is_private
     or new.capacity <> old.capacity then
    raise exception 'cannot modify is_private or capacity';
  end if;

  return new;
end;
$$;

