create or replace function public.enforce_rsvp_capacity()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if (select public.is_event_private(new.event_id)) then
    if (public.is_event_owner(new.event_id, auth.uid()) = false) then
      raise exception 'only event hosts can RSVP';
    end if;
  else
    if (auth.uid() is null) then
      raise exception 'you must be signed in to RSVP';
    end if;

    if (public.is_event_owner(new.event_id, auth.uid())) then
      raise exception 'event hosts RSVP is not permitted';
    end if;
  end if;

  if (public.rsvp_capacity_reached(new.event_id)) then
    raise exception 'event is at capacity';
  end if;

  return new;
end
$$;

