-- Helper: only a moderator has the "supa" double-claim in their JWT.
create or replace function public.is_moderator()
returns boolean
language sql
immutable
as $$
  select coalesce((select auth.jwt() ->> 'role' = 'moderator'), false);
$$;

-- R1: anyone (including anon) can read every note.
create policy "board_notes_select_all"
on public.board_notes
for select
to anon, authenticated
using (true);

-- R2: signed-in users can post as themselves.
create policy "board_notes_insert_authenticated_author"
on public.board_notes
for insert
to authenticated
with check (author_id = auth.uid());

-- R3 + R4 + R5:
create policy "board_notes_update_author_or_moderator"
on public.board_notes
for update
to authenticated
using (
  author_id = auth.uid()
  or public.is_moderator()
)
with check (
  (author_id = auth.uid() and is_pinned = false)
  or public.is_moderator()
);

create policy "board_notes_delete_author_or_moderator"
on public.board_notes
for delete
to authenticated
using (
  author_id = auth.uid()
  or public.is_moderator()
);

-- R3 (fine-grained enforcement): authors may never set is_pinned.
create or replace function public.board_notes_enforce_pin()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if coalesce(auth.role(), '') <> 'service_role'
     and new.is_pinned is distinct from old.is_pinned
  then
    raise exception 'only moderators can change is_pinned';
  end if;

  if coalesce(auth.role(), '') = 'service_role' or auth.uid() is null then
    return new;
  end if;

  if new.author_id is distinct from old.author_id then
    raise exception 'authors cannot change author_id';
  end if;

  if coalesce(auth.jwt() ->> 'role', '') <> 'service_role'
     and new.author_id is distinct from auth.uid() then
    raise exception 'only the author or a moderator can update this note';
  end if;

  return new;
end;
$$;

create trigger board_notes_enforce_pin_trigger
before update or insert or delete on public.board_notes
for each row
execute function public.board_notes_enforce_pin();

-- R2 / R5: rows added without an author_id are attributed to the caller.
create or replace function public.board_notes_default_author()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if coalesce(auth.role(), '') = 'service_role' then
    return new;
  end if;

  if new.author_id is null then
    new.author_id := auth.uid();
  end if;

  return new;
end;
$$;

create trigger board_notes_default_author_trigger
before insert on public.board_notes
for each row execute function public.board_notes_default_author();

