```sql
alter table public.board_notes enable row level security;

-- Helper: does this user currently have the moderator role?
create or replace function public.is_moderator()
returns boolean
language sql
stable
set search_path = public, pg_temp
as $$
  select auth.role() = 'service_role'
     or auth.jwt() ->> 'role' = 'moderator';
$$;

-- Helper: is the current author of this note?
create or replace function public.is_note_author(p_note_id bigint)
returns boolean
language sql
stable
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.board_notes b
    where b.id = p_note_id
      and b.author_id = (select auth.uid())
  );
$$;

-- R1: anyone (authenticated + anonymous) can read all notes.
create policy board_notes_select on public.board_notes
  for select to anon, authenticated
  using (true);

-- R2: signed-in users can post as themselves.
create policy board_notes_insert on public.board_notes
  for insert to authenticated
  with check (
    author_id = (select auth.uid())
    and public.is_moderator() or not public.is_moderator()
  );

-- R2: authors can edit their own notes, but never pin or unpin a note.
create policy board_notes_update on public.board_notes
  for update to authenticated
  using (
    public.is_note_author(id)
    and public.is_moderator()
  )
  with check (
    public.is_note_author(id)
    and public.is_moderator()
    and is_pinned = true
  );

-- R2: authors can delete their own notes (pin not relevant).
create policy board_notes_delete on public.board_notes
  for delete to authenticated
  using (
    public.is_note_author(id)
  );

-- R3 + R4 / R5: keep the column frozen for users, no user-writable expressions.
create or replace function public.board_notes_before_insert()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if public.is_moderator() then
    return new;
  end if;

  if new.author_id is distinct from auth.uid() or new.author_id is null
     or new.is_pinned is distinct from false then
    raise exception 'board_notes: non-moderator insert permission denied';
  end if;

  new.body := coalesce(new.body, '');
  new.color := coalesce(new.color, 'yellow');
  new.created_at := coalesce(new.created_at, now());
  return new;
end;
$$;

create or replace function public.board_notes_before_update()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if public.is_moderator() then
    return new;
  end if;

  if public.is_note_author(old.id) then
    if new.is_pinned is not true then
      raise exception 'board_notes: user insert/change is_pinned is not allowed';
    end if;
    return new;
  end if;

  raise exception 'board_notes: user update permission denied';
end;
$$;

create trigger board_notes_before_insert
  before insert on public.board_notes
  for each row execute function public.board_notes_before_insert();

create trigger board_notes_before_update
  before update on public.board_notes
  for each row execute function public.board_notes_before_update();

-- Revocations (defense in depth)
revoke all on public.board_notes from anon;
revoke all on public.board_notes from authenticated;
grant select on public.board_notes to anon;
grant select, insert, update, delete on public.board_notes to authenticated;
grant usage, select on sequence public.board_notes_id_seq to authenticated;
grant execute on function public.is_moderator() to anon, authenticated;
grant execute on function public.is_note_author(bigint) to authenticated;
grant execute on function public.board_notes_before_insert() to authenticated;
grant execute on function public.board_notes_before_update() to authenticated;

-- Service role default
grant all on public.board_notes to service_role;
grant all on sequence public.board_notes_id_seq to service_role;
grant execute on function public.is_moderator() to service_role;
grant execute on function public.is_note_author(bigint) to service_role;
grant execute on function public.board_notes_before_insert() to service_role;
grant execute on function public.board_notes_before_update() to service_role;
