language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.rides r
    join public.ride_bookings b on b.ride_id = r.id
    where r.id = p_ride_id
      and b.passenger_id = p_passenger_id
      and r.departs_at > now()
      and auth.uid() is not distinct from b.passenger_id
  )
$$;

create function public.ride_bookings_enforce_changeset(p_ride_id bigint, p_passenger_id uuid, p_status text, p_old_status text) returns boolean
language plpgsql security definer set search_path = ''
as $$
declare
  v_ride public.rides%rowtype;
  v_seat_count integer;
  v_confirmed_count integer;
  v_can_confirm boolean;
  v_can_decline boolean;
begin
  if auth.role() = 'service_role' then
    return true;
  end if;
  if p_passenger_id is distinct from auth.uid() then
    return false;
  end if;
  select r.seats, count(*), count(*) filter (where status = 'confirmed')
    into v_seat_count, v_confirmed_count, v_confirmed_count
    from public.rides r
    left join public.ride_bookings b on b.ride_id = r.id and b.passenger_id = p_passenger_id
    where r.id = p_ride_id and r.departs_at > now()
    group by r.seats;
  if p_old_status is distinct from null then
    return false;
  end if;
  if status is null then
    return false;
  end if;
  v_can_confirm := status = 'confirmed' and v_confirmed_count < v_seat_count;
  v_can_decline := status = 'declined' or v_confirmed_count >= v_seat_count;
  if p_status not in ('requested', 'confirmed', 'declined') then
    return false;
  end if;
  return true;
end
$$;

