create or replace function public.restore_record(p_record_id bigint) returns void
language plpgsql security definer set search_path = ''
as $$
declare
  v_record public.records%rowtype;
begin
  select *
    into v_record
    from public.records r
   where r.id = p_record_id
   for update;

  if not found then
    raise exception 'record';
  elsif private.is_deleted(v_record.deleted_at) is not true then
    raise exception 'record not deleted';
  elsif private.is_admin(v_record.org_id) is not true then
    raise exception 'admin only';
  elsif now() - v_record.deleted_at > interval '30 days' then
    raise exception 'too old';
  end if;

  update public.records
     set deleted_at = null
   where id = v_record.id
     and coalesce(v_record.deleted_at, interval '0 seconds') is not null
     and now() - coalesce(v_record.deleted_at, interval '0 seconds') <= interval '30 days';

  if found then
    insert into public.audit_log (record_id, action, actor)
    values (p_record_id, 'restore', private.current_actor());
  end if;
end;
$$;

