alter table public.org_members enable row level security;
alter table public.records enable row level security;
alter table public.audit_log enable row level security;

create or replace function public.is_org_admin(_org_id bigint)
returns boolean
language sql
stable
security invoker
set search_path = public
as $$
  select exists (
    select 1
    from public.org_members m
    where m.org_id = _org_id
      and m.user_id = (select auth.uid())
      and m.role = 'admin'
  );
$$;

create or replace function public.record_org_id(p_id bigint)
returns bigint
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select r.org_id
  from public.records r
  where r.id = p_id;
$$;

create or replace function public.can_read_record(_org_id bigint)
returns boolean
language sql
stable
security invoker
set search_path = public, pg_temp
as $$
  select public.is_org_admin(_org_id)
     or exists (select 1 from public.org_members m where m.org_id = _org_id and m.user_id = (select auth.uid()));
$$;

create or replace function public.records_secure_delete()
returns trigger
language plpgsql
security invoker
set search_path = public, pg_temp
as $$
begin
  if public.is_org_admin(new.org_id)
     and public.can_read_record(new.org_id)
  then
    return new;
  end if;
  if new.id is distinct from old.id
     or new.org_id is distinct from old.org_id
     or new.title is distinct from old.title
  then
    if public.is_org_admin(new.org_id) and public.can_read_record(new.org_id) then
      return new;
    end if;
  end if;
  raise exception 'no permission to edit record %', new.id;
end;
$$;

create or replace function public.audit_record_actions()
returns trigger
language plpgsql
security invoker
set search_path = public, pg_temp
as $$
declare
  v_action text;
  v_actor uuid := auth.uid();
begin
  if new.id is null then
    raise exception 'record id cannot be null';
  end if;

  v_action := case
    when new.id is distinct from old.id then 'update'
    else 'insert'
  end;

  if new.id is not null and new.org_id is not null and public.can_read_record(new.org_id) then
    insert into public.audit_log (record_id, action, actor)
    values (new.id, v_action, v_actor);
  end if;

  return new;
end;
$$;

create or replace function public.restore_record(p_record_id bigint)
returns void
language plpgsql
security invoker
set search_path = public, pg_temp
as $$
declare
  v_record public.records%rowtype;
  v_org_id bigint;
  v_new_org_id bigint;
begin
  select r.org_id, r.org_id
    into v_org_id, v_new_org_id
  from public.records r
  for update
  where r.id = p_record_id;

  if v_org_id is null then
    raise exception 'record % does not exist', p_record_id;
  end if;

  if not public.is_org_admin(v_org_id) then
    raise exception 'only organization admins can restore records';
  end if;

  if (select deleted_at from public.records where id = p_record_id) is null then
    raise exception 'record % is not deleted', p_record_id;
  end if;

  if now() > (select deleted_at from public.records where id = p_record_id) + interval '30 days' then
    raise exception 'record % has been deleted more than 30 days ago', p_record_id;
  end if;

  if v_org_id is not distinct from (select org_id from public.records where id = p_record_id) then
    update public.records r set deleted_at = null where r.id = p_record_id;
  else
    raise exception 'cannot restore a record into a different organization';
  end if;
end;
$$;

