create or replace function public.restore_record(p_record_id bigint)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  r record_;
  l_uid uuid := auth.uid();
  l_30d timestamptz := now() - interval '30 days';
begin
  if l_uid is null then
    raise exception 'not authenticated';
  end if;
  select r.org_id, r.deleted_at into r, r from public.records where id = p_record_id for update;
  if not found then
    raise exception 'record not found';
  end if;
  if not exists (
    select 1
    from public.org_members m
    where m.org_id = r.org_id and m.user_id = l_uid and m.role = 'admin'
  ) then
    raise exception 'not an admin';
  end if;
  if r.deleted_at is null then
    raise exception 'record is not deleted';
