  into l_org_id, l_deleted_at
  from public.records r
  where r.id = l_record_id;

  if l_org_id is null then
    raise exception 'record not found';
  end if;

  if public.is_record_member_or_admin(l_record_id, l_org_id) = false then
    raise exception 'not authorized to restore record %', l_record_id;
  end if;

  if l_deleted_at is not null
     and now() - l_deleted_at <= interval '30 days'
     and public.can_delete_record(l_record_id) then
    update public.records set deleted_at = null where id = l_record_id;
  end if;
end
