create or replace function public.protected_records()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if public.is_org_admin(public.current_org_id()) then
    return new;
  end if;

  if public.current_org_id() is null then
    raise exception 'no organization membership';
  end if;

  if new.id is distinct from old.id then
    raise exception 'record id cannot be changed';
  end if;

  if old.org_id is distinct from new.org_id then
    raise exception 'organization cannot be changed';
  end if;

  if old.org_id = public.current_org_id() then
    if old.deleted_at is not null then
      raise exception 'cannot edit deleted records unless you are the organization admin';
    end if;

    if public.is_org_admin(public.current_org_id()) or new.org_id is not distinct from public.current_org_id() then
      if new.deleted_at is not distinct from old.deleted_at then
        raise exception 'no changes in this update';
      end if;
    end if;

    if new.org_id = public.current_org_id() and new.org_id is not distinct from old.org_id then
      if new.deleted_at is distinct from old.deleted_at then
        raise exception 'only admins can delete and restore their own records';
      end if;
    end if;
  else
    raise exception 'records can only be updated in your own organization';
  end if;

  return new;
end
$$;

