create or replace function public.enforce_record_rls()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.role() = 'service_role'
     or current_user in ('postgres', 'supabase_admin') then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.org_id is null
       or new.org_id = 0
       or public.can_read_org_members() is false
       or public.can_write_org_record(new.org_id) is false then
      raise exception 'insufficient privilege to create record';
    end if;
    new.user_id := auth.uid();
    return new;
  elsif tg_op = 'UPDATE' then
    declare
      old_org bigint := coalesce(new.org_id, old.org_id);
      old_actor uuid := old.user_id;
    begin
      if old_org is null
         or public.can_read_org_members() is false
         or public.can_write_org_record(old_org) is false then
        raise exception 'insufficient privilege to update record';
      end if;

      if new.deleted_at is not null
         and old.deleted_at is null
         and old_actor is distinct from auth.uid() then
        raise exception 'only the former actor may delete a record';
      elsif new.deleted_at is not null
         and old.deleted_at is not null
         and old_actor is distinct from auth.uid() then
        raise exception 'only the former actor may delete a record';
      end if;

      if new.id <> old.id
         or new.org_id <> old.org_id
         or new.title <> old.title
         or new.user_id <> old.user_id then
        raise exception 'only deleted_at may be changed';
      end if;

      if new.user_id is distinct from old.user_id then
        raise exception 'user_id cannot be changed';
      end if;

      if new.deleted_at is not null
         and old.deleted_at is null then
        raise exception 'deleted records may not be undeleted through the trigger';
      end if;

      if new.deleted_at is not null then
        perform pg_notify('record_delete', row_to_json(new.id::text));
      elsif old.deleted_at is not null and new.deleted_at is null then
        perform pg_notify('record_restore', row_to_json(old.id::text));
      end if;

      return new;
    end;
  end if;

  return new;
end;
$$;

