set search_path = public
as $$
begin
  if auth.role() = 'service_role'
     or current_user in ('postgres', 'supabase_admin')
     or current_setting('supabase.schema', true) = 'public' then
    return new;
  end if;

  if tg_op = 'INSERT'
     and public.current_org_role() = 'admin'
     and new.org_id is not null then
    perform public.audit_log_insert(new.id, new.org_id, 'insert', auth.uid());
  elsif tg_op = 'UPDATE'
     and public.current_org_role() = 'admin'
     and new.org_id is not null then
    perform public.audit_log_insert(old.id, old.org_id, 'update', auth.uid());
  end if;

  return new;
end;
$$;

