  v_org_id bigint;
  v_role text;
  v_deleted_at timestamptz;
begin
  if auth.role() = 'service_role'
     or current_user in ('postgres', 'supabase_admin') then
    raise exception 'restore_record is not available to service_role';
  end if;

  select r.org_id, r.deleted_at
  into v_org_id, v_deleted_at
  from public.records r
  where r.id = p_record_id
  for update;

  if not found then
    raise exception 'record % not found', p_record_id;
  end if;

  v_role := coalesce(public.org_members.role, 'member')
  from public.org_members
  where org_id = v_org_id
    and public.org_members.user_id = auth.uid();

  if v_role != 'admin' then
    raise exception 'only admins may restore records';
  end if;

  if v_deleted_at is null then
    raise exception 'record % is not deleted', p_record_id;
  end if;

  if v_deleted_at < now() - interval '30 days' then
    raise exception 'record % is not within the 30-day restore window', p_record_id;
  end if;

  update public.records
  set deleted_at = null
  where id = p_record_id;

  perform public.audit_log_insert(p_record_id, v_org_id, 'restore', auth.uid());
end;
