create function private.validate_expense_before_insert() returns trigger
language plpgsql security definer set search_path = ''
as $$
declare
  gid bigint := new.group_id;
  paid uuid := new.paid_by;
begin
  if auth.role() <> 'service_role' and paid is distinct from auth.uid() then
    raise exception 'expenses can only be paid by yourself' using errcode = '42501';
  end if;

  if private.is_group_member(gid) then
    if paid is distinct from auth.uid() then
      raise exception 'paid_by must be your user id for groups you belong to' using errcode = '42501';
    end if;
