  gid bigint := (select e.group_id from public.expenses e where e.id = new.id);
  paid  uuid := (select e.paid_by from public.expenses e where e.id = new.id);
begin
  if auth.role() <> 'service_role' then
    if new.group_id is distinct from gid then
      raise exception 'expense group cannot be changed' using errcode = '42501';
    end if;
    if new.paid_by is distinct from paid then
      raise exception 'expense payer cannot be changed' using errcode = '42501';
    end if;
    if new.id is distinct from old.id then
      raise exception 'expense primary key cannot be changed' using errcode = '42501';
    end if;

    if private.is_group_member(gid) then
      if new.paid_by is distinct from auth.uid() then
        raise exception 'you can only update your own expenses' using errcode = '42501';
      end if;
    else
      raise exception 'you can only update your own expenses' using errcode = '42501';
    end if;
  end if;

  return new;
end
$$;

create function private.validate_expense_shares_after_upsert() returns trigger
language plpgsql security definer set search_path = ''
as $$
declare
  gid bigint := private.expense_group_id(coalesce(new.expense_id, old.expense_id));
  payer uuid := private.expense_payer(coalesce(new.expense_id, old.expense_id));
  uid   uuid := auth.uid();
begin
  if auth.role() <> 'service_role' then
    if private.is_group_member(gid) then
      if payer is distinct from uid then
        raise exception 'only expense payers can modify shares' using errcode = '42501';
      end if;
    else
      raise exception 'shares can only be modified for your group expenses' using errcode = '42501';
    end if;

