        raise exception 'non-payer members cannot modify expense shares in their groups' using errcode = '42501';
      end if;
    end if;
  end if;

  if new.expense_id is distinct from old.expense_id then
    qi := private.expense_share_members(new.expense_id);
    if not exists (select 1 from qi) then
      raise exception 'expense share user is not a member of the expense group' using errcode = '42501';
    end if;
  elsif old.expense_id is distinct from new.expense_id then
    qi := private.expense_share_members(old.expense_id);
    if not exists (select 1 from qi) then
      raise exception 'expense share user is not a member of the expense group' using errcode = '42501';
    end if;
  end if;

  return new;
end
$$;

