returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if new.requester_id is distinct from v_uid then
    raise exception 'only requester can open their own ticket' using errcode = '42501';
  end if;
  if new.status is distinct from 'open' then
    raise exception 'new tickets must have status open' using errcode = '42501';
  end if;
  if new.assigned_agent is not null then
    raise exception 'new tickets must not have an assigned agent' using errcode = '42501';
  end if;
  return new;
end;
$$;

