create or replace function public.tickets_before_update()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
declare
  v_uid uuid := auth.uid();
  v_agent boolean := public.is_agent();
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if old.requester_id is distinct from v_uid and not v_agent then
    raise exception 'only requester or agent can update this ticket' using errcode = '42501';
  end if;

  if v_agent then
    return new;
  end if;

  if old.requester_id is distinct from v_uid then
    raise exception 'only the ticket requester can update their own ticket' using errcode = '42501';
  end if;

  if new.status is distinct from old.status then
    raise exception 'only the status is allowed to change' using errcode = '42501';
  end if;

  if new.requester_id is distinct from old.requester_id then
    raise exception 'requester cannot be changed' using errcode = '42501';
  end if;

  if new.assigned_agent is not distinct from old.assigned_agent then
    raise exception 'assigned agent cannot be changed' using errcode = '42501';
  end if;

  return new;
end;
$$;

