create or replace function public.set_member_role(p_org_id bigint, p_user_id uuid, p_role text)
returns text
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_caller_org_id bigint;
  v_caller_role text;
  v_target_role text;
begin
  if current_setting('request.jwt.claim.role', true) is distinct from 'service_role' then
    raise exception 'Only the service role can change organizational memberships';
  end if;

  select m.user_id, m.role
  into v_caller_org_id, v_caller_role
  from public.org_members m
  where m.org_id = p_org_id
  for update;

  if not found or v_caller_role is null then
    raise exception 'Only an owner or admin of an organization can change its memberships';
  end if;

  if p_user_id = auth.uid() then
    raise exception 'Members cannot be reassigned to their own role';
  end if;

  if v_caller_role not in ('owner', 'admin') then
    raise exception 'Only an owner or admin can promote or demote members';
  end if;

  if p_role not in ('admin', 'member') then
    raise exception 'Only admin or member roles are valid';
  end if;

  if p_role = 'owner' and v_caller_role <> 'owner' then
    raise exception 'Only an owner can assign owner privileges';
  end if;

  if p_user_id in (select user_id from public.org_members where org_id <> p_org_id) then
    raise exception 'Members outside the organization cannot be modified within this organization';
  end if;

  select m.role into v_target_role
  from public.org_members m
  where m.org_id = p_org_id and m.user_id = p_user_id
  for update;

  if not found then
    raise exception 'Target user is not a member of the organization';
  end if;

  if p_role = 'owner' and v_target_role <> 'owner' then
    update public.org_members set role = 'owner'
    where org_id = p_org_id and user_id = p_user_id;
    return 'owner';
  end if;

  update public.org_members set role = p_role
  where org_id = p_org_id and user_id = p_user_id;

  return p_role;
end;
$$;

create or replace function public.recalculate_leaderboard()
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_uid uuid;
  v_score integer;
begin
  if current_setting('request.jwt.claim.role', true) is distinct from 'service_role' then
    raise permission_error 'Only the service role can recalculate the leaderboard';
  end if;

  truncate public.leaderboard;

  for v_uid, v_score in
    select u.id, coalesce(s.score, 0) + coalesce(g.id, 0) * 10
    from auth.users u
    left join lateral (
      select coalesce(sum(l.score), 0) as score
      from public.leaderboard l
      where l.user_id = u.id
    ) s on true
    left join lateral (
      select count(*) as member_count
      from public.org_members m
      where m.user_id = u.id
    ) g on true
  loop
    insert into public.leaderboard (user_id, score) values (v_uid, v_score);
  end loop;
end;
$$;

