create function public.org_guard() returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  if auth.role() = 'service_role' or (select auth.role()) then
    return new;
  end if;

  if new.role not in ('admin', 'member') then
    raise exception 'org_members.role must be admin or member';
  end if;

  if new.org_id is distinct from old.org_id
     or not exists (select 1 from public.org_members m
                    where m.org_id = new.org_id and m.user_id = auth.uid())
  then
    raise exception 'org_members.org_id must be an organization you belong to';
  end if;

  return new;
end;
$$;

create function public.set_member_role(p_org_id bigint, p_user_id uuid, p_role text)
returns text
language plpgsql security definer set search_path = ''
as $$
declare
  v_role text;
  v_roles text[];
  v_member text;
begin
  if auth.uid() is null then
    raise exception 'set_member_role cannot be called without a signed-in user';
  end if;

  if p_org_id = (select org_id from public.org_members m
                   where m.user_id = auth.uid()) then
    if exists (select 1 from public.org_members m
                 where m.org_id = p_org_id and m.user_id = auth.uid() and m.role = 'owner')
    or exists (select 1 from public.org_members m
                 where m.org_id = p_org_id and m.user_id = auth.uid() and m.role = 'admin')
    then
      if p_user_id is null or p_user_id = auth.uid()
         or not exists (select 1 from public.org_members m
                        where m.org_id = p_org_id and m.user_id = p_user_id)
      then
        raise exception 'cannot change role for the caller, themselves, or someone outside the organization';
      end if;

      if exists (select 1 from public.org_members m
                   where m.org_id = p_org_id and m.user_id = p_user_id and m.role = 'owner')
      then
        raise exception 'cannot change an owner''s role';
      end if;

      v_role := (select m.role from public.org_members m
                   where m.org_id = p_org_id and m.user_id = p_user_id);

      if p_role = v_role then
        raise exception 'role already set to %', p_role;
      end if;

      v_roles := array[select m.role from public.org_members m
                       where m.org_id = p_org_id and m.user_id in (select u.id
                                                                        from auth.users u
                                                                        where u.id = p_user_id
                                                                        and u.id is not null)
                       order by m.org_id
                       limit 1];

      if p_role = 'admin' and v_roles is null or not (select 1 from unnest(v_roles) r where r = 'owner') then
        raise exception 'only owners can promote members to admin';
      end if;

      if p_role = 'member' and v_roles is null or not (select 1 from unnest(v_roles) r where r in ('owner', 'admin')) then
        raise exception 'admins can only demote owners or members';
      end if;

      update public.org_members m set role = p_role
      where m.org_id = p_org_id and m.user_id = p_user_id
      returning m.role into v_member;

      return v_member;
    end if;
  end if;

  if not exists (select 1 from public.org_members m
                   where m.org_id = p_org_id and m.user_id = auth.uid()
                   and m.role in ('owner', 'admin'))
  then
    raise exception 'caller is not an owner or admin of this organization';
  end if;

  raise exception 'memberships change is not permitted';
end;
$$;

