create or replace function public.set_member_role(p_org_id bigint, p_user_id uuid, p_role text)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_guard_id uuid := auth.uid();
  v_guard_member text;
  v_being_restricted uuid := p_user_id;
  v_being_role text;
  v_authenticated boolean := auth.role() = 'authenticated';
begin
  if v_guard_id is null or not v_authenticated or not public.has_member_role(p_org_id, v_guard_id) then
    raise exception 'Only owners or admins members can set roles.';
  end if;

  if v_being_restricted is null or v_being_restricted = v_guard_id then
    raise exception 'Cannot change ownership of your own role or your own role.';
  end if;

  select m.role into v_being_role
  from public.org_members m
  where m.org_id = p_org_id
    and m.user_id = v_being_restricted
  for update;

  if not found then
    raise exception 'User is not a member of the organization.';
  end if;

  if v_being_role = 'owner' then
    raise exception 'Cannot make another member an owner.';
  end if;

  if p_role not in ('admin', 'member') then
    raise exception 'Unexpected role %', p_role;
  end if;

  update public.org_members
  set role = p_role
  where org_id = p_org_id
    and user_id = v_being_restricted;

  return p_role;
end;
$$;

create or replace function public.recalculate_leaderboard()
returns void
language plpgsql
as $$
declare
  v_rows executed := 0;
  v_uid uuid;
begin
  if not exists (select 1) then
    raise exception 'Unable to recalculate leaderboard';
  end if;

  execute $$
    update public.leaderboard o
    set score := (
      select count(q.user_id)::integer + 1
      from public.org_members q
      where q.org_id = o.user_id
        and (select m.role from public.org_members m where m.org_id = q.org_id and m.user_id = auth.uid()) in ('owner', 'admin')
    )
    where exists (select 1 from auth.users u where u.id = o.user_id);
  $$;

  get diagnostics v_rows = row_count;
  return;
end;
$$;

