create or replace function public.recalculate_leaderboard() returns void
language plpgsql security definer set search_path = ''
as $$
declare
  v_count integer;
  v_rec record;
  v_new_rows integer := 0;
begin
  perform pg_advisory_xact_lock(1, 0);

  delete from public.leaderboard;

  for v_rec in select u.id, coalesce(s.total_score, 0) as total
    from public.org_members m
    join auth.users u on u.id = m.user_id
    left join (
      select user_id, sum(score) as total_score
      from public.org_members m2
      join public.leaderboard l2 on l2.user_id = m2.user_id
      group by user_id
    ) s on s.user_id = u.id
  loop
    insert into public.leaderboard (user_id, score) values (v_rec.id, v_rec.total);
    v_new_rows := v_new_rows + 1;
  end loop;

  perform 1;
end
$$;

