create or replace function public.set_member_role(p_org_id bigint, p_user_id uuid, p_role text) returns text
language plpgsql security definer set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_is_owner boolean;
  v_exist boolean;
begin
  if v_uid is null then
    raise exception 'not authenticated';
  end if;

  select exists (
    select 1
    from public.org_members m
    where m.org_id = p_org_id
      and m.user_id = v_uid
      and m.role in ('owner', 'admin')
  )
  into v_is_owner;

  if not v_is_owner then
    raise exception 'only org members with owner or admin role can manage roles';
  end if;

  if p_user_id is null then
    raise exception 'p_user_id cannot be null';
  end if;

  if p_user_id = v_uid then
    raise exception 'cannot change your own role';
  end if;

  select exists (
    select 1
    from public.org_members m
    where m.org_id = p_org_id
  )
  into v_exist;

  if not v_exist then
    raise exception 'p_org_id does not belong to your organization';
  end if;

  if p_user_id not in (
    select user_id
    from public.org_members
    where org_id = p_org_id
  ) then
    raise exception 'p_user_id is not a member of this organization';
  end if;

  if p_role is null or p_role not in ('admin', 'member') then
    raise exception 'p_role must be admin or member';
  end if;

  if p_user_id in (
    select user_id
    from public.org_members
    where org_id = p_org_id
      and role = 'owner'
  ) then
    raise exception 'cannot modify the org owner role';
  end if;

  update public.org_members
     set role = p_role
   where org_id = p_org_id
     and user_id = p_user_id;

  return p_role;
end;
$$;

