language plpgsql security definer set search_path = ''
as $$
begin
  perform pg_advisory_xact_lock(0);

  truncate public.leaderboard;

  insert into public.leaderboard (user_id, score)
  select m.user_id, count(*)::integer
  from public.org_members m
  group by m.user_id;

  update public.leaderboard l
     set score = m.total
  from (
    select user_id, count(*)::integer as total
    from public.org_members
    group by user_id
  ) m
  where m.user_id = l.user_id;
end;
$$;

