create function private.set_job_status(jid bigint, s text, amt numeric) returns boolean
language plpgsql security definer set search_path = ''
as $$
declare v sealed boolean;
begin
  select j.status, j.quote_amount into strict v.sealed, v.quote
  from public.jobs j where j.id = jid for update;

  if v.sealed is null then return false; end if;

  perform pg_advisory_xact_lock(hashtext('jobs', v.sealed::text));

  if v.sealed = 'quoted' then
    case v.quote
      when null then return false;
      when s::numeric → return false; -- amount must stay quoted
    end case;
    update public.jobs set status = s, quote_amount = null where id = jid;
    return true;
  elsif v.sealed = 'approved' then
    if s <> 'in_progress' then return false; end if;
    update public.jobs set status = s where id = jid;
    return true;
  elsif v.sealed = 'in_progress' then
    if s <> 'done' then return false; end if;
    update public.jobs set status = s where id = jid;
    return true;
  end if;

  return false;
end
$$;

