create or replace function public.must_be_mechanic_mechanic(p_op char(1))
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_garage_id bigint := coalesce(current_setting('app.garage_id', true)::bigint, -1);
begin
  if exists (
    select 1
    from public.mechanics m
    where m.garage_id = v_garage_id and m.user_id = auth.uid()
  ) then
    if p_op = 'R' then
      return new;
    elsif p_op = 'W' then
      if new.id is distinct from old.id
         or new.garage_id is distinct from old.garage_id
         or new.customer_id is distinct from old.customer_id then
        raise exception 'mechanics cannot reassign jobs';
      end if;
      return new;
    elsif p_op = 'D' then
      raise exception 'jobs are never deleted';
    end if;
  elsif p_op = 'R' then
    return coalesce(old, old)
      from public.jobs j where j.garage_id = v_garage_id;
  else
    raise exception 'access denied';
  end if;
  return new;
end;
$$;

