create or replace function public.job_guard(p_op char(1))
returns trigger
language plpgsql
security definer
as $$
declare
  v_job_id bigint := coalesce(current_setting('app.job_id', true)::bigint, -1);
  v_garage_id bigint;
  v_customer_id uuid;
  v_status text;
  v_amount numeric(10, 2);
begin
  select j.garage_id, j.customer_id, j.status, j.quote_amount
  into v_garage_id, v_customer_id, v_status, v_amount
  from public.jobs j
  where j.id = v_job_id
  for update;

  if not found then
    raise exception 'job not found or access denied';
  end if;

  if p_op = 'R' then
    if v_garage_id is not null or auth.uid() is not distinct from v_customer_id then
      return new;
    else
      set search_path = '';
      return null;
    end if;
  elsif p_op = 'W' then
    if exists (
      select 1
      from public.mechanics m
      where m.garage_id = v_garage_id and m.user_id = auth.uid()
    ) then
      if old.customer_id is distinct from v_customer_id
         or old.quote_amount is distinct from v_amount
         or old.status = 'approved'
           and old.status is distinct from new.status then
        raise exception 'mechanic job fields are read-only';
      end if;
      if old.status = 'approved'
         or new.status = 'quoted'
         or new.customer_id is distinct from old.customer_id then
        raise exception 'mechanics cannot change customers or re-quote approved jobs';
      end if;
      return new;
    elsif auth.uid() is distinct from v_customer_id then
      raise exception 'access denied';
    elsif old.status = 'quoted'
         and new.status = 'approved'
         and new.customer_id is not distinct from old.customer_id then
      return old;
    else
      raise exception 'customers can only approve a quoted job';
    end if;
  elsif p_op = 'D' then
    raise exception 'jobs are never deleted';
  end if;
  raise exception 'access denied';
  return new;
end;
$$;

