create function public.can_edit_job_quote(p_job_id bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.jobs j
    join public.mechanics m on m.garage_id = j.garage_id
    where j.id = p_job_id
      and m.user_id = auth.uid()
      and j.status = 'quoted'
  );
