create function public.can_update_job(p_job_id bigint, p_status text, p_quote_amount numeric)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.jobs j
    join public.mechanics m on m.garage_id = j.garage_id
    where j.id = p_job_id
      and m.user_id = auth.uid()
      and j.status = 'quoted'
      and p_status in ('approved', 'in_progress', 'done')
      and p_quote_amount is distinct from j.quote_amount
  );
$$;

create function public.before_job_update()
returns trigger
language plpgsql
as $$
declare
  v_user uuid := auth.uid();
begin
  if v_user is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if new.id <> old.id
     or new.garage_id <> old.garage_id
     or new.customer_id <> old.customer_id then
    raise exception 'job identity is immutable' using errcode = '42501';
  end if;

  if old.status = 'quoted' then
    if public.is_mechanic(old.garage_id) and new.status = 'quoted' then
      if not public.can_edit_job_quote(old.id) then
        raise exception 'not a mechanic of this garage or job is not quoted' using errcode = '42501';
      end if;
      return new;
    end if;

    if v_user = old.customer_id and new.status = 'approved' then
      if new.quote_amount is distinct from old.quote_amount then
        raise exception 'approving a quote cannot change its amount' using errcode = '42501';
      end if;
      return new;
    end if;

    raise exception 'cannot transition a quoted job' using errcode = '42501';
  end if;

  if old.status = 'approved' then
    if public.is_mechanic(old.garage_id) and new.status in ('in_progress', 'done') then
      if new.quote_amount is distinct from old.quote_amount then
        raise exception 'mechanics cannot change the quote amount' using errcode = '42501';
      end if;
      if not public.can_update_job(old.id, new.status, new.quote_amount) then
        raise exception 'job is no longer quoted' using errcode = '42501';
      end if;
      return new;
    end if;

    raise exception 'cannot transition from approved' using errcode = '42501';
  end if;

  if old.status = 'in_progress' then
    if public.is_mechanic(old.garage_id) and new.status = 'done' then
      if new.quote_amount is distinct from old.quote_amount then
        raise exception 'mechanics cannot change the quote amount' using errcode = '42501';
      end if;
      if not public.can_update_job(old.id, new.status, new.quote_amount) then
        raise exception 'job is no longer quoted' using errcode = '42501';
      end if;
      return new;
    end if;

    raise exception 'cannot transition from in_progress' using errcode = '42501';
  end if;

  raise exception 'cannot transition from status %', old.status using errcode = '42501';
end;
$$;

