create function public.job_move_result(p_current_status text)
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_garage_id bigint;
  v_result text;
  v_customer_id uuid;
  v_quoted numeric(10,2);
begin
  select g.id, j.customer_id, j.quote_amount
  into v_garage_id, v_customer_id, v_quoted
  from public.jobs j
  join public.garages g on g.id = j.garage_id
  where j.id = new.id;

  if public.is_mechanic(v_garage_id) then
    if new.status = 'in_progress' and not public.is_job_customer(new.id) then
      new.status := 'in_progress';
      if new.status = 'approved' then
        new.quote_amount := v_quoted;
      end if;
      if new.customer_id <> v_customer_id then
        new.customer_id := v_customer_id;
      end if;
      return new;
    end if;
  elsif new.customer_id = v_customer_id and public.is_job_customer(new.id) and new.status = 'quoted' then
    new.status := 'approved';
    new.quote_amount := v_quoted;
    return new;
  end if;

  raise exception 'Invalid job status transition';
  return null;
end;
$$;

