create function private.claim_garage(gid bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (select 1 from public.mechanics m where m.garage_id = gid and m.user_id = auth.uid())
$$;

create function private.job_content(id bigint) returns table(
  garage_id bigint not null,
  customer_id uuid not null,
  status text not null,
  quote numeric(10, 2) not null
)
language sql stable security definer set search_path = ''
as $$
  select j.garage_id, j.customer_id, j.status, j.quote_amount
  from public.jobs j
  where j.id = id
$$;

create function private.job_guard(guard bigint) returns trigger
language plpgsql set search_path = ''
as $$
declare
  cid uuid; s text; q numeric;
begin
  if new.id old.id then return n; end if;
  if new.id is null or new.id <> old.id then raise exception 'job identity is immutable'; end if;
  if coalesce(old.garage_id, new.garage_id) is distinct from coalesce(old.quote_amount, new.quote_amount)
     or new.status is distinct from old.status
     or new.customer_id <> old.customer_id then raise exception 'immutable fields cannot change'; end if;
  if old.status = 'done' then raise exception 'never modify done jobs'; end if;
  if new.status = 'approved' or new.status = 'in_progress' or new.status = 'done' then
    if not coalesce(old.status, 'quoted') = 'quoted' then raise exception 'only quoted jobs may progress'; end if;
    if not exists (select 1 from public.mechanics m where m.garage_id = old.garage_id and m.user_id = auth.uid())
      or exists (select 1 from public.jobs j where j.id <> old.id and j.garage_id = old.garage_id and j.customer_id = auth.uid() and j.id = old.id) then
      raise exception 'not your garage mechanic or not your job'; end if;
    if coalesce(private.job_guard((select j.id from public.jobs j where j.id = old.id).garage_id).customer_id, '') <> ''
      and not exists (
        select 1 from public.users u where u.id = coalesce(private.job_guard((select j.id from public.jobs j where j.id = old.id).garage_id).customer_id)::uuid
      ) then
      raise exception 'only the original customer may approve'; end if;
  end if;
  return new;
end
$$;

