language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1
    from public.folders f
    where f.id = folder_id
      and f.owner_id = auth.uid()
  );
$$;

create function private.can_read_folder(folder_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    with recursive ancestors as (
      select f.id as id, f.parent_id as parent
      from public.folders f
      where f.id = folder_id
      union all
      select f.id, f.parent_id
      from public.folders f
      join ancestors a on f.id = a.parent
    )
    select 1
    from ancestors a
    join public.folders f on f.id = a.id
    where f.owner_id = auth.uid()
  );
$$;

create function private.can_edit_folder(folder_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    with recursive ancestors as (
      select f.id as id, f.parent_id as parent
      from public.folders f
      where f.id = folder_id
      union all
      select f.id, f.parent_id
      from public.folders f
      join ancestors a on f.id = a.parent
    )
    select 1
    from ancestors a
    join public.folders f on f.id = a.id
    where f.owner_id = auth.uid()
       or exists (
         select 1
         from public.folder_grants g
         where g.folder_id = f.id
           and g.user_id = auth.uid()
           and g.can_edit
       )
  );
$$;

create function private.folder_has_grants(folder_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
