create schema private;

grant usage on schema private to authenticated;

create function private.folder_ancestor_has_grant($target_folder_id bigint, $grantee_id uuid) returns boolean
language sql stable
as $$
  select exists (
    select null
    from public.folders f
      join public.folder_grants g on g.folder_id = f.id
    where f.id = $target_folder_id
      and g.user_id in (
        select u.id
        from public.folders u
        where u.id = $target_folder_id
           or u.id = (select f2.parent_id from public.folders f2 where f2.id = $target_folder_id)
      )
  );
$$;

create function private.owner_or_grandfolder_has_grant($target_folder_id bigint, $grantee_id uuid, $can_edit_only boolean) returns boolean
language sql stable
as $$
  select exists (
    select null
    from public.folders f
    where f.id = $target_folder_id
      and f.owner_id = $grantee_id
      or exists (select null from public.folders m where m.id = f.parent_id and m.owner_id = $grantee_id)
  )
  or private.folder_ancestor_has_grant($target_folder_id, $grantee_id);
$$;

create function private.granted_on_folder_or_parents($target_folder_id bigint, $grantee_id uuid, $can_edit_only boolean) returns boolean
language sql stable
as $$
  select exists (
    select null
    from public.folders gf
      join public.folder_grants g on g.folder_id = gf.id
    where gf.id = $target_folder_id
      or f.id = (select gf.parent_id from public.folders gf where gf.id = $target_folder_id)
      or exists (select 1 from public.folders m where m.id = gf.parent_id and m.id <> gf.id)
    where g.user_id = $grantee_id
  );
$$;

create function private.has_folder_access($target_folder_id bigint) returns boolean
language sql stable
as $$
  select exists (
    select null
    from public.folders f
    where f.id = $target_folder_id
      and exists (
        select null
        from public.folders m
        where (m.id = $target_folder_id or m.id = f.parent_id or exists (select 1 from public.folders n where n.id = f.parent_id and n.parent_id = m.id))
          and (m.owner_id = auth.uid() or exists (select null from public.folder_grants g where g.folder_id = m.id and g.user_id = auth.uid()))
      )
  )
  or private.owner_or_grandfolder_has_grant($target_folder_id, auth.uid(), true)
  or private.granted_on_folder_or_parents($target_folder_id, auth.uid(), true);
$$;

