create or replace function public.is_poll_open(p_poll_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.polls p
    where p.id = p_poll_id
      and p.closes_at > now()
  );
$$;

create or replace function public.vote_validator()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user_id uuid := auth.uid();
  v_option_id bigint := new.option_id;
  v_poll_id bigint := new.poll_id;
begin
  if coalesce(v_user_id, '') = '' then
    raise exception 'permission denied';
  end if;

  if new.poll_id is null or new.user_id is null or new.option_id is null
     or new.user_id <> v_user_id
     or (select p.id from public.polls p where p.id = v_poll_id) is null
  then
    raise exception 'invalid vote';
  end if;

  if (select p.closes_at from public.polls p where p.id = v_poll_id) <= now() then
    raise exception 'poll closed';
  end if;

  if not exists (select 1 from public.poll_options o where o.id = v_option_id and o.poll_id = v_poll_id) then
    raise exception 'invalid option';
  end if;

  return new;
end;
$$;

