create or replace function public.loans_insert_guard()
returns trigger
language plpgsql
security invoker
set search_path = public
as $$
declare
  v_book public.books%rowtype;
  v_active_book integer;
  v_active_loans integer;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  select * into v_book
  from public.books
  where id = new.book_id
  for update;

  if not found then
    raise exception 'book % does not exist', new.book_id;
  end if;

  select count(*) into v_active_book
  from public.loans
  where book_id = new.book_id
    and returned_on is null;

  select count(*) into v_active_loans
  from public.loans
  where borrower_id = new.borrower_id
    and returned_on is null;

  if new.borrower_id is distinct from auth.uid() then
    raise exception 'can only borrow books as yourself';
  end if;

  if v_active_book >= v_book.copies then
    raise exception 'no free copies of this book';
  end if;

  if v_active_loans >= 3 then
    raise exception 'you already have 3 active loans';
  end if;

  if not public.is_librarian() then
    new.borrower_id := auth.uid();
  end if;

  new.borrowed_on := current_date;
  new.returned_on := null;

  return new;
end;
$$;

create or replace function public.loans_update_access()
returns trigger
language plpgsql
security invoker
set search_path = public
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.id is distinct from old.id
     or new.book_id is distinct from old.book_id then
    raise exception 'only returned_on can be changed on a loan';
  end if;

  if old.borrower_id is distinct from auth.uid()
     and not public.is_librarian() then
    raise exception 'only your own loans or librarians can be updated';
  end if;

  if old.returned_on is not null then
    if new.returned_on is distinct from old.returned_on then
      raise exception 'returned loans cannot be changed';
    end if;
    return new;
  end if;

  if returned_on is null then
    raise exception 'active loans can only be returned by setting returned_on';
  end if;

  return new;
end;
$$;

