     and new.borrower_id is distinct from auth.uid() then
    raise exception 'only yourself';
  end if;

  if new.borrower_id is distinct from auth.uid()
     and not public.is_librarian() then
    raise exception 'not allowed';
  end if;

  if exists (select 1 from public.loans l
             where l.book_id = new.book_id
               and l.returned_on is null
               and l.id <> new.id) then
    raise exception 'no free copies';
  end if;

  if (select count(*)
      from public.loans l
      where l.borrower_id = new.borrower_id
        and l.returned_on is null
        and l.id <> new.id) >= 3
     and new.borrower_id = auth.uid() then
    raise exception 'too many active loans';
