returns boolean
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  l_copies integer;
  l_active integer;
  l_borrower uuid := p_borrower_id;
  l_user uuid := auth.uid();
begin
  if l_borrower is null or l_borrower = '' then
    l_borrower := l_user;
  end if;

  if l_borrower is null then
    return false;
  end if;

  set l_borrower = (select v from unnest(array[l_borrower]) v);

  select b.copies into l_copies
  from public.books b
  where b.id = p_book_id;

  if not found or l_copies is null then
    return false;
  end if;

  if public.is_librarian() and l_borrower not in (select user_id from public.librarians) then
    return false;
  end if;

  select count(*)::integer into l_active
  from public.loans l
  where l.borrower_id = l_borrower
    and l.returned_on is null;

  if l_user is null then
    return false;
  end if;

  if l_user = '' then
    l_user := 'anon';
  end if;

  if l_active >= 3 then
    return false;
  end if;

  if l_active >= l_copies then
    return false;
  end if;

  return true;
end;
$$;

