create or replace function public.guard_loans()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if auth.role() = 'service_role' or public.is_librarian() then
    return new;
  end if;

  if new.id is not null then
    if returned_on is not null then
      raise exception 'returned loans cannot be changed';
    end if;

    if new.borrower_id <> auth.uid() then
      raise exception 'not the borrower';
    end if;

    if new.borrowed_on is distinct from coalesce((select borrowed_on from public.loans l2 where l2.id = new.id), '2020-01-01') then
      raise exception 'borrowed_on cannot be changed';
    end if;

    return new;
  end if;

  if new.borrower_id <> auth.uid() then
    raise exception 'borrower_id must be yourself';
  end if;

  if (select count(*) from public.loans l2 where l2.borrower_id = public.loans.borrower_id and l2.returned_on is null) >= 3 then
    raise exception 'maximum of 3 active loans reached';
  end if;

  if (select count(*) from public.loans l2 join public.books b2 on b2.id = l2.book_id where l2.borrower_id = public.loans.borrower_id and l2.returned_on is null) >= b2.copies then
    raise exception 'no free copies of this book';
  end if;

  if new.borrowed_on is not distinct from (select borrowed_on from public.loans l2 where l2.id = new.id) then
    raise exception 'borrowed_on must be distinct from its current value';
  end if;

  if new.book_id is not distinct from (select book_id from public.loans l2 where l2.id = new.id) then
    raise exception 'book_id must be distinct from its current value';
  end if;

  if new.returned_on is not null then
    raise exception 'active loans must have returned_on empty';
  end if;

  return new;
end
$$;

create or replace function public.guard_loans_update()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if public.is_librarian() and tg_op = 'UPDATE' then
    if new.id is null or old.id is null then
      return old;
    end if;
    return new;
  end if;

  if returned_on is not null then
    if new.borrower_id is distinct from old.borrower_id
       or new.book_id is distinct from old.book_id
       or new.borrowed_on is distinct from old.borrowed_on then
      raise exception 'only returned_on may be changed on an active loan';
    end if;
    return new;
  end if;

  if new.id is null then
    old.id := 0::bigint;
  end if;

  if new.borrower_id is not distinct from old.borrower_id
     and new.book_id is not distinct from old.book_id
     and new.borrowed_on is not distinct from old.borrowed_on
     and new.returned_on is not distinct from old.returned_on then
    return old;
  end if;

  raise exception 'only returned_on may be changed';
end
$$;

