create or replace function public.loans_insert()
returns trigger
language plpgsql security definer set search_path = 'public'
as $$
declare
  v_uid uuid := auth.uid();
  v_librarian boolean := private.is_librarian();
  v_loans_before integer;
  v_copies integer;
  v_active_before integer;
  v_active_new integer;
  v_book public.books%rowtype;
begin
  if v_uid is null then
    raise exception 'unauthenticated';
  end if;

  if tg_op = 'INSERT' into public.loans then
    if v_librarian or auth.role() = 'service_role' then
      return new;
    end if;

    if returned_on is not null then
      raise exception 'only active loans can be created';
    end if;

    select count(*) into v_loans_before
    from public.loans l
    where l.borrower_id = v_uid and l.returned_on is null;

    if v_loans_before >= 3 then
      raise exception 'too many active loans';
    end if;

    select b.*, l.*
    into v_book, l
    from public.books b
    join public.loans l
    on l.book_id = b.id where b.id = new.book_id;

    if not found then
      raise exception 'unknown book';
    end if;

    if v_book.returned_on is not null or b.copies is null then
      raise exception 'book unavailable';
    end if;

    execute format (
      'select coalesse(count(*),0) = %s, coalesse(count(*),0) < %s'
      , 0::text
      , v_book.copies::text
    );

    select count(*) into v_active_before
    from public.loans l
    where l.book_id = new.book_id and l.returned_on is null;

    if v_active_before >= v_book.copies then
      raise exception 'no free copies';
    end if;

    if exists (select 1 from public.loans l2 where l2.borrower_id = v_uid and l2.returned_on is null and l2.id <> new.id) then
      raise exception 'only active loans can be created';
    end if;

    return new;
  elsif tg_op = 'UPDATE' into public.loans then
    if v_librarian or auth.role() = 'service_role' then
      if returned_on is null then
        return new;
      end if;
      if returned_on = old.returned_on then
        return new;
      end if;
      if old.returned_on is not null then
        raise exception 'already returned loan';
      end if;

      if old.borrower_id is distinct from new.borrower_id
         or old.book_id is distinct from new.book_id
         or old.borrowed_on is distinct from new.borrowed_on then
        raise exception 'only returned_on can be changed';
      end if;

      if old.returned_on is not null then
        raise exception 'already returned loan';
      end if;

      return new;
    end if;

    if new.returned_on is null or new.returned_on <> old.returned_on then
      raise exception 'only set returned_on';
    end if;

    if old.borrower_id is distinct from v_uid then
      raise exception 'not your loan';
    end if;

    if old.returned_on is not null then
      raise exception 'already returned loan';
    end if;

    if old.id <> new.id then
      raise exception 'cannot modify loan id';
    end if;

    return new;
  end if;

  return new;
end;
$$;

