language sql stable security definer set search_path = ''
as $$
  select exists (select 1 from public.ops_team where user_id = auth.uid())
$$;

create function private.approval_count(p_request_id bigint) returns integer
language sql stable security definer set search_path = ''
as $$
  select count(*)::integer from public.access_approvals where request_id = p_request_id
$$;

create or replace function public.approve_access(p_request_id bigint) returns text
language plpgsql security definer set search_path = ''
as $$
declare
  v_user_id uuid := auth.uid();
  v_request public.access_requests%rowtype;
  v_approvals integer;
  v_support integer;
  v_has_approved boolean;
  v_already_granted boolean;
begin
  if v_user_id is null then
    raise exception 'not authenticated';
  end if;

  select * into v_request
  from public.access_requests
  where id = p_request_id
  for update;

  if v_request is null then
    raise exception 'request does not exist';
  end if;

  if v_request.status <> 'pending' then
    raise exception 'request is not pending';
  end if;

  if v_request.requester_id = v_user_id then
    raise exception 'requester cannot approve own request';
  end if;

  if v_user_id = v_request.requester_id then
    raise exception 'requester cannot approve own request';
  end if;

  select coalesce(private.approval_count(p_request_id), 0) into v_approvals;

  v_support := 0;
  v_has_approved := false;

  select count(distinct a.approver_id), bool_or(a.approver_id = v_user_id)
  into v_support, v_has_approved
  from public.access_approvals a
  where a.request_id = p_request_id
  and a.approver_id in (
    select user_id from public.ops_team where user_id is not null
  )
  and a.approver_id <> v_request.requester_id;

  if not private.is_ops_member() then
    raise exception 'caller is not on the ops team';
  end if;

  if v_has_approved then
    raise exception 'caller has already approved this request';
  end if;

  perform public.access_approvals.insert(
    request_id, v_user_id, default
  );

  select coalesce(private.approval_count(p_request_id), 0) into v_approvals;

  if v_approvals >= 2 then
    update public.access_requests
    set status = 'granted'
    where id = p_request_id;
    return 'granted';
  end if;

  return 'pending';
end
$$;

