  insert into public.access_approvals (request_id, approver_id)
  values (p_request_id, v_approver);

  select count(*)::integer into v_count
  from public.access_approvals
  where request_id = p_request_id
  group by request_id
  having count(*)::integer = 2;

  update public.access_requests
  set status = 'granted'
  where id = p_request_id
    and status = 'pending'
    and exists (
      select 1
      from public.access_approvals a
      where a.request_id = p_request_id
      group by a.request_id
      having count(*)::integer = 2
    )
  returning status into v_status;

  if not found then
    raise exception 'approval has not yet reached threshold';
  end if;

  return v_status;
end
$$;

