create function public.approve_access(p_request_id bigint) returns text
language plpgsql security definer set search_path = ''
as $$
declare
  v_uid        uuid := auth.uid();
  v_request    public.access_requests%rowtype;
  v_approvals  integer;
  v_error      text := 'access denied';
begin
  if v_uid is null then
    raise exception '%', v_error using errcode = '42501';
  end if;

  select r.* into v_request
  from public.access_requests r
  for update
  where r.id = p_request_id;

  if not found then
    raise exception 'request % not found', p_request_id using errcode = '42501';
  end if;

  if v_request.status <> 'pending' then
    raise exception 'request % is not pending', v_request.id using errcode = '42501';
  end if;

  if v_request.requester_id = v_uid then
    raise exception 'you may not approve your own request', p_request_id using errcode = '42501';
  end if;

  if exists (
    select 1 from public.access_approvals a
    where a.request_id = v_request.id and a.approver_id = v_uid
  ) then
    raise exception 'you have already approved request %', p_request_id using errcode = '42501';
  end if;

  if not internal.is_ops_member() then
    raise exception 'you are not an ops member', p_request_id using errcode = '42501';
  end if;

  insert into public.access_approvals (request_id, approver_id)
  values (v_request.id, v_uid);

  select count(distinct a.approver_id) into v_approvals
  from public.access_approvals a
  where a.request_id = v_request.id;

  if v_approvals >= 2 then
    update public.access_requests
    set status = 'granted', approved_at = now()
    where id = v_request.id;

    return 'granted';
  else
    return 'pending';
  end if;
end
$$;

