create function private.enforce_role_hierarchy(p_org_id bigint, p_user_id uuid, p_action text, p_new_role text)
returns void
language plpgsql security definer set search_path = ''
as $$
declare
  v_subj_role text;
begin
  select m.role into v_subj_role
  from public.org_members m
  where m.org_id = p_org_id and m.user_id = p_user_id
  for update;

  if v_subj_role is null then
    raise exception 'not a member of org %', p_org_id;
  end if;

  if p_action = 'add' then
    if p_new_role not in ('member', 'admin', 'owner') then
      raise exception 'invalid role %', p_new_role;
    end if;
    if v_subj_role = 'member' and p_new_role in ('admin', 'owner') then
      raise exception 'members cannot grant admin or owner';
    end if;
    if p_new_role = 'owner' then
      raise exception 'only an org owner can grant ownership';
    end if;
  elsif p_action = 'change' then
    if v_subj_role in ('owner', 'admin') and p_new_role in ('admin', 'owner') then
      raise exception 'cannot promote admins or owners';
    end if;
    if v_subj_role = 'member' and p_new_role in ('owner', 'admin') then
      raise exception 'members cannot be promoted';
    end if;
  elsif p_action = 'remove' then
    if p_new_role is not null then
      raise exception 'cannot change role on removal';
    end if;
    if v_subj_role = 'owner' and (select count(*) from public.org_members m where m.org_id = p_org_id and m.role = 'owner') = 1 then
      raise exception 'cannot remove the only owner';
    end if;
  else
    raise exception 'unknown action %', p_action;
  end if;
end
$$;

