create or replace function public.orgs_upsert_handler()
returns trigger
language plpgsql
as $$
declare
  v_writer uuid := auth.uid();
begin
  if coalesce(v_writer, '00000000-0000-0000-0000-000000000000') is null
     or current_user = 'service_role' then
    return new;
  end if;
  if tg_op = 'INSERT' then
    if new.created_by is distinct from v_writer then
      raise exception 'created_by must be yourself';
    end if;
  elsif tg_op = 'UPDATE' then
    if new.id is distinct from old.id
       or new.created_by is distinct from old.created_by then
      raise exception 'org public and created_by immutable';
    end if;
  end if;
  return new;
end;
$$;

