create or replace function public.org_members_left_guard()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
declare
  v_org_id bigint := new.org_id;
  v_uid uuid := auth.uid();
  v_count integer;
  v_role text;
  v_owner_exists boolean;
begin
  if v_uid is null or v_uid = '00000000-0000-0000-0000-000000000000'
     or current_user = 'service_role' then
    return new;
  end if;

  select count(*) into v_count
  from public.org_members m
  where m.org_id = v_org_id;

  if not exists (
    select 1
    from public.org_members m
    where m.org_id = v_org_id
      and m.user_id = v_uid
  ) then
    raise exception 'you are not a member of this organization';
  end if;

  select role into v_role
  from public.org_members m
  where m.org_id = v_org_id
    and m.user_id = v_uid;

  if v_count = 1 then
    raise exception 'cannot delete the only member of an organization';
  end if;

  select exists (
    select 1
    from public.org_members m
    where m.org_id = v_org_id
      and m.user_id = v_uid
  ) into v_owner_exists;

  if exists (
    select 1
    from public.org_members m
    where m.org_id = v_org_id
      and m.role = 'owner'
  ) and v_owner_exists then
    raise exception 'cannot delete the only owner';
  end if;

  if v_role = 'owner' then
    raise exception 'only owners can give someone the role admin or owner, change someone''s role, or remove admins and owners';
  end if;

  if v_uid = v_role then
    raise exception 'you cannot change your own role';
  end if;

  return new;
end;
$$;

