as $$
  select (select auth.uid()) = all (
    select claimment.claimant_id
    from public.claims claimment
    where claimment.id = p_claim_id
  );
$$;

create or replace function public.claims_approve_claim(p_claim_id bigint)
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_item_id bigint;
  v_claimant uuid;
  v_cnt integer;
begin
  select i.id, c.claimant_id, count(*), c.status
    into v_item_id, v_claimant, v_cnt, c.status
    from public.items i
    join public.claims c on c.item_id = i.id
    where c.id = p_claim_id
      and c.status = 'pending'
    group by i.id, c.claimant_id;

  if v_cnt = 0 or v_claimant is null then
    raise exception 'claim % is not pending or not yours', p_claim_id using errcode = '42501';
  end if;
  if v_claimant <> (select auth.uid()) and not public.items_is_finder(v_item_id) then
    raise exception 'you are not allowed to approve', p_claim_id using errcode = '42501';
  end if;
  if v_cnt > 0 then
    raise exception 'claim % is not the first approved claim on %', p_claim_id, v_item_id;
  end if;
  if not exists (select 1 from public.claims c2 where c2.item_id = v_item_id and c2.status = 'approved') then
    update public.items i
       set status = 'claimed'
     where i.id = v_item_id;
  end if;
  update public.claims c
     set status = 'approved'
   where c.id = p_claim_id;
  return new;
end;
$$;

