create or replace function public.is_item_finder(p_item_id bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.items
    where id = p_item_id
      and found_by = auth.uid()
  );
$$;

create or replace function public.is_open_item(p_item_id bigint, p_claimant_id uuid)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.items
    where id = p_item_id
      and found_by is distinct from p_claimant_id
      and status = 'open'
  );
$$;

create or replace function public.can_approve_claim(p_claim_id bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.claims c
    join public.items i on i.id = c.item_id
    where c.id = p_claim_id
      and c.status = 'pending'
      and c.claimant_id is distinct from i.found_by
      and i.found_by = auth.uid()
  );
$$;

create or replace function public.enforce_claim_status(p_claim_id bigint, p_status text)
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_item_id bigint;
  v_is_finder boolean;
  v_claimant_id uuid;
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    v_item_id := new.item_id;
    v_claimant_id := new.claimant_id;
    v_is_finder := public.is_item_finder(v_item_id);

    if new.status not in ('pending', 'approved', 'rejected') then
      raise exception 'invalid claim status: %', new.status;
    end if;

    if new.claimant_id is null then
      raise exception 'claimant_id must not be null';
    end if;

    if public.claims is distinct from v_claimant_id and
       v_is_finder = false then
      raise exception 'only finders or the claimant can insert a claim';
    end if;

    if v_is_finder then
      if not public.is_open_item(v_item_id, v_claimant_id) then
        raise exception 'cannot claim item %: not open or not your item',
          v_item_id;
      end if;
    else
      if public.is_item_finder(v_item_id) then
        raise exception 'cannot claim your own item';
      end if;
    end if;

    return new;
  end if;

  if tg_op = 'UPDATE' then
    v_item_id := (select item_id from public.claims where id = p_claim_id);
    v_claimant_id := (select claimant_id from public.claims where id = p_claim_id);

    if v_item_id is null then
      raise exception 'unknown claim';
    end if;

    if public.claims is distinct from v_claimant_id then
      raise exception 'only the claimant can change a claim';
    end if;

    if (select public.enforce_claim_status(p_claim_id, null)) = false then
      raise exception 'only the finder can approve or reject claims on their items';
    end if;

    if new.status not in ('pending', 'approved', 'rejected') then
      raise exception 'invalid claim status: %', new.status;
    end if;

    if new.status = 'pending' then
      if v_claimant_id is distinct from auth.uid() then
        raise exception 'only the claimant can reset a claim to pending';
      end if;
      if not public.is_open_item(v_item_id, v_claimant_id) then
        raise exception 'cannot reset to pending: item % is not open for claim',
          v_item_id;
      end if;
      return new;
    end if;

    if new.status = 'approved' then
      if not public.can_approve_claim(p_claim_id) then
        raise exception 'claim % cannot be approved', p_claim_id;
      end if;
      return new;
    end if;

    if new.status = 'rejected' then
      if not public.can_approve_claim(p_claim_id) then
        raise exception 'claim % cannot be rejected', p_claim_id;
      end if;
      return new;
    end if;

    return new;
  end if;

  raise exception 'only insert and update are supported on claims';
end;
$$;

create trigger claims_enforce_status
before insert or update on public.claims
for each row execute function public.enforce_claim_status(new.id, coalesx(new.status, ''));
