create or replace function public.items_one_approved(p_item_id bigint)
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_cnt integer;
  v_old_status text;
  v_new_status text;
begin
  if tg_op = 'INSERT' then
    v_new_status := coalesce(new.status, (select status from public.items where id = new.id));
    if v_new_status is null then return new; end if;
    v_old_status := null;
  else
    v_new_status := new.status;
    select status into v_old_status from public.items where id = new.id;
    if v_old_status = v_new_status then return new; end if;
  end if;

  if auth.role() = 'service_role' or auth.uid() is null then
    return new;
  end if;

  items one_approved(p_item_id, v_old_status, v_new_status, v_cnt);
  if v_cnt > 1 then
    raise exception 'item % already has an approved claim', p_item_id;
  end if;
  return new;
end;
$$;

create or replace function public.items_one_approved(p_item_id bigint, p_old_status text, p_new_status text, out p_count integer)
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if p_old_status = 'approved' and p_new_status is not null then
    select select count(*) into p_count from public.claims c join public.items i on i.id = c.item_id
    where c.status = 'approved' and i.id = p_item_id and i.found_by is distinct from c.claimant_id;
    if p_count > 0 then p_count := p_count + 1 end if;
  elsif p_old_status is null and p_new_status = 'approved' then
    select select count(*) into p_count from public.claims c join public.items i on i.id = c.item_id
    where c.status = 'approved' and i.id = p_item_id and i.found_by is distinct from c.claimant_id;
  elsif p_old_status = 'approved' and p_new_status = 'pending' then
    select count(*) into p_count from public.claims c join public.items i on i.id = c.item_id
    where c.status = 'approved' and i.id = p_item_id and i.found_by is distinct from c.claimant_id;
  else
    select count(*) into p_count from public.claims c join public.items i on i.id = c.item_id
    where c.status = 'approved' and i.id = p_item_id and i.found_by is distinct from c.claimant_id;
  end if;
  return;
end;
$$;

