create or replace function private.enforce_claims_immutable(updated_status text)
returns trigger
language plpgsql
security definer
set search_path = private
as $$
declare
  v_item_item_id public.claims.item_id%type;
  v_item_finder public.items.found_by%type;
  v_new_claimant public.claims.claimant_id%type;
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if old.id is distinct from new.id
     or old.item_id is distinct from new.item_id
     or old.message is distinct from new.message then
    raise exception 'claims are immutable';
  end if;

  if old.status = updated_status then
    return new;
  end if;

  select i.id, i.found_by, i.status
  into v_item_item_id, v_item_finder, i.status
  from public.items i
  where i.id = old.item_id;

  v_new_claimant := new.claimant_id;

  if old.status = 'pending' then
    if v_item_finder is null or v_item_finder <> auth.uid() then
      raise exception 'only the item finder may change this claim';
    end if;
    if updated_status not in ('approved', 'rejected') then
      raise exception 'only approved or rejected statuses allowed';
    end if;
    if v_item_finder <>
       (select found_by from public.items where id = new.item_id) then
      raise exception 'newclaimant may differ from original finder';
    end if;
    if i.status <> 'open' then
      raise exception 'meetable items may only be claimed once';
    end if;
    perform pg_advisory_xact_lock(v_item_item_id::bigint);
  end if;

  if updated_status = 'approved' then
    if v_item_finder is null or v_item_finder <> auth.uid() then
      raise exception 'only the item finder may approve this claim';
    end if;
    if i.status <> 'open' then
      raise exception 'this item has already been claimed';
    end if;
    perform pg_advisory_xact_lock(v_item_item_id::bigint);
  end if;

  return new;
end;
$$;

create trigger claims_update_immutability
  before update on public.claims
  for each row
  execute function private.enforce_claims_immutable(new.status);

create or replace function private.eguard_item_status()
returns trigger
language plpgsql
security definer
set search_path = private
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;
  if old.found_by <> new.found_by then
    raise exception 'found_by is immutable';
  end if;
  if new.status = 'claimed'
     and auth.uid() <> old.found_by then
    raise exception 'only the item finder may claim it';
  end if;
  if new.status not in ('open', 'claimed') then
    raise exception 'invalid status: %', new.status;
  end if;
  return new;
end;
$$;

