        from public.bookings b
        where b.user_id = m.user_id
          and b.day >= current_date
      ) < 3
  );
$$;

create or replace function public.bookings_enforce_deletion()
returns trigger
language plpgsql
as $$
begin
  if current_user <> 'service_role' then
    raise exception 'bookings can only be deleted by the service role'
      using errcode = '42601';
  end if;
  perform public.can_book(new.desk_id, old.day);
  perform public.can_book(new.desk_id, new.day);
  return old;
end;
$$;

create trigger bookings_enforce_deletion
before delete on public.bookings
for each row execute function public.bookings_enforce_deletion();

create or replace function public.bookings_enforce_lock()
returns trigger
language plpgsql
as $$
begin
  if new.user_id is distinct from old.user_id then
    raise exception 'bookings.user_id cannot be changed';
  end if;
  if new.desk_id is distinct from old.desk_id then
    raise exception 'bookings.desk_id cannot be changed';
  end if;
  if new.day <> old.day then
    raise exception 'bookings.day cannot be changed';
  end if;
  return new;
end;
$$;

create or replace function public.bookings_enforce_rls()
returns trigger
language plpgsql
as $$
begin
  if new.day < current_date then
    raise exception 'bookings can only be made for today or a later day';
  end if;
  if not public.can_book(new.desk_id, new.day) then
    raise exception 'booking not allowed';
  end if;
  return new;
end;
$$;

create trigger bookings_enforce_rls
before insert or update on public.bookings
for each row execute function public.bookings_enforce_rls();

