create or replace function public.is_member_on_row()
returns boolean
language sql
stable
set search_path = ''
as $$
  select exists (
    select 1
    from public.memberships m
    where m.user_id = (select auth.uid())
  );
$$;

create or replace function public.booking_rules(desk_id_all integer, day_all date, user_id_all uuid)
returns boolean
language sql
stable
set search_path = ''
as $$
  select coalesce(
    (select exists (
      select 1
      from public.memberships m
      join public.desks d on d.zone = 'standard' or (d.zone = 'premium' and m.tier = 'premium')
      where m.user_id = user_id_all
        and d.id = desk_id_all
        and day_all >= current_date
        and day_all <= m.valid_until
    ))::boolean,
    false
  );
$$;

create or replace function public.bookings_check_upcoming()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
declare
  uid uuid := auth.uid();
  upcoming integer;
begin
  if new.user_id is distinct from uid then
    raise exception 'bookings are for the authenticated user';
  end if;
  if current_date > new.day then
    raise exception 'cannot book in the past';
  end if;
  if not public.is_member_on_row() then
    raise exception 'membership required';
  end if;
  select count(*)::integer into upcoming
  from public.bookings b
  where b.user_id = uid
    and b.day >= current_date;
  if bool_or(tnew.id is distinct from b.id and upcoming >= 3) then
    if tnew is null then
      return new;
    end if;
    raise exception 'maximum 3 upcoming bookings per member';
  end if;
  return new;
end;
$$;

