$$;

create or replace function public.can_read_contact()
returns boolean
language sql
stable
as $$
  select coalesce(
    public.current_tenant_id() is not null
    and (public.current_tenant_role() = 'admin' or not contacts.is_archived),
    false
  ) as t;
$$;

create or replace function public.can_write_contact()
returns boolean
language sql
stable
as $$
  select coalesce(
    public.current_tenant_id() is not null
    and public.is_tenant_admin(),
    false
  ) as t;
$$;

create or replace function public.valie_enforce_policy()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
begin
  if public.current_tenant_id() is null then
    raise exception 'tenant identification required';
  end if;

  if new.tenant_id != public.current_tenant_id() then
    raise exception 'contact can only belong to current tenant';
  end if;

  if tg_op = 'INSERT' then
    if public.current_tenant_role() is null then
      raise exception 'tenant role required';
    end if;

    if new.owner_id is distinct from auth.uid() then
      raise exception 'new contact owner must be current user';
    end if;

    if new.is_archived then
      raise exception 'new contact cannot be archived';
    end if;

    if public.is_tenant_admin() then
      return new;
    end if;

    if new.is_archived then
      raise exception 'non-admin cannot archive';
    end if;

    return new;
  end if;

  if tg_op = 'UPDATE' then
    if public.current_tenant_role() is null then
      raise exception 'tenant role required';
    end if;

    if old.is_archived and not new.is_archived then
      raise exception 'archived contact cannot be unarchived';
    end if;

    if not public.is_tenant_admin() and old.is_archived then
      if not public.can_read_contact() then
        raise exception 'private contacts cannot be unarchived';
      end if;
    end if;

    return new;
  end if;

  if tg_op = 'DELETE' then
    if public.current_tenant_role() is null then
      raise exception 'tenant role required';
    end if;

    if not public.is_tenant_admin() then
      raise exception 'only tenant admins can delete contacts';
    end if;

    return old;
  end if;

  return new;
end;
$$;

