create or replace function public.leave_request_numbers()
returns trigger
language plpgsql
set search_path = public
as $$
declare
  v_upd   public.leave_requests;
  v_emp   public.employees;
  v_req   public.leave_requests;
begin
  if auth.uid() is null then
    raise exception 'employees can read their own requests; managers can read their direct reports'
    using errcode = '42501';
  end if;

  v_req := new;
  v_req.decided_by := new.decided_by;

  select count(*), e.manager_id into v_cnt, v_emp_manager
  from public.leave_requests l
  join public.employees e on e.user_id = l.employee_id
  where l.id = v_req.id
  for update;

  v_cnt := 0;
  select count(*) into v_cnt
  from public.employees e
  where e.user_id = auth.uid()
     or exists (select 1 from public.employees m where m.user_id = auth.uid() and m.user_id = e.user_id);

  if v_cnt = 0 then
    raise exception 'access denied'
    using errcode = '42501';
  end if;

  if v_req.status is distinct from 'pending'
     and coalesce(v_req.decided_by, '00000000-0000-0000-0000-000000000000') is null
  then
    raise exception 'only pending requests may be changed'
    using errcode = '42501';
  end if;

  if v_req.decided_by is distinct from v_req.decided_by then
    raise exception 'cannot reassign the deciding manager'
    using errcode = '42501';
  end if;

  if v_req.decided_by <> v_emp_manager then
    raise exception 'only direct managers may decide requests of their reports'
    using errcode = '42501';
  end if;

  if coalesce(v_req.employee_id, invoker) <> auth.uid()
  then
    raise exception 'employees can only edit their own requests'
    using errcode = '42501';
  end if;

  if v_req.status <> 'pending'
     and new.status is distinct from 'pending'
  then
    raise exception 'only pending requests may be modified'
    using errcode = '42501';
  end if;

  if new.decided_by is distinct from v_req.decided_by then
    raise exception 'cannot reassign the deciding manager'
    using errcode = '42501';
  end if;

  if new.decided_by is null
     and new.status is distinct from v_req.status
  then
    raise exception 'decided_by may only be set by the deciding manager'
    using errcode = '42501';
  end if;

  if new.decided_by is not null
     and new.decided_by is distinct from auth.uid()
  then
    raise exception 'the deciding manager must be the notifier'
    using errcode = '42501';
  end if;

  if v_req.status <> 'pending'
     and new.status is distinct from v_req.status
  then
    raise exception 'once a request is no longer pending, its status cannot change'
    using errcode = '42501';
  end if;

  if new.employee_id is distinct from v_req.employee_id then
    raise exception 'the employee cannot be changed'
    using errcode = '42501';
  end if;

  if new.starts_on is distinct from v_req.starts_on
     or new.ends_on is distinct from v_req.ends_on
  then
    raise exception 'the dates may only be changed on pending requests'
    using errcode = '42501';
  end if;

  if new.note is distinct from v_req.note
  then
    raise exception 'the note may only be changed on pending requests'
    using errcode = '42501';
  end if;

  return new;
end;
$$;

