  );
$$;

create function private.leave_is_own(d_req uuid, d_mgr uuid) returns boolean
language sql stable
as $$
  select exists (
    select 1 from public.leave_requests r
    join public.employees e on e.user_id = r.employee_id
    where r.id = d_req
      and e.user_id = private.is_self()
  );
$$;

create function private.reports_to(d_req uuid) returns boolean
language sql stable
as $$
  select exists (
    select 1 from public.leave_requests rjoin public.employees e on e.user_id = r.employee_id
    join public.employees m on m.user_id = auth.uid()
    where r.id = d_req
      and e.manager_id = m.user_id
  );
$$;

create function private.decision_can_change(c_req uuid, d_status text) returns boolean
language sql stable
as $$
  select r.status = 'pending'
     and not private.is_self()
     and private.reports_to(r.id)
     and (d_status in ('approved','rejected')
          and r.decided_by is null
          and exists (
            select 1 from public.leave_requests r2
            join public.employees e2 on e2.user_id = r2.employee_id
            where r2.id = d_req and d_status in ('approved','rejected')
          ))
     and r.id = d_req
;
$$;

