create function public.enforce_time_entry_eligibility()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_project_id bigint := (select p.project_id from public.projects p where p.id = coalesce(new.project_id, new.project_id));
  v_period_id  bigint := (select p.id      from public.periods p where p.id = new.period_id);
  v_is_locked  boolean := (select p.is_locked from public.periods p where p.id = v_period_id);
begin
  if new.id is not null and new.id is distinct from old.id
     and exists (select 1 from public.time_entries e where e.id = new.id and e.user_id <> auth.uid()) then
    raise exception 'Only the entry owner can modify the row';
  end if;

  if auth.role() <> 'service_role'
     and exists (select 1 from public.assignments a where a.project_id = new.project_id and a.user_id = auth.uid()) = false then
    raise exception 'Entry project is not assigned to you';
  end if;

  if v_is_locked
     and (auth.role() <> 'service_role'
          or (new.id is not null and new.id is distinct from old.id)) then
    raise exception 'Cannot modify time entries in a locked period';
  end if;

  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.user_id <> auth.uid()
     or new.project_id <> v_project_id
     or v_is_locked then
    raise exception 'Operation not permitted';
  end if;

  return new;
end
$$;

