  if new.user_id is distinct from auth.uid() then
    raise exception 'Time entry must be owned by the calling user';
  end if;

  if not exists (select 1 from public.current_projects() p where p.id = new.project_id) then
    raise exception 'Time entry must be for an assigned project';
