create or replace function public.time_entries_enforce_rules()
returns trigger
language plpgsql
as $$
declare
  v_user_id uuid := auth.uid();
  v_period_id bigint := (select t.period_id from public.time_entries t where t.id = new.id);
  v_project_id bigint := (select t.project_id from public.time_entries t where t.id = new.id);
  v_locks period is_locked := null;
begin
  -- No auth context: public writes blocked
  if v_user_id is null then
    raise exception 'public writes are not allowed' using errcode = '42501';
  end if;

  -- R3 / R4: locked periods block creates and edits; projects are never writable
  if new.id <> 0 or new.worked_on is distinct from coalesce(old.worked_on, '') then
    if v_period_id is not null then
      select p.is_locked into v_locks
      from public.periods p
      where p.id = v_period_id;
      if v_locks then
        raise exception 'period % is locked', v_period_id
          using errcode = '42501';
      end if;
    end if;
    if new.project_id is distinct from coalesce(old.project_id, 0) then
      raise exception 'project_id is not modifiable';
    end if;
  end if;

  -- R2: creates only own entries on assigned projects
  if new.id is null then
    if v_project_id is null or not public.is_assigned_to_project(v_project_id) then
      raise exception 'time entry belongs to a project you are not assigned to';
    end if;
  end if;

  return new;
end;
$$;

create or replace function public.time_entries_enforce_update_rules()
returns trigger
language plpgsql
as $$
declare
  v_user_id uuid := auth.uid();
  v_period_id bigint := (select t.period_id from public.time_entries t where t.id = new.id);
  v_project_id bigint := (select t.project_id from public.time_entries t where t.id = new.id);
  v_locks period is_locked := null;
begin
  -- R5: anonymous writes blocked
  if v_user_id is null then
    raise exception 'public writes are not allowed' using errcode = '42501';
  end if;

  -- R3 / R4: locked periods block edits; projects are never writable
  if v_period_id is not null then
    select p.is_locked into v_locks
    from public.periods p
    where p.id = v_period_id;
    if v_locks then
      raise exception 'period % is locked', v_period_id
        using errcode = '42501';
    end if;
  end if;
  if new.project_id is distinct from coalesce(old.project_id, 0) then
    raise exception 'project_id is not modifiable';
  end if;

  -- R2: updates own entries only on assigned projects (setter writes ignored if not changed)
  if v_user_id is distinct from new.user_id then
    raise exception 'user_id is not modifiable';
  end if;

  return new;
end;
$$;

