as $$
begin
  if new.revoked_at is null then
    raise exception 'revoked_at may not be left unset';
  end if;
  -- Preserve all other columns, only revoke is allowed to change
  if old.id is distinct from new.id
     or old.user_id is distinct from new.user_id
     or old.name is distinct from new.name
     or old.key_hash is distinct from new.key_hash
     or old.last4 is distinct from new.last4
     or old.created_at is distinct from new.created_at
     or old.revoked_at is distinct from new.revoked_at then
