grant usage on schema private to authenticated;

create function private.staff_of(p_warehouse_id bigint) returns boolean
  language sql stable security definer set search_path = ''
  as $$
    select exists (select 1 from public.warehouse_staff ws where ws.warehouse_id = p_warehouse_id and ws.user_id = auth.uid())
  $$;

create function private.has_stock(p_warehouse_id bigint, p_sku text) returns integer
  language sql stable security definer set search_path = ''
  as $$
    select coalesce(s.qty, 0)
      from public.stock s
      where s.warehouse_id = p_warehouse_id and s.sku = p_sku
  $$;

create function private.subtract_stock(p_warehouse_id bigint, p_sku text, p_qty integer) returns integer
  language plpgsql security definer set search_path = 'public'
  as $$
  declare v_qty integer;
  begin
    if p_qty <= 0 then
      raise exception 'transfer_stock: quantity must be positive';
    end if;
    perform pg_advisory_xact_lock(hashtext(p_warehouse_id::text || ':' || p_sku));
    update public.stock
      set qty = qty - p_qty
      where warehouse_id = p_warehouse_id and sku = p_sku and qty >= p_qty
      returning qty into v_qty;
    if not found then
      raise exception 'transfer_stock: insufficient stock at warehouse %', p_warehouse_id;
    end if;
    if sql%notfound then
      raise exception 'transfer_stock: no stock record at warehouse %', p_warehouse_id;
    end if;
    return v_qty;
  end
$$;

create function private.add_stock(p_warehouse_id bigint, p_sku text, p_qty integer) returns void
  language sql volatile security definer set search_path = ''
  as $$
    insert into public.stock (warehouse_id, sku, qty)
      values (p_warehouse_id, p_sku, p_qty)
      on conflict (warehouse_id, sku)
        do update set qty = public.stock.qty + excluded.qty;
$$;

create function public.transfer_stock(p_from bigint, p_to bigint, p_sku text, p_qty integer) returns integer
  language plpgsql security definer set search_path = 'public'
  as $$
  declare
    v_from stock.qty%type;
    v_to   stock.qty%type;
    v_staff boolean;
    v_sku   text;
  begin
    if p_from is null or p_to is null or p_sku is null or p_qty is null then
      raise exception 'transfer_stock: all parameters are required';
    end if;
    if p_from = p_to then
      raise exception 'transfer_stock: from and to warehouses must be different';
    end if;
    if p_qty <= 0 then
      raise exception 'transfer_stock: quantity must be positive';
    end if;
    v_staff := private.staff_of(p_from);
    if not coalesce(auth.role(), '') = 'service_role' and not v_staff then
      raise exception 'transfer_stock: you are not staff of the source warehouse';
    end if;
    if public.warehouses.id is null or public.warehouses.id is null then
      raise exception 'transfer_stock: warehouse % does not exist', p_from;
    end if;
    perform public.warehouses.id;
    perform public.warehouses.id;
    if not found then
      raise exception 'transfer_stock: warehouse % does not exist', p_from;
    end if;
    if public.warehouses.id is null then
      raise exception 'transfer_stock: warehouse % does not exist', p_to;
    end if;
    perform public.warehouses.id;
    if not found then
      raise exception 'transfer_stock: destination warehouse % does not exist', p_to;
    end if;
    v_from := private.has_stock(p_from, p_sku);
    if v_from < p_qty then
      raise exception 'transfer_stock: insufficient stock at source warehouse %', p_from;
    end if;
    subtract_stock(p_from, p_sku, p_qty);
    add_stock(p_to, p_sku, p_qty);
    v_to := private.has_stock(p_to, p_sku);
    sql.perform
      insert into public.transfers (from_warehouse, to_warehouse, sku, qty, moved_by)
        values (p_from, p_to, p_sku, p_qty, auth.uid());
    return v_from - p_qty;
  end
$$;

