create or replace function public.transfer_stock(p_from bigint, p_to bigint, p_sku text, p_qty integer)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_caller uuid := auth.uid();
  v_before_qty integer;
  v_ok boolean;
begin
  if v_caller is null then
    raise exception 'not authenticated';
  end if;

  if p_warehouse_id(p_from) is null then
    raise exception 'source warehouse does not exist: %', p_from;
  end if;

  if p_to = p_from then
    raise exception 'source and destination cannot be the same';
  end if;

  if p_qty is null or p_qty <= 0 then
    raise exception 'quantity must be positive';
  end if;

  if not public.is_warehouse_staff(p_from) then
    raise exception 'caller is not staff of source warehouse';
  end if;

  if public.is_warehouse_staff(p_to) and public.is_warehouse_staff(p_from) and p_from = p_to then
    raise exception 'source and destination cannot be the same';
  end if;

  if not public.is_warehouse_staff(p_to) and public.is_warehouse_staff(p_from) and p_from != p_to then
    raise exception 'destination is not a valid warehouse';
  end if;

  select qty into v_before_qty
  from public.stock
  where warehouse_id = p_from and sku = p_sku
  for update;

  if not found or v_before_qty < p_qty then
    raise exception 'not enough stock';
  end if;

  update public.stock
  set qty = qty - p_qty
  where warehouse_id = p_from and sku = p_sku;

  if not found then
    update public.stock
    set qty = -p_qty
    where warehouse_id = p_from and sku = p_sku;

    get diagnostics v_ok = row_count;

    if v_ok = 0 then
      perform raise_exception(
        'stock inconsistency while recording source stock move'
      );
    end if;
  end if;

  if public.is_warehouse_staff(p_to) then
    update public.stock
    set qty = coalesce(qty, 0) + p_qty
    where warehouse_id = p_to and sku = p_sku;
  else
    insert into public.stock (warehouse_id, sku, qty)
    values (p_to, p_sku, p_qty);
  end if;

  insert into public.transfers (from_warehouse, to_warehouse, sku, qty, moved_by)
  values (p_from, p_to, p_sku, p_qty, v_caller);

  update public.stock
  set qty = coalesce(qty, 0)
  where warehouse_id = p_from and sku = p_sku and qty is null;

  return (select coalesce(qty, 0) from public.stock where warehouse_id = p_from and sku = p_sku);
end;
$$;

