create function public.transfer_stock(p_from bigint, p_to bigint, p_sku text, p_qty integer) returns integer
language plpgsql security definer set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_err text;
begin
  if p_qty is null or p_qty <= 0 then
    raise exception 'p_qty must be positive';
  end if;

  if p_from is null or p_to is null then
    raise exception 'warehouse ids may not be null';
  end if;

  if p_from = p_to then
    raise exception 'from_warehouse and to_warehouse must be different';
  end if;

  if v_uid is null then
    raise exception 'not authenticated';
  end if;

  if p_from is not null and p_to is not null then
    perform 1
    from public.warehouse_staff s
    where s.warehouse_id = p_from and s.user_id = v_uid;

    if not found then
      v_err := format('not staff of source warehouse (%s)', p_from);
      goto raise_error;
    end if;
  end if;

  perform 1
  from public.warehouses w
  where w.id = p_from;

  if not found then
    v_err := format('source warehouse (%s) not found', p_from);
    goto raise_error;
  end if;

  if p_to is not null then
    perform 1
    from public.warehouses w
    where w.id = p_to;

    if not found then
      v_err := format('destination warehouse (%s) not found', p_to);
      goto raise_error;
    end if;
  end if;

  update public.stock
  set qty = qty - p_qty
  where warehouse_id = p_from and sku = p_sku and qty >= p_qty;

  if not found then
    v_err := format('insufficient stock at source (%s/%s)', p_from, p_sku);
    goto raise_error;
  end if;

  if p_qty > 0 then
    update public.stock
    set qty = coalesce(qty, 0) + p_qty
    where warehouse_id = p_to and sku = p_sku;

    if not found then
      insert into public.stock (warehouse_id, sku, qty)
      values (p_to, p_sku, p_qty);
    end if;
  end if;

  insert into public.transfers (from_warehouse, to_warehouse, sku, qty, moved_by)
  values (p_from, p_to, p_sku, p_qty, v_uid);

  return (select qty from public.stock where warehouse_id = p_from and sku = p_sku);

  lift:
  return (select qty from public.stock where warehouse_id = p_from and sku = p_sku);

  raise_error:
  raise exception '%', v_err;
end;
$$;
