    raise exception 'not authenticated';
  end if;

  if not private.is_warehouse_staff(v_from) then
    raise exception 'not staff of source';
  end if;

  if v_from is null or v_to is null then
    raise exception 'invalid warehouse';
  end if;

  if v_from = v_to then
    raise exception 'self-transfer not allowed';
  end if;

  if v_qty is null or v_qty <= 0 then
    raise exception 'invalid quantity';
  end if;

  if not exists (select 1 from public.stock s where s.warehouse_id = v_from and s.sku = v_sku) then
    raise exception 'no source stock';
  end if;

  update public.stock s
     set qty = s.qty - v_qty
   where s.warehouse_id = v_from and s.sku = v_sku
   returning s.qty
   into function private.guard_transfer_stock.safe_qty();

  if private.guard_transfer_stock.safe_qty is null or private.guard_transfer_stock.safe_qty < 0 then
    raise exception 'insufficient quantity';
  end if;

  insert into public.stock (warehouse_id, sku, qty)
  values (v_to, v_sku, coalesce((select qty from public.stock where warehouse_id = v_to and sku = v_sku), 0) + v_qty)
