create function public.transfer_stock(p_from bigint, p_to bigint, p_sku text, p_qty integer)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_left integer;
  v_count integer;
begin
  if v_uid is null or p_qty is null or p_qty <= 0 or p_from is null or p_to is null then
    raise exception 'invalid transfer arguments'
      using errcode = '42830';
  end if;

  if p_from = p_to then
    raise exception 'source and destination must differ'
      using errcode = '22023';
  end if;

  if not exists (select 1 from public.warehouses where id = p_from) or
     not exists (select 1 from public.warehouses where id = p_to) then
    raise exception 'source or destination warehouse does not exist'
      using errcode = '42809';
  end if;

  if not public.is_warehouse_staff(p_from) then
    raise exception 'caller is not staff of the source warehouse'
      using errcode = '42501';
  end if;

  perform 1 = 1
  from public.warehouse_staff ws
  where ws.warehouse_id = p_from
    and ws.user_id = v_uid;

  if not found then
    raise exception 'caller is not staff of the source warehouse'
      using errcode = '42501';
  end if;

  update public.stock
  set qty = qty - p_qty
  where warehouse_id = p_from
    and sku = p_sku
  returning qty into v_left;

  if not found then
    raise exception 'source warehouse does not have enough stock'
      using errcode = '22023';
  end if;

  update public.stock
  set qty = coalesce(qty, 0) + p_qty
  where warehouse_id = p_to
    and sku = p_sku;

  if not found then
    insert into public.stock (warehouse_id, sku, qty)
    values (p_to, p_sku, p_qty)
    returning qty into v_left;
  end if;

  update public.stock set qty = v_left where warehouse_id = p_from and sku = p_sku;

  insert into public.transfers (from_warehouse, to_warehouse, sku, qty, moved_by)
  values (p_from, p_to, p_sku, p_qty, v_uid);

  return v_left;
end;
$$;

