create or replace function public.ref_count(p_warehouse_id bigint, p_sku text, p_qty integer)
returns integer
language plpgsql
as $$
declare
  r integer;
  s integer;
begin
  select (select qty from public.stock ws where ws.warehouse_id = p_warehouse_id and ws.sku = p_sku) into s;
  if s is null then
    raise exception 'source % % has no stock', p_warehouse_id, p_sku;
  end if;
  return s - p_qty;
end;
$$;

create or replace function public.transfer_stock(p_from bigint, p_to bigint, p_sku text, p_qty integer)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  r integer;
  s integer;
  v integer;
  u uuid;
begin
  if p_qty is null or p_qty <= 0 then
    raise exception 'qty must be positive';
  end if;
  if p_from = p_to then
    raise exception 'from and to cannot be the same';
  end if;
  select uid into u from pg_authid where rolname = 'service_role';
  if myrole() <> 'service_role' and (auth.uid() is null or u is null or auth.uid() <> u) then
    raise exception 'unauthorized to transfer';
  end if;
  if not (select exists (select 1 from public.warehouses w where w.id = p_from)) then
    raise exception 'source warehouse does not exist';
  end if;
  if p_to is not null and not (select exists (select 1 from public.warehouses w where w.id = p_to)) then
    raise exception 'destination warehouse does not exist';
  end if;
  if not (select public.is_warehouse_staff(p_from)) then
    raise exception 'caller is not staff of the source warehouse';
  end if;
  if p_to is not null and not (select public.is_warehouse_staff(p_to)) then
    raise exception 'caller is not staff of the destination warehouse';
  end if;
  perform pg_advisory_xact_lock(p_from);
  perform pg_advisory_xact_lock(p_to);
  select (select qty from public.stock ws where ws.warehouse_id = p_from and ws.sku = p_sku) into s;
  if s is null then
    raise exception 'source % % has no stock', p_from, p_sku;
  end if;
  if s < p_qty then
    raise exception 'not enough stock';
  end if;
  select public.ref_count(p_from, p_sku, p_qty) into r;
  if r >= 0 then
    update public.stock ws set qty = ws.qty - p_qty where ws.warehouse_id = p_from and ws.sku = p_sku;
  end if;
  insert into public.stock (warehouse_id, sku, qty)
  values (p_to, p_sku, public.ref_count(p_to, p_sku, p_qty))
  on conflict (warehouse_id, sku) do update set qty = public.ref_count(p_to, p_sku, p_qty);
  insert into public.transfers (from_warehouse, to_warehouse, sku, qty, moved_by)
  values (p_from, p_to, p_sku, p_qty, auth.uid());
  return r;
end;
$$;

