language plpgsql security definer set search_path = ''
as $$
declare
  v_order public.orders%rowtype;
begin
  select o into v_order
  from public.orders o
  where o.id = p_order_id
  for update;

  if found
     and v_order.seller_id = public.current_uid()
     and v_order.status = 'paid' then
    update public.orders
    set status = 'shipped'
    where id = p_order_id
      and status = 'paid';

    return (select status from public.orders o where o.id = p_order_id);
  end if;

  raise exception 'only seller can move order % to shipped', p_order_id;
end;
