create or replace function public.release_funds(p_order_id bigint) returns text
language plpgsql security definer set search_path = ''
as $$
declare
  v_order public.orders%rowtype;
begin
  select o into v_order
  from public.orders o
  where o.id = p_order_id
  for update;

  if found
     and v_order.buyer_id = public.current_uid()
     and v_order.status = 'shipped' then
    update public.orders
    set status = 'released'
    where id = p_order_id
      and status = 'shipped';

    return (select status from public.orders o where o.id = p_order_id);
  end if;

