  select o into v_order
  from public.orders o
  where o.id = p_order_id
  for update;

  if not found
     or v_order.seller_id is distinct from public.current_uid() then
    raise exception 'only seller can refund order %', p_order_id;
  end if;

  v_status := (select status from public.orders o where o.id = p_order_id);

  if v_status not in ('paid', 'shipped') then
    raise exception 'order % status cannot be refunded: %', p_order_id, v_status;
  end if;

  update public.orders
  set status = 'refunded'
  where id = p_order_id
    and status in ('paid', 'shipped');

  if sql%rowcount = 0 then
    raise exception 'order % not in refundable status', p_order_id;
  end if;

  return 'refunded';
end;
$$;

