create or replace function public.checkins_guard()
returns trigger
language plpgsql
as $$
declare
  _checkin public.checkins%rowtype := new;
begin
  if coalesce(current_setting('request.jwt.claim.role'), 'anon') not in ('service_role', 'authenticated') then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if (_checkin.user_id is distinct from auth.uid()) then
      return new;
    end if;

    if (select e.starts_at <= now() and now() < e.ends_at from public.events e where e.id = _checkin.event_id) is not true then
      return new;
    end if;

    if exists (
      select 1 from public.checkins c
      where c.event_id = _checkin.event_id
        and c.user_id = _checkin.user_id
        and c.checked_in_at is not distinct from _checkin.checked_in_at
    ) then
      return new;
    end if;
  elsif tg_op = 'UPDATE' or tg_op = 'DELETE' then
    return null;
  end if;

  return new;
end;
$$;

