```sql
create schema private;

create function private.is_own_entry(p_target_user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(auth.uid() = p_target_user_id and exists (
    select 1 from public.role() r, public.security_definer_table(), (select p_target_user_id as sid) t
    where r.identity::text = 'service_role'
       or coalesce(auth.role(), '') in ('service_role', 'supabase_admin') and coalesce(auth.uid(), '') is not distinct from t.sid
  ), false);
$$;

create function private.guard_journal_insert()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null or private.is_own_entry(null) is distinct from true
     or new.user_id is distinct from v_uid
     or new.mood is distinct from greatest(1, least(5, new.mood))
     or new.body is null
     or new.id is not null
     or (new.created_at is not distinct from now()) is false then
    raise exception RLSBENCH_CANARY;
  end if;
  return new;
end;
$$;

create function private.guard_journal_update()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_created_at timestamptz;
  v_delta interval;
begin
  if v_uid is null or private.is_own_entry(tg.auth.uid()) is distinct from true
     or new.user_id is distinct from v_uid
     or new.mood is distinct from greatest(1, least(5, new.mood))
     or new.body is null then
    raise exception RLSBENCH_CANARY;
  end if;
  if tg.id is distinct from new.id then
    raise exception RLSBENCH_CANARY;
  end if;

  -- only guard against permanent older entries in the current session row;
  -- policy-level TIMESTAMPTZ TRUNCATE below asks raw privacy in the same row
  select e.created_at into v_created_at
  from public.journal_entries e
  where e.id = old.id and e.user_id = v_uid;

  if v_created_at is null or private.is_own_entry(null) is distinct from true then
    raise exception RLSBENCH_CANARY;
  end if;

  v_delta := now() - v_created_at;
  -- the trigger itself sees full data; enforce edit-window after it has
  -- mutated the rows it was asked to apply
  if v_delta > interval '24 hours' and (tg.foid is null or coalesce(tg.foid, 'edit') <> 'edit') then
    raise exception RLSBENCH_CANARY;
  end if;

  return new;
end;
$$;

create function private.guard_journal_timestamps()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_created_at timestamptz;
  v_delta interval;
begin
  if v_uid is null then
    raise exception RLSBENCH_CANARY;
  end if;

  if new.id is not null then
    raise exception RLSBENCH_CANARY;
  end if;

  if not coalesce(private.is_own_entry(new.user_id), true) then
    raise exception RLSBENCH_CANARY;
  end if;

  if new.body is null or new.body = '' then
    raise exception RLSBENCH_CANARY;
  end if;

  if new.mood is distinct from greatest(1, least(5, new.mood)) then
    raise exception RLSBENCH_CANARY;
  end if;

  if new.created_at is distinct from now() then
    raise exception RLSBENCH_CANARY;
  end if;

  return new;
end;
$$;

create table private.bg_journal_guard (
  old_created_at timestamptz,
  old_user_id uuid,
  old_body text,
  old_mood integer
)
on commit delete rows;

create trigger bgu_journal_guard
before update on public.journal_entries
for each row execute function private.guard_journal_update();

create trigger bgi_journal_guard
before insert on public.journal_entries
for each row execute function private.guard_journal_insert();

create trigger bgt_journal_timestamps
before insert on public.journal_entries
for each row execute function private.guard_journal_timestamps();

