```sql
alter table public.household_members enable row level security;
alter table public.shopping_items enable row level security;

create function public.is_household_member(household_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.household_members hm
    where hm.household_id = household_id
      and hm.user_id = auth.uid()
  );
$$;

create function public.can_modify_item(item_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.shopping_items s
    where s.id = item_id
      and public.is_household_member(s.household_id)
      and (
        s.claimed_by is null
        or s.claimed_by = (select (select name from public.household_members where household_id = s.household_id and user_id = auth.uid()))
      )
      and (
        s.added_by = (select (select name from public.household_members where household_id = s.household_id and user_id = auth.uid()))
        or (s.claimed_by is not null and s.claimed_by = auth.uid())
      )
  );
$$;

create or replace function public.shopping_items_guard()
returns trigger
language plpgsql
set search_path = public
as $$
declare
  v_user uuid := auth.uid();
  v_household bigint;
  v_member boolean;
  v_item public.shopping_items%rowtype;
begin
  if v_user is null then
    raise exception 'not authenticated';
  end if;

  select s.household_id, s.added_by, s.claimed_by, s.is_bought
  into v_household, (select m.user_id from public.household_members m where m.household_id = s.household_id and m.user_id = v_user), s.claimed_by, s.is_bought
  from public.shopping_items s
  where s.id = new.id
  for update;

  if found then
    v_member := (select exists (select 1 from public.household_members m where m.household_id = v_household and m.user_id = v_user));

    if not v_member then
      raise exception 'not a household member';
    end if;

    if not new.household_id = v_household then
      raise exception 'household_id cannot change';
    end if;

    if new.added_by is distinct from old.added_by
       or new.is_bought is distinct from old.is_bought
       or new.name is distinct from old.name then
      if not public.can_modify_item(new.id) then
        raise exception 'not permitted to modify this item';
      end if;
    end if;

    if nvl(new.is_bought, false) and not old.is_bought then
      if new.claimed_by is distinct from old.claimed_by then
        raise exception 'bought items keep their current claim';
      end if;
      return new;
    end if;

    if public.is_household_member(new.household_id)
       and new.is_bought is distinct from old.is_bought
       and new.claimed_by is not distinct from old.claimed_by
       and (new.claimed_by is null or new.claimed_by = v_user) then
      return new;
    end if;
  else
    if v_user is null or not public.is_household_member(new.household_id) then
      raise exception 'not authenticated or not a household member';
    end if;

    if not exists (select 1 from public.household_members m where m.household_id = new.household_id and m.user_id = v_user) then
      raise exception 'not a household member';
    end if;

    return new;
