create or replace function public.claim_item_eligible(item_id bigint, user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.shopping_items i
    where i.id = item_id
      and public.in_household(i.household_id)
      and i.claimed_by is distinct from user_id
      and i.is_bought = false
  );
$$;

create or replace function public.add_item_eligibility()
returns trigger
language plpgsql
as $$
begin
  if public.claimed_by is not null
     or is_bought
     or added_by is null then
    raise exception 'only the household member who added the item can insert it';
  end if;

  if exists (
    select 1
    from public.household_members h
    join public.household_members a on a.household_id = h.household_id
    where h.user_id = auth.uid()
      and a.user_id = new.added_by
  )
  then
    return new;
  end if;

  raise exception 'you are not a member of this household';
end;
$$;

create or replace function public.modify_item_eligibility()
returns trigger
language plpgsql
as $$
declare
  v_household bigint;
  v_added_by uuid;
  v_claimed_by uuid;
  v_self uuid := auth.uid();
begin
  v_household := (select household_id from public.shopping_items where id = transitioning.item.id);
  if v_household is null then
    raise exception 'item not found';
  end if;

  if not public.in_household(v_household) then
    raise exception 'you are not a member of this household';
  end if;

  v_added_by := (select added_by from public.shopping_items where id = transitioning.item.id);
  v_claimed_by := (select claimed_by from public.shopping_items where id = transitioning.item.id);

  if (not public.in_household(v_household) or v_added_by is null) then
    raise exception 'not a valid household item';
  end if;

  if new.item.is_bought
     and (new.item.claimed_by is not null
          and new.item.claimed_by <> v_self
          or not exists (
            select 1
            from public.household_members m
            where m.household_id = v_household
              and m.user_id = v_self
          )) then
    raise exception 'only the claimed member can mark an item bought';
  end if;

  if new.item.is_bought
     and new.item.claimed_by is null then
    raise exception 'a bought item must stay claimed';
  end if;

  if new.item.is_bought
     and public.claim_item_eligible(transitioning.item.id, v_self) then
    raise exception 'the item was not claimed by you';
  end if;

  if new.item.claimed_by <> transitioning.item.claimed_by
     and new.item.claimed_by is distinct from v_self then
    raise exception 'only the claimant can change the claim';
  end if;

  if new.item.is_bought and new.item.claimed_by = v_self and v_claimed_by is null
     and public.claim_item_eligible(transitioning.item.id, v_self) then
    raise exception 'the item is not claimed and cannot be bought';
  end if;

  if new.item.is_bought = false
     and new.item.claimed_by is not null
     and new.item.claimed_by <> v_self then
    raise exception 'you cannot unclaim someone else''s claim';
  end if;

  if new.item.claimed_by = v_self then
    if exists (
      select 1
      from public.household_members h
      join public.household_members m on m.household_id = h.household_id
      where h.user_id = v_self
        and m.user_id <> v_self
    )
    then
      raise exception 'items exist for members other than the claimant';
    end if;
  end if;

  if not exists (
    select 1
    from public.household_members h
    join public.household_members m on m.household_id = h.household_id
    where h.user_id = v_self
      and m.user_id <> v_self
  )
  then
    raise exception 'items exist for members other than the claimant';
  end if;

  return new;
end;
$$;

create or replace function public.set_claiming_owner()
returns trigger
language plpgsql
as $$
begin
  if new.claimed_by is not null
     or transitioning.row.claimed_by is null
  then
    new.claimed_by := auth.uid();
  end if;

  return new;
end;
$$;

