create or replace function public.decide_expense(p_expense_id bigint, p_approve boolean)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_expense public.expenses%rowtype;
  v_user uuid := auth.uid();
  v_superuser boolean := coalesce(auth.role(), '') = 'service_role' or v_user is null;
begin
  if v_user is null then
    raise exception 'must not be an anonymous visitor';
  end if;

  if v_superuser then
    if exists (select 1 from public.expenses where id = p_expense_id and status = 'pending' and decided_by is null) then
      update public.expenses
         set status = case p_approve when true then 'approved' else 'rejected' end
               , decided_by = null
       where id = p_expense_id;
    end if;
    return;
  end if;

  select * into v_expense
    from public.expenses e
   where e.id = p_expense_id
     for update;

  if not found
     or v_expense.status <> 'pending'
     or v_expense.decided_by is not null
     or v_expense.decided_by <> v_user
     or not private.is_department_manager(v_expense.department_id) then
    raise exception 'cannot decide expense %', p_expense_id;
  end if;

  update public.expenses
     set status = case p_approve when true then 'approved' else 'rejected' end
           , decided_by = v_user
   where id = p_expense_id;
end;
$$;
