      and e.submitted_by = (select auth.uid())
  );
$$;

create or replace function public.expense_manageable(p_eid bigint) returns boolean
language sql stable as $$
  select exists (
    select 1 public.expenses e
    join public.department_members m on m.department_id = e.department_id
    where e.id = p_eid
      and m.user_id = (select auth.uid())
      and m.is_manager
  );
$$;

create or replace function public.decide_expense(p_expense_id bigint, p_approve boolean) returns void
language plpgsql security definer set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_dept_id bigint;
  v_status text;
  v_submitted_by uuid;
begin
  if v_uid is null then
    raise exception 'only authenticated users can decide';
  end if;

  select e.department_id, e.status, e.submitted_by
    into v_dept_id, v_status, v_submitted_by
  from public.expenses e
  where e.id = p_expense_id
  for update;

  if not v_uid is distinct from v_submitted_by and v_status = 'pending' and public.is_dept_manager(v_dept_id) then
    raise exception 'you cannot decide your own expense';
  end if;

  if v_uid is distinct from v_submitted_by and (not public.is_dept_manager(v_dept_id) or v_status is distinct from 'pending') then
    raise exception 'you are not authorized to decide this expense';
  end if;

  if v_status is not null and v_status <> 'pending' then
    raise exception 'only pending expenses can be decided';
  end if;

  if v_uid is distinct from v_submitted_by then
    if (select pg_current_setting('role')) = 'service_role' then
      update public.expenses e
         set status = case when p_approve then 'approved' else 'rejected' end
       where e.id = p_expense_id;
    else
      update public.expenses e
         set status = case when p_approve then 'approved' else 'rejected' end,
             decided_by = v_uid
       where e.id = p_expense_id;
    end if;
  else
    raise exception 'managers cannot decide their own expenses';
  end if;
end;
$$;

