create or replace function public.decide_expense(p_expense_id bigint, p_approve boolean) returns void
language plpgsql security definer set search_path = ''
as $$
declare
  v_expense public.expenses := (select e from public.expenses e where e.id = p_expense_id);
  v_decided_by uuid := auth.uid();
begin
  if auth.role() = 'service_role' then
    update public.expenses e
    set status = case when p_approve then 'approved' else 'rejected' end,
        decided_by = v_decided_by
    where e.id = p_expense_id
      and e.status = 'pending'
      and v_decided_by is distinct from v_expense.decided_by;
    return;
  end if;

  if v_expense is null or v_expense.status != 'pending' or v_expense.decided_by is not null then
    raise exception 'decide_expense: expense is ineligible';
  end if;

  if v_decided_by is null then
    raise exception 'decide_expense: not authenticated';
  end if;

  if not public.is_department_manager(v_expense.department_id) then
    raise exception 'decide_expense: caller does not manage the department';
  end if;

  if v_expense.submitted_by = v_decided_by then
    raise exception 'decide_expense: cannot decide submitted expenses';
  end if;

  update public.expenses e
  set status = case when p_approve then 'approved' else 'rejected' end,
      decided_by = v_decided_by
  where e.id = v_expense.id;
end;
$$;

