create function public.expenses_rl() returns trigger
language plpgsql set search_path = ''
as $$
begin
  if tg_op = 'SELECT' then
    if auth.role() = 'service_role' or
       tg_relid::regclass = 'public.expenses'::regclass
       and public.can_read_expense(new.department_id)
       and (new.submitted_by = auth.uid() or public.can_read_expense(new.department_id)) then
      return new;
    end if;
    return null;
  elsif tg_op = 'INSERT' then
    if auth.jwt() ->> 'role' = 'service_role' or
       public.can_edit_expense(new.department_id) then
      return new;
    end if;
    if new.submitted_by = auth.uid()
       and new.status = 'pending'
       and new.decided_by is null then
      return new;
    end if;
    return null;
  elsif tg_op = 'UPDATE' then
    if public.can_edit_expense(new.department_id) then
      return new;
    end if;
    if new.submitted_by = auth.uid()
       and new.decided_by is null
       and new.status = 'pending' then
      return new;
    end if;
    return null;
  end if;
  return new;
end;
$$;

