  select * into v_expense from public.expenses where id = p_expense_id for update;

  if not found then
    raise exception 'expense % not found', p_expense_id;
  end if;

  if v_expense.status <> 'pending' then
    raise exception 'expense % is not pending', p_expense_id;
  end if;

  if v_expense.decided_by is not null then
    raise exception 'expense % already decided', p_expense_id;
  end if;

  if v_caller is null then
    raise exception 'not authenticated';
  end if;

  if private.can_read_department(v_expense.department_id) and v_expense.submitted_by <> v_caller then
    if private.is_manager(v_expense.department_id) then
      if p_approve then
        update public.expenses set status = 'approved', decided_by = v_caller where id = p_expense_id;
      else
        update public.expenses set status = 'rejected', decided_by = v_caller where id = p_expense_id;
      end if;
    else
      raise exception 'only managers can decide %', p_expense_id;
    end if;
  else
    raise exception 'you may not decide %', p_expense_id;
  end if;
end;
$$;

