create or replace function public.decide_expense(p_expense_id bigint, p_approve boolean)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_expense public.expenses%rowtype;
  v_dept_id bigint;
  v_user_id uuid := auth.uid();
  v_role text := auth.role();
begin
  if v_user_id is null then
    raise exception 'not authenticated';
  end if;

  if v_role = 'service_role' then
    if p_approve not in (true, false) then
      raise exception 'p_approve must be true or false';
    end if;
  elsif v_role isnull or v_role in ('anon', 'public') then
    raise exception 'only authenticated users can decide expenses';
  else
    if not exists (select 1 from public.expenses where id = p_expense_id) then
      raise exception 'expense % not found', p_expense_id;
    end if;

    select e.department_id, e.submitted_by, e.status, e.decided_by
    into v_dept_id, v_dept_user, v_expense.status, v_expense.decided_by
    from public.expenses e
    where e.id = p_expense_id
    for update;

    if not found then
      raise exception 'expense % not found', p_expense_id;
    end if;

    if v_expense.status <> 'pending' then
      raise exception 'expense % is not pending', p_expense_id;
    end if;

    if p_approve not in (true, false) then
      raise exception 'p_approve must be true or false';
    end if;

    if v_expense.submitted_by = v_user_id then
      raise exception 'author cannot decide their own expense';
    end if;

    if not exists (select 1 from public.department_members dm where dm.department_id = v_dept_id and dm.user_id = v_user_id and dm.is_manager) then
      raise exception 'user is not a manager of department %', v_dept_id;
    end if;
  end if;

  update public.expenses
  set status = case when p_approve then 'approved' else 'rejected' end,
      decided_by = case when v_role is not distinct from 'service_role' then null else v_user_id end
  where id = p_expense_id;
end
$$;

