returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_expense public.expenses%rowtype;
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception 'decide_expense: cannot be called anonymously';
  end if;

  select e.department_id, e.status, e.submitted_by
  into v_expense.department_id, v_expense.status, v_expense.decided_by
  from public.expenses e
  where e.id = p_expense_id
