  end if;

  if v_expense.status <> 'pending' then
    raise exception 'decide_expense: expense % is not pending', p_expense_id;
  end if;

  if v_expense.submitted_by = v_uid then
    raise exception 'decide_expense: cannot decide your own expense';
  end if;

  if p_approve then
    if not public.is_expense_manager(v_expense.department_id) then
      raise exception 'decide_expense: caller does not manage department %', v_expense.department_id;
    end if;
  else
    if not public.is_expense_manager(v_expense.department_id) then
      raise exception 'decide_expense: caller does not manage department %', v_expense.department_id;
    end if;
  end if;

  if v_uid is not null then
    update public.expenses
    set status = case when p_approve then 'approved' else 'rejected' end,
        decided_by = v_uid
    where id = p_expense_id
      and status = 'pending'
      and decided_by is distinct from v_uid
      and exists (
        select 1
        from public.expenses e2
        where e2.id = p_expense_id
          and e2.status = 'pending'
          and (e2.submitted_by is distinct from v_uid)
      );
  end if;
end;
$$;

