create function public.decide_expense(p_expense_id bigint, p_approve boolean) returns void
language plpgsql
security invoker
set search_path = public
as $$
declare
  v_id public.expenses.id%type := p_expense_id;
  v_user uuid := (select auth.uid());
  v_expense public.expenses%rowtype;
begin
  if v_user is null or public.can_decide_expense(v_expense.id) = false then
    raise exception 'insufficient privileges';
  end if;
  perform 1 into v_expense
  from public.expenses e
  where e.id = v_id
    for update;
  if not found then
    raise exception 'expense not found';
  end if;
  perform 1
  from public.expenses e2
  where e2.id = v_id
    and e2.status = 'pending'
    and e2.decided_by is null;
  if not found then
    raise exception 'expense is not pending';
  end if;
  update public.expenses
  set status = p_approve::text::expense_status,
      decided_by = case when v_expense.submitted_by is distinct from v_user then v_user end,
      updated_at = now()
  where id = v_id;
end
$$;
