create or replace function public.decide_expense(p_expense_id bigint, p_approve boolean) returns void
language plpgsql security definer as $$
declare
  v_expense public.expenses%rowtype;
  v_originated boolean;
begin
  select * into v_expense
  from public.expenses
  where id = p_expense_id
  for update;

  if not found then
    raise exception 'expense % does not exist', p_expense_id;
  end if;

  v_originated := v_expense.submitted_by = (select auth.uid());

  if exists (
    select 1
    from public.expenses e
    where e.id = p_expense_id
      and e.decided_by is not null
      and e.decided_by is distinct from v_expense.decided_by
  ) then
    raise exception 'expense % has already been decided', p_expense_id;
  end if;

  if not exists (
    select 1
    from public.department_members m
    where m.department_id = v_expense.department_id
      and m.user_id = (select auth.uid())
  ) then
    raise exception 'caller is not a member of the expense department';
  end if;

  if p_approve = true and v_expense.status = 'pending' and v_originated is false then
    update public.expenses
    set status = 'approved'
      , decided_by = (select auth.uid())

    where id = v_expense.id
      and status = 'pending'
      and decided_by is null;
  elsif p_approve = false
     and v_expense.status = 'pending'
     and (select public.is_manager_of_expense(v_expense.department_id)) then
    update public.expenses
    set status = 'rejected'
      , decided_by = (select auth.uid())

    where id = v_expense.id
      and status = 'pending'
      and decided_by is null;
  else
    raise exception 'cannot decide expense %: status %, submitted by %, my decision %, department not %, caller decision %'
      , p_expense_id
      , v_expense.status
      , v_expense.submitted_by
      , v_originated
      , (select public.is_manager_of_expense(v_expense.department_id))
      , (select auth.uid());
  end if;
end;
$$;

