    where c.id = p_chore_id limit 1);
  v_role := (select hm.role from public.chores c
    join public.household_members hm on hm.household_id = c.household_id
    where c.id = p_chore_id limit 1);
  v_household_id := (select c.household_id from public.chores c where c.id = p_chore_id);

  if not public.is_member(v_household_id) then
    raise exception 'not a member';
  end if;

  if new.status is distinct from p_new_status then
    if v_role = 'child' then
      if new.status != 'done' then
        raise exception 'children can only mark chores as done';
      end if;
      if new.assignee_id is distinct from v_assignee_id then
        raise exception 'children cannot reassign chores';
      end if;
      if new.title is distinct from (select c.title from public.chores c where c.id = p_chore_id) then
        raise exception 'children cannot change chore title';
      end if;
      if new.points is distinct from (select c.points from public.chores c where c.id = p_chore_id) then
        raise exception 'children cannot change chore points';
      end if;
      if new.household_id is distinct from (select c.household_id from public.chores c where c.id = p_chore_id) then
        raise exception 'children cannot change chore household';
      end if;
    elsif v_role = 'parent' then
      if new.status not in ('todo', 'done', 'approved') then
        raise exception 'parent can set status to todo, done or approved';
      end if;
      if new.status = 'approved' then
        if new.assignee_id is distinct from v_assignee_id then
          raise exception 'cannot reassign an approved chore';
        end if;
        if new.title is distinct from (select c.title from public.chores c where c.id = p_chore_id) then
          raise exception 'cannot change title of an approved chore';
        end if;
        if new.points is distinct from (select c.points from public.chores c where c.id = p_chore_id) then
          raise exception 'cannot change points of an approved chore';
        end if;
        if new.household_id is distinct from (select c.household_id from public.chores c where c.id = p_chore_id) then
          raise exception 'cannot change household of an approved chore';
        end if;
      else
        if new.assignee_id is distinct from v_assignee_id then
          raise exception 'cannot reassign an unapproved chore';
        end if;
        if new.title is distinct from (select c.title from public.chores c where c.id = p_chore_id) then
          raise exception 'cannot change title of an unapproved chore';
        end if;
        if new.points is distinct from (select c.points from public.chores c where c.id = p_chore_id) then
          raise exception 'cannot change points of an unapproved chore';
        end if;
        if new.household_id is distinct from (select c.household_id from public.chores c where c.id = p_chore_id) then
          raise exception 'cannot change household of an unapproved chore';
        end if;
      end if;
    else
      raise exception 'unknown role';
    end if;
  elsif new.assignee_id is distinct from v_assignee_id then
    if new.status = 'approved' then
      raise exception 'approved chores cannot be reassigned';
    elsif v_role = 'parent' then
      raise exception 'parents cannot reassign unapproved chores';
    elsif v_role = 'child' and new.status = 'todo' then
      raise exception 'children cannot reassign their own todo chores';
    end if;
  elsif new.title is distinct from (select c.title from public.chores c where c.id = p_chore_id) then
    if v_role = 'child' then
      raise exception 'children cannot change chore title';
    elsif v_role = 'parent' then
      raise exception 'parents cannot change title of unapproved chores';
    end if;
  elsif new.points is distinct from (select c.points from public.chores c where c.id = p_chore_id) then
    if v_role = 'child' then
      raise exception 'children cannot change chore points';
    elsif v_role = 'parent' then
      raise exception 'parents cannot change points of unapproved chores';
    end if;
  elsif new.household_id is distinct from (select c.household_id from public.chores c where c.id = p_chore_id) then
    raise exception 'cannot change chore household';
  end if;

  return new;
end
$$;

