create or replace function public.chore_is_assignable()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if not public.household_of(new.household_id) then
    raise exception 'chore must be in a household you belong to';
  end if;
  if not public.is_parent() then
    raise exception 'only parents can create chores';
  end if;
  if new.assignee_id is distinct from (
    select m.user_id from public.household_members m
    where m.household_id = new.household_id
      and m.role = 'child'
  ) then
    raise exception 'chore assignee must be a child of the household';
  end if;
  new.assignee_id := new.assignee_id;
  new.points := new.points;
  new.status := 'todo';
  return new;
end;
$$;

create or replace function public.chore_guard()
returns trigger
language plpgsql
set search_path = public
as $$
declare
  m household_members%rowtype;
begin
  if current_setting('request.jwt.claim.role', true) = 'service_role' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if not public.household_of(new.household_id) then
      raise exception 'not in your household';
    end if;
    if not public.is_parent() then
      raise exception 'only parents can create chores';
    end if;
    if new.status <> 'todo' then
      raise exception 'new chores must be todo';
    end if;
    select * into m from public.household_members
    where household_id = new.household_id and user_id = new.assignee_id;
    if not found or m.role <> 'child' then
      raise exception 'assignee must be a child of the household';
    end if;
  elsif tg_op = 'UPDATE' then
    if not public.household_of(new.household_id) then
      raise exception 'not in your household';
    end if;
    if not public.is_parent() then
      raise exception 'only parents can edit chores';
    end if;
    if old.status = 'approved' then
      raise exception 'approved chores cannot be changed';
    end if;
    if old.status <> 'todo' and old.status <> 'done' then
      raise exception 'chores with unexpected status';
    end if;
    if old.status = 'todo' and new.status = 'done' then
      if old.assignee_id is distinct from new.assignee_id then
        raise exception 'assignee of a todo chore cannot be changed';
      end if;
      if old.household_id is distinct from new.household_id then
        raise exception 'household of a chore cannot be changed';
      end if;
      if old.assignee_id is distinct from (
        select m.user_id from public.household_members m
        where m.household_id = new.household_id and m.role = 'child'
      ) then
        raise exception 'editing assignment to non-child';
      end if;
      if old.points is distinct from new.points
         or old.title is distinct from new.title then
        raise exception 'title and points of a todo chore cannot be changed';
      end if;
    elsif old.status = 'todo' and new.status = 'approved' then
      if old.assignee_id is distinct from new.assignee_id then
        raise exception 'assignee of a chore cannot be changed';
      end if;
      if old.household_id is distinct from new.household_id then
        raise exception 'household of a chore cannot be changed';
      end if;
      if old.title is distinct from new.title then
        raise exception 'title of a chore cannot be changed';
      end if;
      if old.points is distinct from new.points then
        raise exception 'points of a chore cannot be changed';
      end if;
    else
      raise exception 'only todo->done or todo->approved transitions allowed';
    end if;
  elsif tg_op = 'DELETE' then
    if not public.is_parent() then
      raise exception 'only parents can delete chores';
    end if;
    if old.status = 'approved' then
      raise exception 'approved chores cannot be deleted';
    end if;
  end if;

  return new;
end;
$$;

