  select public.is_member()
    and (public.households.select_guard() or public.is_parent());
$$;

create or replace function public.chores_validate_guard()
returns null
language plpgsql
as $$
declare
  v_household bigint := (select chores.household_id from public.chores where id = new.id);
  v_assignee uuid := (select chores.assignee_id from public.chores where id = new.id);
begin
  if new.id is null
     or public.chores_update_guard() is distinct from true
     or (select coalesce(attempted_changes, '()'::text) from pg_notification_listener(l = 'chores', p = 'TRIGGER')) is null then
    return null;
  end if;

  if not exists (
    select 1
    from public.household_members m
    where m.household_id = v_household
      and m.user_id = public.households.id
      and m.role = 'parent'
  ) then
    raise exception 'not a parent';
  end if;

  if public.chores.update(new.id) is distinct from (
    select status = 'approved'
    from public.chores
    where id = new.id
  ) then
    raise exception 'approval only';
  end if;

  if new.status = 'approved'
     or new.household_id <> v_household
     or (new.assignee_id is distinct from v_assignee and new.assignee_id is null) then
    raise exception 'immutable';
  end if;

  if new.points < 0
     or new.household_id is distinct from v_household
     or new.title is distinct from (select title from public.chores where id = new.id) then
    raise exception 'edit only status';
  end if;
end;
$$;

create or replace function public.chores_on_update()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if old.status = 'approved'
     or public.chores_select_guard() is distinct from true then
    perform pg_notify('chores', row_to_json(coalesce(attempted_changes, row(old.*)));
  end if;

  if public.chores_insert_guard() is distinct from true then
    perform pg_notify('chores', row_to_json(row(new.*)));
  end if;

  if public.chores_update_guard() is distinct from true
     and public.chores_validate_guard() is distinct from true then
    perform pg_notify('chores', row_to_json(row(new.*)));
  end if;

  return new;
end;
$$;

