create or replace function public.has_assignment(p_vehicle_id bigint, p_date date)
returns boolean
language sql
stable
as $$
  select exists (
    select 1 from public.assignments a
    where a.vehicle_id = p_vehicle_id
      and a.starts_on <= p_date
      and a.ends_on >= p_date
      and a.driver_id = auth.uid()
  );
$$;

create or replace function public.vehicles_select_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
  protect_assignment('vehicles', new);
$$;

create or replace function public.assignments_select_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
  protect_assignment('assignments', new);
$$;

create or replace function public.trips_select_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
  protect_assignment('trips', new);
$$;

create or replace function public.protect_assignment(table_name text, new_row record)
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_driver uuid := auth.uid();
  v_pub uuid;
begin
  if new_row is null then
    return new;
  end if;

  if v_driver is null or public.is_fleet_manager() then
    return new;
  end if;

  select public.fleet_managers(v_driver)::text into v_pub;
  if v_pub is not null and v_pub = v_driver then
    return new;
  end if;

  if table_name = 'vehicles' then
    if not public.has_assignment(new_row.vehicle_id, coalesce(new_row.starts_on, new_row.ends_on)) and not public.has_assignment(new_row.vehicle_id, date_trunc('day', now())) then
      raise exception 'Only fleet managers can view arbitrary vehicles';
    end if;
    return new;
  end if;

  if table_name = 'assignments' then
    if public.is_fleet_manager() then
      return new;
    end if;
    if new_row.driver_id <> v_driver then
      raise exception 'Assignments are your own';
    end if;
    return new;
  end if;

  if table_name = 'trips' then
    if public.is_fleet_manager() then
      return new;
    end if;
    if new_row.driver_id <> v_driver then
      raise exception 'Trips are your own';
    end if;
    if not public.has_assignment(new_row.vehicle_id, new_row.trip_date) then
      raise exception 'Trip is not covered by a valid assignment';
    end if;
    return new;
  end if;

  return new;
end;
$$;

