language plpgsql set search_path = ''
as $$
declare
  v bool;
begin
  if new.vehicle_id is null or new.driver_id is null or new.trip_date is null then
    raise exception 'vehicle_id, driver_id, and trip_date are required';
  end if;
  if new.driver_id is distinct from auth.uid() and private.is_fleet_manager() then
    raise exception 'driver must be yourself';
  end if;
  if private.is_fleet_manager() then
    return new;
  end if;
  if private.is_driver() then
    v := private.is_assigned_to(new.vehicle_id, new.trip_date);
    if not v then
      raise exception 'no assignment covers vehicle date';
    end if;
    return new;
  end if;
  raise exception 'not authenticated';
end
$$;

