create function private.can_read_comment(bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.project_comments c
    where c.id = $1
      and (private.is_staff()
           or (private.can_read_comment.project_id
               and not c.is_internal
               and c.author_id = auth.uid()))
  )
$$;

create or replace function private.is_project_owner(bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
