    select 1 from public.project_comments c
    where c.id = $1
      and c.author_id = auth.uid()
  )
$$;

create or replace function private.enforce_comment_project(bigint) returns trigger
language plpgsql security definer set search_path = ''
as $$
declare
  v_staff boolean;
  v_client boolean;
begin
  v_staff := private.is_staff();
  v_client := private.is_project_owner(new.id);
  if not v_staff and not v_client
     and (select p.client_id from public.projects p where p.id = new.project_id) is null
  then
    raise exception 'comments must be on owned projects';
  end if;
  if new.is_internal and not v_staff
     and (select p.client_id from public.projects p where p.id = new.project_id) is distinct from auth.uid()
  then
    raise exception 'only staff may post internal comments';
  end if;
  new.author_id := auth.uid();
  if not new.is_internal then
    new.is_internal := false;
  end if;
  return new;
end
$$;

