create or replace function public.fn_trips_check_assignment()
returns trigger
language plpgsql
as $$
declare
  v_driver_id uuid := auth.uid();
  v_assignment boolean;
begin
  if public.is_fleet_manager() then
    return new;
  end if;

  if new.driver_id is distinct from v_driver_id then
    raise exception 'trips.driver_id % conflicts with session', v_driver_id
      using errcode = '42501';
  end if;

  select exists (
    select 1 from public.assignments a
    where a.vehicle_id = new.vehicle_id
      and new.trip_date between a.starts_on and a.ends_on
      and a.driver_id = v_driver_id
  ) into v_assignment;

  if not v_assignment then
    raise exception 'trip % not covered by any assignment', new.id
      using errcode = '42501';
  end if;

  return new;
end;
$$;
