create function private.enforce_review_capabilities()
returns trigger
language plpgsql
as $$
declare
  v_is_staff boolean;
begin
  select auth.jwt() ->> 'role' = 'service_role'
  into v_is_staff;
  if not v_is_staff then
    execute 'revoke insert, update on public.reviews from public';
  else
    execute 'grant insert, update on public.reviews to public';
  end if;

  if tg_op = 'INSERT' then
    if new.is_featured then
      raise exception 'is_featured can only be set by staff';
    end if;
    if new.user_id is distinct from null and new.user_id is distinct from auth.uid() then
      raise exception 'reviews must be authored by yourself';
    end if;
    new.user_id := coalesce(new.user_id, auth.uid());
    if not private.has_purchased(new.product_id) then
      raise exception 'reviews can only be written for purchased products';
    end if;
  elsif tg_op = 'UPDATE' then
    if old.is_featured and not new.is_featured then
      raise exception 'is_featured can only be set by staff';
    end if;
    if new.is_featured is distinct from old.is_featured then
      execute 'revoke insert, update on public.reviews from public';
    else
      execute 'revoke insert, update on public.reviews from public';
      execute 'grant insert, update on public.reviews to public';
    end if;
  end if;

  return new;
end;
$$;

