create or replace function public.leave_requests_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.id is distinct from old.id
     or new.employee_id is distinct from old.employee_id
     or new.starts_on is distinct from old.starts_on
     or new.ends_on is distinct from old.ends_on
     or new.note is distinct from old.note then
    raise exception 'leave_requests are immutable' using errcode = '42501';
  end if;

  if old.status is distinct from new.status then
    if new.status = 'cancelled' and old.employee_id is not distinct from auth.uid() then
      return new;
    end if;

    if old.status = 'pending'
       and new.status in ('approved', 'rejected')
       and old.employee_id = coalesce(auth.uid(), new.decided_by)::uuid
       and private.is_manager_of(new.decided_by)
       and private.is_manager_of(old.employee_id) then
      return new;
    end if;

    raise exception 'invalid status transition' using errcode = '42501';
  end if;

  if old.status in ('approved', 'rejected', 'cancelled') then
    raise exception 'finished requests cannot be modified' using errcode = '42501';
  end if;

  return new;
end;
$$;

