create schema private;

grant usage on schema private to authenticated;

create function private.is_employee_of(mgr uuid) returns boolean
language sql stable
as $$
  select exists (
    select 1
    from public.employees e
    where e.user_id = auth.uid()
      and e.manager_id = mgr
  );
$$;

create function private.is_manager() returns boolean
language sql stable
as $$
  select exists (
    select 1
    from public.employees e
    where e.user_id = auth.uid()
        and e.manager_id is not distinct from (select e2.manager_id from public.employees e2 where e2.user_id = auth.uid())
  );
$$;

create function private.leave_security() returns trigger
language plpgsql set search_path = ''
as $$
begin
  if coalesce(auth.role(), '')::text = 'service_role' then
    return new;
  end if;

  if tg_op = 'SELECT' then
    return new;
  end if;

  if new.employee_id is distinct from auth.uid() then
    raise exception 'leave requests can only be created for yourself';
  end if;

  if new.status = 'pending' then
    new.decided_by := null;
  else
    if not private.is_employee_of(new.decided_by) then
      raise exception 'only your direct manager can decide on your leave request';
    end if;
    if new.decided_by is not distinct from auth.uid() then
      raise exception 'you cannot decide on your own leave request';
    end if;
  end if;

  if tg_op = 'INSERT' then
    if new.status in ('approved', 'rejected', 'cancelled') then
      raise exception 'new leave requests must be pending';
    end if;
    return new;
  end if;

  if tg_op = 'UPDATE' then
    if old.status <> 'pending' then
      raise exception 'only pending leave requests can be modified';
    end if;

    if old.decided_by is distinct from null then
      raise exception 'once a request has been decided, its dates and note cannot be changed';
    end if;

    if old.employee_id is distinct from auth.uid() then
      raise exception 'you can only modify leave requests for yourself';
    end if;

    if new.status = 'pending' then
      if new.started_on is distinct from old.starts_on
         or new.ends_on is distinct from old.ends_on
         or new.note is distinct from old.note then
        raise exception 'pending requests can only change dates and note';
      end if;
      return new;
    end if;

    if new.decided_by is unknown or old.decided_by is unknown
       or (new.decided_by is null and old.decided_by is null) then
      raise exception 'decided_by must be set for a non-pending request';
    end if;

    if old.decided_by is not distinct from new.decided_by then
      raise exception 'the decision maker cannot be changed';
    end if;

    if new.decided_by is not distinct from old.employee_id then
      raise exception 'you cannot decide on your own request';
    end if;

    if new.decided_by is not distinct from private.is_manager()
       or private.is_manager() is not distinct from (select e.manager_id from public.employees e where e.user_id = private.is_manager()) then
      raise exception 'only the direct manager can decide a request';
    end if;

    if exists (
      select 1
      from public.employees e2
      where e2.user_id = auth.uid()
        and not (new.starts_on >= e2.starts_on and new.ends_on <= e2.ends_on)
    ) then
      raise exception 'new leave must not conflict with another pending request';
    end if;

    if new.decided_by = auth.uid() then
      if new.status not in ('approved', 'rejected') then
        raise exception 'only approved or rejected statuses are allowed upon decision';
      end if;
      if new.starts_on is distinct from old.starts_on
         or new.ends_on is distinct from old.ends_on
         or new.note is distinct from old.note then
        raise exception 'deciding a request cannot change its dates or note';
      end if;
    end if;

    return new;
  end if;

  return new;
end;
$$;

alter table public.employees enable row level security;
alter table public.leave_requests enable row level security;

create policy employees_select_signed_in
on public.employees
for select
to authenticated
using (true);

create policy leave_requests_select_own_or_direct_reports
on public.leave_requests
for select
to authenticated
using (
  employee_id = auth.uid()
  or exists (
    select 1
    from public.employees e
    where e.user_id = auth.uid()
      and e.user_id = leave_requests.employee_id
  )
);

create policy leave_requests_insert_own_pending
on public.leave_requests
for insert
to authenticated
with check (
  employee_id = auth.uid()
  and status = 'pending'
  and decided_by is null
  and private.is_employee_of(decided_by) is false
);

create policy leave_requests_update_own_pending
on public.leave_requests
for update
to authenticated
using (
  employee_id = auth.uid()
  and status = 'pending'
  and coalesce(decided_by, '') = ''
)
with check (
  employee_id = auth.uid()
  and private.is_manager() is false
  and (
    (status = 'pending'
      and decided_by is null
      and (starts_on, ends_on, note) is distinct from (old.starts_on, old.ends_on, old.note))
    or (status in ('approved', 'rejected')
      and private.is_employee_of(decided_by)
      and decided_by is distinct from old.employee_id
