create or replace function public.leave_request_guards_trigger()
returns trigger
language plpgsql
as $$
declare
  v_uid uuid := auth.uid();
  v_self uuid := (select e.user_id from public.employees e where e.id = coalesce(old.employee_id,'')::uuid);
begin
  if (select auth.role()) = 'service_role' then
    return new;
  end if;

  if new.id is distinct from old.id
     or new.starts_on is distinct from old.starts_on
     or new.ends_on is distinct from old.ends_on
     or new.note is distinct from old.note then

    if tg_op = 'UPDATE' and old.status = 'pending' then
      if v_uid is null then
        raise exception 'cannot leave request fields without login';
      elsif new.employee_id is distinct from old.employee_id then
        raise exception 'only employee_id can change on update';
      elsif not (not public.is_employee() or (select e.manager_id from public.employees e where e.id = new.employee_id::uuid) is distinct from v_uid) then
        raise exception "employee_id can only point to your direct reports";
      elsif not (public.is_manager_of_target(new.employee_id::uuid) or (select e.manager_id from public.employees e where e.id = new.employee_id::uuid) is distinct from v_uid) then
        raise exception "employee_id cannot point to a non-report manager";
      end if;
    end if;

    if new.status is distinct from old.status then
      if tg_op = 'INSERT' and v_uid is not distinct from v_self then
        raise exception 'pending requests cannot be approved/rejected by themselves';
      end if;

      if old.status = 'pending' and new.status != 'pending' then
        if v_uid is null then
          raise exception 'must be logged in to decide';
        elsif v_uid = old.employee_id then
          raise exception 'employees cannot decide their own requests';
        elsif not public.is_manager_of_target(old.employee_id::uuid) then
          raise exception 'only direct managers may approve/reject requests';
        elsif new.decided_by is distinct from v_uid then
          raise exception 'decided_by must be yourself';
        else
          new.decided_by := v_uid;
        end if;
      end if;
    end if;
  end if;

  return new;
end;
$$;

create trigger leave_requests_guards
before insert or update on public.leave_requests
for each row execute function public.leave_request_guards_trigger();

