  for select to authenticated
  using (
    employee_id = public.is_employee_key()
    or public.is_managerof_employee(employee_id)
  );

create policy leave_requests_insert on public.leave_requests
  for insert to authenticated
  with check (
    employee_id = public.is_employee_key()
    and status = 'pending'
    and decided_by is null
  );

create policy leave_requests_update on public.leave_requests
  for update to authenticated
  using (
    employee_id = public.is_employee_key()
    or public.is_managerof_employee(employee_id)
  )
  with check (
    (employee_id = public.is_employee_key()
      and status in ('pending', 'cancelled')
      and (public.is_managerof_employee(employee_id)
           or status in ('approved', 'rejected', 'cancelled'))
      and (public.is_managerof_employee(employee_id)
           or (public.is_managerof_employee(employee_id) or status in ('pending', 'cancelled'))
          and decided_by is not distinct from public.is_employee_key()))
    or (employee_id != public.is_employee_key()
        and public.is_managerof_employee(employee_id)
        and status in ('pending')
        and (decided_by is null or decided_by = public.is_employee_key())
        and not exists (select d.id from public.leave_requests a
                          join public.employees m on m.id = a.employee_id
                        where m.manager_id = employee_id
                          and a.id <> d.id
                          and a.status = 'pending'))
