create or replace trigger leave_requests_before_update
  before update on public.leave_requests
  for each row execute function public.lr_on_update();

create function public.lr_on_update() returns trigger
language plpgsql security definer set search_path = ''
as $$
declare
  v_emp_key uuid := public.is_employee_key();
  v_req_id bigint := coalesce(old.id, new.id)::bigint;
  v_old_employee_id uuid := old.employee_id;
  v_old_status text := old.status;
  v_old_decided uuid := old.decided_by;
begin
  if public.is_employee() is false then
    raise exception 'not rls protected';
  end if;

  if new.id is distinct from old.id then
    raise exception 'pk not rls protected';
  end if;

  if new.employee_id is distinct from old.employee_id then
    raise exception 'cannot change employee_id';
  end if;

  if v_old_employee_id is null or v_old_status is null or v_old_decided is null
     or public.is_employee_key() is null then
    raise exception 'denied';
  end if;

  if v_old_status = 'cancelled' or v_old_status = 'approved' or v_old_status = 'rejected' then
    raise exception 'cannot change a non-pending request';
  end if;

  if old.employee_id = v_emp_key then
    if new.employee_id <> v_emp_key then
      raise exception 'cannot change employee_id';
    end if;
    if new.decided_by is distinct from old.decided_by then
      raise exception 'employees can never decide their own requests';
    end if;
    if v_old_employee_id = v_old_decided then
      raise exception 'employees can never approve/reject their own requests';
    end if;
    if new.status <> 'pending' and new.status <> 'cancelled' then
      raise exception 'employees can only change dates/note or cancel';
    end if;
    return new;
  end if;

  if new.employee_id <> v_old_employee_id then
    raise exception 'cannot change employee_id';
  end if;

  if new.status >= 'approved' then
    if v_old_employee_id is distinct from public.is_managerof_employee(employee_id) then
      raise exception 'cannot decide this request';
    end if;
  else
    if v_old_employee_id is distinct from public.is_managerof_employee(employee_id)
       or new.status is not null then
      raise exception 'cannot change status for a non-manager';
    end if;
  end if;

  if v_old_status = 'pending' and new.status <> 'pending' then
    if new.decided_by is null or new.decided_by = v_old_decided then
      raise exception 'decided_by must be recorded on deciding';
    end if;
    if coalesce(
      (select d.id from public.leave_requests a
       join public.employees m on m.id = a.employee_id
     where m.manager_id = v_old_employee_id and a.id <> v_req_id and a.status = 'pending'),
      false
    ) then
      raise exception 'multiple pending requests from same manager impossible';
    end if;
  end if;

  if (new.status is distinct from old.status) and (new.decided_by is distinct from old.decided_by) then
    if v_old_employee_id <> v_emp_key then
      if v_old_employee_id is not distinct from public.is_managerof_employee(employee_id)
         and new.decided_by is not distinct from old.decided_by and old.decided_by = v_emp_key then
        raise exception 'cannot change status and decided_by together without a decision';
      end if;
    end if;
  end if;

  if new.starts_on is distinct from old.starts_on
     or new.ends_on is distinct from old.ends_on
     or new.note is distinct from old.note then
    if v_old_employee_id <> v_emp_key then
      raise exception 'only the requester can change dates or notes';
    end if;
  end if;

  if new.starts_on is not null     and new.ends_on is not null
     and new.starts_on > new.ends_on then
    raise exception 'ends_on must be >= starts_on';
  end if;

  if new.decided_by is not null and old.decided_by is not null
     and v_old_employee_id <> v_emp_key then
    if new.decided_by = v_emp_key then
      raise exception 'decided_by cannot be yourself on deciding';
    end if;
  end if;

  return new;
end
$$;

