create or replace function public.events_published_only()
returns trigger
language plpgsql
set search_path = 'public'
as $$
begin
  if new.starts_at is null or new.ends_at is null or new.starts_at > new.ends_at then
    raise exception 'events: valid starts_at before ends_at';
  end if;
  if new.starts_at < now() then
    raise exception 'events: starts_at must be in the future';
  end if;
  return new;
end;
$$;

create trigger events_published_check
before insert or update on public.events
for each row execute function public.events_published_only();
