create or replace function public.org_member_query(p_org_id bigint)
returns setof public.org_members
language sql
volatile
as $$
  select m.id, m.org_id, m.user_id, m.role
  from public.org_members m
  where m.org_id = p_org_id
    and exists (
      select 1
      from public.org_members m2
      where m2.org_id = p_org_id
        and m2.user_id = auth.uid()
        and m2.role = 'admin'
    )
  order by m.org_id, m.user_id, m.role;
$$;

create or replace function public.can_manage_org_projects()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_org bigint;
  v_admin boolean;
begin
  select p.org_id, public.org_member_of(p.org_id)
    into v_org, v_admin
  from public.projects p
  where p.id = new.id;
  if v_org is null then
    raise exception 'project % does not exist', new.id using errcode = '23503';
  end if;
  if not v_admin then
    raise exception 'only organization admins can manage projects in %', p_org_id
      using errcode = '42501';
  end if;
  return new;
end;
$$;

