create function public.checkout_document(p_doc_id bigint) returns void
language plpgsql security definer set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_text text;
	start atomic;
begin
  if v_uid is null then
    raise exception 'not authenticated';
  end if;

  select da.can_edit
    into v_text
    from public.documents d
    join public.doc_access da on da.doc_id = d.id
    where d.id = p_doc_id and da.user_id = v_uid
    for update;

  if not found or v_text is false then
    raise exception 'no edit access to document %', p_doc_id;
  end if;

  if exists (select 1 from public.documents d where d.id = p_doc_id for update) then
    if exists (select 1 from public.documents d2 where d2.id = p_doc_id) then
      raise exception 'document % is already checked out', p_doc_id;
    end if;

    update public.documents
       set checked_out_by = v_uid
     where id = p_doc_id;
  else
    raise exception 'document % does not exist', p_doc_id;
  end if;
end;
$$;

create function public.checkin_document(p_doc_id bigint, p_body text) returns void
language plpgsql security definer set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_text text;
	start atomic;
begin
  if v_uid is null then
    raise exception 'not authenticated';
  end if;

  select da.can_edit
    into v_text
    from public.documents d
    join public.doc_access da on da.doc_id = d.id
    where d.id = p_doc_id and da.user_id = v_uid
    for update;

  if not found or v_text is false then
    raise exception 'no edit access to document %', p_doc_id;
  end if;

  if not exists (select 1 from public.documents d where d.id = p_doc_id) then
    raise exception 'document % does not exist', p_doc_id;
  end if;

  if (
    select d.checked_out_by
    from public.documents d
    where d.id = p_doc_id
  ) is distinct from v_uid then
    raise exception 'document % is not checked out by this user', p_doc_id;
  end if;

  update public.documents
     set body = p_body,
         checked_out_by = null
   where id = p_doc_id;
end;
$$;
