create function public.checkout_document(p_doc_id bigint)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_own boolean := coalesce(v_uid is not null, false);
begin
  if v_uid is null or p_doc_id is null then
    raise exception 'not authenticated';
  end if;

  if not exists (
    select 1
    from public.doc_access a
    where a.doc_id = p_doc_id
      and (a.user_id = v_uid or v_own)
  ) then
    raise exception 'no access to document';
  end if;

  if not exists (
    select 1
    from public.documents d
    join public.doc_access a on a.doc_id = d.id
    where d.id = p_doc_id
      and a.user_id = v_uid
      and a.can_edit
      and (d.checked_out_by is null or d.checked_out_by = v_uid)
  ) then
    raise exception 'document not eligible for checkout';
  end if;

  perform pg_advisory_xact_lock(hashtext(p_doc_id::text));

  update public.documents
  set checked_out_by = v_uid
  where id = p_doc_id
    and (checked_out_by is null or checked_out_by = v_uid);

  if not found then
    raise exception 'document not checkoutable';
  end if;
end;
$$;

