returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_doc public.documents%rowtype;
  v_can_edit boolean;
begin
  if auth.role() = 'service_role' then
    return;
  end if;

  select d, da.can_edit into v_doc, v_can_edit
  from public.documents d
  join public.doc_access da on da.doc_id = d.id
  where d.id = p_doc_id and da.user_id = auth.uid()
  for update;

  if not found then
    raise exception 'document % is not accessible', p_doc_id;
  elsif not v_can_edit then
    raise exception 'no edit access to document %', p_doc_id;
  elsif v_doc.checked_out_by is not null and v_doc.checked_out_by <> auth.uid() then
    raise exception 'document % is locked by another user', p_doc_id;
  end if;

  update public.documents
  set checked_out_by = auth.uid()
  where id = p_doc_id and checked_out_by is distinct from auth.uid();
end;
$$;

