  v_doc public.documents%rowtype;
  v_can_edit boolean;
  v_checkout uuid;
begin
  if auth.role() = 'service_role' then
    return;
  end if;

  update public.documents
  set body = p.body,
      checked_out_by = null
  where id = p_doc_id
    and checked_out_by = auth.uid()
  returning d, da.can_edit, da.user_id into v_doc, v_can_edit, v_checkout;

  if not found then
    if exists (select 1 from public.documents d join public.doc_access da on da.doc_id = d.id where d.id = p_doc_id and da.user_id = auth.uid() and da.can_edit) then
      raise exception 'document % is not checked out', p_doc_id;
