    select
      d.id,
      d.checked_out_by,
      a.can_edit
    from public.documents d
    join public.doc_access a on a.doc_id = d.id and a.user_id = v_user
    where d.id = p_doc_id
    for update
  )
  select *
  into target
  from target;

  if not found then
    raise exception 'document % not found or no access', p_doc_id;
  end if;

  if target.checked_out_by is distinct from v_user then
    raise exception 'document % is checked out by another user', p_doc_id;
  end if;

  if not target.can_edit then
    raise exception 'no edit access to document %', p_doc_id;
  end if;

  update public.documents
  set checked_out_by = v_user
  where id = p_doc_id;
end;
$$;

