  v_user uuid := (select auth.uid());
  v_locked uuid;
begin
  if v_user is null then
    raise exception 'not authenticated';
  end if;

  if p_doc_id is null then
    raise exception 'null doc_id';
  end if;

  perform pg_advisory_xact_lock(p_doc_id);

  with target as (
    select
      d.checked_out_by,
      d.id
    from public.documents d
    join public.doc_access a on a.doc_id = d.id and a.user_id = v_user
    where d.id = p_doc_id
    for update
  )
  select d.checked_out_by
  into v_locked
  from target t
  join public.documents d on d.id = t.id
  where t.checked_out_by is not distinct from v_user
  for update;

  if not found then
    raise exception 'document % not found or not checked out by you', p_doc_id;
  end if;

  update public.documents
  set checked_out_by = null,
      body = p_body
  where id = p_doc_id;
end;
