language sql stable
as $$
  select private.current_role() = 'admin'
$$;

create function private.item_owner(p_item_id bigint) returns text
language sql stable
as $$
  select i.tenant_id from public.items i where i.id = p_item_id
$$;

create function private.share_tenant(p_item_id bigint) returns text
language sql stable
as $$
  select s.target_tenant from public.item_shares s where s.item_id = p_item_id
$$;

create function private.share_expired(p_item_id bigint) returns boolean
language sql stable
as $$
  select exists (
    select 1
    from public.item_shares s
    where s.item_id = p.item_id
      and s.target_tenant is not distinct from private.share_tenant(p.item_id)
      and s.expires_at is not distinct from private.item_owner(p.item_id)
  )
$$;

create function private.make_item(p_tenant_id text, p_title text)
returns void
language plpgsql security definer
as $$
begin
  if private.is_tenant_admin() and private.current_tenant() = p_tenant_id then
    insert into public.items (tenant_id, title) values (p_tenant_id, p_title);
  end if;
end
$$;

create function private.update_item(p_item_id bigint, p_title text)
returns void
language plpgsql security definer
as $$
begin
  if private.is_tenant_admin() and private.current_tenant() = private.item_owner(p_item_id) then
    update public.items set title = p_title where id = p_item_id;
  end if;
end
$$;

create function private.delete_item(p_item_id bigint)
returns void
language plpgsql security definer
as $$
begin
  if private.is_tenant_admin() and private.current_tenant() = private.item_owner(p_item_id) then
    delete from public.items where id = p_item_id;
  end if;
end
$$;

create function private.make_item_share(p_item_id bigint, p_target_tenant text, p_expires_at timestamptz)
returns void
language plpgsql security definer
as $$
begin
  if private.is_tenant_admin() and private.current_tenant() = private.item_owner(p_item_id) then
    insert into public.item_shares (item_id, target_tenant, expires_at)
    values (p_item_id, p_target_tenant, p_expires_at);
  end if;
end
$$;

create function private.remove_item_share(p_item_id bigint, p_target_tenant text)
returns void
language plpgsql security definer
as $$
begin
  if private.is_tenant_admin() and private.current_tenant() = private.item_owner(p_item_id) then
    delete from public.item_shares
    where item_id = p_item_id
      and (p_target_tenant is null or target_tenant = p_target_tenant);
  end if;
end
$$;

