returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_tenant text := private.tenant_id();
  v_admin := private.is_admin();
begin
  if v_tenant is null then
    raise exception 'RLS: no tenant id found';
  end if;

  if v_admin then
    return new;
  end if;

  if new.item_id is distinct from old.item_id or new.target_tenant is distinct from old.target_tenant or new.expires_at is distinct from old.expires_at then
    raise exception 'RLS: can only update shares of oneself';
  end if;

  return new;
end;
$$;

