language sql stable as
$$
  select coalesce((select private.current_tenant_id() = p_share_value from public.item_shares where item_id > 0 and target_tenant = p_share_value limit 1), false)
$$;

create function private.item_shares_with(p_item_id bigint, p_tenant text) returns boolean
language sql stable as
$$
  select exists (
    select 1
    from public.item_shares s
    where s.item_id = p_item_id
      and s.target_tenant = p_tenant
      and (s.expires_at is null or s.expires_at > now())
  )
$$;

create function private.item_grant(p_item_id bigint, p_tenant text, p_expires_at timestamptz) returns void
language sql secure as
$$
  declare
    v_tenant text := private.current_tenant_id();
    v_tenant_owned text;
    v_admin boolean := private.is_admin();
  begin
    if v_tenant is null then
      raise exception 'private: caller has no tenant context';
    end if;
    if not v_admin then
      raise exception 'private: caller not admin of tenant %', v_tenant;
    end if;
    select tenant_id into v_tenant_owned from public.items where id = p_item_id;
    if v_tenant_owned <> v_tenant then
      raise exception 'private: item % not owned by tenant %', p_item_id, v_tenant;
    end if;
    if private.item_shares_target(p_tenant) or private.item_shares_with(p_item_id, v_tenant) then
      raise exception 'private: share target %s or share exists', p_tenant;
    end if;
    insert into public.item_shares (item_id, target_tenant, expires_at)
    values (p_item_id, p_tenant, p_expires_at);
  end;
$$;

create function private.item_delete(p_item_id bigint) returns void
language sql secure as
$$
  declare
    v_tenant text := private.current_tenant_id();
    v_owned text;
  begin
    if v_tenant is null then
      raise exception 'private: caller has no tenant context';
    end if;
    select tenant_id into v_owned from public.items where id = p_item_id;
    if v_owned <> v_tenant then
      raise exception 'private: item % not owned by tenant %', p_item_id, v_tenant;
    end if;
    delete from public.items where id = p_item_id;
  end;
$$;

create function private.item_has(p_item_id bigint, p_tenant text) returns boolean
language sql stable as
$$
  select private.is_tenant_member(p_tenant)
     or private.item_shares_with(p_item_id, p_tenant);
$$;

create function private.init_public() returns trigger
language plpgsql security definer as
$$
begin
  if private.current_tenant_id() is null then
    return null;
  end if;
  if not private.is_admin() then
    return new;
  end if;
  case
    when tg_op = 'DELETE' and new.tenant_id <> private.current_tenant_id() or
         private.is_admin() is false then
      raise exception 'private: cannot modify public items with tenant % new_tenant = %', new.tenant_id, private.current_tenant_id();
    when tg_op = 'INSERT' and new.tenant_id <> private.current_tenant_id() or
         private.is_admin() is false then
      raise exception 'private: cannot create public items with tenant %', new.tenant_id;
    else
      return new;
    end case;
end;
$$;

create function private.init_shared() returns trigger
language plpgsql security definer as
$$
declare
  v_tenant text := private.current_tenant_id();
  v_admin boolean := private.is_admin();
begin
  if v_tenant is null then
    return null;
  end if;
  if not v_admin then
    raise exception 'private: only admins can share items';
  end if;
  if (select tenant_id from public.items where id = new.item_id) <> v_tenant then
    raise exception 'private: target item % not owned by tenant %', new.item_id, v_tenant;
  end if;
  if new.target_tenant is null or new.target_tenant = v_tenant or
     private.item_shares_with(new.item_id, v_tenant) or
     private.item_shares_target(new.target_tenant) then
    raise exception 'private: invalid share target or existing share';
  end if;
  return new;
end;
$$;

alter table public.items enable row level security;
alter table public.item_shares enable row level security;

create policy items_select on public.items
  for select to authenticated
  using (private.current_tenant_id() is not distinct from tenant_id
     or private.item_shares_with(id, private.current_tenant_id()));

create policy items_insert on public.items
  for insert to authenticated
  with check (private.current_tenant_id() is not distinct from tenant_id
     and private.is_admin());

create policy items_update on public.items
  for update to authenticated
  using (private.current_tenant_id() is not distinct from tenant_id
     and private.is_admin())
  with check (private.current_tenant_id() is not distinct from tenant_id
     and private.is_admin());

create policy items_delete on public.items
  for delete to authenticated
  using (private.current_tenant_id() is not distinct from tenant_id
     and private.is_admin());

create policy item_shares_select on public.item_shares
  for select to authenticated
  using (private.current_tenant_id() = target_tenant
     or private.item_shares_with(item_id, private.current_tenant_id()));

create policy item_shares_insert on public.item_shares
  for insert to authenticated
  with check (private.item_grant(item_id, target_tenant, expires_at) is null);

create policy item_shares_update on public.item_shares
  for update to authenticated
  using (private.item_has(item_id, private.current_tenant_id()))
  with check (private.item_has(item_id, private.current_tenant_id()));

create policy item_shares_delete on public.item_shares
  for delete to authenticated
  using (private.item_has(item_id, private.current_tenant_id()));

create trigger trg_items_public_init
  before insert or update on public.items
  for each row execute function private.init_public();

create trigger trg_item_shares_shared_init
  before insert on public.item_shares
  for each row execute function private.init_shared();
