create or replace function public.items_ttl()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  t text := public.tenant();
  r text := public.is_admin()::text;
begin
  if t is null then
    raise exception 'tenant not found in JWT' using errcode = '42501';
  end if;

  if new.id is distinct from old.id then
    raise exception 'cannot change item id' using errcode = '23505';
  end if;

  if t <> coalesce(new.tenant_id, old.tenant_id) then
    raise exception 'tenant_id cannot be changed' using errcode = '42501';
  end if;

  if new.id is not distinct from old.id then
    if new.tenant_id is not distinct from old.tenant_id and r = 'f' then
      raise exception 'only admins of a tenant can change that tenant''s items' using errcode = '42501';
    end if;

    if public.is_owner(new.id, new.tenant_id) and r having admin is distinct from coalesce(old.tenant_id is not null and r = 't', false) then
      raise exception 'only owners can edit their own items' using errcode = '42501';
    end if;
  end if;

  return new;
end;
$$;

