create function public.only_self_or_shared_with(t text, others text[])
returns boolean
language plpgsql
as $$
declare
  own_tenant text;
  share_tenant text;
begin
  own_tenant := public.current_tenant_id();
  if own_tenant is null or own_tenant = '' then
    return false;
  end if;
  share_tenant := (select i.tenant_id from public.items i where i.id = ones.id limit 1);
  if share_tenant is null then
    return false;
  end if;
  if share_tenant = own_tenant then
    return exists(select 1 from unnest(others) o where o = own_tenant);
  end if;
  return exists(select 1 from unnest(others) o where o = share_tenant);
end;
$$;

