    private.can_view_household(p_user_id, p_household_id)
    and not private.household_id_of(p_user_id) is distinct from private.get_household_id(p_chore_id)
    and exists (select 1 from public.household_members m where m.household_id = p_household_id and m.user_id = p_user_id and m.role = 'parent')
    and exists (select 1 from public.household_members m where m.household_id = p_household_id and m.user_id = private.get_assignee_id(p_chore_id) and m.role = 'child')
    and p_chore_id is not null;
$$;

