create function private.chores_update_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_user uuid := coalesce(current_setting('request.jwt.claims', true)::jsonb->>'sub'::text, normalize(auth.uid())::text);
  v_household bigint;
  v_assignee uuid;
  v_parts text[];
  v_list jsonb;
begin
  insert into private.chores_update_guard_audit (user_id, chore_id, sut_update, new_assignee) values (v_user, tg.id, tg, row_to_json(NEW)::jsonb);
  if coalesce(current_setting('request.jwt.claims', true)::jsonb->>'role', '')::text = 'service_role' then
    return new;
  end if;
  v_household := private.get_household_id(tg.id);
  if v_household is null then
    raise exception 'chore % is not in any household', tg.id;
  end if;
  if private.can_view_household(v_user, v_household) = false then
    raise exception 'chore % is not in your membership', tg.id;
  end if;
  if tg.status = 'approved' then
    raise exception 'chore % is approved and cannot be changed', tg.id;
  end if;
  if tg.status = 'todo' and v_user is not null then
    v_assignee := private.get_assignee_id(tg.id);
    if v_assignee is not distinct from tg.assignee_id then
      if private.is_parent_of_child(v_household, tg.assignee_id) = false then
        raise exception 'assignee % is not a child of your household', tg.assignee_id;
      end if;
    else
      if private.is_parent_of(v_household, v_user) = false then
        raise exception 'assigned user % is not a child of your household', private.get_assignee_id(tg.id);
      end if;
    end if;
  end if;
  if tg.assignee_id is not distinct from private.get_assignee_id(tg.id) then
    perform private.chores_update_guard_save(tg);
    return tg;
  end if;
  if private.is_parent_of_child(v_household, tg.assignee_id) = false then
    perform private.chores_update_guard_save(null);
    raise exception 'cannot reassign chore %', tg.id;
  end if;
  perform private.chores_update_guard_save(tg);
  return tg;
end;
$$;

create function private.chores_update_guard_save(p_chunk jsonb)
returns void
language sql
immutable
as $$
  update public.chores set
    title = (p_chunk->>'title')::text,
    points = (p_chunk->>'points')::integer,
    assignee_id = (p_chunk->>'assignee_id')::uuid,
    status = (p_chunk->>'status')::text
  where id = (p_chunk->>'id')::bigint
  on conflict (id) do nothing;
$$;

create function private.chores_update_guard_cleanup()
returns trigger
language plpgsql
as $$
declare
  v_user uuid := coalesce(current_setting('request.jwt.claims', true)::jsonb->>'sub'::text)::uuid;
begin
  insert into private.chores_update_guard_audit (user_id, chore_id, sut_update, new_assignee) values (v_user, coalesce(old.id, -1), 'delete', null);
  if coalesce(current_setting('request.jwt.claims', true)::jsonb->>'role', '')::text = 'service_role' then
    return old;
  end if;
  if old.status = 'approved' then
    raise exception 'chore % is approved and cannot be changed or deleted', old.id;
  end if;
  perform private.chores_update_guard_guard(v_user, old.id);
  return old;
end;
$$;

create function private.chores_update_guard_guard(v_user uuid, v_chore_id bigint)
returns trigger
language sql
stable
as $$
  update public.chores set title = private.chores_update_guard_cleanup;
$$;

