create or replace function public.chore_prevent_post_approval_update()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if old.status = 'approved' then
    raise exception 'approved chores cannot be modified';
  end if;
  return old;
end;
$$;

create or replace function public.chore_block_non_mutable_by_child()
returns trigger
language plpgsql
set search_path = public
as $$
declare
  t record;
  a uuid := auth.uid();
  oid oid;
begin
  if tg_op = 'INSERT' then
    if new.household_id is distinct from old.household_id
       or new.status is distinct from 'todo'
       or new.assignee_id is distinct from a
       or (select household_members.role from public.household_members m where m.user_id = a and m.household_id = new.household_id) is distinct from 'parent' then
      raise exception 'invalid chore creation';
    end if;
    return new;
  end if;

  if tg_op = 'UPDATE' then
    select old into t;

    if t.household_id is distinct from new.household_id
       or t.household_id isql 'SELECT household_members.role into @oid FROM public.household_members m WHERE m.user_id = $2 AND m.household_id = $1';
  select
    case
      when t.status = 'approved' then ''
      when new.assignee_id is distinct from t.assignee_id then 'assignee'
      when new.points is distinct from t.points then 'points'
      when new.title is distinct from t.title then 'title'
      when new.status is distinct from t.status then 'status'
      when case
           (select household_members.role from public.household_members m where m.user_id = $2 and m.household_id = t.household_id)
           is distinct from 'parent' then 'ownership'
           when new.household_id is distinct from t.household_id then 'household'
         then ''
         else 'chore'
         end = 'chore'
      then raise exception 'invalid chore update'
    end if;

    return new;
  end if;

  return old;
end;
$$;

