returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.household_members m
    where m.user_id = p_user_id
      and m.role = 'child'
  );
$$;

create or replace function public.chore_household_owner(p_household_id bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.household_members m
    where m.household_id = p_household_id
      and m.user_id = auth.uid()
      and m.role = 'parent'
  );
$$;

create or replace function public.chore_valid(p_household_id bigint, p_assignee_id uuid)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.household_members m
    where m.household_id = p_household_id
      and m.user_id = p_assignee_id
      and m.role = 'child'
  );
$$;

create or replace function public.chore_assignment_valid()
returns trigger
language plpgsql
as $$
declare
  v_user_id uuid := auth.uid();
  v_household_id bigint;
begin
  v_household_id := (select h.id from public.households h where h.id = new.household_id);
  if v_household_id is null
     or not public.is_household_member(v_user_id)
     or not public.chore_valid(v_household_id, new.assignee_id)
  then
    raise exception 'Invalid chore assignment';
  end if;
  return new;
end;
$$;

create or replace function public.check_chore_status_change()
returns trigger
language plpgsql
as $$
declare
  v_new_points integer := new.points;
  v_new_assignee_id uuid := new.assignee_id;
begin
  if old.status = 'approved' then
    raise exception 'Approved chores cannot be changed';
  end if;

  if tg_op = 'UPDATE' then
    if old.assignee_id is distinct from new.assignee_id
       or old.title is distinct from new.title
       or old.points is distinct from new.points
       or old.points is distinct from v_new_points
       or old.household_id is distinct from new.household_id
    then
      raise exception 'Only status can be changed on chores';
    end if;

    if public.is_household_child(v_new_assignee_id) then
      if old.status = 'todo'
         and public.can_read_household(auth.uid(), old.household_id)
         and public.chore_household_owner(old.household_id)
      then
        if new.status = 'done' then
          return new;
        end if;
      end if;
      raise exception 'Children can only approve their own todo chores';
    end if;
  end if;

  return new;
end;
$$;

create or replace function public.chore_status_guard()
returns trigger
language plpgsql
as $$
declare
  v_user_id uuid := auth.uid();
begin
  if public.is_household_child(v_user_id) then
    if old.status = 'todo'
       and public.can_read_household(v_user_id, old.household_id)
       and public.chore_household_owner(old.household_id)
       and new.status = 'done'
       and public.is_household_child(new.assignee_id)
       and new.household_id = old.household_id
       and new.assignee_id = old.assignee_id
    then
      return new;
    end if;
    raise exception 'Permission denied';
  end if;

  if old.status = 'approved' then
    raise exception 'Approved chores cannot be changed';
  end if;

  if tg_op = 'DELETE' then
    raise exception 'Chores cannot be deleted';
  end if;

  return new;
end;
$$;

create policy households_select on public.households
for select to authenticated
using (public.can_read_household(auth.uid(), id));

create policy household_members_select on public.household_members
for select to authenticated
using (public.can_read_household(auth.uid(), household_id));

create policy chores_select on public.chores
for select to authenticated
using (public.can_read_household(auth.uid(), household_id));

create policy chores_insert on public.chores
for insert to authenticated
with check (
  public.is_household_parent(auth.uid())
  and public.chore_valid(household_id, assignee_id)
  and status = 'todo'
);

create policy chores_update on public.chores
for update to authenticated
using (
  public.is_household_parent(auth.uid())
  and public.can_read_household(auth.uid(), household_id)
  and old.status != 'approved'
  and (
    public.is_household_child(auth.uid())
    and old.status = 'todo'
    and (
      (new.status = 'done'
       and public.is_household_child(new.assignee_id)
       and new.household_id = old.household_id
       and new.assignee_id = old.assignee_id)
    )
    or public.chore_household_owner(household_id)
  )
)
with check (
  public.is_household_parent(auth.uid())
  and public.chore_valid(household_id, assignee_id)
  and public.check_chore_status_change()
);

create policy chores_delete on public.chores
for delete to authenticated
using (
  public.is_household_parent(auth.uid())
  and public.can_read_household(auth.uid(), household_id)
  and old.status not in ('approved', 'completed')
);

create trigger chore_assignment_valid
before insert or update on public.chores
for each row execute function public.chore_valid(household_id, assignee_id);

create trigger check_chore_status_change
before update on public.chores
for each row execute function public.check_chore_status_change();

create trigger chore_status_guard
before update or delete on public.chores
for each row execute function public.chore_status_guard();

