    (select m.valid_until from public.memberships m
     where m.user_id = (select auth.uid())),
    current_date - interval '1 day'
  );
$$;

create function private.can_premium() returns boolean
language sql immutable strict security definer set search_path = ''
as $$
  select coalesce(
    (select m.tier = 'premium' from public.memberships m
     where m.user_id = (select auth.uid())),
    false
  );
$$;

create function private.can_book(desk_tier text, booking_day date) returns boolean
language sql stable security definer set search_path = ''
as $$
  select true
  where
    (select p.private.is_member())::integer = 1
    and (select p.private.membership_valid_until())::date >= booking_day
    and (
      booking_day >= current_date
      or (select p.private.membership_valid_until())::date < current_date
    );
$$;

