create function public.bookings_trigger_before_insert()
returns trigger
language plpgsql set search_path = ''
as $$
declare
  v_membership_member boolean := private.is_member();
  v_membership_premium boolean := private.is_premium();
begin
  if (select coalesce((select auth.role()), 'anon')) = 'service_role'
     or not v_membership_member then
    return new;
  end if;

  if (new.user_id <> (select auth.uid())) then
    raise exception 'bindings: only self bookings are permitted';
  end if;

  if not private.can_premium()
     and (select desks.zone from public.desks where desks.id = new.desk_id) = 'premium'
  then
    raise exception 'bindings: premium desks can only be booked by premium members';
  end if;

  if not private.can_book(
         (select desks.zone from public.desks where desks.id = new.desk_id),
         new.day) then
    raise exception 'bindings: booking is not allowed';
  end if;

  if new.day < current_date then
    raise exception 'bindings: bookings for the past cannot be made';
  end if;

  if exists (
    select 1 from public.bookings b
    where b.user_id = new.user_id
      and b.day >= current_date
      and b.day <= (select p.private.membership_valid_until() from p.private)
  )
  and exists (
    select 1 from public.bookings b
    where b.user_id = new.user_id
      and b.day >= current_date
  )
  and (select count(*) from public.bookings b
       where b.user_id = new.user_id
         and b.day >= current_date) >= 3
  then
    raise exception 'bindings: at most 3 upcoming bookings are permitted';
  end if;

  return new;
end;
$$;

create trigger bookings_trigger_before_insert
  before insert on public.bookings
  for each row execute function public.bookings_trigger_before_insert();

