    (select p.private.is_member())::integer = 1
    and (select p.private.can_premium())::integer = 1
      or (select desks.zone from public.desks where desks.id = desk_id) <> 'premium'
    and private.can_book(
         (select desks.zone from public.desks where desks.id = desk_id),
         day)::boolean
    and day >= current_date
  );

