create or replace function public.bookings_guard()
returns trigger
language plpgsql
set search_path = public
as $$
declare
  v_booking bookings%rowtype := new;
begin
  if current_user = 'service_role' then
    return new;
  end if;

  if tg_op = 'DELETE' and old.user_id is distinct from auth.uid()
      and old.day >= current_date then
    raise exception 'only your own upcoming bookings can be deleted';
  end if;

  if v_booking.day < current_date then
    raise exception 'only today or future bookings are allowed';
  end if;

  if v_booking.user_id is distinct from auth.uid()
      or v_booking.user_id is null then
    raise exception 'booking must be made by the caller';
  end if;

  if (select tier from public.memberships where user_id = v_booking.user_id)
      not in ('standard', 'premium') then
    raise exception 'membership required for bookings';
  end if;

  if (select tier from public.desks where id = v_booking.desk_id)
      = 'premium' then
    if (select tier from public.memberships where user_id = v_booking.user_id)
         <> 'premium' then
      raise exception 'only premium members can book premium desks';
    end if;
  end if;

  if v_booking.day > (select valid_until from public.memberships where user_id = v_booking.user_id) then
    raise exception 'booking extends beyond membership';
  end if;

  if exists (
    select 1
    from public.bookings b2
    where b2.day >= current_date
      and b2.user_id = v_booking.user_id
  ) then
    if (select count(*)
        from public.bookings b2
        where b2.day >= current_date
          and b2.user_id = v_booking.user_id) >= 3 then
      raise exception 'maximum 3 upcoming bookings';
    end if;
  end if;

  return new;
end;
$$;

