create or replace function public.submissions_security()
returns trigger
language plpgsql
as $$
declare
  v_event timestamptz;
  v_deadline timestamptz;
begin
  if new.id is distinct from old.id then
    raise exception 'submissions.id is immutable';
  end if;

  if new.updated_at is distinct from old.updated_at then
    raise exception 'submissions.updated_at is immutable';
  end if;

  select t.event_id, e.deadline
    into v_event, v_deadline
  from public.teams t
  join public.events e on e.id = t.event_id
  where t.id = new.team_id;

  if not found then
    raise exception 'no such team';
  end if;

  if v_deadline is not null and now() > v_deadline then
    raise exception 'deadline passed';
  end if;

  if public.is_team_member(new.team_id) then
    if not public.can_submissions_changed() then
      raise exception 'out of sync';
    end if;
  elsif public.is_judge(v_event) then
    if not public.can_submissions_changed() then
      raise exception 'out of sync';
    end if;
  else
    raise exception 'not a team member or judge';
  end if;

  return new;
end;
$$;

