create or replace function public.is_own_team_member(p_team_id bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.team_members tm
    where tm.team_id = p_team_id
      and tm.user_id = (select auth.uid())
  );
$$;

create or replace function public.is_own_team_submission(p_team_id bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.team_members tm
    where tm.team_id = p_team_id
      and tm.user_id = (select auth.uid())
  );
$$;

create or replace function public.is_own_event_judge(p_event_id bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.judges j
    where j.event_id = p_event_id
      and j.user_id = (select auth.uid())
  );
$$;

create or replace function public.is_deadline_passed(p_event_id bigint)
returns boolean
language sql
stable
as $$
  select e.deadline < now()
  from public.events e
  where e.id = p_event_id
  limit 1;
$$;

create or replace function public.is_submission_editable(p_team_id bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.teams t
    join public.events e on e.id = t.event_id
    where t.id = p_team_id
      and e.deadline > now()
      and public.is_own_team_member(p_team_id)
  );
$$;

create or replace function public.has_event_deadline(p_event_id bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.events e
    where e.id = p_event_id
      and e.deadline is not null
  );
$$;

create policy events_select_authenticated
on public.events
for select
to authenticated
using (true);

create policy teams_select_authenticated_or_own_member
on public.teams
for select
to authenticated
using (true);

create policy team_members_select_own
on public.team_members
for select
to authenticated
using (user_id = (select auth.uid()));

create policy submissions_select_own_team_or_judge_after_deadline
on public.submissions
for select
to authenticated
using (
  public.is_own_team_submission(team_id)
  or (
    public.has_event_deadline(
      (select t.event_id from public.teams t where t.id = submissions.team_id)
    )
    and public.is_own_event_judge(
      (select t.event_id from public.teams t where t.id = submissions.team_id)
    )
    and public.is_deadline_passed(
      (select t.event_id from public.teams t where t.id = submissions.team_id)
    )
  )
);

create policy submissions_insert_own_team_before_deadline
on public.submissions
for insert
to authenticated
with check (
  public.is_own_team_submission(team_id)
  and public.is_submission_editable(team_id)
  and public.has_event_deadline(
    (select t.event_id from public.teams t where t.id = submissions.team_id)
  )
);

create policy submissions_update_own_team_before_deadline
on public.submissions
for update
to authenticated
using (
  public.is_own_team_submission(team_id)
  and public.is_submission_editable(team_id)
  and public.has_event_deadline(
    (select t.event_id from public.teams t where t.id = submissions.team_id)
  )
)
with check (
  public.is_own_team_submission(team_id)
  and public.is_submission_editable(team_id)
  and public.has_event_deadline(
    (select t.event_id from public.teams t where t.id = submissions.team_id)
  )
);

