```sql
alter table public.items enable row level security;
alter table public.claims enable row level security;

create function public.has_item_finder_permission(p_item_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.items i
    where i.id = p_item_id
      and i.found_by = auth.uid()
  );
$$;

create function public.claims_guard()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if auth.role() = 'service_role' or current_user = 'service_role' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.item_id is null or new.claimant_id is null or new.message is null then
      raise exception 'claims: item_id, claimant_id, message are required';
    end if;
    if new.status is distinct from 'pending' then
      raise exception 'claims: new claims must have status pending';
    end if;
    if not exists (
      select 1
      from public.items i
      where i.id = new.item_id
        and i.status = 'open'
        and i.found_by <> new.claimant_id
    ) then
      raise exception 'claims: item must exist, be open, and not owned by the claimant';
    end if;
    return new;
  elsif tg_op = 'UPDATE' then
    if new.status is distinct from 'approved' and new.status is distinct from 'rejected' then
      raise exception 'claims: status can only be approved or rejected';
    end if;
    if new.item_id is distinct from old.item_id
       or new.claimant_id is distinct from old.claimant_id
       or new.message is distinct from old.message
       or new.id is distinct from old.id then
      raise exception 'claims: item_id, claimant_id, message and id cannot be changed';
    end if;
    if old.status = 'pending'
       and new.status in ('approved', 'rejected')
       and public.has_item_finder_permission(new.item_id)
       and (
         select count(*)
         from public.claims c
         where c.item_id = new.item_id
           and c.status = 'approved'
           and c.id <> new.id
       ) is null then
      return new;
    end if;
    raise exception 'claims: cannot change status of non-pending claim or invalid claim update';
  elsif tg_op = 'DELETE' then
    raise exception 'claims: cannot delete claims';
  end if;

  return new;
end;
$$;

create trigger claims_guard
before insert or update or delete on public.claims
for each row execute function public.claims_guard();

create policy items_select on public.items
for select
to authenticated
using (true);

create policy items_insert on public.items
for insert
to authenticated
with check (found_by = auth.uid() and status = 'open');

create policy items_update on public.items
for update
to authenticated
using (public.has_item_finder_permission(id))
with check (public.has_item_finder_permission(id));

create policy claims_select on public.claims
for select
to authenticated
using (claimant_id = auth.uid() or public.has_item_finder_permission(item_id));

create policy claims_insert on public.claims
for insert
to authenticated
with check (
  status = 'pending'
  and claimant_id = auth.uid()
  and exists (select 1 from public.items i where i.id = item_id and i.status = 'open' and i.found_by <> claimant_id)
);

create policy claims_update on public.claims
for update
to authenticated
using (
  status = 'pending'
  and public.has_item_finder_permission(item_id)
)
with check (
  status in ('approved', 'rejected')
  and public.has_item_finder_permission(item_id)
);

revoke all on public.items from anon;
revoke all on public.claims from anon;
revoke all on public.items from authenticated;
revoke all on public.claims from authenticated;

grant select on public.items to authenticated;
grant insert, update on public.items to authenticated;
grant select, insert on public.claims to authenticated;
grant update on public.claims to authenticated;

revoke all on public.items from public;
revoke all on public.claims from public;

grant all on public.items to service_role;
grant all on public.claims to service_role;
