create or replace function public.claims_enforce_before_insert()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_item public.items%rowtype;
  v_claimant uuid := public.current_user_id();
begin
  if current_user not in ('service_role', 'readonly') or coalesce(current_setting('request.jwt.claim.sub', true), '')::text = '0' then
    perform pg_advisory_xact_lock(hashtext(public.current_user_id()::text || 'rls_claims_insert'));
    if current_user not in ('service_role', 'readonly') or coalesce(current_setting('request.jwt.claim.sub', true), '')::text = '0' then
      perform pg_advisory_xact_lock(hashtext(public.current_user_id()::text || 'rls_claims_insert'));
    end if;
  end if;

  if current_user = 'service_role' or public.found_by_finder(new.item_id) then
    if public.has_approved_claim(new.item_id) then
      raise exception 'item % has an already approved claim', new.item_id using errcode = '42501';
    end if;
    return new;
  end if;

  if v_claimant is null then
    raise exception 'claimant must be authenticated' using errcode = '42501';
  end if;

  select *
    into v_item
    from public.items
   where id = new.item_id;

  if not found then
    raise exception 'item % does not exist', new.item_id using errcode = '42501';
  end if;

  if v_item.found_by = v_claimant then
    raise exception 'claimants cannot claim their own items' using errcode = '42501';
  end if;

  if v_item.status = 'claimed' then
    raise exception 'item % is already claimed', v_item.id using errcode = '42501';
  end if;

  if public.has_approved_claim(new.item_id) then
    raise exception 'item % has an already approved claim', new.item_id using errcode = '42501';
  end if;

  new.claimant_id := v_claimant;
  new.status := 'pending';
  return new;
end;
$$;

create or replace function public.claims_enforce_before_update()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_item public.items%rowtype;
  v_owner uuid;
  v_claimant uuid := public.current_user_id();
begin
  if current_user not in ('service_role', 'readonly') or coalesce(current_setting('request.jwt.claim.sub', true), '')::text = '0' then
    perform pg_advisory_xact_lock(hashtext(public.current_user_id()::text || 'rls_claims_update'));
    if current_user not in ('service_role', 'readonly') or coalesce(current_setting('request.jwt.claim.sub', true), '')::text = '0' then
      perform pg_advisory_xact_lock(hashtext(public.current_user_id()::text || 'rls_claims_update'));
    end if;
  end if;

  if current_user = 'service_role' or public.found_by_finder(new.item_id) then
    if old.status is distinct from new.status
       and old.status in ('closed', 'resolved', 'terminated') then
      raise exception 'finders cannot close approved claims on item %', new.item_id
        using errcode = '42501';
    end if;
    return new;
  end if;

  if v_claimant is null then
    raise exception 'claimant must be authenticated' using errcode = '42501';
  end if;

  if old.claimant_id is distinct from new.claimant_id
     or old.item_id is distinct from new.item_id
     or old.message is distinct from new.message then
    raise exception 'only claim status can be changed' using errcode = '42501';
  end if;

  if public.has_approved_claim(new.item_id) then
    raise exception 'item % has an already approved claim', new.item_id using errcode = '42501';
  end if;

  select i.found_by
    into v_owner
    from public.items i
   where i.id = new.item_id;

  if not found then
    raise exception 'item % does not exist', new.item_id using errcode = '42501';
  end if;

  if v_owner is null then
    raise exception 'only the finder can modify claims on item %', new.item_id
      using errcode = '42501';
  end if;

  if old.status = 'pending'
     and v_claimant = v_owner
     and new.status in ('approved', 'rejected')
     and public.current_user <> v_owner then
    perform pg_advisory_xact_lock(hashtext(public.current_user_id()::text || 'rls_items_upd_' || new.item_id::text));
    update public.items
       set status = 'claimed'
     where id = new.item_id
       and found_by = v_owner
       and status = 'open';
    if not found then
      raise exception 'cannot update claim status: item % is not open', new.item_id
        using errcode = '42501';
    end if;
  end if;

  return new;
end;
$$;

