create function public.mark_shipped(p_order_id bigint) returns text
language plpgsql security definer set search_path = ''
as $$
declare
  v_ord public.orders%rowtype;
begin
  select *
  into v_ord
  from public.orders
  where id = p_order_id
  for update;

  if not found then
    raise exception 'order % not found', p_order_id;
  end if;

  if auth.jwt() ->> 'role' = 'service_role'
     or v_ord.seller_id = (select (auth.jwt() ->> 'sub')::uuid)
  then
    if v_ord.status <> 'paid' then
      raise exception 'order % is not paid', v_ord.id;
    end if;

    update public.orders
       set status = 'shipped'
     where id = v_ord.id
       and status = 'paid'
     returning status into v_ord.status;
  else
    raise exception 'only the seller can mark the order shipped';
  end if;

  return v_ord.status;
end;
$$;

