returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.articles a
    where a.id = p_id
      and (
        (public.is_editor() and a.status = 'in_review')
        or (a.author_id = (select auth.uid()) and a.status in ('draft', 'in_review'))
      )
  );
$$;

create or replace function public.before_update_articles()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception 'not authenticated', hint = 'public.before_update_articles';
  end if;

  if new.id is distinct from old.id then
    raise exception 'article identifiers cannot be changed', hint = 'public.before_update_articles';
  end if;

  if old.status = 'published' then
    raise exception 'published articles cannot be changed', hint = 'public.before_update_articles';
  end if;

  if new.status = 'draft' then
    if old.status = 'published' then
      raise exception 'published articles cannot be reverted to draft via the app', hint = 'public.before_update_articles';
    end if;
    if v_uid <> old.author_id and not public.is_editor() then
      raise exception 'only authors or editors can set status to draft', hint = 'public.before_update_articles';
    end if;
    new.published_at := null;
    return new;
  end if;

  if new.status = 'in_review' then
    if old.status not in ('draft', 'in_review') then
      raise exception 'only drafts or in-review articles can be submitted', hint = 'public.before_update_articles';
    end if;
    if not public.can_edit_or_publish(old.id) then
      raise exception 'not authorized to edit/publish article id %', old.id, hint = 'public.before_update_articles';
    end if;
    new.published_at := null;
    return new;
  end if;

  if new.status = 'published' then
    if old.status <> 'in_review' then
      raise exception 'only in-review articles can be published', hint = 'public.before_update_articles';
    end if;
    if v_uid <> old.author_id and not public.is_editor() then
      raise exception 'only authors or editors can publish articles', hint = 'public.before_update_articles';
    end if;
    new.published_at := now();
    return new;
  end if;

  raise exception 'invalid status value %', new.status, hint = 'public.before_update_articles';
  return new;
end;
$$;

