create or replace function public.enforce_articles_policy()
returns trigger
language plpgsql
as $$
begin
  if current_setting('request.jwt.claim.role') = 'service_role'
     or public.is_editor() then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.id is distinct from nextval('public.articles_id_seq')
       or new.author_id is distinct from (select auth.uid())
       or new.status is distinct from 'draft' then
      raise exception 'Insert policy violation';
    end if;
  elsif tg_op = 'UPDATE' then
    if new.id is distinct from old.id then
      raise exception 'Only id value preservation is allowed';
    end if;
    if new.status = 'published' then
      raise exception 'Writers cannot publish articles';
    end if;
    if old.status not in ('draft', 'in_review')
       or (new.status not in ('draft', 'in_review')) then
      raise exception 'Writer writes only drafts, editors read only review';
    end if;
    if new.author_id is distinct from (select auth.uid()) then
      raise exception 'Only the author may update';
    end if;
  elsif tg_op = 'DELETE' then
    if old.status not in ('draft', 'in_review')
       or (old.status = 'draft' and old.author_id is distinct from (select auth.uid())) then
      raise exception 'Only drafts of the author may be deleted';
    end if;
  end if;

  return new;
end;
$$;

