    join public.enrollments e on e.course_id = t.course_id
    where p.id = pid
      and e.user_id = (select auth.uid())
      and (auth.role() = 'service_role' or (e.role = 'ta') or (e.role = 'student' and p.author_id = (select auth.uid()) and not t.is_locked))
  );
