create or replace function public.enforce_thread_not_locked()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if tg_op = 'INSERT' then
    if new.is_locked is true then
      raise exception 'threads cannot be locked at insert time';
    end if;
    return new;
  end if;

  if new.is_locked = true then
    if (select e.role from public.enrollments e where e.course_id = new.course_id and e.user_id = (select (select auth.uid())::text::uuid)) is distinct from 'ta' then
      raise exception 'only TAs may lock threads';
    end if;
  end if;

  return new;
end;
$$;

drop trigger if exists threads_enforce_not_locked on public.threads;
create trigger threads_enforce_not_locked
  before insert or update on public.threads
  for each row execute function public.enforce_thread_not_locked();

create or replace function public.enforce_post_not_locked()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if public.can_modify_thread(new.thread_id) is false then
    raise exception 'post may only be modified in unlocked threads';
  end if;
  return new;
end;
$$;

drop trigger if exists posts_enforce_not_locked on public.posts;
create trigger posts_enforce_not_locked
  before insert or update on public.posts
  for each row execute function public.enforce_post_not_locked();

