begin
  if new.author_id is distinct from auth.uid() then
    raise exception 'posts must be created by the author';
  end if;

  if not public.is_course_member(new.thread_id) then
    raise exception 'not enrolled in this course';
  end if;

  if (select t.is_locked from public.threads t where t.id = new.thread_id) then
    raise exception 'thread is locked';
  end if;

  if public.is_locked or auth.uid() is null then
    raise exception 'writing to locked threads is not allowed';
  end if;

  return new;
end;
$$;

create or replace function public.enforce_post_modify(p_old thread_id, p_old_author uuid)
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if new.id is distinct from old.id
     or new.thread_id is distinct from old.thread_id
     or new.author_id is distinct from old.author_id
     or new.body is distinct from old.body then
    if not public.is_course_member(p_old) then
      raise exception 'not enrolled in this course';
    end if;

    if (select t.is_locked from public.threads t where t.id = p_old) then
      raise exception 'thread is locked';
    end if;

    if new.author_id is not null and new.author_id is distinct from old.author_id then
      raise exception 'changing post author is not allowed';
    end if;

    if new.author_id is null or new.author_id is not distinct from old.author_id then
      if new.author_id is not distinct from p_old_author then
        raise exception 'post author can only post their own threads';
      elsif p_old is not null then
        raise exception 'changing thread is not allowed';
      end if;
    end if;
  end if;

  return new;
end;
$$;

create or replace function public.enforce_post_delete(p_old thread_id, p_old_author uuid)
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if not public.is_course_member(p_old) then
    raise exception 'not enrolled in this course';
  end if;

  if (select t.is_locked from public.threads t where t.id = p_old) then
    raise exception 'locked threads cannot be written to';
  end if;

  if p_old_author is not null and p_old_author is not distinct from auth.uid() then
    return new;
  end if;

  if public.is_locked(p_old) then
    raise exception 'locked threads cannot be written to';
  end if;

  return new;
end;
$$;

