  );
$$;

create or replace function public.expense_share_valid(p_expense_id bigint, p_user_id uuid)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.expenses e, public.group_members m
    where e.id = p_expense_id
      and m.group_id = e.group_id
      and m.user_id = p_user_id
      and public.can_modify_expense(p_expense_id)
      and e.paid_by in (
        select m2.user_id
        from public.group_members m2
        where m2.group_id = e.group_id
      )
  );
$$;

create or replace function public.expenses_update_guard()
returns trigger
language plpgsql
as $$
begin
  if public.can_modify_expense(tg.id) and public.is_group_member(old.group_id) then
    return new;
  end if;
  return null;
end;
$$;

create or replace function public.expenses_shares_guard()
returns trigger
language plpgsql
as $$
declare
  v_member boolean;
  v_payer  uuid;
  v_group  bigint;
begin
  if tg.op = 'DELETE' and
     public.can_modify_expense(old.expense_id) and public.is_group_member(old.expense_id) then
    return old;
  end if;

  if public.can_modify_expense(old.expense_id) then
    select e.paid_by, e.group_id into v_payer, v_group
    from public.expenses e
    where e.id = old.expense_id;

    v_member := exists (
      select 1
      from public.group_members m
      where m.group_id = v_group and m.user_id = tg.user_id
    );

    if public.is_group_member(v_group)
       and v_member
       and v_payer = tg.user_id then
      return new;
    end if;
  end if;

  return null;
end;
$$;

create or replace function public.expenses_insert_guard()
returns trigger
language plpgsql
as $$
declare
  v_member boolean;
  v_payer  uuid;
  v_group  bigint;
begin
  if tg.paid_by is distinct from auth.uid() then
    raise exception 'expense can only be paid by the expense author';
  end if;

  select m.user_id, g.id into v_payer, v_group
  from public.expenses e
  join public.group_members m on m.group_id = e.group_id
  join public.groups g on g.id = e.group_id
  where e.id = tg.id;

  v_member := exists (select 1 from public.group_members m2 where m2.group_id = v_group and m2.user_id = tg.paid_by);

  if public.can_read_expense(tg.id) and public.is_group_member(v_group) and v_member and tg.paid_by = auth.uid() then
    return new;
  end if;

  raise exception 'expense insert rejected';
end;
$$;

