create or replace function public.org_is_owner(p_org_id bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.org_members m
    where m.org_id = p_org_id
      and m.user_id = auth.uid()
      and m.role = 'owner'
  );
$$;

create or replace function public.org_row_security()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if tg_op = 'INSERT' then
    if auth.uid() is null then
      raise exception 'not authenticated';
    end if;
    if new.created_by is distinct from auth.uid() then
      raise exception 'created_by must be current user';
    end if;
    if not exists (select 1 from public.org_members m where m.org_id = new.id and m.user_id = auth.uid()) then
      insert into public.org_members (org_id, user_id, role) values (new.id, auth.uid(), 'owner');
    end if;
    return new;
  elsif tg_op = 'UPDATE' then
    if not public.org_may_write(old.id) then
      raise exception 'not permitted';
    end if;
    if old.name is distinct from new.name then
      if not public.org_is_owner(old.id) then
        raise exception 'only the owner can rename the organization';
      end if;
    end if;
    return new;
  elsif tg_op = 'DELETE' then
    if old.id is not null and public.org_is_owner(old.id) then
      raise exception 'owners cannot delete their organization';
    end if;
    return old;
  end if;
  return null;
end;
$$;

