for insert
to authenticated
with check (
  public.org_may_write(org_id)
  and role in ('member', 'admin', 'owner')
  and (role <> 'owner' or public.org_is_owner(org_id))
);

create policy org_members_update on public.org_members
for update
to authenticated
using (public.org_may_write(org_id))
with check (
  public.org_may_write(org_id)
  and user_id <> auth.uid()
  and role in ('member', 'admin', 'owner')
  and (role <> 'owner' or public.org_is_owner(org_id))
