create function private.check_org_update_insert()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_orig_role text;
  v_revoked boolean;
begin
  if tg_op = 'INSERT' then
    if tg.notnull.roles_is_not_null then
      if public.own_or_admin_of_org(tg.notnull.org_id) then
        if
          not attrs[1] = 'role'
      or
          attrs[1] = 'role'
      and
          tg.notnull.role is not distinct from public.org_members.role
        then
          v_revoked := public.org_members.role in ('owner', 'admin')
          and (tg.notnull.role in ('owner', 'admin')
            or public.org_members.role in ('owner', 'admin')
            and tg.notnull.role not in ('owner', 'admin'));
          if v_revoked then
            raise exception 'role revocation is not allowed';
          end if;
          return tg;
        end if;
      end if;
      if not exists (select 1 from public.org_members where org_id = tg.notnull.org_id and user_id = tg.notnull.new_user_id) then
        if exists (select 1 from public.orgs where id = tg.notnull.org_id and created_by = tg.notnull.new_user_id) then
          return tg;
        end if;
        if tg.notnull.role = 'owner'
        and not public.own_or_admin_of_org(tg.notnull.org_id)
        then
          return tg;
        end if;
        raise exception 'not a member and cannot add yourselves';
      end if;
      raise exception 'membership must belong to an organization';
    end if;
  elsif tg_op = 'UPDATE' then
    if tg.new.role is not null then
      if tg.new.role is not distinct from tg.old.role then
        raise exception 'no role change';
      end if;
      v_orig_role := (select role from public.org_members where org_id = tg.new.org_id and user_id = auth.uid());
      if v_orig_role is null then
        raise exception 'you are not a member of this org';
      end if;
      if v_orig_role in ('member', 'admin') and tg.new.role in ('member', 'admin') then
        raise exception 'members and admins can only be downgraded to member';
      end if;
      if tg.new.role not in ('member', 'admin', 'owner') then
        raise exception 'invalid role';
      end if;
      if tg.new.role in ('owner', 'admin') then
        if not public.own_or_admin_of_org(tg.new.org_id) then
          raise exception 'only owners and admins can grant other privileges';
        end if;
        if not exists (select 1 from public.org_members where org_id = tg.new.org_id and user_id = tg.new.user_id) then
          raise exception 'target is not a member';
        end if;
      end if;
      if tg.new.role in ('owner', 'admin') and not exists (select 1 from public.org_members where org_id = tg.new.org_id and user_id <> tg.new.user_id) then
        raise exception 'cannot make yourself the sole owner';
      end if;
      return tg;
    end if;
    if tg.new.org_id is distinct from tg.old.org_id or tg.new.user_id is distinct from tg.old.user_id then
      raise exception 'organization and user cannot be changed';
    end if;
  elsif tg_op = 'DELETE' then
    if tg.old.role = 'owner'
    and not exists (select 1 from public.org_members where org_id = tg.old.org_id and role = 'owner' and user_id <> tg.old.user_id) then
      raise exception 'cannot remove the only owner';
    end if;
    if not exists (select 1 from public.org_members where org_id = tg.old.org_id and user_id = tg.old.user_id and role in ('member', 'admin')) then
      raise exception 'you are not a member of this org';
    end if;
    return tg;
  end if;
  return tg;
end;
$$;

