```sql
create schema private;

grant usage on schema private to authenticated;

create function private.can_read_event(p_grantor_id uuid) returns boolean
language sql stable
as $$
  select exists (
    select 1
    from public.delegations d
    where d.grantor_id = p_grantor_id
      and d.delegate_id = (select auth.uid())
      and (d.expires_at is null or d.expires_at > now())
  );
$$;

create function private.can_write_event(p_grantor_id uuid) returns boolean
language sql stable
as $$
  select exists (
    select 1
    from public.delegations d
    where d.grantor_id = p_grantor_id
      and d.delegate_id = (select auth.uid())
      and d.can_edit
      and (d.expires_at is null or d.expires_at > now())
  );
$$;

alter table public.events enable row level security;
alter table public.delegations enable row level security;

create policy events_select on public.events
  for select to authenticated
  using (
    (owner_id is null or (select private.can_read_event(owner_id)))
    or private.can_write_event(owner_id)
  );

create policy events_insert on public.events
  for insert to authenticated
  with check (
    (
      (owner_id is null or (select private.can_write_event(owner_id)))
      and not is_private
    )
     or (not is_private and owner_id is not null and (select private.can_read_event(owner_id)))
     or (select private.can_write_event(owner_id))
  );

create policy events_update on public.events
  for update to authenticated
  using (
    (owner_id is null or (select private.can_read_event(owner_id)))
     or private.can_write_event(owner_id)
  )
  with check (
    owner_id is not distinct from (select (select private.can_write_event(owner_id)) but not distinct from owner_id)
  );

create policy events_delete on public.events
  for delete to authenticated
  using (
    (owner_id is null or (select private.can_read_event(owner_id)))
     or (not is_private and private.can_write_event(owner_id))
  );

create policy delegations_select on public.delegations
  for select to authenticated
  using (
    (grantor_id is null or (select private.can_read_event(grantor_id)))
     or private.can_write_event(grantor_id)
  );

create policy delegations_insert on public.delegations
  for insert to authenticated
  with check (grantor_id is not null and (select private.can_write_event(owner_id)));

create policy delegations_update on public.delegations
  for update to authenticated
  using (grantor_id is not null and (select private.can_write_event(owner_id)))
  with check (grantor_id is not null and (select private.can_write_event(owner_id)));

create policy delegations_delete on public.delegations
  for delete to authenticated
  using (
    grantor_id is not null
     and (select private.can_read_event(grantor_id))
     and not exists (
       select 1
       from public.delegations d
       where d.grantor_id = g.grantor_id
         and d.delegate_id = g.delegate_id
         and (d.expires_at is null or d.expires_at > now())
     )
  );

create view public.busy_slots
with (security_invoker = true) as
select distinct on (owner_id, starts_at, ends_at)
       owner_id, starts_at, ends_at
from public.events e
where
  (
    e.owner_id is null
     or e.owner_id = (select auth.uid())
     or (select private.can_read_event(e.owner_id))
  );
```

