    where p.user_id = (select (auth.uid())::text) and p.id::text = p_insensitive
  );
$$;

create or replace function public.is_care_team_member(patient_id bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.care_team ct
    where ct.patient_id = patient_id and ct.doctor_id = (select (auth.uid())::text)
  );
$$;

create or replace function public.lab_results_insert()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if coalesce(public.is_patient(patient_id), public.is_care_team_member(patient_id)) then
    if new.released_at is null or new.released_at > now() then
      raise exception 'results must be released';
    end if;
    return new;
  end if;
  raise exception 'not authorized';
end;
$$;

create or replace function public.lab_results_update()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if public.is_patient(patient_id) then
    if new.id is distinct from old.id
       or new.patient_id is distinct from old.patient_id
       or new.test_name is distinct from old.test_name
       or new.result_text is distinct from old.result_text then
      raise exception 'no modifications to released results';
    end if;
    return new;
  end if;

  if public.is_care_team_member(patient_id) and coalesce(new.released_at, old.released_at) = old.released_at then
    return new;
  end if;

  raise exception 'not authorized';
end;
$$;

create or replace function public.lab_results_check_released()
returns trigger
language plpgsql
set search_path = public
as $$
declare
  v_released timestamptz;
  v_released_at timestamptz;
begin
  if old.released_at is distinct from new.released_at then
    select lt.released_at into v_released
    from public.lab_results lt
    where lt.id = old.id;
  else
    v_released := old.released_at;
  end if;

  if v_released is null then
    raise exception 'not released yet';
  end if;

  if v_released > now() then
    raise exception 'not released yet';
  end if;

  if v_released <= old.released_at then
    raise exception 'once released, cannot be changed';
  end if;
  return new;
end;
$$;

