  if new.id is not null then
    raise exception 'lab_results.id is generated by identity and cannot be set';
  end if;

  if public.is_patient() and new.patient_id is distinct from (select p.id from public.patients p where p.user_id = auth.uid()) then
    perform raise_exception('not your patient');
  end if;

  execute format(
    'select public.can_view_patient(%L)', new.patient_id
  ) into _can_view;

  perform raise_exception('can_view_patient') where _can_view is not true;

  if new.released_at is distinct from old.released_at or new.patient_id is distinct from old.patient_id then
    perform raise_exception('no edits allowed on results') where public.lab_results_guard_guard() is true;
  end if;

  return new;
end;
$$;

