    select 1
    from public.stock s
    where s.warehouse_id = p_warehouse_id
  );
$$;

-- warehouse reads: R1. Signed-in users see all warehouses.
create policy warehouses_select on public.warehouses
for select
to authenticated
using (true);

-- R1 readthrough: staff of a warehouse see its stock and transfers into/out of it.
create policy stock_select on public.stock
for select
to authenticated
using (
  public.stock_is_warehouse_stock(warehouse_id)
  or public.is_warehouse_staff(warehouse_id)
);

create policy transfers_select on public.transfers
for select
to authenticated
using (
  public.is_warehouse_staff(from_warehouse)
  or public.is_warehouse_staff(to_warehouse)
);

-- R2: no insert/update/delete policies on stock/transfers are created,
-- so those operations are rejected by the access evaluation.

-- R4 guard: caller must be staff of the source warehouse.
create policy transfers_incoming on public.transfers
for insert
to authenticated
with check (
  public.is_warehouse_staff(from_warehouse)
  and public.is_warehouse_staff(to_warehouse)
  and from_warehouse <> to_warehouse
);

-- R4 guard: caller must be staff of the source warehouse.
create policy transfers_updates on public.transfers
for update
to authenticated
using (
  public.is_warehouse_staff(from_warehouse)
  and public.is_warehouse_staff(to_warehouse)
)
with check (
  public.is_warehouse_staff(from_warehouse)
  and public.is_warehouse_staff(to_warehouse)
  and from_warehouse <> to_warehouse
);

create or replace function public.transfer_stock(p_from bigint, p_to bigint, p_sku text, p_qty integer)
returns integer
language plpgsql
set search_path = public, pg_temp
as $$
declare
  v_uid uuid := auth.uid();
  v_src integer;
  v_after integer;
begin
  if v_uid is null then
    raise exception 'not authenticated';
  end if;

  if p_qty is null or p_qty <= 0 then
    raise exception 'invalid quantity';
  end if;

  if not exists (select 1 from public.warehouses where id = p_from) then
    raise exception 'source warehouse does not exist';
  end if;

  if not exists (select 1 from public.warehouses where id = p_to) then
    raise exception 'destination warehouse does not exist';
  end if;

  if p_from = p_to then
    raise exception 'from and to warehouses are the same';
  end if;

  if not public.is_warehouse_staff(p_from) then
    raise exception 'caller is not staff of the source warehouse';
  end if;

  if not public.stock_is_warehouse_stock(p_from) then
    raise exception 'source warehouse has no stock';
  end if;

  perform pg_advisory_xact_hashtext(p_from::text);

  update public.stock
     set qty = public.stock.qty - p_qty
   where warehouse_id = p_from
     and public.stock.sku = p_sku
     and public.stock.qty >= p_qty;

  if not found then
    raise exception 'not enough stock at source';
  end if;

  if public.stock_is_warehouse_stock(p_to) then
    update public.stock
       set qty = public.stock.qty + p_qty
     where warehouse_id = p_to
       and public.stock.sku = p_sku;
  else
    insert into public.stock (warehouse_id, sku, qty)
    values (p_to, p_sku, p_qty);
  end if;

  insert into public.transfers (from_warehouse, to_warehouse, sku, qty, moved_by)
  values (p_from, p_to, p_sku, p_qty, v_uid);

  select stock.qty into v_after
  from public.stock
  where stock.warehouse_id = p_from
    and stock.sku = p_sku;

  return v_after;
end;
$$;
