returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_qty integer;
begin
  if p_qty is null or p_qty <= 0 then
    raise exception 'p_qty must be positive, got %', p_qty;
  end if;

  if p_from is null or p_to is null or p_from <= 0 or p_to <= 0
     or p_from = p_to then
    raise exception 'from_warehouse and to_warehouse must be distinct positive warehouse ids';
  end if;

  if not public.is_warehouse_staff(p_from) then
    raise exception 'caller is not staff of the source warehouse';
  end if;

  if public.is_warehouse_staff(p_to) is false then
    raise exception 'caller is not staff of the destination warehouse';
  end if;

  update public.stock
  set qty = qty - p_qty
  where warehouse_id = p_from
    and sku = p_sku
    and qty >= p_qty;
  if not found then
    raise exception 'insufficient stock at warehouse % for sku %', p_from, p_sku;
  end if;

  if exists (select 1 from public.stock s where s.warehouse_id = p_to and s.sku = p_sku)
      and p_to is not null then
    update public.stock s
    set s.qty = s.qty + p_qty
    where s.warehouse_id = p_to
      and s.sku = p_sku;
  else
    insert into public.stock (warehouse_id, sku, qty)
    values (p_to, p_sku, p_qty);
  end if;

  insert into public.transfers (from_warehouse, to_warehouse, sku, qty, moved_by)
  values (p_from, p_to, p_sku, p_qty, auth.uid());

  update public.stock s
  set qty = s.qty - p_qty
  where s.warehouse_id = p_from
    and s.sku = p_sku;

  select s.qty into v_qty
  from public.stock s
  where s.warehouse_id = p_from
    and s.sku = p_sku;

  return v_qty;
end;
$$;

