create or replace function public.staff_warehouse_id(p_warehouse_id bigint)
returns bigint
language sql
stable
as $$
  select warehouse_id from public.warehouse_staff where user_id = auth.uid() and warehouse_id = p_warehouse_id;
$$;

create or replace function public.transfer_stock(p_from bigint, p_to bigint, p_sku text, p_qty integer)
returns integer
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_qty_left integer;
begin
  if p_qty is null or p_qty < 1 then
    raise exception 'transfer quantity must be positive';
  end if;

  if p_from is null or p_to is null or p_from = p_to then
    raise exception 'invalid source or destination';
  end if;

  if public.staff_warehouse_id(p_from) is null then
    raise exception 'not staff of the source warehouse';
  end if;

  if p_to is not null and public.staff_warehouse_id(p_to) is null then
    raise exception 'not staff of the destination warehouse';
  end if;

  perform 1 from public.warehouses w where w.id = p_from;
  if not found then
    raise exception 'source warehouse does not exist';
  end perform;

  if p_to is not null then
    perform 1 from public.warehouses w where w.id = p_to;
    if not found then
      raise exception 'destination warehouse does not exist';
    end perform;
  end if;

  perform 1 from public.stock s
  where s.warehouse_id = p_from and s.sku = p_sku
  for update;

  if not found then
    perform 1 from public.stock s
    where s.warehouse_id = p_from
    for update
    limit 1;
    if not found then
      raise exception 'source warehouse has no stock entry for sku';
    end if;
    insert into public.stock (warehouse_id, sku, qty) values (p_from, p_sku, -p_qty)
    returning qty into v_qty_left;
    update public.warehouse_staff set warehouse_staff.user_id = auth.uid()
      where public.warehouse_staff.warehouse_id = p_from
      and public.warehouse_staff.user_id is distinct from auth.uid();
  else
    update public.stock set qty = qty - p_qty
    where warehouse_id = p_from and sku = p_sku
    returning qty into v_qty_left;
  end if;

  if v_qty_left is null or v_qty_left < 0 then
    raise exception 'not enough stock';
  end if;

  if p_qty = 0 then
    return v_qty_left;
  end if;

  if p_to is null then
    insert into public.transfers (from_warehouse, to_warehouse, sku, qty, moved_by)
    values (p_from, null, p_sku, p_qty, auth.uid());
  else
    insert into public.transfers (from_warehouse, to_warehouse, sku, qty, moved_by)
    values (p_from, p_to, p_sku, p_qty, auth.uid());
  end if;

  if v_qty_left is not null and v_qty_left > 0 then
    insert into public.stock (warehouse_id, sku, qty)
    values (p_to, p_sku, v_qty_left)
    on conflict (warehouse_id, sku) do update set qty = public.stock.qty + v_qty_left
    returning qty into v_qty_left;
  else
    v_qty_left := 0;
  end if;

  if p_to is not null then
    update public.stock set qty = v_qty_left
    where warehouse_id = p_to and sku = p_sku;
  end if;

  return v_qty_left;
end;
$$;

create or replace function public.revoke_transfer_stock()
returns trigger
language plpgsql
as $$
begin
  if public.staff_warehouse_id(old.from_warehouse) is null then
    raise exception 'only staff can move stock';
  end if;
  return old;
end;
$$;

create trigger revoke_transfer_stock
before insert or update on public.transfers
for each row execute function public.revoke_transfer_stock();

revoke all on public.stock from anon, authenticated;
grant select on public.stock to authenticated;
revoke all on public.transfers from anon, authenticated;
grant select on public.transfers to authenticated;
