create or replace function public.transfer_stock(
  p_from bigint,
  p_to bigint,
  p_sku text,
  p_qty integer
) returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_remaining integer;
  v_warehouse integer;
  v_user uuid;
begin
  if p_qty is null or p_qty <= 0 then
    raise exception 'Quantity must be positive';
  end if;

  if p_from is null or p_to is null or p_sku is null then
    raise exception 'Invalid parameters';
  end if;

  if p_from = p_to then
    raise exception 'Cannot transfer to the same warehouse';
  end if;

  if p_from is null or p_to is null then
    raise exception 'Warehouse must exist';
  end if;

  select 1 from public.warehouses where id = p_from into v_warehouse;
  if not found then
    raise exception 'Source warehouse does not exist';
  end if;

  select 1 from public.warehouses where id = p_to into v_warehouse;
  if not found then
    raise exception 'Destination warehouse does not exist';
  end if;

  select auth.uid() into v_user;
  if not exists (
    select 1
    from public.warehouse_staff ws
    where ws.warehouse_id = p_from
      and ws.user_id = v_user
  ) then
    raise exception 'Caller is not staff of the source warehouse';
  end if;

  if exists (
    select 1
    from public.stock s
    where s.warehouse_id = p_from
      and s.sku = p_sku
      and s.qty < p_qty
  ) then
    raise exception 'Not enough stock at the source warehouse';
  end if;

  -- Consume from source
  update public.stock
  set qty = qty - p_qty
  where warehouse_id = p_from
    and sku = p_sku;

  if not found then
    raise exception 'No stock record at the source warehouse';
  end if;

  update public.stock
  set qty = coalesce(qty, 0) + p_qty
  where warehouse_id = p_from
    and sku = p_sku;

  if not found then
    insert into public.stock (warehouse_id, sku, qty)
    values (p_from, p_sku, -p_qty);
  end if;

  if exists (
    select 1
    from public.stock s
    where s.warehouse_id = p_to
      and s.sku = p_sku
  ) then
    update public.stock
    set qty = coalesce(qty, 0) + p_qty
    where warehouse_id = p_to
      and sku = p_sku;
  else
    insert into public.stock (warehouse_id, sku, qty)
    values (p_to, p_sku, p_qty);
  end if;

  insert into public.transfers (from_warehouse, to_warehouse, sku, qty, moved_by)
  values (p_from, p_to, p_sku, p_qty, v_user);

  return -p_qty;
end;
$$;
