  ) then
    raise exception 'caller is not staff of the source warehouse';
  end if;

  if p_to not in (
    select warehouse_id
    from public.warehouses
  ) then
    raise exception 'destination warehouse does not exist';
  end if;

  if p_sku not in (
    select sku
    from public.stock
    where warehouse_id = p_from and qty >= p_qty
  ) then
    raise exception 'source does not have enough stock of sku %', p_sku;
  end if;

  if p_sku not in (
    select sku
    from public.stock
    where warehouse_id = p_to
  ) then
    insert into public.stock (warehouse_id, sku, qty)
    values (p_to, p_sku, 0)
    on conflict (warehouse_id, sku) do update set qty = 0
    returning qty;
  end if;

  update public.stock
  set qty = qty - p_qty
  where warehouse_id = p_from and sku = p_sku and qty >= p_qty
  returning qty into r_qty;

  if r_qty is null then
    raise exception 'concurrent modification or stock inconsistent';
  end if;

  insert into public.transfers (from_warehouse, to_warehouse, sku, qty, moved_by)
  values (p_from, p_to, p_sku, p_qty, auth.uid());

  return r_qty;
end;
$$;

