  on public.transfers
  for each row
  execute function public.check_transfers_rls();

create or replace function public.check_transfers_rls()
returns trigger
language plpgsql
as $$
begin
  if session_user = 'service_role' or auth.role() = 'service_role' then
    new.moved_by := coalesce(new.moved_by, auth.uid());
    new.moved_at := coalesce(new.moved_at, now());
    return new;
  end if;

  if exists (
    select 1
    from public.warehouse_staff ws
    where ws.warehouse_id = old.from_warehouse
      and ws.user_id = auth.uid()
  ) then
    new.moved_by := auth.uid();
    new.moved_at := now();
    return new;
  end if;

  raise exception 'transfers not allowed';
end;
$$;

