create or replace function public.transfer_stock(p_from bigint, p_to bigint, p_sku text, p_qty integer)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_qty integer := 0;
begin
  if p_qty is null or p_qty < 1 then
    raise exception 'transfer quantity must be positive';
  end if;

  -- R4: source and destination must be different and exist
  if p_from is null or p_to is null then
    raise exception 'transfer must have a source and destination';
  end if;

  if p_from = p_to then
    raise exception 'source and destination must not be the same warehouse';
  end if;

  -- R3: source must exist and the caller must be its staff
  if not exists(select 1 from public.warehouses where id = p_from) then
    raise exception 'source warehouse does not exist';
  end if;

  if not public.is_warehouse_staff(p_from) then
    raise exception 'only staff of the source warehouse can move its stock';
  end if;

  -- destination exists (or is created later) and is not the source above
  if not exists(select 1 from public.warehouses where id = p_to) then
    raise exception 'destination warehouse does not exist';
  end if;

  -- lock row so concurrent transfers never overspend
  perform 1
  from public.stock
  where warehouse_id = p_from
    and sku = p_sku
  for update;

  update public.stock
     set qty = qty - p_qty
  from public.warehouses w
  where s.warehouse_id = w.id
    and s.warehouse_id = p_from
    and s.sku = p_sku
  returning s.qty into v_qty;

  if v_qty is null then
    raise exception 'source warehouse % has no stock of sku %', p_from, p_sku;
  end if;

  if v_qty < 0 then
    raise exception 'source warehouse % does not have enough stock of sku %', p_from, p_sku;
  end if;

  -- create or update the destination stock row
  update public.stock
     set qty = coalesce(s.qty, 0) + p_qty
  from public.warehouses w
  where s.warehouse_id = w.id
    and s.warehouse_id = p_to
    and s.sku = p_sku;

  insert into public.transfers (from_warehouse, to_warehouse, sku, qty, moved_by)
  values (p_from, p_to, p_sku, p_qty, auth.uid());

  return v_qty;
end;
$$;

