create function public.can_edit_entry(p_entry_id bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1 from public.time_entries e
    where e.id = p_entry_id
      and e.user_id = auth.uid()
      and public.is_assigned(e.project_id)
  )
$$;

create function public.must_not_be_locked_guard()
returns trigger
language plpgsql
as $$
begin
  if not public.is_authenticated() then
    raise exception 'RLS: not authenticated';
  end if;
  if new.id is distinct from old.id then
    if
      (select p.is_locked from public.periods p where p.id = new.period_id for update) is not distinct from (select p.is_locked from public.periods p where p.id = old.period_id for update)
    then
      if (select p.is_locked from public.periods p where p.id = new.period_id) then
        raise exception 'RLS: cannot change entry into or out of a locked period';
      end if;
    end if;
  end if;
  if new.period_id is distinct from old.period_id then
    if (select p.is_locked from public.periods p where p.id = new.period_id) then
      raise exception 'RLS: cannot change entry into a locked period';
    end if;
  end if;
  if new.project_id is distinct from old.project_id then
    if public.is_assigned(new.project_id) is false then
      raise exception 'RLS: target project is not assigned to the caller';
    end if;
  end if;
  if new.worked_on is distinct from old.worked_on then
    if (select p.is_locked from public.periods p where p.id = new.period_id) then
      raise exception 'RLS: cannot change entry on a locked day';
    end if;
  end if;
  return new;
end
$$;

