create or replace function public.enforce_loan_change()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.id is distinct from old.id
     or new.book_id is distinct from old.book_id
     or new.borrower_id is distinct from old.borrower_id
     or new.borrowed_on is distinct from old.borrowed_on then
    raise exception 'only returned_on can be changed on a loan';
  end if;

  if old.returned_on is not null then
    raise exception 'a returned loan cannot be changed';
  end if;

  if new.returned_on is null then
    return new;
  end if;

  if new.returned_on = old.returned_on then
    return new;
  end if;

  if (select auth.uid()) is distinct from old.borrower_id then
    raise exception 'only the borrower can update their own loans';
  end if;

  if new.returned_on is null then
    raise exception 'only posting a return is allowed';
  end if;

  if new.returned_on < old.borrowed_on then
    raise exception 'return_on cannot be before borrowed_on';
  end if;

  return new;
end;
$$;

