create or replace function public.handle_loans()
returns trigger
language plpgsql
as $$
begin
  if new.borrower_id is distinct from original.borrower_id then
    if public.is_librarian() then
      return new;
    end if;
    raise exception 'Borrower id cannot be changed';
  end if;

  if original.returned_on is not null then
    raise exception 'Loan is already returned and cannot be modified';
  end if;

  if new.returned_on is not null and new.returned_on is distinct from original.returned_on then
    if public.is_librarian() or new.returned_on is not distinct from original.returned_on then
      return new;
    end if;
    raise exception 'Only own active loans can be returned';
  end if;

  if new.returned_on is not distinct from original.returned_on then
    return new;
  end if;

  return new;
end;
$$;

