create or replace function public.loans_enforce_insert()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' or public.is_librarian() then
    return new;
  end if;

  if new.borrower_id is distinct from auth.uid() then
    raise exception 'loans.borrower_id must be the current user';
  end if;

  if new.returned_on is not null then
    raise exception 'new loans must be active';
  end if;

  if not public.books_have_copies_left(new.book_id) then
    raise exception 'no copies left for book %', new.book_id;
  end if;

  if public.own_active_loan_count() >= 3 then
    raise exception 'member has no open borrowing limits';
  end if;

  return new;
end;
$$;

create or replace function public.loans_enforce_update()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' or public.is_librarian() then
    return new;
  end if;

  if new.id is distinct from old.id then
    raise exception 'loan id cannot be changed';
  end if;

  if new.book_id is distinct from old.book_id then
    raise exception 'loan book_id cannot be changed';
  end if;

  if new.borrower_id is distinct from old.borrower_id then
    raise exception 'loan borrower_id cannot be changed';
  end if;

  if old.returned_on is null and new.returned_on is null then
    raise exception 'inactive loans cannot be updated';
  end if;

  return new;
end;
$$;

