create function public.approve_access(p_request_id bigint) returns text
language plpgsql
as $$
declare
  v_request public.access_requests%rowtype;
  v_status text;
  v_approver uuid := auth.uid();
begin
  if v_approver is null or exists (select 1 from public.ops_team where user_id = v_approver) is false then
    raise exception 'caller is not on the ops team';
  end if;

  select * into v_request from public.access_requests where id = p_request_id for update;

  if v_request is null then
    raise exception 'request % does not exist', p_request_id;
  end if;

  if v_request.status <> 'pending' then
    raise exception 'request % is not pending', v_request.id;
  end if;

  if v_request.requester_id = v_approver then
    raise exception 'caller made the request';
  end if;

  if exists (select 1 from public.access_approvals where request_id = p_request_id and approver_id = v_approver) then
    raise exception 'caller has already approved this request';
  end if;

  insert into public.access_approvals (request_id, approver_id) values (p_request_id, v_approver);

  select count(*)::int into v_status from public.access_approvals where request_id = p_request_id group by request_id having count(*) >= 2;

  if v_status is not null and v_status >= 2 then
    update public.access_requests set status = 'granted' where id = p_request_id;
  end if;

  return coalesce(v_status, 'pending');
end;
$$;
