returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.ops_team o
    join public.access_requests r on r.id = p_request_id
    where r.status = 'pending'
      and o.user_id = auth.uid()
      and o.user_id = r.requester_id
  );
$$;

create or replace function public.is_pending(p_request_id bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.access_requests r
    where r.id = p_request_id
      and r.status = 'pending'
  );
$$;

create or replace function public.approve_access(p_request_id bigint)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_status text;
  v_approvals integer;
begin
  if auth.role() <> 'service_role' then
    raise exception 'approve_access is only callable by service role';
  end if;
  if p_request_id is null then
    raise exception 'approve_access: request id cannot be null';
  end if;

  update public.access_requests r
  set status = 'granted'
  where r.id = p_request_id
    and r.status = 'pending'
    and exists (
      select 1
      from public.access_approvals a
      where a.request_id = p_request_id
    )
  returning r.status into v_status;

  if not found then
    raise exception 'approve_access: cannot approve non-existent or non-pending request';
  end if;
  if v_status = 'granted' then
    return v_status;
  end if;

  update public.access_approvals a
  set approved_at = now()
  where a.request_id = p_request_id
    and a.approver_id is distinct from public.ops_team.user_id
    and exists (
      select o.user_id
      from public.ops_team o
      where o.user_id = a.approver_id
    )
  returning count(*) into v_approvals;

  if v_approvals < 2 then
    raise exception 'approve_access: you must be an ops team member and a new approver';
  end if;

  update public.access_requests r
  set status = 'granted'
  where r.id = p_request_id
    and exists (
      select 1
      from public.access_approvals a
      where a.request_id = p_request_id
      group by a.request_id
      having count(distinct a.approver_id) >= 2
    );

  return (select status from public.access_requests where id = p_request_id);
end;
$$;

