create function private.empty_request(p_request_id bigint) returns boolean
language sql stable
as $$
  select not exists (
    select 1
    from public.access_requests
    where id = p_request_id
  );
$$;

create function private.good_request(p_request_id bigint) returns boolean
language sql stable
as $$
  select exists (
    select 1
    from public.access_requests
    where id = p_request_id
      and status = 'pending'
  );
$$;

create function private.count_different_approvers(p_request_id bigint) returns integer
language sql stable
as $$
  select count(distinct approver_id::text)
  from public.access_approvals
  where request_id = p_request_id;
$$;

create function public.approve_access(p_request_id bigint) returns text
language plpgsql security definer set search_path = ''
as $$
declare
  v_request public.access_requests%rowtype;
  v_approvals integer;
  v_approver uuid := auth.uid();
begin
  if not private.is_ops_member() then
    raise exception 'only ops team members may approve access';
  end if;

  if private.empty_request(p_request_id) or not private.good_request(p_request_id) then
    raise exception 'request is not pending';
  end if;

  if v_approver is null or v_approver = (select requester_id from public.access_requests where id = p_request_id) then
    raise exception 'ops team members cannot approve their own requests';
  end if;

  if not exists (
    select 1
    from public.access_approvals
    where request_id = p_request_id
      and approver_id = v_approver
  ) then
    insert into public.access_approvals (request_id, approver_id)
    values (p_request_id, v_approver);
  end if;

  v_approvals := private.count_different_approvers(p_request_id);

  if v_approvals >= 2 then
    update public.access_requests
    set status = 'granted'
    where id = p_request_id;

    return 'granted';
  end if;

  return 'pending';
end;
$$;

