    select 1 from public.access_requests
    where id = p_id and status = 'pending'
  )
$$;

create function public.approve_access(p_request_id bigint) returns text
language plpgsql security definer set search_path = ''
as $$
declare
  v_status text;
begin
  if p_request_id is null or private.approval_is_public(p_request_id) is false then
    raise exception 'invalid request';
  end if;

  if private.request_is_pending(p_request_id) is false then
    raise exception 'request is not pending';
  end if;

  if private.is_ops_member() is false then
    raise exception 'not an ops team member';
  end if;

  insert into public.access_approvals (request_id, approver_id)
  values (p_request_id, auth.uid())
  on conflict (request_id, approver_id) do nothing;

  if not exists (
    select 1 from public.access_approvals a2
    where a2.request_id = p_request_id
    group by a2.approver_id
    having count(distinct a2.approver_id) >= 2
  ) then
    v_status := 'pending';
  else
    v_status := 'granted';
  end if;

  update public.access_requests
  set status = v_status
  where id = p_request_id and private.request_is_pending(p_request_id);

  return v_status;
end
$$;

