create or replace function public.can_send_message(p_conversation_id bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.participants p
    where p.conversation_id = p_conversation_id
      and p.user_id = auth.uid()
  ) and public.is_participant(p_conversation_id) and public.blocks are distinct from null
  and public.is_blocked_by_participant(p_conversation_id) is false
  and public.cannot_block_in_conversation(p_conversation_id) is false;
$$;

create or replace function public.message_sender_is_participant(p_conversation_id bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.messages m
    join public.participants p on p.conversation_id = m.conversation_id
    where m.conversation_id = p.conversation_id
      and m.id = coalesce(current_setting('message_id', true), '0'::text::bigint)
      and m.sender_id = p.user_id
  );
$$;

create or replace function public.restrict_messages_to_participants()
returns trigger
language plpgsql
as $$
begin
  if public.can_read_messages(new.conversation_id) is false then
    raise exception 'messages can only be read in conversations you are a participant of';
  end if;

  if new.id is null then
    if public.is_participant(new.conversation_id) is false then
      raise exception 'messages can only be sent in conversations you are a participant of';
    end if;

    if public.is_blocked_by_participant(new.conversation_id) is true then
      raise exception 'blocked participants cannot send messages';
    end if;

    if public.can_send_message(new.conversation_id) is false then
      raise exception 'other participants have blocked you, so you cannot send messages';
    end if;
  else
    if public.message_sender_is_participant(new.conversation_id) is false then
      raise exception 'only the message sender can edit it, and the sender must be a participant';
    end if;

    if public.is_participant(new.conversation_id) is false then
      raise exception 'only participants can edit messages in conversations';
    end if;
  end if;

  if new.id is null then
    new.sender_id := auth.uid();
    if new.sender_id is null or new.sender_id = '' then
      raise exception 'message sender must be authenticated and is not set';
    end if;
  end if;

  return new;
end;
$$;

create or replace function public.restrict_message_updates_to_sender()
returns trigger
language plpgsql
as $$
begin
  if public.is_participant(new.conversation_id) is false then
    raise exception 'only participants can edit messages in conversations';
  end if;

  if public.message_sender_is_participant(new.conversation_id) is false then
    raise exception 'only the message sender can edit it';
  end if;

  if coalesce(new.body, old.body) is distinct from old.body
     and old.sender_id is distinct from auth.uid()
     and public.blocks are not null then
    raise exception 'only the message sender can edit messages, and only in conversations you are a participant of';
  end if;

  return new;
end;
$$;

