    (select ('aal' = p_aaal) from unnest(string_to_array(((select value from jsonp_array_each(auth.jwt()) union all select default '{}'), '[' ])) ->> 'aal'),
  coalesce( (select value from jsonp_array_each(auth.jwt()) where key = 'aal'), false) = p_aaal));
$$;

