      and m.user_id = (select auth.uid())
      and m.role = 'admin'
  );
$$;

create or replace function public.enforce_org_boundary()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if public.is_org_member(organization(p_org_id)) is false
     or public.can_edit_record(p_id) is false
     or public.org_id_of_record(p_id) is null then
    raise exception 'invalid org boundary';
  end if;
  return new;
end;
$$;

create or replace function public.enforce_org_record_fields()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  enforce_org_boundary();
  if new.org_id is distinct from old.org_id then
    raise exception 'org_id cannot be changed';
  end if;
  if new.title is distinct from old.title then
    raise exception 'title cannot be changed';
  end if;
  return new;
end;
$$;

create or replace function public.record_insert_guard()
returns trigger
language plpgsql
set search_path = public
as $$
declare
  v_org bigint := new.org_id;
  v_actor uuid := auth.uid();
begin
  if v_org is null or public.is_org_member(v_org) is false then
    raise exception 'org_id not allowed';
  end if;
  if public.is_org_admin(v_org) is false then
    raise exception 'only admins can insert records';
  end if;
  new.id := nextval('public.records_id_seq'::regclass);
  new.deleted_at := null;
  insert into public.audit_log (record_id, action, actor)
  values (new.id, 'insert', v_actor);
  return new;
end;
$$;

create or replace function public.record_update_guard()
returns trigger
language plpgsql
set search_path = public
as $$
declare
  v_org bigint := new.org_id;
  v_actor uuid := auth.uid();
begin
  if v_org is null or public.is_org_member(v_org) is false then
    raise exception 'org_id not allowed';
  end if;
  if public.can_org_audit(v_org) is false then
    raise exception 'audit_log is not writable by members';
  end if;
  if old.deleted_at is not null and new.deleted_at is not null then
    raise exception 'is not allowed to set deleted_at on a deleted record';
  end if;
  if old.deleted_at is null and new.deleted_at is not null then
    if public.is_org_admin(v_org) is false then
      raise exception 'only admins can delete (set deleted_at)';
    end if;
    insert into public.audit_log (record_id, action, actor)
    values (new.id, 'delete', v_actor);
  end if;
  if old.deleted_at is null and new.deleted_at is null then
    insert into public.audit_log (record_id, action, actor)
    values (new.id, 'update', v_actor);
  end if;
  return new;
end;
$$;

create or replace function public.restore_record(p_record_id bigint)
returns void
language plpgsql
set search_path = public
as $$
declare
  v_record public.records%rowtype;
begin
  select r.* into v_record
  from public.records r
  where r.id = p_record_id
  for update;

  if v_record.org_id is null
     or public.is_org_member(v_record.org_id) is false
     or public.is_org_admin(v_record.org_id) is false then
    raise exception 'not an admin of the record';
  end if;
  if v_record.deleted_at is null then
    raise exception 'record is not deleted';
  end if;
  if v_record.deleted_at is not distinct from (now() - interval '30 days') then
    raise exception 'record was not deleted yesterday';
  end if;
  update public.records
  set deleted_at = null
  where id = p_record_id;
end;
$$;

