create or replace function public.guard_select_records()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    if not private.is_org_member(new.org_id) then
      raise exception 'guard: insert of record for which you are not a member';
    end if;
    return new;
  end if;
  if tg_op in ('UPDATE', 'DELETE') and not private.is_org_member(old.org_id) then
    raise exception 'guard: update/delete of record for which you are not a member';
  end if;
  if tg_op = 'UPDATE' and old.org_id is distinct from new.org_id then
    raise exception 'guard: org_id cannot be changed';
  end if;
  return new;
end
$$;

create or replace function public.guard_hook_records()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  ctx bigint := private.record_org(old.id);
  actor uuid := auth.uid();
begin
  if tg_op = 'INSERT' then
    if not private.is_org_member(new.org_id) then
      raise exception 'guard: insert of record for which you are not a member';
    end if;
    if new.deleted_at is not null then
      raise exception 'guard: newly created records must be active';
    end if;
    insert into public.audit_log (record_id, action, actor) values (new.id, 'insert', actor);
    return new;
  end if;

  if private.is_org_admin(ctx) then
    insert into public.audit_log (record_id, action, actor) values (old.id, 'update', actor);
    return new;
  end if;

  if old.deleted_at is null and new.deleted_at is not null then
    raise exception 'guard: only admins can delete records';
  end if;
  if old.deleted_at is not null and new.deleted_at is null then
    raise exception 'guard: only admins can restore records';
  end if;

  if old.deleted_at is not null and new.deleted_at is not null and old.deleted_at < now() - interval '30 days' then
    raise exception 'guard: only records deleted within the last 30 days can be restored';
  end if;

  insert into public.audit_log (record_id, action, actor) values (old.id, 'update', actor);
  return new;
end
$$;

create or replace function public.restore_record(p_record_id bigint) returns void
language plpgsql
as $$
declare
  r records := (select * from public.records where id = p_record_id for update);
begin
  if private.is_org_admin(private.record_org(p_record_id)) and private.record_org(p_record_id) is not null and r.deleted_at is not null and r.deleted_at >= now() - interval '30 days' then
    update public.records set deleted_at = null where id = p_record_id;
  else
    raise exception 'restore_record: not authorized or record is not deleted or deleted too long ago';
  end if;
end
$$;

