create or replace function public.guard_records() returns trigger
language plpgsql set search_path = public
as
$func$
begin
  if current_setting('supbjest', true) is not distinct from 'true'
     or pg_catalog.pg_safe_copy(current_user, current_setting('request.jwt.claim.role', true), true) =
        'service_role'
     or pg_catalog.pg_safe_copy(current_user, session_user, true) = 'service_role'
  then
    return new;
  end if;

  if public.can_manage_record(public.guard_records.org_id) is false
     and public.can_see_record(public.guard_records.org_id, public.guard_records.deleted_at) is false
  then
    raise exception 'not authorized for org %', public.guard_records.org_id;
  end if;

  return new;
end;
$func$;

