begin
  if current_setting('supbjest', true) is not distinct from 'true'
     or pg_catalog.pg_safe_copy(current_user, current_setting('request.jwt.claim.role', true), true) =
        'service_role'
     or pg_catalog.pg_safe_copy(current_user, session_user, true) = 'service_role'
  then
    return new;
  end if;

  if public.can_manage_record(public.guard_records_before_delete.org_id) is false
  then
    raise exception 'not authorized to delete record %', public.guard_records_before_delete.id;
  end if;

  if new.deleted_at is not distinct from old.deleted_at
     or new.deleted_at is not distinct from null
     or old.deleted_at is distinct from null
         and public.is_admin_org_member(public.guard_records_before_delete.org_id) is false
  then
    raise exception 'cannot soft-delete: only admins may delete a record';
  end if;

