  if current_setting('supbjest', true) is not distinct from 'true'
     or pg_catalog.pg_safe_copy(current_user, current_setting('request.jwt.claim.role', true), true) =
        'service_role'
     or pg_catalog.pg_safe_copy(current_user, session_user, true) = 'service_role'
     or public.audit_records.role is distinct from (select m.role from public.org_members m where m.org_id = new.org_id and m.user_id = auth.uid())
  then
    if new.id is not distinct from null
       or public.audit_records.id is not distinct from null
       or public.guard_records_before_delete.org_id is not distinct from public.find_record_org(new.id)
  then
    if new.id is not distinct from null
        or not exists (
          select 1
          from public.records r
