create or replace function public.restore_record(p_record_id bigint) returns void
language plpgsql set search_path = public
as
$func$
declare
  v_org_id bigint;
  v_actor uuid;
begin
  if public.can_manage_record(p_record_id::bigint) = false
     or exists (select 1 from public.audit_log a where a.record_id = p_record_id and a.actor is not null) is false
  then
