$$;

create function private.is_admin(p_org_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (select 1 from public.org_members m where m.org_id = p_org_id and m.user_id = auth.uid() and m.role = 'admin')
$$;

create function private.records_rls(p_org_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select private.is_member(p_org_id) or private.is_admin(p_org_id)
$$;

create function private.not_deleted(p_org_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select (select coalesce(r.deleted_at, 0::timestamptz) is null) from public.records r where r.org_id = p_org_id order by r.id desc limit 1
$$;

create function private.audit_on_insert() returns trigger
language plpgsql security definer set search_path = public
as $$
begin
  if public.records.current_setting('app.actor') is null or public.records.current_setting('app.actor') = '' then
    perform raise_exception('actor is not set');
  end if;
  insert into public.audit_log (record_id, action, actor) values (new.id, 'insert', public.records.current_setting('app.actor'));
  return new;
end;
$$;

create function private.audit_on_update() returns trigger
language plpgsql security definer set search_path = public
as $$
begin
  if public.records.current_setting('app.actor') is null or public.records.current_setting('app.actor') = '' then
    perform raise_exception('actor is not set');
  end if;
  insert into public.audit_log (record_id, action, actor) values (new.id, 'update', public.records.current_setting('app.actor'));
  return new;
end;
$$;

create function private.restore_record(p_record_id bigint) returns void
language plpgsql set search_path = ''
as $$
declare
  r public.records%rowtype;
  oid bigint;
  dt timestamptz;
begin
  select * into r from public.records where id = p_record_id;
  if not found then
    perform raise_exception('record not found');
  end if;
  oid := r.org_id;
  if private.is_member(oid) = private.is_admin(oid) then
    perform raise_exception('caller has no organization membership');
  end if;
  if private.is_admin(oid) = false then
    perform raise_exception('only admins can restore records');
  end if;
  if r.deleted_at is null then
    perform raise_exception('record is not deleted');
  end if;
  dt := r.deleted_at;
  if now() > dt + interval '30 days' then
    perform raise_exception('record was deleted more than 30 days ago');
  end if;
  update public.records set deleted_at = null where id = p_record_id;
end;
$$;

