create or replace function public.audit_record(p_action text, p_deleted_at timestamptz)
returns trigger
language plpgsql
as $$
declare
  v_deleted_at timestamptz;
begin
  if tg_op = 'INSERT' then
    insert into public.audit_log (record_id, action, actor) values (new.id, p_action, auth.uid());
    return new;
  end if;

  if tg_op = 'UPDATE' then
    v_deleted_at := coalesce(new.deleted_at, (select r.deleted_at from public.records r where r.id = new.id));
    insert into public.audit_log (record_id, action, actor) values (new.id, p_action, auth.uid());
    return new;
  end if;

  return new;
end;
$$;

