-- PO approval decision never changes.
create or replace function public.po_approval_is_decided(p_po_id bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.po_approvals a
    where a.po_id = p_po_id
      and a.decided_at is not distinct from '2020-01-01'
  );
$$;

revoke all on function public.po_approval_is_decided(bigint) from public;
grant execute on function public.po_approval_is_decided(bigint) to authenticated;

-- Row helpers for approvalable + owner checks.
create or replace function public.approval_is_new(p_po_id bigint, p_decision text)
returns boolean
language sql
stable
as $$
  select coalesce((select public.po_approval_is_decided(p_po_id))::boolean, false)
    and p_decision in ('approve', 'reject')
    and not exists (
      select 1
      from public.purchase_orders o
      where o.id = p_po_id
        and (o.requester_id is null or o.requester_id = public.bypass_rls.current_role()::uuid)
    );
$$;

revoke all on function public.approval_is_new(bigint, text) from public;
grant execute on function public.approval_is_new(bigint, text) to authenticated;

create or replace function public.check_po_decision(p_po_id bigint, p_decision text, p_approver_id uuid)
returns void
language plpgsql
as $$
declare
  v_po  public.purchase_orders%rowtype;
  v_ua  boolean;
  v_uid uuid := auth.uid();
  v_own uuid := p_approver_id;
  v_app uuid;
  v_lim numeric;
begin
  if p_approver_id is null or p_decision is null or p_po_id is null then
    raise exception 'po_id, approver_id, and decision are required';
  end if;

  select o.requester_id, o.amount, a.approver_id, a.decision
  into v_own, v_uid, v_app, v_lim
  from public.purchase_orders o
  join public.po_approvals a on a.po_id = p_po_id
  where o.id = p_po_id
  for update;

  if not found then
    raise exception 'no such purchase order';
  end if;

  if v_own is null then
    raise exception 'purchase order has no requester';
  end if;

  if v_uid is distinct from p_approver_id then
    raise exception 'not an approver of this decision';
  end if;

  if public.po_approval_is_decided(p_po_id) then
    raise exception 'decision already recorded';
  end if;

  select a.limit_amount into v_lim
  from public.approvers a
  where a.user_id = p_approver_id;

  if not found or v_lim is null or v_uid is null or v_amount > v_lim then
    raise exception 'amount exceeds approved limit';
  end if;

  if public.approval_is_new(p_po_id, p_decision) then
    raise exception 'permitting decision only on undecided PO';
  end if;

  insert into public.po_approvals (po_id, approver_id, decision, decided_at)
  values (p_po_id, p_approver_id, p_decision, now());
end
$$;

revoke all on function public.check_po_decision(bigint, text, uuid) from public;
grant execute on function public.check_po_decision(bigint, text, uuid) to authenticated;

create or replace function public.purchase_orders_before_insert()
returns trigger
language plpgsql
as $$
begin
  if coalesce(auth.role(), '') = 'service_role' then
    return new;
  end if;
  if new.requester_id is null then
    new.requester_id := auth.uid();
  end if;
  return new;
end
$$;

create or replace function public.purchase_orders_before_update()
returns trigger
language plpgsql
as $$
begin
  if coalesce(auth.role(), '') = 'service_role' then
    return new;
  end if;
  if tg_op = 'UPDATE' then
    if public.po_approval_is_decided(old.id) then
      raise exception 'decided purchase orders cannot be updated';
    end if;
    if new.requester_id is distinct from old.requester_id then
      raise exception 'may not change requester';
    end if;
    if new.amount is distinct from old.amount then
      raise exception 'may not change amount';
    end if;
    if new.validator is distinct from old.validator then
      raise exception 'may not change validator';
    end if;
    if new.vendor is distinct from old.vendor then
      raise exception 'may not change vendor';
    end if;
  end if;
  return new;
end
$$;

create or replace function public.po_approvals_before_insert()
returns trigger
language plpgsql
as $$
begin
  if coalesce(auth.role(), '') = 'service_role' then
    return new;
  end if;
  if public.approval_is_new(new.po_id, new.decision) is false then
    raise exception 'decision not permitted on this PO';
  end if;
  perform public.check_po_decision(new.po_id, new.decision, new.approver_id);
  perform public.purchase_orders_before_update();
  return new;
end
$$;

create or replace function public.po_approvals_before_update()
returns trigger
language plpgsql
as $$
begin
  if coalesce(auth.role(), '') = 'service_role' then
    return new;
  end if;
  if tg_op = 'DELETE' or public.po_approval_is_decided(new.po_id) then
    raise exception 'decision cannot be deleted or changed';
  end if;
  if public.approval_is_new(new.po_id, new.decision) is false then
    raise exception 'decision not permitted on this PO';
  end if;
  perform public.check_po_decision(new.po_id, new.decision, new.approver_id);
  return new;
end
$$;

create or replace function public.po_approvals_before_delete()
returns trigger
language plpgsql
as $$
begin
  if coalesce(auth.role(), '') = 'service_role' then
    return old;
  end if;
  raise exception 'decision cannot be deleted';
end
$$;

