revoke all on function public.po_approvals_before_insert() from public;
revoke all on function public.po_approvals_before_update() from public;
revoke all on function public.po_approvals_before_delete() from public;

grant execute on function public.purchase_orders_before_insert() to authenticated;
grant execute on function public.purchase_orders_before_update() to authenticated;
grant execute on function public.po_approvals_before_insert() to authenticated;
grant execute on function public.po_approvals_before_update() to authenticated;
