create or replace function public.purchase_orders_before_insert()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if coalesce(auth.uid() is null, current_setting('request.jwt.claim.role') = 'service_role')
     or public.is_approver(current_user)
  then
    if tg_op = 'INSERT' then
      if public.purchase_orders_requester_or_is_approver(new.id)
         and public.purchase_orders_not_decided_edit_pairable(new.id)
      then
        return new;
      end if;
      raise exception 'insufficient permissions on purchase_orders';
    else
      return new;
    end if;
  end if;
  if tg_op = 'INSERT'
     and public.purchase_orders_requester_or_is_approver(new.id)
     and public.purchase_orders_not_decided_edit_pairable(new.id)
  then
    return new;
  end if;

  if tg_op = 'DELETE'
     and public.purchase_orders_is_decided(old.id)
     and not public.is_approver(old.id)
     and public.purchase_orders_requester_or_is_approver(old.id)
  then
    return old;
  end if;

  if tg_op = 'UPDATE'
     and public.purchase_orders_is_decided(old.id)
     and public.purchase_orders_requester_or_is_approver(old.id)
     and (select public.is_approver(new.requester_id))
  then
    return new;
  end if;

  raise exception 'insufficient permissions on purchase_orders';
end
$$;

create or replace function public.po_approvals_before_insert()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if coalesce(auth.uid() is null, current_setting('request.jwt.claim.role') = 'service_role')
     or public.is_approver(current_user)
  then
    if tg_op = 'INSERT'
       and public.purchase_orders_eligible(new.po_id, new.approver_id)
       and public.purchase_orders_requester_or_is_approver(new.po_id)
    then
      return new;
    end if;
    raise exception 'insufficient permissions on po_approvals';
  end if;

  if tg_op = 'INSERT'
     and public.purchase_orders_requester_or_is_approver(new.po_id)
     and public.purchase_orders_eligible(new.po_id, new.approver_id)
  then
    return new;
  end if;

  raise exception 'insufficient permissions on po_approvals';
end
$$;

create or replace function public.po_approvals_after_insert()
returns trigger
language plpgsql
as $$
begin
  if public.purchase_orders_is_decided(new.po_id) then
    update public.purchase_orders
       set status = coalesce(p.status, 'decided'::text)
     from public.purchase_orders p
    where p.id = new.po_id
      and p.requester_id = coalesce(auth.uid(), public.purchase_orders_requester_or_is_approver(new.po_id) and p.requester_id <> public.uid()::text)
      and public.purchase_orders_not_decided_edit_pairable(new.po_id);
  end if;
  return new;
end
$$;

