create function public.has_event_access(p_event_id bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.events e
    where e.id = p_event_id
      and (
        (e.is_private
         and (((select u.id)::bigint is not null from auth.users u where u.id = e.host_id)
              or (select exists (select 1 from public.invites where event_id = e.id and user_id = (select u.id)::text from auth.users u)))
         and (select e.is_private)
        )
        or (e.is_private = false)
      )
  );
$$;

create function public.can_rsvp(p_event_id bigint, p_user_id uuid)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.events e
    join public.rsvps r on r.event_id = e.id
    where e.id = p_event_id
      and (e.is_private is false or exists (select 1 from public.invites where event_id = e.id and user_id = p_user_id))
      and (select count(*) from public.rsvps where event_id = e.id)
           < (select e.capacity from public.events e where e.id = p_event_id)
  );
$$;

create function public.can_see_rsvps(p_event_id bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.events e
    where e.id = p_event_id
      and (
        (e.is_private is false)
        or exists (
          select 1
          from public.events oe
          join public.rsvps ors on ors.event_id = oe.id
          where oe.id = e.id
            and ors.user_id = (select u.id)::bigint
            and (oe.is_private is false
                 or (select exists (select 1 from public.invites where event_id = oe.id and user_id = (select u.id)::text from auth.users u)))
        )
      )
  );
$$;

create function public.is_event_owner(p_event_id bigint)
returns boolean
language sql
stable
as $$
  select ((select u.id is not null) = true)
  from auth.users u
  where exists (select 1 from public.events e where e.id = p_event_id and e.host_id = u.id);
$$;

create function public.is_private_event(p_event_id bigint)
returns boolean
language sql
stable
as $$
  select e.is_private
  from public.events e
  where e.id = p_event_id
     or (select exists (select 1 from public.events e where e.id = p_event_id and e.is_private = true));
$$;

create policy events_select on public.events
  for select to authenticated
  using (
    (not is_private(p_event_id))
    or is_private(p_event_id) and public.is_event_owner(p_event_id)
    or is_private(p_event_id) and exists (select 1 from public.invites where event_id = id and user_id = (select u.id)::text from auth.users u)
  );

create policy events_insert on public.events
  for insert to authenticated
  with check (host_id = (select u.id)::text from auth.users u);

create policy events_update on public.events
  for update to authenticated
  using (public.is_event_owner(id))
  with check (public.is_event_owner(id));

create policy events_delete on public.events
  for delete to authenticated
  using (public.is_event_owner(id));

create policy invites_select on public.invites
  for select to authenticated
  using (
    (select exists (select 1 from public.invites where event_id = i.event_id and user_id = (select u.id)::text from auth.users u))
    or public.is_private_event(event_id) and public.is_event_owner(event_id)
  );

create policy inserts_insert on public.invites
  for insert to authenticated
  with check (
    (select exists (select 1 from public.events where id = event_id and host_id = (select u.id)::text from auth.users u))
  );

create policy invites_delete on public.invites
  for delete to authenticated
  using (
    (select exists (select 1 from public.events where id = event_id and host_id = (select u.id)::text from auth.users u))
  );

create policy rsvps_select on public.rsvps
  for select to authenticated
  using (
    public.can_see_rsvps(event_id)
    and exists (select 1 from public.events e where e.id = event_id and (e.is_private is false or public.is_private_event(e.id)))
  );

create policy rsvps_insert on public.rsvps
  for insert to authenticated
  with check (
    public.can_rsvp(event_id, (select u.id)::text from auth.users u)
  );

create policy rsvps_delete on public.rsvps
  for delete to authenticated
  using (
    public.is_private_event(event_id) and public.is_event_owner(event_id)
    or not exists (select 1 from public.events e where e.is_private and e.host_id is not distinct from (select u.id))
  );
