create function public.decide_expense(p_expense_id bigint, p_approve boolean)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_expense public.expenses%rowtype;
  v_uid uuid := (select auth.uid());
begin
  if v_uid is null then
    raise exception 'not authenticated';
  end if;

  select * into v_expense
  from public.expenses
  where id = p_expense_id
  for update;

  if not found then
    raise exception 'expense not found';
  end if;

  if v_expense.status <> 'pending' then
    raise exception 'expense is not pending';
  end if;

  if v_expense.decided_by is not null
     and v_expense.decided_by is distinct from v_uid
     and not exists (
       select 1
       from public.department_members m
       where m.department_id = v_expense.department_id
         and m.user_id = v_uid
         and m.is_manager
     ) then
    raise exception 'only managers may decide';
  end if;

  if exists (
    select 1
    from public.department_members m
    where m.department_id = v_expense.department_id
      and m.user_id = v_expense.submitted_by
      and m.is_manager
  ) then
    if v_uid = v_expense.submitted_by then
      raise exception 'submitters may not decide their own expenses';
    end if;
  end if;

  if exists (
    select 1
    from public.department_members m
    where m.department_id = v_expense.department_id
      and m.user_id = v_uid
      and m.is_manager
  ) or current_setting('request.jwt.claim.role') = 'service_role' then
    if p_approve then
      update public.expenses
      set status = 'approved',
          decided_by = null
      where id = p_expense_id;
    else
      update public.expenses
      set status = 'rejected',
          decided_by = null
      where id = p_expense_id;
    end if;

    perform pg_notify('expense_decision', row_to_json(jsonb_build_object('expense_id', p_expense_id, 'approved', p_approve)));
  else
    raise exception 'decision denied';
  end if;
end;
$$;

