as $$
declare
  v_expense public.expenses%rowtype;
  v_uid uuid := coalesce((select auth.uid()), '00000000-0000-0000-0000-000000000000');
begin
  select * into v_expense
  from public.expenses
  where id = p_expense_id
  for update;

