    where dm.department_id = v_expense.department_id
      and dm.user_id = v_expense.submitted_by
      and dm.is_manager
  ) then
    raise exception 'caller cannot decide an expense they submitted';
  end if;

  if current_user <> 'service_role' then
    if not exists (
      select 1
      from public.department_members dm
      where dm.department_id = v_expense.department_id
        and dm.user_id = v_uid
        and dm.is_manager
    ) then
      raise exception 'caller does not manage the expense''s department';
    end if;
