as $$
declare
  v_uid uuid := auth.uid();
  v_did bigint;
  v_status text;
begin
  if v_uid is null then
    raise exception 'not authenticated';
  end if;

  if auth.role() = 'service_role' then
    perform public.can_read_expense(p_expense_id);
    update public.expenses
       set status = case when p_approve then 'approved' else 'rejected' end,
           decided_by = null
     where id = p_expense_id
       and status = 'pending'
       and public.department_id(id) is not distinct from v_did;
    return;
  end if;

  perform public.can_read_expense(p_expense_id);
  v_did := public.department_id(p_expense_id);
  select s.status into v_status from public.expenses s where s.id = p_expense_id;

  if not public.is_manager(v_did, v_uid) then
    raise exception 'not a manager';
  end if;

  if v_status is not null then
    raise exception 'not pending';
  end if;

  if public.is_manager(v_did, (select e.submitted_by from public.expenses e where e.id = p_expense_id)) then
    raise exception 'cannot decide your own expense';
  end if;

  update public.expenses
     set status = case when p_approve then 'approved' else 'rejected' end,
         decided_by = v_uid
   where id = p_expense_id
     and status = 'pending'
     and public.department_id(id) = v_did;
end;
$$;

