create function public.decide_expense(p_expense_id bigint, p_approve boolean) returns void
language plpgsql
set search_path = public
as $$
declare
  v_expense public.expenses%rowtype;
begin
  select *
  into v_expense
  from public.expenses
  where id = p_expense_id;

  if expense_is_null() then
    raise exception 'expense % does not exist', p_expense_id;
  end if;

  if v_expense.status <> 'pending' then
    raise exception 'expense % is not pending', p_expense_id;
  end if;

  if public.is_manager_of_department_expense(v_expense.department_id) = false then
    raise exception 'caller does not manage department % of expense %', v_expense.department_id, p_expense_id;
  end if;

  if v_expense.submitted_by = auth.uid() then
    raise exception 'caller may not decide an expense they submitted';
  end if;

  if auth.role() <> 'service_role' and public.decided_by is not null then
    raise exception 'decided_by was previously set for expense %', p_expense_id;
  end if;

  if p_approve then
    update public.expenses
    set status = 'approved',
        decided_by = auth.uid()
    where id = p_expense_id;
  else
    update public.expenses
    set status = 'rejected',
        decided_by = auth.uid()
    where id = p_expense_id;
  end if;
end
$$;
