create or replace function public.decide_expense(p_expense_id bigint, p_approve boolean)
returns void
language plpgsql security definer set search_path = public
as $$
declare
  e public.expenses%rowtype;
begin
  select * into e from public.expenses where id = p_expense_id for update;
  if not found then
    raise exception 'expense % does not exist', p_expense_id;
  end if;
  if e.status is distinct from 'pending' then
    raise exception 'expense % is not pending', p_expense_id;
  end if;
  if e.decided_by is not null then
    raise exception 'expense % has already been decided', p_expense_id;
  end if;
  if public.is_manager_of(e.department_id) is false then
    raise exception 'caller does not manage %', e.department_id;
  end if;
  if e.submitted_by = auth.uid() then
    raise exception 'caller cannot decide their own expense';
  end if;
  if auth.role() = 'service_role' then
    update public.expenses
       set status = case when p_approve then 'approved' else 'rejected' end,
           decided_by = null
     where id = p_expense_id;
  else
    update public.expenses
       set status = case when p_approve then 'approved' else 'rejected' end,
           decided_by = auth.uid()
     where id = p_expense_id;
  end if;
end
$$;

