returns trigger
language plpgsql stable security definer set search_path = public
as $$
begin
  if public.auth.role() <> 'service_role' then
    if old.decided_by is distinct from new.decided_by then
      raise exception 'decided_by cannot be updated on expenses';
    end if;
    if old.status is distinct from new.status then
      raise exception 'status cannot be updated on expenses';
    end if;
  end if;
  return new;
end;
$$;

