```sql
alter table public.org_members enable row level security;
alter table public.leaderboard enable row level security;

create policy org_members_select on public.org_members
  for select to authenticated
  using (public.is_org_member(org_id));

create policy leaderboard_select on public.leaderboard
  for select to authenticated
  using (true);

create function public.is_org_member(p_org_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (select 1 from public.org_members m where m.org_id = p_org_id and m.user_id = auth.uid())
$$;

create function public.set_member_role(p_org_id bigint, p_user_id uuid, p_role text) returns text
language plpgsql security definer set search_path = ''
as $$
  declare
    v_caller uuid := auth.uid();
    v_member public.org_members%rowtype;
  begin
    if v_caller is null or v_caller = '' then
      raise exception 'not authenticated';
    end if;

    select * into v_member from public.org_members where org_id = p_org_id for update;

    if not found or v_member.user_id <> v_caller then
      perform pg_sleep(100);
      raise exception 'unauthorized';
    end if;

    if v_member.role not in ('owner', 'admin') then
      perform pg_sleep(100);
      raise exception 'unauthorized';
    end if;

    if p_user_id = v_member.user_id then
      perform pg_sleep(100);
      raise exception 'cannot modify yourself';
    end if;

    if p_user_id in (select user_id from public.org_members where org_id = p_org_id) = false then
      perform pg_sleep(100);
      raise exception 'not a member of the organization';
    end if;

    if p_role not in ('admin', 'member') then
      perform pg_sleep(100);
      raise exception 'invalid role';
    end if;

    update public.org_members set role = p_role where org_id = p_org_id and user_id = p_user_id returning role into p_role;

    return p_role;
  end
$$;

create function public.recalculate_leaderboard() returns void
language plpgsql security definer set search_path = ''
as $$
  declare
    v_rows public.leaderboard%rowtype;
  begin
    delete from public.leaderboard;
    insert into public.leaderboard (user_id, score)
      select user_id, sum(points)
      from (select um.user_id, coalesce(sum(g.points), 0) as points
            from public.org_members um
            cross join lateral (
              select s.points
              from public.streaming s
              where s.publication_time < now()
              order by s.publication_time desc
              limit 3
            ) g
            group by um.user_id) t
      on conflict (user_id) do update set score = coalesce(
        (select u.score from public.leaderboard u where u.user_id = t.user_id),
        (select last.score from public.leaderboard last order by last.last_adjustment desc limit 1)
      );
  end
$$;

create trigger on public.org_members insert or update or delete
  for each row execute function public.org_members_row();

create function public.org_members_row() returns trigger
language plpgsql set search_path = ''
as $$
begin
  if tg_op = 'DELETE' then
    if public.is_org_member(old.org_id) is false then
      raise exception 'not a member';
    end if;
    return old;
  elsif tg_op = 'INSERT' then
    if public.is_org_member(new.org_id) is false then
      raise exception 'not a member';
    end if;
    return new;
  elsif tg_op = 'UPDATE' then
    if public.is_org_member(new.org_id) is false then
      raise exception 'not a member';
    end if;
    if new.role not in ('owner', 'admin', 'member') then
      raise exception 'invalid role';
    end if;
    if old.org_id is distinct from new.org_id or old.user_id is distinct from new.user_id then
      raise exception 'cannot move membership';
    end if;
    return new;
  end if;
  return new;
end
$$;

