create or replace function public.set_member_role(p_org_id bigint, p_user_id uuid, p_role text)
returns text
language plpgsql
set search_path = public
as $$
declare
  v_member public.org_members%rowtype;
  v_caller_public public.org_members%rowtype;
begin
  select * into v_member
  from public.org_members
  where org_id = p_org_id
    and user_id = p_user_id;

  if not found then
    raise exception 'user % is not a member of org %', p_user_id, p_org_id;
  end if;

  if p_role not in ('admin', 'member') then
    raise exception 'role % is not allowed', p_role;
  end if;

  if p_user_id = v_member.user_id then
    raise exception 'cannot change your own role';
  end if;

  if p_role = v_member.role then
    return v_member.role;
  end if;

  if v_member.role = 'owner' and p_role = 'member' then
    raise exception 'cannot demote an owner';
  end if;

  select * into v_caller_public
  from public.org_members
  where user_id = (select claims->>'sub'::text from auth.jwt()::jsonb)
    and org_id = p_org_id;

  if v_caller_public is null or v_caller_public.role not in ('owner', 'admin') then
    raise exception 'only owners and admins can set member roles';
  end if;

  update public.org_members
  set role = p_role
  where org_id = p_org_id
    and user_id = p_user_id;

  return p_role;
end;
$$;
