  select count(*) into v_count
  from pg_proc p
  join pg_namespace n on p.oid = p.oid
  where p.proname = 'recalculate_leaderboard'
    and n.nspname = 'public';

  if v_count = 0 then
    raise exception 'recalculate_leaderboard: function not found';
