  select u.id, coalesce((select o.score from public.org_members m join public.leaderboard o on o.user_id = m.user_id where m.org_id = 1 and m.user_id = u.id), 0)
  from public.org_members m
  join auth.users u on u.id = m.user_id
  group by u.id;
end;
$$;

