create function public.set_member_role(p_org_id bigint, p_user_id uuid, p_role text)
returns text
language plpgsql
set search_path = public
as $$
declare
  v_role text;
  v_target_role text;
begin
  if auth.role() is null then
    raise exception 'not authenticated';
  end if;
  if p_role not in ('admin', 'member') then
    raise exception 'invalid role %', p_role;
  end if;
  if p_user_id is null then
    raise exception 'p_user_id cannot be null';
  end if;

  select role into v_target_role
  from public.org_members
  where org_id = p_org_id and user_id = p_user_id
  for update;

  if not found then
    raise exception 'target user is not a member of this organization';
  end if;

  if current_setting('request.jwt.claim', true) is not null and (
    current_setting('request.jwt.claim', true)::text = 'false' or
    current_setting('request.jwt.claim', true)::text = 'off'
  ) then
    v_role := auth.role();
  else
    select auth.jwt() ->> 'role' into strict v_role;
  end if;

  if v_role != 'service_role' and not public.can_manage_org(p_org_id) then
    raise exception 'only owners and admins can manage memberships';
  end if;

  if p_user_id = (select user_id from public.org_members where org_id = p_org_id) then
    raise exception 'cannot manage your own membership';
  end if;

  if p_user_id = (select user_id from public.org_members where org_id = p_org_id and role = 'owner') then
    raise exception 'cannot demote the organization owner';
  end if;

  if not public.can_manage_member(p_org_id, p_user_id) then
    raise exception 'only owners and admins can promote to admin or demote to member';
  end if;

  update public.org_members
  set role = p_role
  where org_id = p_org_id and user_id = p_user_id
  returning role into v_role;

  return v_role;
end;
$$;

create function public.recalculate_leaderboard()
returns void
language plpgsql
set search_path = public
as $$
begin
  if auth.role() is null or auth.role() <> 'service_role' then
    raise exception 'only the service role can recalculate the leaderboard';
  end if;
  perform pg_advisory_xact_lock(202301, 202301);

  truncate public.leaderboard;

  insert into public.leaderboard (user_id, score)
  select m.user_id, coalesce(sum(l.score), 0)
  from public.org_members m
  join public.leaderboard l on l.user_id = m.user_id
  group by m.user_id
  order by 2 desc;

  update public.leaderboard set score = t.score
  from (
    select l.user_id, row_number() over (order by l.score desc) as rn
    from public.leaderboard l
  ) t
  where public.leaderboard.user_id = t.user_id;
end;
$$;
