  end if;
  if new.passenger_id <> auth.uid() then
    raise exception 'ride_bookings.update: only passenger self-bookings before departure';
  end if;
  if old.status is distinct from new.status then
    select count(*) into v_confirmed
    from public.ride_bookings b
    where b.ride_id = new.ride_id and b.status = 'confirmed';
    if new.status = 'confirmed' and v_confirmed >= v_ride.seats then
      raise exception 'ride_bookings.update: ride is full';
    end if;
  end if;
  return new;
end;
$$;

create trigger ride_bookings_enforce_update
before update on public.ride_bookings
for each row execute function public.ride_booking_enforce_update();
