create function public.has_seated_before_departure(p_ride_id bigint) returns boolean
language sql stable
as $$
  select exists (
    select 1
    from public.rides r
    join public.ride_bookings b on b.ride_id = r.id
    where r.id = p_ride_id
      and b.status = 'confirmed'
      and b.passenger_id <> r.driver_id
      and r.departs_at > now()
