create function public.enforce_booking_insert() returns trigger
language plpgsql security definer set search_path = public
as $$
declare
  v_driver_id uuid;
  v_seats integer;
  v_confirmed integer;
begin
  if (select coalesce(auth.role(), '')::text) = 'anon' then
    raise exception 'anonymous visitors cannot create bookings';
  end if;

  v_driver_id := (select r.driver_id from public.rides r where r.id = new.ride_id);
  if v_driver_id is null or new.passenger_id is distinct from auth.uid() or new.passenger_id = v_driver_id then
    raise exception 'passenger must be signed in and not the driver';
  end if;

  if (select r.departs_at from public.rides r where r.id = new.ride_id) is null
     or (select r.departs_at from public.rides r where r.id = new.ride_id) <= now() then
    raise exception 'bookings can only be made before departure';
  end if;

  v_seats := (select r.seats from public.rides r where r.id = new.ride_id);
  if v_seats is null then
    raise exception 'unknown ride';
  end if;

  v_confirmed := (
    select count(*)::integer
    from public.ride_bookings b
    where b.ride_id = new.ride_id
      and b.status = 'confirmed'
  );

  if v_confirmed >= v_seats then
    raise exception 'ride at capacity';
  end if;

  new.status := 'requested';
  return new;
end;
$$;

create function public.enforce_booking_update() returns trigger
language plpgsql security definer set search_path = public
as $$
declare
  v_driver_id uuid;
  v_departs_at timestamptz;
  v_seats integer;
  v_confirmed integer;
  old_status text := old.status;
begin
  if (select coalesce(auth.role(), '')::text) in ('anon', 'service_role') then
    return new;
  end if;

  v_driver_id := (select r.driver_id from public.rides r where r.id = old.ride_id);
  v_departs_at := (select r.departs_at from public.rides r where r.id = old.ride_id);
  v_seats := (select r.seats from public.rides r where r.id = old.ride_id);

  if v_driver_id is null or v_departs_at is null or v_seats is null then
    raise exception 'unknown ride';
  end if;

  if old_status = 'confirmed' and new.status <> 'confirmed' then
    if v_departs_at <= now() then
      raise exception 'cannot change confirmation status after departure';
    end if;
  elsif old_status <> 'confirmed' and new.status = 'confirmed' then
    if v_departs_at <= now() then
      raise exception 'cannot book after departure';
    end if;
  elsif old_status = 'requested' and new.status = 'requested' then
    if v_departs_at <= now() then
      raise exception 'cannot re-request after booking creation';
    end if;
  elsif old_status = 'declined' or new.status = 'declined' then
    raise exception 'booking status cannot be changed to or from declined';
  else
    raise exception 'invalid booking status transition';
  end if;

  if old_status = 'confirmed' then
    v_confirmed := v_confirmed - 1;
  elsif new.status = 'confirmed' then
    v_confirmed := v_confirmed + 1;
  else
    v_confirmed := v_confirmed;
  end if;

  if new.status = 'declined' then
    new.status := old_status;
    return new;
  end if;

  if v_confirmed > v_seats then
    raise exception 'too many confirmed bookings';
  end if;

  if new.passenger_id is distinct from old.passenger_id then
    raise exception 'passenger cannot be changed';
  end if;

  if old.passenger_id is not distinct from v_driver_id then
    raise exception 'driver cannot change other states';
  end if;

  return new;
end;
$$;

