returns trigger
language plpgsql
as $$
  declare
    v_participant boolean;
    v_confirmed boolean;
  begin
    select public.is_booking_participant(new.id) into v_participant;

    if v_participant then
      select public.is_booking_confirmed(new.id) into v_confirmed;
      if v_confirmed then
        return new;
      end if;
    end if;

    return null;
  end;
