returns trigger
language plpgsql
as $$
  declare
    v_participant boolean;
    v_confirmed boolean;
  begin
    select public.is_booking_participant(new.booking_id) into v_participant;

    if v_participant then
      select public.is_booking_confirmed(new.booking_id) into v_confirmed;
      if v_confirmed and new.sender_id = auth.uid() then
        return new;
      end if;
    end if;

    return null;
  end;
$$;

create or replace function public.booking_messages_insert_participant()
returns trigger
language plpgsql
as $$
  declare
    v_participant boolean;
    v_confirmed boolean;
  begin
    select public.is_booking_participant(new.booking_id) into v_participant;

    if not v_participant then
      raise exception 'booking_messages insert: only booking participants can send messages';
    end if;

    select public.is_booking_confirmed(new.booking_id) into v_confirmed;

    if v_confirmed and new.sender_id = auth.uid() then
      return new;
    end if;

    if v_participant and to_regclass('public.public.bookings') is not null then
      raise exception 'booking_messages insert: messages can only be sent on confirmed bookings';
    end if;

    return null;
  end;
$$;

