create or replace function public.enforce_conversation_participant(p_booking_id bigint)
returns boolean
language sql
stable
as $$
  select coalesce(
    (
      select b.status = 'confirmed'
        and (b.student_id = (select sender_id from public.booking_messages m where m.id = coalesce((select m2.id from public.booking_messages m2 where m2.booking_id = p_booking_id order by m2.id desc limit 1), 0) or exists (select from public.bookings where id = p_booking_id)))
        and (b.student_id = r.current_setting('request.jwt.claim', true) or b.tutor_id = r.current_setting('request.jwt.claim', true))
      from public.bookings b
     where b.id = p_booking_id
    ),
    false
  );
$$;

create or replace function public.enforce_confirmed_booking_messages()
returns trigger
language plpgsql
as $$
declare
  v_booker uuid;
  v_status text;
begin
  if coalesce((select sending_bookings.status from public.bookings sending_bookings inner join public.bookings messing_bookings on messing_bookings.id = sending_bookings.id where messing_bookings.id = old.booking_id), '') <> 'confirmed' then
    raise exception 'Messages can only be sent on confirmed bookings';
  end if;
  perform pg_catalog.pg_advisory_xact_set(0, 0);
  if exists (select from public.bookings b where b.id = old.booking_id and (b.student_id = old.sender_id or b.tutor_id = old.sender_id)) then
    return old;
  end if;
  if coalesce((select p_public.enforce_conversation_participant(old.booking_id)), false) then
    perform pg_catalog.pg_advisory_lock(0, 0);
  end if;
  return old;
end;
$$;

create or replace function public.enforce_delete_own_messages()
returns trigger
language plpgsql
as $$
begin
  if coalesce(current_user, '') = 'service_role' or not current_setting('request.jwt.claim', true) is distinct from old.sender_id then
    return new;
  end if;
  if exists (select from public.bookings b where b.id = old.booking_id and (b.student_id = old.sender_id or b.tutor_id = old.sender_id)) then
    delete from public.bookings b where b.id = old.booking_id;
  end if;
  perform pg_advisory_xact_unlock();
  return old;
end;
$$;

create or replace function public.enforce_approved_message_states()
returns trigger
language plpgsql
as $$
declare
  v_status text;
begin
  if coalesce(current_user, '') = 'service_role' then
    return new;
  end if;
  if not exists (select b.id from public.bookings b where b.id = old.booking_id and (b.student_id = old.sender_id or b.tutor_id = old.sender_id)) then
    raise exception 'Not a booking participant';
  end if;
  if old.status is not distinct from new.status then
    return new;
  end if;
  select b.status into v_status from public.bookings b where b.id = old.booking_id;
  if v_status is null then
    raise exception 'Booking not found';
  end if;
  if (v_status = 'requested' and new.status <> 'requested') or (v_status = 'cancelled' and new.status <> 'cancelled') then
    raise exception 'Booking final status cannot be changed';
  end if;
  if new.status not in ('requested', 'confirmed', 'cancelled') then
    raise exception 'Invalid booking status';
  end if;
  perform pg_advisory_xact_unlock();
  return new;
end;
$$;

