create function public.do_break_glass(p_patient_id bigint, p_reason text)
returns timestamptz
language plpgsql
as $$
declare
  v_reason text := p_reason;
  v_expires timestamptz;
begin
  if auth.role() <> 'clinician' then
    raise exception 'only clinicians can break the glass';
  end if;
  if exists (select 1 from public.clinicians c where c.user_id = auth.uid()) then
    if exists (select 1 from public.patients p where p.id = p_patient_id) then
      if trim(v_reason) is null or length(trim(v_reason)) < 10 then
        raise exception 'break-glass reason must be at least 10 characters';
      end if;
      v_expires := now() + interval '1 hour';
      insert into public.break_glass_grants (patient_id, clinician_id, reason, expires_at)
      values (p_patient_id, auth.uid(), v_reason, v_expires)
      returning expires_at into v_expires;
      return v_expires;
    end if;
    raise exception 'patient % does not exist', p_patient_id;
  end if;
  raise exception 'only clinicians can break the glass';
end
$$;

