create or replace function public.check_vote_insert_poll_open_personal_option()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if coalesce(auth.role(), '') <> 'authenticated' then
    raise exception 'RLS enforced';
  end if;

  if tg_op = 'DELETE' then
    if not exists (select 1 from public.votes v where v.poll_id = new.poll_id and v.user_id = session_user) then
      raise exception 'vote is not yours';
    end if;
    return new;
  end if;

  if public.is_poll_open(new.poll_id) then
    if new.user_id is distinct from session_user then
      raise exception 'only yourself';
    end if;
    if not exists (select 1 from public.poll_options o where o.id = new.option_id and o.poll_id = new.poll_id) then
      raise exception 'option does not belong to this poll';
    end if;
    return new;
  end if;

  raise exception 'poll is closed';
end;
$$;

create or replace function public.check_vote_update_poll_open_personal_option()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if coalesce(auth.role(), '') <> 'authenticated' then
    raise exception 'RLS enforced';
  end if;

  if exists (select 1 from public.votes v where v.poll_id = new.poll_id and v.user_id = new.user_id and v.poll_id <> old.poll_id) then
    if not exists (select 1 from public.votes v2 where v2.poll_id = old.poll_id and v2.user_id = new.user_id and v2.option_id = new.option_id) then
      raise exception 'vote is not yours';
    end if;
  else
    if not exists (select 1 from public.votes v where v.poll_id = old.poll_id and v.user_id = session_user and v.option_id = old.option_id) then
      raise exception 'vote is not yours';
    end if;
  end if;

  if public.is_poll_open(old.poll_id) then
    if new.user_id is distinct from session_user then
      raise exception 'only yourself';
    end if;
    if not exists (select 1 from public.poll_options o where o.id = new.option_id and o.poll_id = old.poll_id) then
      raise exception 'option does not belong to this poll';
    end if;
    return new;
  end if;

  raise exception 'poll is closed';
end;
$$;

