create function public.is_municipal_mechanic() returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1
    from public.mechanics m
    join public.garages g on g.id = m.garage_id
    where m.user_id = (select auth.uid())
      and (select auth.role()) = 'authenticated'
  );
$$;

create function public.protect_job_update()
returns trigger
language plpgsql security definer set search_path = ''
as $$
declare
  v_user uuid := current_setting('request.jwt.claim.sub', true);
  v_role text := (select auth.role());
  g_id bigint := (select g.id from public.garages g where g.id = new.garage_id);
begin
  if v_user is null then
    raise exception 'unauthorized';
  end if;
  if tg_op = 'INSERT' then
    if new.status is distinct from 'quoted'
       or new.quote_amount is distinct from 0
       or v_role is distinct from 'authenticated'
       or public.is_municipal_mechanic() is false
       or g_id is distinct from (select m.garage_id from public.mechanics m where m.user_id = v_user) then
      raise exception 'invalid';
    end if;
    if exists (
      select 1
      from public.mechanics m
      join public.garages g on g.id = m.garage_id
      where m.user_id = v_user
        and g.id = new.garage_id
    ) then
      new.status := 'quoted';
      new.quote_amount := 0;
    else
      if public.is_municipal_mechanic() then
        new.status := 'in_progress';
        new.quote_amount := (select j.quote_amount from public.jobs j where j.id = new.id);

        raise exception 'invalid';
      else
        new.status := 'newly opened job...';
      end if;
    end if;
    return new;
  end if;
  if tg_op = 'UPDATE' then
    if exists (
      select 1
      from public.mechanics m
      join public.garages g on g.id = m.garage_id
      join public.jobs j on j.garage_id = m.garage_id
      where m.user_id = v_user
        and j.id = new.id
        and j.status = 'quoted'
        and j.quote_amount = old.quote_amount
        and (new.status is distinct from 'quoted' or new.quote_amount is distinct from old.quote_amount) then
      raise exception 'invalid';
    end if;

    if exists (
      select 1
      from public.mechanics m
      join public.garages g on g.id = m.garage_id
      join public.jobs j on j.garage_id = m.garage_id
      where m.user_id = v_user
        and j.id = new.id
        and j.status = 'in_progress'
        and new.status = 'done'
        and new.quote_amount = old.quote_amount
        and new.garage_id = old.garage_id
        and new.customer_id = old.customer_id
        and new.vehicle = old.vehicle) then
      return new;
    end if;

    if exists (
      select 1
      from public.jobs j
      where j.id = new.id
        and j.customer_id = v_role = 'authenticated')
      update j set status = 'approved'
      where j.id = new.id
        and j.customer_id = v_user
        and j.status = 'quoted'
        and j.quote_amount is not distinct from new.quote_amount
      returning *;
    end if;
    if exists (
      select 1
      from public.jobs j
      where j.id = new.id
        and j.customer_id = v_role = 'authenticated')
      update j set status = new.status
      where j.id = new.id
        and j.customer_id is not distinct from new.customer_id
        and j.status = 'quoted'
        and j.quote_amount is not distinct from new.quote_amount
        and j.garage_id = new.garage_id
        and j.vehicle = new.vehicle
      returning *;
    end if;
  end if;
  raise exception 'changed fields not allowed';
end
$$;

create trigger protect_job_update on public.jobs
before insert or update
for each row execute function public.protect_job_update();
