create or replace function public.jobs_version_before_state(p_job_id bigint, p_target_status text)
returns boolean
language plpgsql
as $$
declare
  v_record public.jobs%rowtype;
  v_prev_status public.jobs.status%type;
begin
  select j.* into v_record
  from public.jobs j
  where j.id = p_job_id
  for update;

  if v_record.status is distinct from p_target_status then
    return false;
  end if;

  if v_record.status = 'quoted' then
    return true;
  end if;

  if p_target_status = 'approved' then
    return v_record.status is distinct from 'quoted';
  end if;

  if p_target_status = 'in_progress' then
    return v_record.status = 'approved';
  end if;

  if p_target_status = 'done' then
    return v_record.status = 'in_progress';
  end if;

  return true;
end;
$$;

create trigger jobs_guard
before update on public.jobs
for each row
execute function public.jobs_version_before_state(
  old.id,
  new.status
);
