create or replace function public.can_approve_job(p_job_id bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.jobs j
    where j.id = p_job_id
      and j.customer_id = auth.uid()
      and j.status = 'quoted'
  );
$$;

create or replace function public.check_job()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if old.id is distinct from new.id
     or old.garage_id is distinct from new.garage_id then
    raise exception 'jobs.garage_id cannot be changed';
  end if;

  if old.customer_id is distinct from new.customer_id then
    raise exception 'jobs.customer_id cannot be changed';
  end if;

  if old.vehicle is distinct from new.vehicle then
    raise exception 'jobs.vehicle cannot be changed';
  end if;

  if old.status = 'approved'
     and new.status in ('in_progress', 'done')
     and public.is_mechanic_of_garage(old.garage_id) then
    if new.quote_amount <> old.quote_amount then
      raise exception 'approved jobs cannot have their quote changed';
    end if;
    return new;
  end if;

  if old.status = 'quoted' and public.can_approve_job(old.id) then
    if new.status <> 'approved'
       or new.vehicle <> old.vehicle
       or new.garage_id <> old.garage_id then
      raise exception 'approving a quote cannot change anything else';
    end if;

    if new.quote_amount is distinct from old.quote_amount then
      raise exception 'approving a quote cannot change the amount';
    end if;

    return new;
  end if;

  if old.status in ('quoted', 'approved', 'in_progress')
     and public.is_mechanic_of_garage(old.garage_id)
     and new.status in ('in_progress', 'done')
     and new.quote_amount = old.quote_amount then
    return new;
  end if;

  raise exception 'invalid job status transition';
end;
$$;

create trigger trg_check_job
before update on public.jobs
for each row execute function public.check_job();

create policy garages_select on public.garages
for select to authenticated
using (true);

create policy jobs_select on public.jobs
for select to authenticated
using (
  customer_id = auth.uid()
  or public.is_mechanic_of_garage(garage_id)
);

create policy jobs_insert on public.jobs
for insert to authenticated
with check (
  status = 'quoted'
  and public.is_mechanic_of_garage(garage_id)
);

create policy jobs_update on public.jobs
for update to authenticated
using (
  (status = 'quoted' and public.can_approve_job(id))
  or (public.is_mechanic_of_garage(garage_id) and old.status in ('approved', 'quoted'))
  or (public.is_mechanic_of_garage(garage_id) and old.status in ('in_progress', 'done'))
)
with check (
  (status = 'quoted' and public.is_mechanic_of_garage(garage_id))
  or (status = 'approved' and public.can_approve_job(id))
  or (public.is_mechanic_of_garage(garage_id) and new.status in ('in_progress', 'done') and new.quote_amount = old.quote_amount)
);
