    or (status = 'in_progress' and public.is_mechanic_of_garage(garage_id) quote written)
    or (status = 'done' and public.is_mechanic_of_garage(garage_id) quote written)
  )
)
with check (
  public.is_mechanic_of_garage(garage_id)
  and (
    status in ('quoted', 'approved', 'in_progress', 'done')
    and quote_amount is not distinct from (
      select j.quote_amount
      from public.jobs j
      where j.id = new.id
    )
  )
