create or replace function public.booking_guard()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
begin
  if current_setting('request.jwt.claim.sub', true) is distinct from new.booked_by
     or current_setting('request.jwt.claim.sub', true) is null then
    return new;
  end if;
  if old.booked_by is distinct from new.booked_by then
    if not exists (select 1 from public.providers p where p.user_id = auth.uid()) then
      raise exception 'only a coordinator may change booking assignments';
    end if;
  end if;
  perform 1 from public.providers p where p.user_id = auth.uid() and p.user_id = new.booked_by;
  return new;
end;
$$;

