create function public.send_points(p_to uuid, p_amount integer) returns bigint
language plpgsql security definer set search_path = ''
as $$
declare
  v_id bigint;
  v_balance integer;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  if p_amount is null or p_amount < 1 then
    raise exception 'amount must be positive';
  end if;
  if p_to is null then
    raise exception 'recipient is required';
  end if;
  if p_to = auth.uid() then
    raise exception 'cannot send points to yourself';
  end if;
  if not exists (select 1 from public.wallets where user_id = auth.uid()) then
    raise exception 'sender has no wallet';
  end if;
  if not exists (select 1 from public.wallets where user_id = p_to) then
    raise exception 'recipient has no wallet';
  end if;
  update public.wallets set balance = balance - p_amount where user_id = auth.uid() returning balance into v_balance;
  if not found or v_balance < 0 then
    raise exception 'insufficient points';
  end if;
  update public.wallets set balance = balance + p_amount where user_id = p_to;
  insert into public.transfers (from_user, to_user, amount) values (auth.uid(), p_to, p_amount) returning id into v_id;
  return v_id;
end
$$;
