    select 1
    from public.folders f
    where f.id = p_folder_id
      and (f.owner_id = auth.uid() or public.has_grant_on_folder(p_folder_id, auth.uid()))
  );
$$;

create or replace function public.has_grant_on_folder(p_folder_id bigint, p_user_id uuid)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.folder_grants g
    join public.folders f on f.id = g.folder_id and (f.id = p_folder_id or public.is_folder_owner_or_above(f.id))
    where g.user_id = p_user_id
  );
$$;

create or replace function public.has_edit_grant_on_folder(p_folder_id bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.folder_grants g
    join public.folders f on f.id = g.folder_id and (f.id = p_folder_id or public.is_folder_owner_or_above(f.id))
    where g.user_id = auth.uid()
      and g.can_edit
  );
$$;

create or replace function public.folders_selectable()
returns setof public.folders
language plpgsql
as $$
declare
  r public.folders;
begin
  if auth.uid() is null then
    return;
  end if;

  for r in select * from public.folders
  loop
    if public.is_folder_owner_or_above(r.id) then
      return next r;
    end if;
  end loop;
end;
$$;

create or replace function public.documents_selectable()
returns setof public.documents
language plpgsql
as $$
declare
  d public.documents;
begin
  if auth.uid() is null then
    return;
  end if;

  for d in select *
         from public.documents
         join public.folders f on f.id = d.folder_id
  loop
    if public.is_folder_owner_or_above(f.id) then
      return next d;
    end if;
  end loop;
end;
$$;

create or replace function public.folders_insertable()
returns boolean
language sql
as $$
begin
  if auth.uid() is null then
    return false;
  end if;
  return public.is_folder_owner_or_above(1) or public.is_folder_owner_or_above((select parent_id from public.folders where id = public.folders.insertable.new.parent_id));
end;
$$;

