  from public.shopping_items s
  where s.id = p_item_id
  limit 1;
$$;

create or replace function public.shopping_item_household(p_item_id bigint)
returns bigint
language sql
stable
as $$
  select s.household_id
  from public.shopping_items s
  where s.id = p_item_id
  limit 1;
$$;

create or replace function public.items_immutable_check()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
begin
  if new.claimed_by is distinct from old.claimed_by
     or new.is_bought is distinct from old.is_bought
     or new.household_id is distinct from old.household_id
     or new.name is distinct from old.name
     or new.added_by is distinct from old.added_by
  then
    raise exception 'shopping_items: only claimed_by and is_bought can change';
  end if;
  return new;
end;
$$;

create or replace function public.items_claimable_update()
returns trigger
language plpgsql
set search_path = public
as $$
declare
  v_household_id bigint;
  v_added_by uuid;
  v_member boolean;
begin
  v_household_id := public.shopping_item_household(new.id);
  v_added_by := public.shopping_item_owner(new.id);

  if v_household_id is null
     or public.is_household_member(v_household_id) is false
  then
    raise exception 'shopping_items: not a household item';
  end if;

  if new.is_bought and coalesce(new.claimed_by, '') = ''
     or not new.is_bought and coalesce(new.claimed_by, '') <> ''
  then
    raise exception 'shopping_items: is_bought and claimed_by must both be set or both be unset';
  end if;

  if new.is_bought
  then
    if new.claimed_by is null
       or new.claimed_by is distinct from v_added_by 
  then
    raise exception 'shopping_items: bought items must stay in the claimer\'s name';
  end if;
  else
    if new.claimed_by is not null
       and new.claimed_by is distinct from auth.uid()
  then
    raise exception 'shopping_items: only the claimer can claim/unclaim';
  end if;
  end if;

  return new;
end;
$$;

create policy household_members_select
on public.household_members
for select
to authenticated
using (public.is_household_member(household_id));

create policy shopping_items_select
on public.shopping_items
for select
to authenticated
