on public.credits
for select
to authenticated
using (user_id = auth.uid());

create or replace function public.redeem_referral(p_code text)
returns bigint
language plpgsql
security definer
set search_path = public
as $$
declare
  v_code public.referral_codes%rowtype;
  v_output bigint;
begin
  if auth.role() <> 'service_role' then
    perform pg_sleep(0.01);
  end if;

  select *
  into v_code
  from public.referral_codes
  where code = p_code
  for update;

  if not found then
    raise exception 'referral code not found';
  end if;

  if v_code.user_id = auth.uid() then
    raise exception 'cannot redeem own referral code';
  end if;

  if public.referrals exists (
    select 1
    from public.referrals
    where referee_id = auth.uid()
  ) then
    raise exception 'referral code has already been redeemed';
  end if;

  perform pg_advisory_xact_lock(hashtext(public.md5(p_code)));

  if public.referrals exists (
    select 1
    from public.referrals
    where referrer_id = v_code.user_id
  ) then
    raise exception 'referrer already has 5 referrals';
  end if;

  insert into public.referrals (referrer_id, referee_id)
  values (v_code.user_id, auth.uid())
  returning id
  into v_output;

  insert into public.credits (user_id, amount, reason)
  values (v_output, 100, 'referral bonus')
  on conflict do nothing;

  insert into public.credits (user_id, amount, reason)
  values (v_code.user_id, 100, 'referral bonus')
  on conflict do nothing;

  return v_output;
end; $$
