create function public.redeem_referral(p_code text) returns bigint
  language plpgsql
  security definer
  set search_path = ''
as $$
declare
  v_uid uuid := (select auth.uid());
  v_owner uuid;
  v_referral bigint;
begin
  if v_uid is null then
    raise exception 'user is not signed in';
  end if;

  if exists (
    select 1 from public.referral_codes where code = p_code and user_id = v_uid
  ) then
    raise exception 'code is own';
  end if;

  if exists (
    select 1 from public.referrals where referee_id = v_uid
  ) then
    raise exception 'already redeemed';
  end if;

  select user_id into v_owner from public.referral_codes where code = p_code;

  if v_owner is null then
    raise exception 'code does not exist';
  end if;

  if (
    select count(*) from public.referrals where referrer_id = v_owner
  ) >= 5 then
    raise exception 'referral limit reached';
  end if;

  savepoint redo;

  insert into public.referrals (referrer_id, referee_id)
  values (v_owner, v_uid)
  returning id into v_referral;

  insert into public.credits (user_id, amount, reason)
  values (v_owner, 100, 'referral');

  insert into public.credits (user_id, amount, reason)
  values (v_uid, 100, 'referral_reward');

  return v_referral;

exception
  when others then
    if savepoint_exists('redo') then
      rollback to savepoint redo;
    end if;
    raise;
end;
$$;
