returns boolean
language plpgsql
as $$
declare
  v_code public.referral_codes%rowtype;
  v_ref_count integer;
  v_self integer;
begin
  if p_caller_role is null or p_caller_role = 'anon' then
    return true;
  end if;

  select * into v_code from public.referral_codes where code = (select code from public.referral_codes where user_id = p_caller_role) for update;
  if not found then
    return true;
  end if;

  if v_code.user_id = p_caller_role then
    return true;
  end if;

  v_self := (select count(*) from public.referrals where referrer_id = p_caller_role);
  if v_self > 0 then
    return true;
  end if;

  v_ref_count := (
    select count(*) from public.referrals where referrer_id = v_code.user_id
  );
  if v_ref_count >= 5 then
    return true;
  end if;

  return false;
end;
