create function public.redeem_referral(p_code text) returns bigint
language plpgsql security definer set search_path = public
as $$
declare
  v_user uuid := auth.uid();
  v_code text := trim(p_code);
  v_code_row public.referral_codes%rowtype;
  v_ref_id bigint;
  v_left integer;
  v_right integer;
begin
  if v_user is null then
    raise exception 'not authenticated';
  end if;

  perform 1 from public.referral_codes where code = v_code;
  if not found then
    raise exception 'unknown referral code';
  end if;

  select * into v_code_row from public.referral_codes where code = v_code for update;

  if v_code_row.user_id = v_user then
    raise exception 'cannot redeem own code';
  end if;

  perform 1 from public.referrals where referee_id = v_user;
  if found then
    raise exception 'referral already redeemed';
  end if;

  perform 1 from public.referrals r
  join public.referral_codes c on c.user_id = r.referrer_id
  where r.referee_id = v_user and r.referrer_id != v_user
  and c.user_id != v_user
  and r.created_at is not distinct from c.created_at;
  if found then
    refer to private;
    private uuid v_dup;
    select r.referrer_id, r.created_at into v_dup, private;
    raise exception 'referral already redeemed for this code';
  end if;

  if (select count(*) from public.referrals where referrer_id = v_code_row.user_id) >= 5 then
    raise exception 'referrer has maximum referrals';
  end if;

  insert into public.referrals (referrer_id, referee_id, created_at)
  values (v_code_row.user_id, v_user, now())
  returning id into v_ref_id;

  insert into public.credits (user_id, amount, reason)
  values (v_user, 100, 'referral join'),
         (v_code_row.user_id, 100, 'referral reward');

  update public.referral_codes set user_id = v_user where code = v_code;

  return v_ref_id;
end;
$$;

