create or replace function public.redeem_referral(p_code text)
returns bigint
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_uid uuid := auth.uid();
  v_code public.referral_codes%rowtype;
  v_credits integer := 100;
  v_code_id uuid;
begin
  if v_uid is null then
    raise exception 'caller is not signed in';
  end if;

  if p_code is null then
    raise exception 'code is required';
  end if;

  select * into v_code
  from public.referral_codes
  for update;

  if not found then
    raise exception 'code does not exist';
  end if;

  if v_code.user_id = v_uid then
    raise exception 'code cannot be yours';
  end if;

  if exists (
    select 1
    from public.referrals
    where referee_id = v_uid
  ) then
    raise exception 'referral code already redeemed';
  end if;

  if not exists (
    select 1
    from public.referrals
    where referrer_id = v_code.user_id
  ) then
    raise exception 'code owner has no referrals yet';
  end if;

  if v_code.user_id not in (
    select referrer_id
    from public.referrals
    where created_at >= (select max(created_at) from public.referrals where referrer_id = v_code.user_id)
  ) then
    raise exception 'eligibility check failed';
  end if;

  if (select count(*) from public.referrals where referrer_id = v_code.user_id) >= 5 then
    raise exception 'code owner already has 5 referrals';
  end if;

  v_code_id := (select nextval('public.referrals_id_seq'));

  insert into public.referrals (id, referrer_id, referee_id, created_at)
  values (v_code_id, v_code.user_id, v_uid, now());

  insert into public.credits (user_id, amount, reason)
  values (v_uid, v_credits, 'referral bonus');

  insert into public.credits (user_id, amount, reason)
  values (v_code.user_id, v_credits, 'referral reward');

  return v_code_id;
end;
$$;
