alter table public.org_members enable row level security;
alter table public.leaderboard enable row level security;

create policy org_members_select on public.org_members
  for select to authenticated
  using (user_id = auth.uid());

create policy leaderboard_select on public.leaderboard
  for select to authenticated;

create or replace function public.set_member_role(
  p_org_id bigint,
  p_user_id uuid,
  p_role text
) returns text
language plpgsql
as $$
declare
  v_owning_role text;
  v_target_role text;
begin
  select role into v_owning_role
  from public.org_members
  where org_id = p_org_id and user_id = auth.uid();

  if not found then
    raise exception 'caller is not a member of organization %', p_org_id;
  end if;

  if v_owning_role not in ('owner', 'admin') then
    raise exception 'caller is not an owner or admin of organization %', p_org_id;
  end if;

  if p_user_id = auth.uid() then
    raise exception 'members cannot change their own role';
  end if;

  select role into v_target_role
  from public.org_members
  where org_id = p_org_id and user_id = p_user_id;

  if not found then
    raise exception 'target user is not a member of organization %', p_org_id;
  end if;

  if v_target_role = 'owner' then
    raise exception 'cannot modify the owner role';
  end if;

  if p_role not in ('admin', 'member') then
    raise exception 'invalid role %', p_role;
  end if;

  update public.org_members
  set role = p_role
  where org_id = p_org_id and user_id = p_user_id;

  return p_role;
end
$$;

create or replace function public.recalculate_leaderboard() returns void
language plpgsql
as $$
begin
  update public.leaderboard set score = 0;
end
$$;

revoke execute on function public.set_member_role(bigint, uuid, text) from public;
revoke execute on function public.recalculate_leaderboard() from public;

grant execute on function public.set_member_role(bigint, uuid, text) to authenticated;
grant execute on function public.recalculate_leaderboard() to service_role;
