create or replace function public.is_member(p_user_id uuid, p_org_id bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.org_members
    where org_id = p_org_id
      and user_id = p_user_id
  );
$$;

create or replace function public.set_member_role(p_org_id bigint, p_user_id uuid, p_role text)
returns text
language plpgsql
set search_path = public
as $$
declare
  l_uid   uuid := auth.uid();
  l_new   text;
begin
  if l_uid is null then
    raise exception 'not authenticated';
  end if;
  if p_role not in ('admin', 'member') then
    raise exception 'invalid role';
  end if;
  if p_uid is null then
    raise exception 'cannot set role of yourself';
  end if;
  if p_uid = l_uid then
    raise exception 'cannot set your own role';
  end if;
  if exists (
    select 1
    from public.org_members
    where org_id = p_org_id
      and user_id = p_uid
      and role = 'owner'
  ) then
    raise exception 'cannot set role of an owner';
  end if;
  if not exists (
    select 1
    from public.org_members m
    where m.org_id = p_org_id
      and m.user_id = l_uid
      and m.role in ('owner', 'admin')
  ) then
    raise exception 'not an owner or admin';
  end if;
  update public.org_members
     set role = p_role
   where org_id = p_org_id
     and user_id = p_uid
     and exists (
       select 1
       from public.org_members m
       where m.org_id = p_org_id
         and m.user_id = l_uid
         and m.role in ('owner', 'admin')
     );
  if not found then
    raise exception 'target not a member of the organization';
  end if;
  select o.role
    into l_new
    from public.org_members o
   where o.org_id = p_org_id
     and o.user_id = p_uid;
  return l_new;
end;
$$;

create or replace function public.recalculate_leaderboard()
returns void
language plpgsql
set search_path = public
as $$
declare
  l_uid uuid := auth.uid();
begin
  if l_uid is null then
    raise exception 'not authenticated';
  end if;
  execute format(
    'update public.leaderboard set score = t.score from (select u.id, coalesce((select count(*)::int from public.org_members o where o.role in (''owner'', ''admin'') and o.org_id = (select o2.org_id from public.org_members o2 where o2.user_id = u.id)) * 10, 0)::int as score from public.users u) t where leaderboard.user_id = t.id',
    l_uid
  );
  return;
end;
$$;

