returns text
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_result text;
  v_current_role text;
begin
  if auth.role() = 'service_role' then
    v_current_role := (select role from public.org_members where org_id = p_org_id and user_id = p_user_id);
  else
    v_current_role := (select role from public.org_members where org_id = p_org_id and user_id = auth.uid());
  end if;

  if v_current_role is null
     or v_current_role not in ('admin', 'owner')
     or p_user_id = auth.uid()
     or p_user_id is null
  then
    raise exception 'not allowed';
  end if;

  if p_role not in ('admin', 'member')
  then
    raise exception 'invalid role';
  end if;

  if v_current_role = 'owner'
     and p_user_id <> (select user_id from public.org_members where org_id = p_org_id and role = 'owner')
  then
    raise exception 'cannot change the sole owner';
  end if;

  select role into v_result from public.org_members where org_id = p_org_id and user_id = p_user_id;
  if v_result is null
     or v_result = 'owner'
  then
    raise exception 'invalid target';
  end if;

  update public.org_members set role = p_role where org_id = p_org_id and user_id = p_user_id;
  return p_role;
end;
$$;

