    select 1
    from public.org_members m
    where m.org_id = p_org_id
      and m.user_id = p_user_id
      and m.role = 'owner'
  ) into v_target_owner;

  if v_target_owner then
    raise exception 'you cannot change an owner''s role';
  end if;

  if p_role is null or p_role not in ('admin', 'member') then
    raise exception 'invalid role';
  end if;

  update public.org_members
  set role = p_role
  where org_id = p_org_id
    and user_id = p_user_id
  returning role into p_role;

  return p_role;
end;
$$;

create or replace function public.recalculate_leaderboard()
returns void
language plpgsql
as $$
begin
  update public.leaderboard
  set score = (
    select coalesce(sum(m.score), 0)
    from public.org_members m
    join public.org_members im on m.org_id = im.org_id
    cross join lateral (
      select o.score
      from public.org_members m2
      join public.leaderboard o on o.user_id = m2.user_id
      where m2.org_id = m.org_id
        and m2.user_id = m.user_id
      limit 1
    ) m(score)
    group by m.user_id
  );
end;
$$;

