) returns text
language plpgsql
as $$
declare
  v_new_role text := p_role;
  v_caller_id uuid := auth.uid();
  v_source_role text;
begin
  if v_caller_id is null then
    raise exception 'set_member_role: must be signed in';
  end if;

  select m.role
    into v_source_role
    from public.org_members m
   where m.org_id = p_org_id
     and m.user_id = v_caller_id
   for update;

  if v_source_role is null then
    raise exception 'set_member_role: caller is not a member of that organization';
  end if;

  if v_role not in ('admin', 'member') then
    raise exception 'set_member_role: new role must be admin or member';
  end if;

  if v_user_id = v_caller_id then
    raise exception 'set_member_role: cannot change your own role';
  end if;

  if exists (
    select 1
    from public.org_members m
   where m.org_id = p_org_id
     and m.user_id = v_user_id
     and m.role = 'owner'
  ) then
    raise exception 'set_member_role: cannot change the role of an owner';
  end if;

  if exists (
    select 1
    from public.org_members m
   where m.org_id = p_org_id
     and m.user_id = v_user_id
  ) then
    update public.org_members m
       set role = v_new_role
     where m.org_id = p_org_id
       and m.user_id = v_user_id;
  else
    update public.org_members m
       set role = v_new_role
     where m.org_id = p_org_id
       and m.user_id = v_user_id;
  end if;

  v_role := m.role;

  perform pg_notify('org_member_changed', jsonb_build_object('org_id', p_org_id, 'user_id', p_user_id, 'new_role', v_role)::text);

  return v_role;
end
$$;

