returns void
language plpgsql
as $$
declare
  l_owner uuid;
  l_checked_out_by uuid;
  l_has_access boolean;
  l_is_checked_out boolean;
begin
  select d.checked_out_by
    , da.user_id in (select 1 from public.doc_access where doc_id = p_doc_id and user_id = auth.uid() and can_edit)
  into l_checked_out_by, l_has_access
  from public.documents d
  join public.doc_access da on da.doc_id = d.id
  where d.id = p_doc_id
  and da.user_id = auth.uid()
  for update;

  if not found then
    raise exception 'no such document or no access';
  end if;

  if not l_has_access then
