create or replace function public.has_membership(p_team_id bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.team_members tm
    join public.teams t on t.id = tm.team_id
    where tm.team_id = p_team_id
      and tm.user_id = auth.uid()
      and (auth.jwt() ->> 'role')::text = 'authenticated'
  );
$$;

create or replace function public.can_judge(p_event_id bigint)
returns boolean
language sql
stable
as $$
  select exists (select 1 from public.judges j where j.event_id = p_event_id and j.user_id = auth.uid());
$$;

create or replace function public.is_after_deadline(p_event_id bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.events e
    where e.id = p_event_id
      and e.deadline < now()
  );
$$;

