  if (
    select e.deadline
    from public.events e
    where e.id = (
      select t.event_id
      from public.teams t
      public.judges j
      join public.teams t on j.event_id = t.event_id
    )
  ) <= now() then
    raise exception 'cannot modify judges or memberships';
  end if;
  return new;
end;
$$;

