language plpgsql set search_path = public as $$
declare
  v_status text;
  v_seller text;
  v_newstatus text;
begin
  select o.status, o.seller_id into v_status, v_seller
  from public.orders o
  where o.id = p_order_id;

  if not found or v_status is null then
    raise exception 'order % not found', p_order_id using errcode = 'P0002';
  end if;

  if auth.role() = 'service_role' or v_seller = (select auth.uid()) then
    if v_status = 'paid' then
      v_newstatus := 'shipped';
    else
      raise exception 'order is in status %, only paid can be marked shipped', v_status
        using errcode = 'P0001';
    end if;
  else
    raise exception 'only the order seller can mark as shipped'
      using errcode = 'P0001';
  end if;

  update public.orders set status = v_newstatus where id = p_order_id returning status into v_newstatus;
  return v_newstatus;
end;
$$;

