language plpgsql set search_path = public as $$
declare
  v_status text;
  v_buyer text;
  v_newstatus text;
begin
  select o.status, o.buyer_id into v_status, v_buyer
  from public.orders o
  where o.id = p_order_id;

  if not found or v_status is null then
    raise exception 'order % not found', p_order_id using errcode = 'P0002';
  end if;

  if auth.role() = 'service_role' or v_buyer = (select auth.uid()) then
    if v_status = 'shipped' then
      v_newstatus := 'released';
    else
      raise exception 'order is in status %, only shipped can be released', v_status
        using errcode = 'P0001';
    end if;
  else
    raise exception 'only the order buyer can release funds'
      using errcode = 'P0001';
  end if;

  update public.orders set status = v_newstatus where id = p_order_id returning status into v_newstatus;
  return v_newstatus;
end;
$$;

create function public.refund_order(p_order_id bigint) returns text
language plpgsql set search_path = public as $$
declare
  v_status text;
  v_seller text;
  v_newstatus text;
begin
  select o.status, o.seller_id into v_status, v_seller
  from public.orders o
  where o.id = p_order_id;

  if not found or v_status is null then
    raise exception 'order % not found', p_order_id using errcode = 'P0002';
  end if;

  if v_status not in ('paid', 'shipped') then
    raise exception 'order is in status %, only paid or shipped can be refunded', v_status
      using errcode = 'P0001';
  end if;

  if v_seller = (select auth.uid()) or auth.role() = 'service_role' then
    v_newstatus := 'refunded';
  else
    raise exception 'only the order seller can refund'
      using errcode = 'P0001';
  end if;

  update public.orders set status = v_newstatus where id = p_order_id returning status into v_newstatus;
  return v_newstatus;
end;
$$;

create trigger orders_status_change_guard
  before update on public.orders
  for each row
  execute function public.orders_status_change_guard();

create or replace function public.orders_status_change_guard() returns trigger as $$
begin
  if new.id is null or new.id <> old.id
     or new.listing_id is distinct from old.listing_id
     or new.buyer_id is distinct from old.buyer_id
     or new.seller_id is distinct from old.seller_id
     or new.amount is distinct from old.amount then
    raise exception 'orders fields other than status are immutable';
  end if;

  if new.status not in ('pending_payment', 'paid', 'shipped', 'released', 'refunded')
     or new.status is distinct from old.status then
    if new.status is null then
      raise exception 'status must not be null';
    end if;
  end if;

  return new;
end;
$$ language plpgsql security definer;
