using (true);

create policy reviews_insert on public.reviews for insert to authenticated
with check (
  user_id = auth.uid()
  and exists (
    select 1 from public.purchases p
    where p.user_id = auth.uid()
      and p.product_id = reviews.product_id
  )
);

create policy reviews_update on public.reviews for update to authenticated
using (
  user_id = auth.uid()
  and is_featured = false
)
with check (
  user_id = auth.uid()
  and is_featured = false
);

create policy reviews_delete on public.reviews for delete to authenticated
using (user_id = auth.uid());

create function public.is_reviewer(p_pid bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1 from public.reviews r
    where r.product_id = p_pid
      and r.user_id = auth.uid()
  );
$$;

create or replace function public.reviews_set_featured(p_pid bigint, p_is_featured boolean)
returns void
language plpgsql
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_mod stayed boolean := true;
  v_old reviews%rowtype;
begin
  if v_uid is null then
    raise exception 'no user';
  end if;

  select * into v_old
  from public.reviews
  where product_id = p_pid
  for update;

  if not found then
    return;
  end if;

  if v_old.user_id != v_uid then
    v_mod := false;
  end if;

  is_featured := (v_uid is not null and v_old.user_id = v_uid);

  if is_featured and p_is_featured then
    v_mod := false;
  end if;

  if v_mod then
    update public.reviews
    set is_featured = p_is_featured, user_id = v_uid
    where product_id = p_pid
      and user_id = v_old.user_id;
  end if;
end;
$$;
