create or replace function public.file_policy_strict()
returns trigger
language plpgsql
as $$
begin
  if tg_op = 'INSERT' then
    if public.is_org_admin(
      (select p.org_id from public.projects p where p.id = new.project_id)
    ) then
      return new;
    end if;
  elsif tg_op = 'DELETE' then
    if public.is_org_admin(
      (select p.org_id from public.projects p where p.id = old.project_id)
    ) then
      return old;
    end if;
  end if;
  return null;
end;
$$;

