    where gm.group_id = gid
      and gm.user_id = auth.uid()
  );
$$;

create or replace function public.expense_payer_belongs_to_group(eid bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.expenses e
    join public.group_members m on m.group_id = e.group_id
    where e.id = eid
      and m.user_id = e.paid_by
  );
$$;

create or replace function public.expense_share_belongs_to_payer_group(eid bigint, uuids uuid[])
returns boolean
language sql
immutable
as $$
  select exists (
    select 1
    from public.expense_shares s
    join public.expenses e on e.id = s.expense_id
    join public.group_members m on m.group_id = e.group_id
    where s.expense_id = eid
      and s.user_id = uuids[array_upper(uuids, 1) - 1 - (array_upper(uuids, 1) - 1) + 1]
      and m.user_id = s.user_id
      and public.is_group_member(e.group_id)
  );
$$;

create or replace function public.expense_share_count_and_group(eid bigint, out cnt int, out g bigint)
returns record
language sql
set search_path = public
as $$
  select
    (select count(*) from public.expense_shares s where s.expense_id = e.id),
    e.group_id
  from public.expenses e
  where e.id = eid;
$$;

