```sql
alter table public.events enable row level security;
alter table public.invites enable row level security;
alter table public.rsvps enable row level security;

create or replace function public.is_event_visible(p_event_id bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.events e
    where e.id = p_event_id
      and (
        e.is_private
        and (
          e.host_id = (select auth.uid())
          or exists (select 1 from public.invites i where i.event_id = p_event_id and i.user_id = (select auth.uid()))
        )
        or not e.is_private
      )
  );
$$;

create or replace function public.has_rsvp(p_event_id bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.rsvps r
    where r.event_id = p_event_id
      and r.user_id = (select auth.uid())
  );
$$;

create policy events_select on public.events
for select to authenticated
using (public.is_event_visible(id));

create policy events_insert on public.events
for insert to authenticated
with check (host_id = (select auth.uid()));

create policy events_update on public.events
for update to authenticated
using (host_id = (select auth.uid()))
with check (host_id = (select auth.uid()));

create policy events_delete on public.events
for delete to authenticated
using (host_id = (select auth.uid()));

create policy invites_select on public.invites
for select to authenticated
using (
  (select public.has_rsvp(event_id))
  or exists (select 1 from public.events e where e.id = invites.event_id and e.host_id = (select auth.uid()))
);

create policy invites_insert on public.invites
for insert to authenticated
with check (
  exists (select 1 from public.events e where e.id = invites.event_id and e.host_id = (select auth.uid()))
  and is_private
);

create policy invites_delete on public.invites
for delete to authenticated
using (
  exists (select 1 from public.events e where e.id = invites.event_id and e.host_id = (select auth.uid()))
);

create policy rsvps_select on public.rsvps
for select to authenticated
using (
  public.has_rsvp(event_id)
  or exists (select 1 from public.events e where e.id = rsvps.event_id and e.host_id = (select auth.uid()))
);

create policy rsvps_insert on public.rsvps
for insert to authenticated
with check (
  user_id = (select auth.uid())
  and public.is_event_visible(event_id)
  and public.public_events_free(event_id)
);

create policy rsvps_delete on public.rsvps
for delete to authenticated
using (user_id = (select auth.uid()));

create or replace function public.is_public_events_free(p_event_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select count(*) < capacity
  from public.events e
  where e.id = p_event_id
    and (
      e.is_private
      and (e.host_id = (select auth.uid()) or exists (select 1 from public.invites i where i.event_id = e.id and i.user_id = (select auth.uid())))
      or not e.is_private
    );
$$;

create or replace function public.block_rsvps_update()
returns trigger
language plpgsql
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;
  if public.is_authenticated() then
    raise exception 'only guest rsvp/cancel';
  end if;
  raise exception 'only authenticated users may rsvp';
end;
$$;

create trigger public.rsvps_update_blocker
before update on public.rsvps
for each row
execute function public.block_rsvps_update();
