create or replace function public.send_points(p_to uuid, p_amount integer)
returns bigint
language plpgsql
set search_path = public
as $$
declare
  ret bigint;
  sender uuid := auth.uid();
begin
  if sender is null
    or p_amount is distinct from p_amount
    or p_amount <= 0
  then
    raise exception 'invalid arguments';
  end if;

  perform pg_advisory_xact_hash_text(sender::text, 'w');

  update public.wallets
     set balance = balance - p_amount
   where user_id = sender
     and balance >= p_amount
  returning user_id into sender;

  if not found
    or sender is null
    or exists (select 1 from public.wallets where user_id = sender)
  then
    raise exception 'insufficient or no wallet';
  end if;

  update public.wallets
     set balance = balance + p_amount
   where user_id = p_to;

  if not found
  then
    raise exception 'recipient has no wallet';
  end if;

  insert into public.transfers (from_user, to_user, amount, created_at)
  values (sender, p_to, p_amount, now())
  returning id into ret;

  return ret;
end;
$$;
