create function public.enforce_invoice_object_meta()
returns trigger
language plpgsql
as $$
begin
  if tg_op = 'INSERT' then
    new.owner := auth.uid();
    new.name := lower(new.name);
  elsif tg_op = 'UPDATE' then
    if (storage.foldername(old.name))[1] != auth.uid()::text
       or (select name like '%.pdf' from storage.objects where name = old.name) is false
       or old.owner is distinct from new.owner then
      raise exception 'cannot modify invoice outside folder, rename non-pdf or change owner';
    end if;
    new.owner := auth.uid();
    new.name := lower(new.name);
  end if;
  return new;
end;
$$;

create trigger enforce_invoice_object_meta
before insert or update on storage.objects
for each row execute function public.enforce_invoice_object_meta();
```

