alter table public.ops_team enable row level security;
alter table public.access_requests enable row level security;
alter table public.access_approvals enable row level security;

create policy ops_team_select on public.ops_team
  for select to authenticated
  using (true);

create policy access_requests_select on public.access_requests
  for select to authenticated
  using (requester_id = auth.uid() or user_id in (select user_id from public.ops_team));

create policy access_requests_insert on public.access_requests
  for insert to authenticated
  with check (requester_id = auth.uid() and status = 'pending');

create policy access_requests_delete on public.access_requests
  for delete to authenticated
  using (requester_id = auth.uid() and status = 'pending');

create policy access_approvals_select on public.access_approvals
  for select to authenticated
  using (user_id in (select user_id from public.ops_team)
         or request_id in (select id from public.access_requests where requester_id = auth.uid()));

create function public.approve_access(p_request_id bigint)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_result text;
begin
  if auth.role() is null or auth.role() not in ('authenticated', 'coordinator', 'admin') then
    raise exception 'approve_access: not authenticated';
  end if;

  if not exists (select 1 from public.ops_team where user_id = auth.uid()) then
    raise exception 'approve_access: caller not on the ops team';
  end if;

  if not exists (select 1 from public.access_requests where id = p_request_id) then
    raise exception 'approve_access: request does not exist';
  end if;

  if not exists (select 1 from public.access_requests where id = p_request_id and status = 'pending') then
    raise exception 'approve_access: request is not pending';
  end if;

  if exists (select 1 from public.access_approvals where request_id = p_request_id and approver_id = auth.uid()) then
    raise exception 'approve_access: caller has already approved it';
  end if;

  if auth.uid() = (select requester_id from public.access_requests where id = p_request_id) then
    raise exception 'approve_access: cannot approve own request';
  end if;

  perform 1
    from public.access_approvals
   where request_id = p_request_id
     and approver_id = auth.uid();

  insert into public.access_approvals (request_id, approver_id)
  values (p_request_id, auth.uid());

  select status into v_result
    from public.access_requests
   where id = p_request_id;

  if exists (
    select 1
    from public.access_approvals a
    join public.access_requests r on r.id = a.request_id
    where r.id = p_request_id and r.status = 'pending'
    group by r.id
    having count(distinct a.approver_id) >= 2
  ) then
    update public.access_requests set status = 'granted' where id = p_request_id;
    v_result := 'granted';
  end if;

  return v_result;
end;
$$;
```

```sql
alter table public.ops_team enable row level security;
alter table public.access_requests enable row level security;
alter table public.access_approvals enable row level security;

create policy ops_team_select_security on public.ops_team
  for select to authenticated
  using (true);

create policy access_request_select_security on public.access_requests
  for select to authenticated
  using (
    requester_id = auth.uid()
    or auth.uid() in (
      select user_id from public.ops_team
    )
  );

create policy access_request_insert_security on public.access_requests
  for insert to authenticated
  with check (
    requester_id = auth.uid()
    and status = 'pending'
  );

create policy access_request_delete_security on public.access_requests
  for delete to authenticated
  using (
    requester_id = auth.uid()
    and status = 'pending'
  );

create policy access_approval_select_security on public.access_approvals
  for select to authenticated
  using (
    not exists (
      select 1
      from public.ops_team
      where user_id = auth.uid()
    )
    or exists (
      select 1
      from public.access_requests
      where id = access_approvals.request_id
        and (
          requester_id = auth.uid()
          or auth.uid() in (
            select user_id from public.ops_team
          )
        )
    )
  );

create function public.approve_access(p_request_id bigint) returns text
language plpgsql security definer set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_request public.access_requests%rowtype;
  v_result text;
begin
  if v_uid is null then
    raise exception 'not authenticated';
  end if;

  select *
  into v_request
  from public.access_requests
  where id = p_request_id
  for update;

  if not found then
    raise exception 'request % does not exist', p_request_id;
  end if;

  if v_request.status <> 'pending' then
    raise exception 'request % is %', p_request_id, v_request.status;
  end if;

  if v_request.requester_id = v_uid then
    raise exception 'cannot approve own request';
  end if;

  if exists (
    select 1
    from public.access_approvals
    where request_id = p_request_id
      and approver_id = v_uid
  ) then
    raise exception 'already approved this request';
  end if;

  if not exists (
    select 1
    from public.ops_team
    where user_id = v_uid
  ) then
    raise exception 'not an ops team member';
  end if;

  insert into public.access_approvals (request_id, approver_id, approved_at)
  values (p_request_id, v_uid, now());

  update public.access_requests
  set status = 'granted'
  where id = p_request_id
    and (
      select count(distinct approver_id)
      from public.access_approvals
      where request_id = p_request_id
    ) >= 2;

  v_result := (select status from public.access_requests where id = p_request_id);

  if v_result <> 'granted' then
    raise exception 'not enough approvals';
  end if;

  return v_result;
end;
$$;

