create or replace function public.approve_access(p_request_id bigint) returns text
language plpgsql
set search_path = public
as $$
declare
  v_role text := (select coalesce(auth.role(), 'anon'));
  v_uid uuid := auth.uid();
  v_req public.access_requests%rowtype;
  v_exists boolean := exists (select 1 from public.ops_team where user_id = v_uid);
  v_approved boolean := exists (select 1 from public.access_approvals where request_id = p_request_id and approver_id = v_uid);
begin
  if v_role is distinct from 'service_role' then
    if not v_exists or not v_approved or v_uid = v_req.requester_id or (select status from public.access_requests where id = p_request_id) <> 'pending'
       then raise exception 'Invalid approval request';
    end if;
  end if;

  select * into v_req from public.access_requests where id = p_request_id for update;

  if v_req.status <> 'pending' then
    raise exception 'Request is no longer pending';
  end if;

  if v_uid = v_req.requester_id then
    raise exception 'Cannot approve your own request';
  end if;

  insert into public.access_approvals (request_id, approver_id, approved_at)
  values (p_request_id, v_uid, now());

  if exists (select 1 from public.access_approvals where request_id = p_request_id group by request_id having count(distinct approver_id) >= 2) then
    update public.access_requests set status = 'granted' where id = p_request_id;
    return 'granted';
  end if;

  return 'pending';
end
$$;
