create policy access_approvals_insert on public.access_approvals
  for insert to authenticated
  with check (exists (select 1 from public.access_requests a where a.id = request_id and a.status = 'pending' and exists (select 1 from public.ops_team where user_id = auth.uid()) and exists (select 1 from public.access_approvals where request_id = request_id)));

create function public.approve_access(p_request_id bigint) returns text
language plpgsql
as $$
declare
  v_approver uuid := auth.uid();
  v_request public.access_requests%rowtype;
  v_approval_count integer;
  v_new_status text;
  v_outcome text;
begin
  if public.role() = 'anon' then
    raise exception 'approve_access not permitted for anonymous visitors';
  end if;

  select * into v_request
  from public.access_requests
  where id = p_request_id
  for update;

  if not found then
    raise exception 'request % does not exist', p_request_id;
  end if;

  if v_request.status <> 'pending' then
    raise exception 'request % is not pending', p_request_id;
  end if;

  if v_request.requester_id = v_approver then
    raise exception 'approver cannot be the requester';
  end if;

  if exists (select 1 from public.access_approvals where request_id = p_request_id and approver_id = v_approver) then
    raise exception 'approver % has already approved request %', v_approver, p_request_id;
  end if;

  if not exists (select 1 from public.ops_team where user_id = v_approver) then
    raise exception 'approver % is not on the ops team', v_approver;
  end if;

  insert into public.access_approvals (request_id, approver_id)
  values (p_request_id, v_approver);

  select count(distinct approver_id) into v_approval_count
  from public.access_approvals
  where request_id = p_request_id;

  v_new_status := case when v_approval_count >= 2 then 'granted' else 'pending' end;
  v_outcome := v_new_status;

  update public.access_requests
  set status = v_new_status
  where id = p_request_id;

  return v_outcome;
end;
$$;
