on public.bookings
for insert
to authenticated
with check (
  user_id = (select auth.uid())
  and day >= current_date
  and exists (
    select 1
    from public.memberships m
    where m.user_id = (select auth.uid())
      and day <= m.valid_until
  )
  and not exists (
    select 1
    from public.bookings b
    where b.user_id = (select auth.uid())
      and b.day >= current_date
      and b.day < (select m.valid_until
                   from public.memberships m
                   where m.user_id = (select auth.uid()))
    group by b.user_id, day
    having count(*) > 3
  )
  and exists (
    select 1
    from public.desks d
    join public.memberships m on m.user_id = (select auth.uid())
    where d.id = bookings.desk_id
      and m.tier = d.zone
  )
);

