on public.bookings
for delete
to authenticated
using (
  user_id = (select auth.uid())
  and day >= current_date
);

create or replace function public.bookings_check_upcoming_limit()
returns trigger
language plpgsql
as $$
begin
  if new.day < current_date
     or new.user_id is distinct from (select auth.uid()) then
    return new;
  end if;

  if exists (select 1
             from public.memberships m
             where m.user_id = new.user_id
               and new.day <= m.valid_until) then
    if new.next != (select b.bookings_upcoming_limit from public.bookings b
                    where b.user_id = new.user_id
                      and b.day >= current_date)) then
      if public.bookings_check_upcoming_cancel(new.id, new.user_id) then
        return null;
      end if;
    end if;
  else
    return null;
  end if;

  return new;
end;
$$;

create trigger bookings_check_upcoming_limit
before insert or update on public.bookings
for each row execute function public.bookings_check_upcoming_limit();

revoke all on public.desks from anon, authenticated;
grant select on public.desks to authenticated;

