```sql
alter table public.employees enable row level security;
alter table public.leave_requests enable row level security;

create or replace function public.current_employee_id()
returns uuid
language sql
stable
as $$
  select coalesce(auth.uid()::uuid, (select user_id from public.employees where full_name = current_setting('request.jwt.claims', true)::text[2]), null);
$$;

create or replace function public.is_manager_of(e uuid)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.employees m
    where m.user_id = public.current_employee_id()
      and m.id = e
  );
$$;

create or replace function public.has_pending_leave_request()
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.leave_requests l
    where l.employee_id = public.current_employee_id()
      and l.status = 'pending'
  );
$$;

create or replace function public.can_decide_leave_request()
returns boolean
language sql
stable
as $$
  select public.has_pending_leave_request()
       and public.is_manager_of((select l.employee_id from public.leave_requests l where l.id = public.current_employee_id()));
$$;

create policy employees_select on public.employees
  for select to authenticated
  using (
    user_id = public.current_employee_id()
    or public.is_manager_of(id)
  );

create policy leave_requests_select on public.leave_requests
  for select to authenticated
  using (
    employee_id = public.current_employee_id()
    or public.is_manager_of(employee_id)
  );

create policy leave_requests_insert on public.leave_requests
  for insert to authenticated
  with check (
    employee_id = public.current_employee_id()
    and status = 'pending'
    and decided_by is null
  );

create policy leave_requests_update on public.leave_requests
  for update to authenticated
  using (
    employee_id = public.current_employee_id()
    and public.can_decide_leave_request()
    and status = 'pending'
    and public.has_pending_leave_request()
  )
  with check (
    employee_id = public.current_employee_id()
    and public.has_pending_leave_request()
    and (status <> 'approved' or status <> 'rejected' or status <> 'cancelled'
         or status is distinct from public.current_setting('request.jwt.claims', true)::text[2])
  );
