       and exists (
         select 1
         from public.ride_bookings b
         where b.ride_id = ride_bookings.ride_id
           and b.passenger_id = ride_bookings.passenger_id
           and b.status = 'requested'
       ))
      or exists (
        select 1
        from public.ride_bookings b
        where b.ride_id = ride_bookings.ride_id
          and b.passenger_id = ride_bookings.passenger_id
          and b.status = 'requested'
          and (
