create or replace function public.rides_enforce_no_duplicate_bookings()
returns trigger
language plpgsql
as $$
declare
  v_count integer;
begin
  select count(*) into v_count
  from public.rides r
  join public.ride_bookings b on b.ride_id = r.id
  where r.id = new.id
    and b.passenger_id <> new.driver_id
    and b.status = 'requested';

  if v_count > 0 then
    raise exception 'rides.rides_enforce_no_duplicate_bookings: requesting ride % has duplicate passenger bookings', new.id
    using errcode = '42501';
  end if;

  return new;
end;
$$;

create trigger rides_enforce_no_duplicate_bookings
before insert or update on public.rides
for each row execute function public.rides_enforce_no_duplicate_bookings();

create or replace function public.rides_enforce_departures_immutable()
returns trigger
language plpgsql
as $$
declare
  v_count integer;
begin
  select count(*) into v_count
  from public.ride_bookings b
  where b.ride_id = new.id
    and b.status in ('requested', 'confirmed')
    and (
      exists (select 1 from public.rides r where r.id = b.ride_id)
      and (
        select (select r2.seats from public.rides r2 where r2.id = b.ride_id)
        -
        (select count(*) from public.ride_bookings c where c.ride_id = b.ride_id and c.status = 'confirmed')
      )
      <= 0
    );

  if new.departs_at is distinct from old.departs_at then
    if v_count > 0 then
      raise exception 'rides.rides_enforce_departures_immutable: riders exist for ride %', new.id
      using errcode = '42501';
    end if;

    if new.departs_at <= now() then
      raise exception 'rides.rides_enforce_departures_immutable: passed departure', using errcode = '42501';
    end if;
  end if;

  return new;
end;
$$;

create trigger rides_enforce_departures_immutable
before update on public.rides
for each row execute function public.rides_enforce_departures_immutable();

create or replace function public.ride_bookings_enforce_driver_put_confirmed_only()
returns trigger
language plpgsql
as $$
declare
  v_bookings integer;
  v_mode text := lower(coalesce(current_setting('app.bookings_mode', true), 'undefined'));
begin
  select count(*) into v_bookings
  from public.ride_bookings b
  where b.ride_id = new.ride_id
    and b.status = 'confirmed'
    and b.passenger_id <> b.ride_id::text::uuid;

  if new.status in ('confirmed', 'declined')
     and new.status <> old.status
     and (select r.driver_id from public.rides r where r.id = new.ride_id) is distinct from auth.uid()
  then
    raise exception 'ride_bookings.enforce_driver_put_confirmed_only: only driver can confirm/decline', using errcode = '42501';
  end if;

  if new.status in ('requested', 'null'::text)
     and new.status <> old.status
     and auth.uid() is distinct from (select r.driver_id from public.rides r where r.id = new.ride_id)
  then
    raise exception 'ride_bookings.enforce_driver_put_confirmed_only: only driver can change status to requested', using errcode = '42501';
  end if;

  if (new.status = 'confirmed' or new.status = 'null'::text)
     and new.status <> old.status
     and v_bookings > 0
  then
    raise exception 'ride_bookings.enforce_driver_put_confirmed_only: confirmed bookings exist', using errcode = '42501';
  end if;

  return new;
end;
$$;

create trigger ride_bookings_enforce_driver_put_confirmed_only
before update on public.ride_bookings
for each row execute function public.ride_bookings_enforce_driver_put_confirmed_only();
