create function public.can_borrow_book(p_book_id bigint) returns boolean
language sql
stable
as $$
  select
    public.books.copies > (
      select count(*)
      from public.loans
      where public.loans.book_id = p_book_id
        and public.loans.returned_on is null
    )
    and not exists (
      select 1
      from public.loans
      where public.loans.borrower_id = auth.uid()
        and public.loans.returned_on is null
      limit 1
    )
$$;

