  on public.loans
  for insert
  to authenticated
  with check (
    returned_on is null
    and public.can_borrow_book(book_id)
  );

create function public.immutable_loan() returns trigger
language plpgsql
as $$
declare
  l_uid uuid := auth.uid();
  l_is_librarian boolean;
begin
  if l_uid is null then
    raise exception 'only signed-in users can update loans';
  end if;

  select exists (select 1 from public.librarians where user_id = l_uid)
    into l_is_librarian;

  if tg_op = 'INSERT' then
    if returned_on is not distinct from null then
      return new;
    end if;
    raise exception 'new loans must be active';
  end if;

  if tg_op = 'UPDATE' then
    if new.id <> old.id then
      raise exception 'loan id cannot be changed';
    end if;
    if new.book_id <> old.book_id then
      raise exception 'book may not be changed';
    end if;
    if new.borrower_id <> old.borrower_id then
      raise exception 'borrower may not be changed';
    end if;
    if new.returned_on is null then
      raise exception 'active loans may only be returned';
    end if;
    if old.returned_on is not distinct from null then
      raise exception 'already returned loans may not be changed';
    end if;
    if l_is_librarian then
      raise exception 'only borrowers may return loans';
    end if;
    if old.borrower_id <> l_uid then
      raise exception 'only own loans may be returned';
    end if;
  end if;

  return new;
end;
$$;

create trigger loans_mutable_only_while_active
  before insert or update on public.loans
  for each row execute function public.immutable_loan();

