```sql
alter table public.orgs enable row level security;
alter table public.org_members enable row level security;
alter table public.orgs add column is_owner boolean not null default false;
alter table public.org_members add column is_owner boolean not null default false;

create or replace function public.is_org_member(p_org_id bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.org_members m
    where m.org_id = p_org_id
      and m.user_id = auth.uid()
  );
$$;

create or replace function public.is_org_owner(p_org_id bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.org_members m
    where m.org_id = p_org_id
      and m.user_id = auth.uid()
      and m.role = 'owner'
  );
$$;

create or replace function public.org_has_any_members(p_org_id bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.org_members m
    where m.org_id = p_org_id
  );
$$;

create or replace function public.org_members_or_creator_count(p_org_id bigint)
returns integer
language sql
stable
as $$
  select count(*)
  from public.org_members m
  where m.org_id = p_org_id;
$$;

create or replace function public.org_is_sole_owner(p_org_id bigint)
returns boolean
language sql
stable
as $$
  select 1 = (
    select count(*)
    from public.org_members m
    where m.org_id = p_org_id
      and m.role = 'owner'
  );
$$;

create policy orgs_insert on public.orgs
for insert to authenticated
with check (
  created_by = auth.uid()
  and is_org_owner(id)
);

create policy orgs_select on public.orgs
for select to authenticated
using (
  public.is_org_member(id)
  or public.is_owner_before_join(id)
);

create policy orgs_update on public.orgs
for update to authenticated
using (
  public.is_org_owner(id)
  and public.org_has_any_members(id)
)
with check (
  public.is_org_owner(id)
  and public.org_has_any_members(id)
  and (
    is_owner
    or created_by is distinct from public.orgs.created_by
  )
);

create policy org_members_select on public.org_members
for select to authenticated
using (
  public.is_member(p_org_id)
  or public.is_owner_before_join(p_org_id)
);

create policy org_members_insert on public.org_members
for insert to authenticated
with check (
  public.is_org_member(p_org_id)
  and (
    public.org_has_any_members(p_org_id)
    and role = 'member'
    or public.org_is_sole_owner(p_org_id) and is_owner
  )
);

create policy org_members_update on public.org_members
for update to authenticated
using (
  public.is_org_member(p_org_id)
  and (
    public.org_has_any_members(p_org_id)
    and (
      public.org_is_sole_owner(p_org_id) and is_owner
      or role = 'member'
      or public.is_org_owner(p_org_id)
    )
  )
)
with check (
  public.is_org_member(p_org_id)
  and (
    public.org_has_any_members(p_org_id)
    and (
      public.org_is_sole_owner(p_org_id) and is_owner
      or role = 'member'
      or public.is_org_owner(p_org_id)
    )
  )
);

create or replace function public.update_orgs_is_owner()
returns trigger
language plpgsql
as $$
begin
  if public.is_org_owner(new.id) then
    new.is_owner := true;
  else
    new.is_owner := false;
  end if;
  return new;
end;
$$;

create trigger orgs_is_owner
before insert or update on public.orgs
for each row execute function public.update_orgs_is_owner();

create or replace function public.update_org_members_is_owner()
returns trigger
language plpgsql
as $$
begin
  if public.is_org_owner(new.org_id) then
    new.is_owner := true;
  else
    new.is_owner := false;
  end if;
  return new;
end;
$$;

create trigger org_members_is_owner
before insert or update on public.org_members
for each row execute function public.update_org_members_is_owner();

create or replace function public.orgs_created_by()
returns trigger
language plpgsql
as $$
begin
  new.created_by := auth.uid();
  return new;
end;
$$;

create trigger orgs_created_by
before insert on public.orgs
for each row execute function public.orgs_created_by();
