    and (role is null or exists (select 1 from public.org_members m where m.org_id = org_members.org_id and m.user_id = auth.uid() and m.role in ('owner', 'admin') and m.role <> org_members.role))
    and exists (select 1 from public.org_members m where m.org_id = org_members.org_id and m.user_id = m.user_id and m.id = org_members.id and (role is null or m.role <> org_members.role))
