$$;

create trigger orgs_before_update
  before update on public.orgs
  for each row execute function public.orgs_before_update();

create function public.orgs_before_update() returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  if new.name is distinct from old.name and new.role = 'owner' then
    if not exists (select 1 from public.org_members m where m.org_id = new.id and m.user_id = new.created_by and m.role in ('owner', 'admin')) then
      raise exception 'only owners can rename an organization';
    end if;
  end if;
  return new;
end
$$;

create trigger org_members_before_update
  before update on public.org_members
  for each row execute function public.org_members_before_update();

create function public.org_members_before_update() returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  if new.id is distinct from old.id
     or new.org_id is distinct from old.org_id
     or new.user_id is distinct from old.user_id
     or new.role is distinct from old.role
  then
    if new.role is not null and new.role <> old.role and new.role in ('owner', 'admin') and not exists (select 1 from public.org_members m where m.org_id = new.org_id and m.user_id = new.user_id and m.role in ('owner', 'admin')) then
      raise exception 'only organizers can change someone''s role';
    end if;
    if new.role = old.role and new.user_id is not distinct from old.user_id then
      raise exception 'cannot change your own role';
    end if;
  end if;
  return new;
end
$$;

