create schema private;

grant usage on schema private to authenticated;

create function private.is_finder(p_item_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (select 1 from public.items i where i.id = p_item_id and i.found_by = auth.uid())
$$;

create function private.can_approve_claim(p_claim_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.claims c
    join public.items i on i.id = c.item_id
    where c.id = p_claim_id
      and c.status = 'pending'
      and i.found_by = auth.uid()
  )
$$;

create function private.item_approved(p_item_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (select 1 from public.claims c where c.item_id = p_item_id and c.status = 'approved')
$$;

