    and private.item_approved(item_id) is false
    and private.is_finder(item_id) is false
    and claimant_id = auth.uid()
  );

create policy claims_update on public.claims
  for update to authenticated
  using (private.can_approve_claim(id))
  with check (private.can_approve_claim(id) and status in ('approved', 'rejected'));
