alter table public.household_members enable row level security;
alter table public.shopping_items enable row level security;

create or replace function public.is_household_member(p_household_id bigint)
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.household_members hm
    where hm.household_id = p_household_id
      and hm.user_id = auth.uid()
  );
$$;

create or replace function public.can_add_item(p_household_id bigint)
returns boolean
language sql
stable
as $$
  select public.is_household_member(p_household_id)
     and (select exists (
  select 1
  from public.shopping_items s
  where s.household_id = p_household_id
    and s.added_by = auth.uid()
));$$;

create or replace function public.can_claim_item(p_household_id bigint, p_item_id bigint)
returns boolean
language sql
stable
as $$
  select public.is_household_member(p_household_id)
     and exists (
  select 1
  from public.shopping_items s
  where s.household_id = p_household_id
    and s.id = p_item_id
    and s.is_bought = false
    and s.claimed_by is distinct from auth.uid()
);$$;

create or replace function public.can_update_item(p_household_id bigint, p_item_id bigint)
returns boolean
language sql
stable
as $$
  select public.is_household_member(p_household_id)
     and exists (
  select 1
  from public.shopping_items s
  where s.household_id = p_household_id
    and s.id = p_item_id
    and s.is_bought = false
    and s.claimed_by = auth.uid()
);$$;

create or replace function public.f_item_household(p_household_id bigint)
returns trigger
language plpgsql
as $$
begin
  if public.is_household_member(new.household_id) is distinct from public.is_household_member(old.household_id) then
    raise exception 'cannot change household';
  end if;
  return new;
end;
$$;

create or replace function public.f_item_can_update(p_household_id bigint, p_id bigint)
returns trigger
language plpgsql
as $$
begin
  if public.is_household_member(new.household_id) is distinct from public.is_household_member(old.household_id) then
    raise exception 'cannot change household';
  end if;
  if new.claimed_by is distinct from old.claimed_by then
    if (select public.can_update_item(p_household_id, p_id)) is false then
      raise exception 'not your claim';
    end if;
  end if;
  if (select old.claimed_by) is not null and new.claimed_by is null and (select old.is_bought) is true then
    raise exception 'cannot unclaim a bought item';
  end if;
  if (select old.claimed_by) is null and new.claimed_by is not null and new.is_bought is not false then
    raise exception 'bought items must remain unset';
  end if;
  if new.claimed_by is not distinct from old.claimed_by then
    if new.is_bought is distinct from old.is_bought then
      raise exception 'cannot toggle bought on owned item';
    end if;
  end if;
  return new;
end;
$$;

create policy household_members_select on public.household_members
  for select to authenticated
  using (public.is_household_member(household_id));

create policy shopping_items_select on public.shopping_items
  for select to authenticated
  using (public.is_household_member(household_id));

create policy shopping_items_insert on public.shopping_items
  for insert to authenticated
  with check (public.can_add_item(household_id) and added_by = auth.uid());

create policy shopping_items_update on public.shopping_items
  for update to authenticated
  using (public.can_claim_item(household_id, id) or public.can_update_item(household_id, id))
  with check (public.f_item_can_update(household_id, id));

create policy shopping_items_delete on public.shopping_items
  for delete to authenticated
  using (public.can_add_item(household_id) and not (select is_bought) and added_by = auth.uid());

create trigger t_item_household
  before insert or update on public.shopping_items
  for each row execute function public.f_item_household(new.household_id);

create trigger t_item_can_update
  before update on public.shopping_items
  for each row execute function public.f_item_can_update(new.household_id, old.id);
