create or replace function public.patient_portal_security()
returns trigger
language plpgsql
as $$
begin
  if coalesce(current_setting('request.jwt.claim.role', true), 'anon') = 'service_role'
     or current_setting('request.jwt.claim.role', true) is null
  then
    return new;
  end if;

  if new.id is distinct from old.id
     or new.patient_id is distinct from old.patient_id
     or new.doctor_id is distinct from old.doctor_id
  then
    raise exception 'care_team changes are not allowed through the app';
  end if;

  if new.released_at is not null
     and new.released_at <= now()
  then
    raise exception 'cannot release results in the past';
  end if;

  if new.released_at is not null
     and old.released_at is null
  then
    raise exception 'results can only be released, not dereleased';
  end if;

  if new.released_at is null
     and old.released_at is not null
  then
    raise exception 'results cannot be made unreleased once released';
  end if;

  return new;
end;
$$;

create trigger patient_portal_security_trigger
before insert or update on public.lab_results
