create function public.restore_record(p_record_id bigint)
returns void
language plpgsql
as $$
declare
  v_org_id bigint;
  v_deleted_at timestamptz;
  v_deleted_timestamp timestamptz;
  v_actor uuid := auth.uid();
begin
  if v_actor is null then
    raise exception 'restore_record is not allowed for anonymous users';
  end if;

  select r.org_id, r.deleted_at
  into v_org_id, v_deleted_at
  from public.records r
  where r.id = p_record_id;

  if not found or v_org_id is null or v_deleted_at is null then
    raise exception 'record % not found or not deleted', p_record_id;
  end if;

  if not public.is_org_admin(v_org_id) then
    raise exception 'restorer is not an admin of organization %', v_org_id;
  end if;

  v_deleted_timestamp := now();

  if v_deleted_at < v_deleted_timestamp - interval '30 days' then
    raise exception 'record % was deleted over 30 days ago and cannot be restored', p_record_id;
  end if;

  update public.records
  set deleted_at = null
  where id = p_record_id;
end;
$$;
