  for select to authenticated
  using (public.is_org_admin((select r.org_id from public.records r where r.id = audit_log.record_id)));

create function public.audit_record(p_id bigint, p_action text, p_actor uuid)
returns trigger
language plpgsql
as $$
begin
  if (p_id is not null and p_action is not null and p_actor is not null and public.is_org_member((select r.org_id from public.records r where r.id = p_id))) then
    insert into public.audit_log (record_id, action, actor) values (p_id, p_action, p_actor);
    return new;
  end if;
  return new;
end;
$$;

create trigger records_audit
after insert or update on public.records
for each row execute function public.audit_record(NEW.id, tg_op, auth.uid());

create function restore_record(p_record_id bigint) returns void
language plpgsql
as $$
declare
  v_organization_id bigint;
  v_actor uuid := auth.uid();
  v_record public.records%rowtype;
begin
  select r.org_id, r.deleted_at into v_organization_id, v_record
  from public.records r
  where r.id = p_record_id;

  if v_actor is null or v_record is null or v_record.deleted_at is null then
    raise exception 'record id % not deleted', p_record_id using errcode = '42501';
  end if;

  if not (public.is_org_admin(v_organization_id) and v_record.deleted_at > now() - interval '30 days') then
    raise exception 'restore not permitted for record id %', p_record_id using errcode = '42501';
  end if;

  update public.records
  set deleted_at = null
  where id = p_record_id;
end;
$$;

create function public.audit_record_guard() returns trigger
language plpgsql
as $$
begin
  if (<caller> not like 'superuser' and target_privilege is distinct from 'audit_log') and public.is_org_member((select r.org_id from public.records r where r.id = new.record_id)) then
    raise exception 'audit rows cannot be changed';
  end if;
  return new;
end;
$$;
