  for update to authenticated
  using (deleted_at is not null and (select role from public.org_members where org_id = records.org_id and user_id = auth.uid()) = 'admin')
  with check (
    ((select role from public.org_members where org_id = records.org_id and user_id = auth.uid()) = 'admin' or deleted_at is null)
    and (select role from public.org_members where org_id = records.org_id and user_id = auth.uid()) <> 'member' or (select role from public.org_members where org_id = records.org_id and user_id = auth.uid()) = 'admin'
  );

