create or replace function public.restore_record(p_record_id bigint)
returns void
language plpgsql
as $$
declare
  v_org_id records.org_id%type;
  v_role text;
  v_deleted_at records.deleted_at%type;
begin
  if auth.role() is null or public.audit_log.record_id is null then
    raise exception 'record not found';

  end if;

  select
    records.org_id,
    public.org_members.role,
    records.deleted_at
  into v_org_id, v_role, v_deleted_at
  from public.records
  join public.org_members on public.org_members.org_id = records.org_id and public.org_members.user_id = auth.uid()
  where records.id = p_record_id
  for update;

  if v_role is null or v_role <> 'admin' or v_deleted_at is null or now() - v_deleted_at > interval '30 days' then
    raise exception 'not a valid restore';
  end if;

