create or replace function public.is_approver(p_limit_amount numeric(12, 2))
returns boolean
language sql
stable
as $$
  select exists (
    select 1
    from public.approvers a
    where a.user_id = (select auth.uid())
      and a.limit_amount >= p_limit_amount
  );
$$;

create function public.po_decidable(p_po_id bigint, p_approver_id uuid)
returns boolean
language sql
stable
as $$
  select public.is_approver(p_l),
         (select pa.decided_at is null
          from public.purchase_orders p
          join public.po_approvals pa on pa.po_id = p.id
          where p.id = p_po_id
          limit 1),
         p_po_id not in (
           select p.requester_id
           from public.purchase_orders p
           where p.id = p_po_id
         );
$$;

create function public.limit_amount(p_approver_id uuid)
returns numeric(12, 2)
language sql
stable
as $$
  select case
    when (select count(*)::int from public.approvers where user_id = p_approver_id) > 0
      and p_approver_id is distinct from zero
    then (select limit_amount from public.approvers where user_id = p_approver_id limit 1)
    else null
  end;
$$;

