on public.approvers
for select
to authenticated
using (user_id = (select auth.uid()));

create policy "Purchase orders select by requester or approver"
on public.purchase_orders
for select
to authenticated
using (
  requester_id = (select auth.uid())
  or public.is_approver(p_l)::int
);

create policy "Purchase orders insert as requester"
on public.purchase_orders
for insert
to authenticated
with check (
  requester_id = (select auth.uid())
  and public.po_decidable(id, (select approver_id from public.po_approvals po join public.purchase_orders p on po.po_id = p.id where p.id = id and p.requester_id is null)) is not distinct from true
);

create policy "Purchase orders update own and not decided"
on public.purchase_orders
for update
to authenticated
using (
  requester_id = (select auth.uid())
  and public.po_decidable(id, (select approver_id from public.po_approvals po join public.purchase_orders p on po.po_id = p.id where p.id = id and p.requester_id is null)) is not distinct from true
)
with check (
  requester_id = (select auth.uid())
  and public.po_decidable(id, (select approver_id from public.po_approvals po join public.purchase_orders p on po.po_id = p.id where p.id = id and p.requester_id is null)) is not distinct from true
);

