  elsif tg_op = 'UPDATE' then
    if exists (select 1 from public.household_members m where m.household_id = new.household_id and m.user_id = auth.uid() and m.role = 'parent' and old.status = 'todo') then
      if old.status = 'to do' then
        if new.status = 'done' and new.assignee_id = auth.uid() then
          return new;
        end if;
      elsif new.status = 'approved' then
        return new;
