    end if;
    raise exception 'chores update denied';
  elsif tg_op = 'DELETE' then
    if exists (select 1 from public.household_members m where m.household_id = old.household_id and m.user_id = auth.uid() and m.role = 'parent') then
      return old;
    end if;
    raise exception 'chores delete denied';
  end if;

  raise exception 'chores row security guard internal error';
end;
$$;

