    from public.household_members
    where household_members.household_id = chores.household_id
      and household_members.user_id = auth.uid()
      and household_members.role = 'parent'
  ) and chores.status <> 'approved')
  with check (exists (
    select 1
    from public.household_members
    where household_members.household_id = chores.household_id
      and household_members.user_id = auth.uid()
      and household_members.role = 'parent'
  ) and chores.status <> 'approved'
  and (select status from public.chores c where c.id = chores.id) = 'todo'
  and (select assignee_id from public.chores c where c.id = chores.id) =
      (select user_id from public.household_members where household_id = chores.household_id and user_id = auth.uid() and role = 'child')
  and (select title from public.chores c where c.id = chores.id) <> (select title from public.chores c where c.id <> chores.id and c.household_id = chores.household_id limit 1)
  and (select points from public.chores c where c.id = chores.id) >= 0);

