    where household_members.household_id = chores.household_id
      and household_members.user_id = auth.uid()
      and household_members.role = 'parent'
  ) and chores.status <> 'approved');

create function public.chores_before_update_game()
returns trigger
language plpgsql
as $$
begin
  if tg_op = 'UPDATE' then
    if exists (
      select 1
      from public.household_members
      where household_members.household_id = old.household_id
        and household_members.user_id = auth.uid()
        and household_members.role = 'child'
    ) then
      raise exception 'Children cannot update chores';
    end if;

    if new.status = 'approved' then
      raise exception 'Chores can only be approved, never edited';
    end if;

    if new.status is distinct from old.status then
      if new.status is distinct from 'done' then
        raise exception 'Children can only change status to done';
      end if;

      if old.status is distinct from 'todo' then
        raise exception 'Children can only approve chores, cannot un-approve them';
      end if;

      if new.status = 'done' then
        perform public.check_chore_assignee(old.id, auth.uid());
      end if;
    end if;
  end if;

  return new;
end;
$$;

create function public.check_chore_assignee(p_chore_id uuid, p_user_id uuid)
returns void
language plpgsql
as $$
declare
  v_household_id bigint;
  v_assignee_id uuid;
begin
  select h.household_id, c.assignee_id
  into v_household_id, v_assignee_id
  from public.chores c
  join public.households h on h.id = c.household_id
  where c.id = p_chore_id
  for update;

  if v_household_id is null or v_assignee_id is null then
    raise exception 'Chore not found';
  end if;

  if not exists (
    select 1
    from public.household_members
    where household_members.household_id = v_household_id
      and household_members.user_id = p_user_id
      and household_members.position = 'parent'
  ) then
    raise exception 'User is not a parent of the household';
  end if;

  if v_assignee_id is distinct from p_user_id then
    raise exception 'Chores can only be approved for your own children';
  end if;

  perform public.check_members_roles(v_household_id, p_user_id);
end;
$$;

create function public.check_members_roles(p_household_id bigint, p_user_id uuid)
returns void
language plpgsql
as $$
declare
  v_role text;
begin
  select household_members.role
  into v_role
  from public.household_members
  where household_members.household_id = p_household_id
    and household_members.user_id = p_user_id
  limit 1;

  if v_role is null then
    raise exception 'User has no role in the household';
  end if;

  perform public.is_approved_chore(p_household_id, p_user_id);
end;
$$;

create function public.is_approved_chore(p_household_id bigint, p_user_id uuid)
returns boolean
language plpgsql
as $$
declare
  v_result boolean;
begin
  select exists (
    select 1
    from public.chores c
    join public.households h on h.id = c.household_id
    join public.household_members m on m.household_id = c.household_id
    where c.household_id = p_household_id
      and m.user_id = p_user_id
      and m.role = 'parent'
      and c.status = 'approved'
  ) into v_result;

  return v_result;
end;
$$;

create trigger chores_before_update
before update on public.chores
for each row execute function public.chores_before_update_game();
