create function public.break_glass(p_patient_id bigint, p_reason text)
returns timestamptz
language plpgsql
as $$
declare
  v_minutes int := 60;
  v_expires timestamptz;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  if not exists (select 1 from public.clinicians where user_id = auth.uid()) then
    raise exception 'only clinicians can break glass';
  end if;

  if not exists (select 1 from public.patients where id = p_patient_id) then
    raise exception 'patient does not exist';
  end if;

  if trim(p_reason) is null or length(trim(p_reason)) < 10 then
    raise exception 'reason must be at least 10 characters';
  end if;

  v_expires := now() + interval '1 hour';

  insert into public.break_glass_grants (patient_id, clinician_id, reason, expires_at)
  values (p_patient_id, auth.uid(), p_reason, v_expires);

  return v_expires;
end;
$$;
