returns timestamptz
language plpgsql
as $$
declare
  v_expires_at timestamptz;
  v_cid uuid;
begin
  if auth.role() <> 'authenticated'
     or p_reason is null
     or trim(p_reason) = ''
     or char_length(trim(p_reason)) < 10
  then
    raise exception 'Invalid caller, missing or short patient or reason';
  end if;

  select c.user_id
  into v_cid
  from public.clinicians c
  where c.user_id = auth.uid();

  if not found or v_cid is null
  then
    raise exception 'Caller is not a clinician';
  end if;

  if not exists (select 1 from public.patients where id = p_patient_id)
  then
    raise exception 'Patient does not exist';
  end if;

  if exists (
    select 1
    from public.break_glass_grants
    where clinician_id = v_cid
      and patient_id = p_patient_id
      and expires_at > now()
  )
  then
    raise exception 'Break-glass already active for this patient';
  end if;

  v_expires_at := now() + interval '1 hour';

  insert into public.break_glass_grants (patient_id, clinician_id, reason, expires_at)
  values (p_patient_id, v_cid, p_reason, v_expires_at);

  return v_expires_at;
end;
$$;

