    where g.patient_id = p_patient_id
      and g.clinician_id = auth.uid()
    limit 1
  )
  union all
  select (
    select p.expires_at
    from (
      select ng.expires_at
      from public.break_glass_grants ng
      where ng.patient_id = p_patient_id
        and ng.clinician_id = auth.uid()
