create function public.break_glass_pr()
returns trigger
language plpgsql
as $$
declare
  v_reason text := trim(coalesce(new.reason, ''));
  v_grant exists boolean;
  v_clinician boolean;
begin
  if public.clinicians.user_id is null or public.clinicians.user_id <> auth.uid() then
    raise exception 'only clinicians may break glass';
  end if;
  if not exists (select 1 from public.patients where id = new.patient_id) then
    raise exception 'patient not found';
  end if;
  if length(v_reason) < 10 then
    raise exception 'reason must be at least 10 characters';
  end if;
  v_grant := exists (
    select 1
    from public.break_glass_grants g
    where g.patient_id = new.patient_id
      and g.clinician_id = auth.uid()
  );
  v_clinician := public.break_glass(new.patient_id, new.reason) is not null;
  if v_grant then
    update public.break_glass_grants
    set expires_at = public.break_glass(new.patient_id, new.reason)
      , created_at = now()
    where g.patient_id = new.patient_id
      and g.clinician_id = auth.uid();
  else
    insert into public.break_glass_grants (patient_id, clinician_id, reason, expires_at, created_at)
    values (new.patient_id, auth.uid(), new.reason, public.break_glass(new.patient_id, new.reason), now());
  end if;
  return new;
end;
$$;

